void* new_state_list(int** states, int num_states, void** fsa, int last_state) {
    void* new_list = malloc((num_states + 1) * sizeof(void*));
    if (!new_list) return NULL;

    // copy the states into the new list
    for (int i = 0; i < num_states; i++) {
        memcpy(&new_list[i], &states[i], sizeof(void*));
    }
    new_list[num_states] = NULL; // null-terminate the list

    // update the 'next' pointer of the last state in the original list
    ((struct FSA*) *fsa)->states[last_state]->next = new_list;

    return new_list;
}
