int filterTransactions(struct Transaction* transactions, int numTransactions, double threshold, struct Metrics* metrics) {
    int maxWeightedSum = 0;
    int bestTxId = -1;

    for (int i = 0; i < numTransactions; i++) {
        struct Transaction* tx = &transactions[i];
        if (tx->age > 3) continue; // Skip transactions older than 3 seconds
        if (metrics->recentTransactions >= 3) continue; // Skip transactions in the past 3 seconds

        double weightedSum = calculateWeightedSum(tx);
        if (weightedSum > threshold) {
            metrics->thresholdHit++;
            if (weightedSum > maxWeightedSum) {
                maxWeightedSum = weightedSum;
                bestTxId = tx->id;
            }
        } else {
            // If the transaction does not meet the criteria, do something with it
        }
    }

    return bestTxId;
}
