```c
int load_resource_bundle(const char *path) {
    int num_items = 0;
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        return -1; // error opening file
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        fclose(file);
        return -2; // error allocating memory for bundle
    }

    ResourceBundleItem **items = malloc(sizeof(ResourceBundleItem *));
    if (items == NULL) {
        free(bundle);
        fclose(file);
        return -3; // error allocating memory for items
    }

    while (fscanf(file, "%s", (char *)bundle->name) != 1) {
        break;
    }

    while (fscanf(file, "%s", (char *)bundle->description) != 1) {
        break;
    }

    // read and store the rest of the items
    num_items = 0;
    ResourceBundleItem *item = malloc(sizeof(ResourceBundleItem));
    while (fscanf(file, "%s %s", (char *)item->name, (char *)item->description) == 2) {
        items[num_items] = item;
        num_items++;
        free(item);
        item = malloc(sizeof(ResourceBundleItem));
    }

    free(item);

    fclose(file);
    free(bundle);
    free(items);
    return num_items;
}

