#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 10

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        return 1;
    }

    char *line = malloc(MAX_LINE_LENGTH);
    if (line == NULL) {
        fclose(file);
        return 1;
    }

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char **fields = malloc(sizeof(char *) * MAX_FIELDS);
        int field_count = 0;

        char *token = strtok(line, " ");
        while (token != NULL && field_count < MAX_FIELDS - 1) {
            fields[field_count++] = strdup(token);
            token = strtok(NULL, " ");
        }

        if (field_count > 0) {
            double average = (atof(fields[field_count - 2]) + atof(fields[field_count - 1])) / 2.0;
            printf("%s", fields[0]);
            for (int i = 1; i < field_count - 1; i++) {
                printf(",%s", fields[i]);
            }
            printf(",%.2f\n", average);
        }

        for (int i = 0; i < field_count; i++) {
            free(fields[i]);
        }
        free(fields);

        free(line);
        line = malloc(MAX_LINE_LENGTH);
    }

    fclose(file);
    return 0;
}

