struct Node {
    int key;
    struct Node* left;
    struct Node* right;
};

struct Node* insertOffset(struct Node* root, int offset) {
    if (root == NULL) {
        root = (struct Node*)malloc(sizeof(struct Node));
        root->key = offset;
        root->left = NULL;
        root->right = NULL;
    } else if (offset < root->key) {
        root->left = insertOffset(root->left, offset);
    } else if (offset > root->key) {
        root->right = insertOffset(root->right, offset);
    }
    return root;
}
