typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TIFFImageInfo;

TIFFImageInfo parseTIFFImage(const char* filename) {
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) return (TIFFImageInfo){-1, -1, -1};

    uint16_t bitsPerSample;
    TIFFGetField(tiff, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
    int samplesPerPixel;
    TIFFGetField(tiff, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);

    if (bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16) {
        TIFFImageInfo info = (TIFFImageInfo){
            .bitsPerSample = bitsPerSample,
            .samplesPerPixel = samplesPerPixel,
            .extraSamples = 0
        };
        return info;
    } else {
        TIFFImageInfo info = (TIFFImageInfo){
            .bitsPerSample = -1,
            .samplesPerPixel = -1,
            .extraSamples = TIFFExtraSamples(tiff)
        };
        return info;
    }
}
