#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <resolv.h>

int dns_resolve(const char* hostname, u_char** ip) {
    int status;
    struct hostent *he;

    if (!hostname || !ip) {
        return -1; // invalid input
    }

    he = gethostbyname(hostname);
    if (he == NULL) {
        return -2; // unable to resolve hostname
    }

    *ip = malloc(he->h_length + 1);
    if (*ip == NULL) {
        return -3; // memory allocation failed
    }
    memcpy(*ip, he->h_addr, he->h_length);
    (*ip)[he->h_length] = '\0';

    status = 0;
    return status;
}

