#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int receive_file(char* filename, char* mode) {
    int sockfd;
    struct sockaddr_in server_addr;

    // Create a UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("socket creation failed");
        return -1;
    }

    // Set up the server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345); // Replace with your port number

    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) == -1) {
        perror("inet_pton failed");
        return -1;
    }

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("connection failed");
        close(sockfd);
        return -1;
    }

    int bytes_received = 0;
    FILE* file_ptr = fopen(filename, mode);

    if (!file_ptr) {
        perror("fopen failed");
        close(sockfd);
        return -1;
    }

    char buffer[1024];
    while (1) {
        // Receive data from the server
        int bytes_read = recv(sockfd, buffer, 1024, 0);
        if (bytes_read == -1) {
            perror("recv failed");
            fclose(file_ptr);
            close(sockfd);
            return -1;
        }

        if (bytes_read == 0) {
            break; // End of file
        }

        fwrite(buffer, sizeof(char), bytes_read, file_ptr);

        bytes_received += bytes_read;
    }

    printf("%d bytes received.\n", bytes_received);

    fclose(file_ptr);
    close(sockfd);

    return 0;
}
