int setup_tx_desc_queue(struct gmac_device *gmac, int num_descriptors, enum gmac_descriptor_mode mode) {
    struct scatterlist sg;
    void *desc_ptr = NULL;

    if (num_descriptors <= 0) {
        return -EINVAL;
    }

    desc_ptr = kmalloc_array(num_descriptors, sizeof(struct tx_desc), GFP_KERNEL);
    if (!desc_ptr) {
        return -ENOMEM;
    }

    gmac->TxDescCount = num_descriptors;

    struct tx_desc *desc = (struct tx_desc *)desc_ptr;
    sg.set_first_frag(&sg, desc);

    desc->dma_address = (uint32_t)sg_dma_address(&sg);
    desc->address = (uint16_t)desc;

    return 0;
}
