#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *str;
    int count;
} StringCount;

int process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL)
        return -1;

    int string_count = 0;
    StringCount **strings = NULL;
    size_t total_size = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        if (line[0] != '\n' && line[0] != '#') {
            if (line[0] == '!') {
                int count = atoi(&line[1]);
                string_count++;
                StringCount *new_string = malloc(sizeof(StringCount));
                new_string->str = NULL;
                new_string->count = count;
                if (total_size == 0) {
                    strings = malloc(sizeof(StringCount *));
                    total_size = sizeof(StringCount *);
                } else {
                    strings = realloc(strings, (total_size + sizeof(StringCount *)) * sizeof(StringCount *));
                }
                strings[total_size / sizeof(StringCount *)] = new_string;
                total_size += sizeof(StringCount *);
            } else if (line[0] == '\'') {
                size_t len = strlen(&line[1]);
                char *str = malloc((len + 1) * sizeof(char));
                strcpy(str, &line[1]);
                for (int i = 0; i < total_size / sizeof(StringCount *); i++) {
                    if (strings[i]->str == NULL) {
                        strings[i]->str = str;
                        break;
                    }
                }
            }
        }
    }

    fclose(file);

    int total_strings = total_size / sizeof(StringCount *);
    for (int i = 0; i < total_strings; i++) {
        free(strings[i]->str);
        free(strings[i]);
    }
    free(strings);

    return string_count;
}
