#include <string.h>

int main(int argc, char **argv) {
    int opt;
    int opt_index = 0;
    static struct option long_opts[] = {
        {"manpage", required_argument, NULL, 'm'},
        {"cs", no_argument, NULL, 'c'},
        {"output-file", required_argument, NULL, 'o'}
    };
    while ((opt = getopt_long(argc, argv, "+:mc:o:", long_opts, &opt_index)) != -1) {
        switch (opt) {
            case 'm':
                printf("manpage option\n");
                break;
            case 'c':
                printf("cs option\n");
                break;
            case 'o':
                printf("output file set to %s\n", optarg);
                break;
        }
    }

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] <input_file>\n", argv[0]);
        return 1;
    }

    char *input_file = argv[argc - 1];
    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file: %s\n", input_file);
        return 1;
    }
    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        line_count++;
    }
    fclose(fp);
    printf("Number of lines in file: %d\n", line_count);
    return 0;
}
