char* tokenize(char* str) {
    static char tokens[][10] = {"if", "else", "while", "int", "float", "+", "-", "*", "/", "=", "<", ">"}; 
    int i, len = strlen(str);
    bool found = false;

    for(i = 0; i < len; i++) {
        for(int j = 0; j < sizeof(tokens) / sizeof(*tokens); j++) {
            if(strncmp(str+i, tokens[j], strlen(tokens[j])) == 0) {
                return str + i;
            }
        }
        found = true;
    }

    return found ? NULL : str;
}
