int compressTiffData(tiff *t, uint8_t **buf) {
    t = NULL;
    int i = 0;
    TIFF *newFile;
    if ((newFile = TIFFOpen("compressed.tiff", "w")) == NULL)
        return 1;
    for (i = 0; i < t->imagewidth; i++) {
        uint8_t *scanline = (*buf) + (t->rowsize / 2);
        for (int j = 0; j < t->rowsize / 2; j++) {
            ((uint8_t *)scanline)[j] = ((uint8_t *)scanline)[(t->imagewidth - 1) - j];
        }
    }
    int status = TIFFWriteScanlines(newFile, *buf, (t->imagelength / t->bytesperrow), 0);
    if (status < 0)
        return 2;
    free(*buf);
    (*buf) = NULL;
    TIFFClose(newFile);
    return 0;
}

