void parse_ip_options(void *packet, int packet_len) {
    uint8_t *options = (uint8_t *) packet + sizeof(struct ip);
    while (packet_len - sizeof(struct ip) >= 1) {
        if (*options == 0) {
            printf("End-of-options option found\n");
            break;
        } else if (*options == 1) {
            printf("No-Operation option found\n");
        } else {
            uint8_t opt_len = *++options;
            uint8_t opt_type = *++options;
            printf("Option type: %u, length: %u\n", opt_type, opt_len);
        }
        options += 2 + opt_len;
    }
}
