struct DownstreamHost {
    char* hostname;
    int dataPort;
    int healthPort;
};

struct HostListResult {
    int numDownstreamHosts;
    struct DownstreamHost** downstreamHosts;
};

struct HostListResult parseHostList(char* hostList) {
    // assume hostList is a comma-separated list of hosts and ports in the format "hostname:port1,port2"
    char* token = strtok(hostList, ",");
    int numDownstreamHosts = 0;
    struct DownstreamHost** downstreamHosts = NULL;

    while (token != NULL) {
        // split the token into hostname and port
        char* hostnameToken = strtok(token, ":");
        int dataPort = atoi(strtok(NULL, ","));
        int healthPort = atoi(strtok(NULL, ","));

        struct DownstreamHost* downstreamHost = malloc(sizeof(struct DownstreamHost));
        downstreamHost->hostname = strdup(hostnameToken);
        downstreamHost->dataPort = dataPort;
        downstreamHost->healthPort = healthPort;

        if (numDownstreamHosts == 0) {
            downstreamHosts = malloc(sizeof(struct DownstreamHost*));
            downstreamHosts[0] = downstreamHost;
        } else {
            struct DownstreamHost** temp = malloc((numDownstreamHosts + 1) * sizeof(struct DownstreamHost*));
            memcpy(temp, downstreamHosts, numDownstreamHosts * sizeof(struct DownstreamHost*));
            free(downstreamHosts);
            downstreamHosts = temp;
            downstreamHosts[numDownstreamHosts] = downstreamHost;
        }

        token = strtok(NULL, ",");
        numDownstreamHosts++;
    }

    struct HostListResult result;
    result.numDownstreamHosts = numDownstreamHosts;
    result.downstreamHosts = downstreamHosts;

    return result;
}

