#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

int main() {
    pid_t pid;
    int num_vowels = 0, num_uppercase = 0, num_lowercase = 0;

    printf("Enter a sentence: ");
    char str[100];
    fgets(str, sizeof(str), stdin);

    pid = fork();
    if (pid == 0) {
        for (int i = 0; str[i]; i++) {
            if (strchr("aeiouAEIOU", str[i]))
                num_vowels++;
            else if (isupper(str[i]))
                num_uppercase++;
            else
                num_lowercase++;
        }
    } else {
        waitpid(pid, NULL, 0);
    }

    printf("Number of vowels: %d\n", num_vowels);
    printf("Number of uppercase letters: %d\n", num_uppercase);
    printf("Number of lowercase letters: %d\n", num_lowercase);

    return 0;
}
