void *lua_to_bson(lua_State *L) {
    bson_t *b;
    bson_error_t *e;

    b = bson_new();
    if (!b) {
        lua_pushnil(L);
        return NULL;
    }

    int top = lua_gettop(L);

    bson_append_document(b, 0, &e);

    switch (lua_toint(lua_checkstack(L, 1), -2)) {
        case 10: {
            bson_append_null(b, "bsontype", &e);
            break;
        }
        case 11: {
            lua_pushvalue(L, -2);
            lua_rotate(L, 1, -1);
            lua_pushcfunction(L, lua_to_string);
            lua_call(L, 1, 1);
            char *regex = (char *)lua_tolstring(L, -1, NULL);
            bson_append_regex(b, "bsontype", regex, &e);
            lua_pop(L, 1);
            break;
        }
    }

    bson_finish(b);

    return b;
}

