int parse_font_spec(char **spec) {
    int i = 0;
    char *font_type = NULL;
    char *style = NULL;
    int size = 0;

    while ((*spec)[i] && (*spec)[i] != '-') {
        if (!strncmp(&((*spec)[i]), "-italic", 7)) {
            style = "-italic";
            i += 7;
        } else if (!strncmp(&((*spec)[i]), "-bold", 5)) {
            style = "-bold";
            i += 5;
        }
    }

    *spec += i;

    while ((*spec)[i] && (*spec)[i] != '-') {
        if (isdigit((*spec)[i])) {
            size = atoi(&((*spec)[i]));
            i++;
        } else if (!strncmp(&((*spec)[i]), "-italic", 7)) {
            style = "-italic";
            i += 7;
        } else if (!strncmp(&((*spec)[i]), "-bold", 5)) {
            style = "-bold";
            i += 5;
        }
    }

    *spec += i;

    font_type = strtok(*spec, "-");

    return (font_type && strlen(font_type) > 0) ? 1 : 0;
}

