function perm = fillreducingordering(A)
    [n,m] = size(A);
    perm = zeros(1,n);
    for i = 1:n
        row = A(i,:);
        idx = find(row,1,'first');
        if isempty(idx)
            % Check for remaining non-zero elements
            idx = find(row ~= 0);
            if isempty(idx)
                % All elements are zero, so this is the last permutation
                break;
            end
        end
        [val,idx] = max(abs(row(idx)));
        perm(i) = idx;
    end
end

