scheduler_t* scheduler_init(int num_threads, int suspend_thresholds[], cpulist_t* cpu_list, assign_cpus_fn assign_cpus) {
    scheduler_t* scheduler = (scheduler_t*)malloc(sizeof(scheduler_t));
    if (!scheduler) return NULL;

    scheduler->num_threads = num_threads;
    scheduler->threads = (thread_t*)malloc(num_threads * sizeof(thread_t));
    if (!scheduler->threads) {
        free(scheduler);
        return NULL;
    }

    for (int i = 0; i < num_threads; i++) {
        scheduler->threads[i].state = SLEEPING;
        scheduler->threads[i].suspend_threshold = suspend_thresholds[i];
    }

    scheduler->cpu_list = cpu_list;
    scheduler->num_cpus = cpu_list ? cpu_list->size : 0;

    if (!assign_cpus) return NULL;

    for (int i = 0; i < num_threads; i++) {
        scheduler->threads[i].cpu = assign_cpus(&scheduler->cpu_list, i);
    }

    scheduler->mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(scheduler->mutex, NULL);

    return scheduler;
}

