struct {
    char* str;
    int vec[0];
    int arr[];
}* copyStruct(struct {
    char* str;
    int vec[0];
    int arr[];
}* source) {
    size_t vecSize = sizeof(source->vec) / sizeof(source->vec[0]);
    size_t arrSize = sizeof(source->arr) / sizeof(source->arr[0]);

    struct {
        char* str;
        int vec[vecSize];
        int arr[arrSize];
    }* newStruct = malloc(sizeof(struct {
        char* str;
        int vec[vecSize];
        int arr[arrSize];
    }));

    if (!newStruct) return NULL;

    newStruct->str = source->str ? strdup(source->str) : NULL;
    if (!newStruct->str) {
        free(newStruct);
        return NULL;
    }

    newStruct->vec[0] = 0; // Initialize the first element to zero
    for (int i = 0; i < vecSize - 1 && i < source->vec[0]; i++) {
        newStruct->vec[i + 1] = source->vec[i];
    }
    if (source->vec[0]) {
        newStruct->vec[source->vec[0]] = 0;
    }

    memcpy(&newStruct->arr, &source->arr, sizeof(int) * arrSize);

    return newStruct;
}

