#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char** strings;
    int capacity;
    int size;
} StringStack;

StringStack* stringStackInit(int capacity) {
    StringStack* stack = (StringStack*)malloc(sizeof(StringStack));
    stack->strings = (char**)malloc((capacity+1)*sizeof(char*));
    stack->capacity = capacity;
    stack->size = 0;
    return stack;
}

void stringStackPush(StringStack* stack, char* str) {
    if (stack->size >= stack->capacity) {
        stack->capacity *= 2;
        stack->strings = (char**)realloc(stack->strings, (stack->capacity+1)*sizeof(char*));
    }
    stack->strings[stack->size] = (char*)malloc((strlen(str)+1)*sizeof(char));
    strcpy(stack->strings[stack->size], str);
    free(str);
    stack->size++;
}

int stringStackIsEmpty(StringStack* stack) {
    return stack->size == 0;
}

void stringStackFree(StringStack* stack) {
    for (int i = 0; i < stack->size; i++) {
        free(stack->strings[i]);
    }
    free(stack->strings);
    free(stack);
}
