#include <stdlib.h>
#include <string.h>

struct server {
    char* hostname;
    int port;
};

struct server** split_servers(char* servers) {
    if (strlen(servers) == 0)
        return NULL;

    struct server** list = malloc(sizeof(struct server*));
    *list = NULL;

    char* token = strtok(servers, ",");
    while(token != NULL) {
        struct server* new_server = malloc(sizeof(struct server));
        char* port_token = strtok(token, ":");
        char* hostname = strdup(port_token);
        int port = atoi(strtok(NULL, ":"));
        new_server->hostname = hostname;
        new_server->port = port;

        if (*list == NULL) {
            *list = new_server;
        } else {
            struct server** temp_list = list;
            while(*temp_list != NULL) {
                temp_list = &((*temp_list)->next);
            }
            *temp_list = new_server;
        }

        free(token);
        token = strtok(NULL, ",");
    }

    return list;
}
