uint8_t* encrypt(uint8_t flag, uint8_t* arr1, uint8_t* arr2, uint8_t* arr3) {
    int len = sizeof(arr1)/sizeof(arr1[0]);
    uint8_t* result = (uint8_t*)malloc(len);
    for(int i=0; i<len; i++) {
        if(flag & 1) {
            result[i] = arr1[i] ^ arr2[i];
        } else if(flag & 2) {
            result[i] = (arr3[i] >> (flag % 8)) & 1;
        } else {
            result[i] = arr1[i] & arr2[i];
        }
    }
    return result;
}

