char* process_line(char* line) {
    int length = strlen(line);
    char* stack = (char*)malloc((length + 2)*sizeof(char));
    if(stack == NULL) return NULL;

    char* top = stack;
    for(int i = 0; i < length; i++) {
        *top++ = line[i];
    }
    *top++ = '\n';
    *top = '\0';

    // Parse the line into a function call and its arguments
    int start_idx = 0;
    if(line[0] == '(') {
        for(int i = 1; i < length; i++) {
            if(line[i] == ')') {
                char* func_name = (char*)malloc((i - start_idx + 2)*sizeof(char));
                memcpy(func_name, &line[start_idx], i - start_idx);
                func_name[i - start_idx] = '\0';
                // Call the function with arguments
                int num_args = 1;
                for(int j = i + 1; j < length; j++) {
                    if(line[j] == '(') num_args++;
                    else if(line[j] == ')') num_args--;
                    if(num_args == 0) break;
                }
                // Add more code to handle the function call and its arguments
                return func_name;
            }
        }
    }

    free(stack);
    return NULL;
}

