char* replace_substrings(char** str, char** format_str) {
    char* result = NULL;
    size_t len = strlen(*str);
    size_t format_len = strlen(*format_str);

    for (size_t i = 0; i < len; i++) {
        if (strncmp((*str) + i, *format_str, format_len) == 0) {
            size_t new_len = len - i + format_len;
            result = (char*) realloc(result, sizeof(char) * (new_len + 1));
            memcpy(result, (*str), i);
            strcat(result, *format_str);
            len = new_len;
        }
    }

    if (!result) {
        result = strdup(*str);
    } else {
        size_t new_len = len + 1;
        char* temp = (char*) malloc(sizeof(char) * new_len);
        strcpy(temp, result);
        free(result);
        result = temp;
    }

    return result;
}
