```c
struct pollfd* allocate_pollset(int initial_size) {
    int *sizes = (int*)malloc(sizeof(int));
    *sizes = initial_size;
    struct pollfd *pollset = (struct pollfd*)malloc(initial_size * sizeof(struct pollfd));

    return pollset;
}

void deallocate_pollset(struct pollfd* pollset, int size) {
    free(pollset);
}

int double_and_reallocate(int *size, int new_size, struct pollfd** pollset) {
    if (new_size > *size) {
        *pollset = (struct pollfd*)realloc(*pollset, new_size * sizeof(struct pollfd));
        *size = new_size;
        return 1; // Successfully reallocated
    }
    return 0; // No need to reallocate
}

void free_pollset(struct pollfd* pollset, int size) {
    if (size > 0) {
        deallocate_pollset(pollset, size);
    }
}

int main() {
    int initial_size = 2;
    struct pollfd *pollset = allocate_pollset(initial_size);

    int current_size = initial_size;
    while (1) {
        // Use the pollset...

        if (double_and_reallocate(&current_size, current_size * 2, &pollset)) {
            printf("Poll set doubled!\n");
        }
        else {
            printf("No need to reallocate.\n");
        }

        if (current_size > initial_size) {
            free_pollset(pollset, initial_size);
        }
    }

    return 0;
}
