int is_rotation(char *str1, char *str2) {
    int len = strlen(str1);
    if (len != strlen(str2)) return 0;
    char *str2_copy = malloc(len + 1);
    strcpy(str2_copy, str2);
    int i;
    for (i = 0; i < len; i++) {
        if (strcmp(str1 + i, str2_copy) == 0)
            break;
        str2_copy++;
        free(str2_copy - len);
        strcpy(str2_copy, str2);
    }
    if (i != len) return 1;
    free(str2_copy);
    return 0;
}

