    switch (dtype) {
        case 0:
            fwrite(addr, sizes[dtype], size / sizes[dtype], fp);
            break;
        default:
            for (int i = 0; i < size / sizes[dtype]; i++) {
                fprintf(fp, "%s%x\n", names[dtype], *(uint8_t *)((char*)addr + i * sizes[dtype]));
            }
            break;
    }

    fclose(fp);

    return buf;
}
