    for (i = 0; i < strlen(hostname); i++) {
        if (hostname[i] >= 'A' && hostname[i] <= 'Z') {
            hostname[i] += ('a' - 'A');
        }
    }

    // Resolve the hostname
    struct in_addr ip;
    struct hostent *hostinfo = gethostbyname(hostname);
    if (!hostinfo) {
        printf("Error: %s not found.\n", hostname);
        return 1;
    }

    // Convert IP address to octal and print it
    for (i = 0; i < sizeof(ip.s_addr); i++) {
        char c = (char)((ip.s_addr >> (24 - i * 8)) & 0xFF);
        if (c > '9' && c < 'A') {
            c -= 7;
        }
        printf("%c", c);
    }

    return 0;
}

