```c
#include <stdio.h>
#include <stdlib.h>

#define LINE_BUF_SIZE 1024

typedef struct {
    char *buf;
    size_t cap;
    size_t pos;
} LineBuffer;

LineBuffer* newLineBuffer() {
    LineBuffer* lb = (LineBuffer*)malloc(sizeof(LineBuffer));
    lb->buf = (char*)malloc(LINE_BUF_SIZE);
    lb->cap = LINE_BUF_SIZE;
    lb->pos = 0;
    return lb;
}

void freeLineBuffer(LineBuffer* lb) {
    free(lb->buf);
    free(lb);
}

int pushBackLine(LineBuffer* lb, FILE* file) {
    size_t bytesRead;
    fseek(file, -lb->cap, SEEK_CUR);
    bytesRead = fread(lb->buf, 1, lb->cap, file);
    if (bytesRead < lb->cap) {
        lb->pos -= bytesRead;
        return bytesRead;
    }
    return lb->cap;
}

int readLine(LineBuffer* lb, FILE* file, char** line) {
    size_t bytesRead;

    while (lb->pos == lb->cap) {
        if ((bytesRead = pushBackLine(lb, file)) <= 0) {
            *line = NULL;
            return 1; // end of file
        }
    }

    *line = malloc(bytesRead + 1);
    memcpy(*line, lb->buf, bytesRead);
    (*line)[bytesRead] = '\0';

    fseek(file, ftell(file) - bytesRead, SEEK_SET);

    return 0;
}

void freeLine(LineBuffer* lb, char* line) {
    free(line);
}

