    int size = 3; // Verb, path, and HTTP version
    char** request = (char**)malloc(size * sizeof(char*));
    for(int i = 0; i < size; i++) {
        if(i == 0) {
            request[i] = malloc(strlen(verb) + 1);
            strcpy(request[i], verb);
        }
        else if(i == 1) {
            request[i] = malloc(strlen(path) + 1);
            strcpy(request[i], path);
