```c
#include <openssl/aes.h>
#include <openssl/sha.h>

void* aes_init(const unsigned char* password, size_t password_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Set the IV length to 16 bytes (128 bits)
    unsigned char iv[16];
    memset(iv, 0, sizeof(iv));
    EVP_CIPHER_CTX_iv_length(ctx) = 16;
    EVP_CIPHER_CTX_set_padding(ctx, 1);

    // Set the key length to 32 bytes (256 bits)
    unsigned char key[EVP_MAX_KEY_LENGTH];
    SHA_CTX sha_ctx;
    SHA_Init(&sha_ctx);
    SHA_Update(&sha_ctx, password, password_len);
    SHA_Final(&sha_ctx, key);
    EVP_CIPHER_CTX_set_key_length(ctx, sizeof(key));

    // Enable the cipher
    int err = EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv, 1);
    if (err != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void aes_cleanup(void* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
