#include <omp.h>
#include <stdio.h>
#include <stdlib.h>

int** createMatrix(int* arr, int rows, int cols) {
    int size = sizeof(int*) * rows;
    int** matrix = (int**)malloc(size);
    for (int i = 0; i < rows; i++) {
        size = sizeof(int) * cols;
        matrix[i] = (int*)malloc(size);
    }

    #pragma omp parallel
    {
        int row = omp_get_thread_num();
        int start = row * cols;
        int end = (row + 1) * cols;

        for (int i = start; i < end && i < cols; i++) {
            for (int j = 0; j < rows; j++) {
                matrix[j][i] = arr[i * rows + j];
            }
        }
    }

    return matrix;
}
