void* generate_dns_response(void* buffer, int num_services) {
    uint16_t* buffer_ptr = (uint16_t*)buffer;
    struct dns_header* header = (struct dns_header*)(buffer);
    header->id = 0x1234; // Assign a random ID
    header->flags = 0x0100; // Set the flags to indicate this is a response message

    for(int i=0; i<num_services; i++) {
        struct resource_record* record = (struct resource_record*)(buffer_ptr + sizeof(struct dns_header) + i*sizeof(struct resource_record));
        char service_name[] = "SERVICE_NAME"; // Replace with actual service name
        int service_name_len = strlen(service_name);

        *record = 0;
        record->type = htons(_PTR); // Set the type to PTR
        record->class = htons(IN); // Set the class to IN (Internet)
        record->ttl = htonl((int)(4*60)); // Set the TTL in seconds, converted to network byte order
        strcpy((char*)record->data, service_name);
        *record->data_len = htons(service_name_len);

        buffer_ptr += sizeof(struct resource_record) + service_name_len;
    }

    return buffer;
}
