char* concatenatePathAndFileName(const char* dirPath, const char* fileName) {
    if (!dirPath || !fileName) {
        return NULL;
    }

    size_t dirLength = strlen(dirPath);
    size_t fileNameLength = strlen(fileName);

    // Check if the file name is not provided
    if (fileNameLength == 0) {
        return NULL;
    }

    char* filePath = malloc((dirLength + fileNameLength + 1) * sizeof(char));
    if (!filePath) {
        return NULL;
    }

    strcpy(filePath, dirPath);
    strcat(filePath, "/");
    strcat(filePath, fileName);

    // Handle cases where the file is removed or renamed
    struct stat sb;
    if (stat(filePath, &sb) == -1) {
        free(filePath);
        return NULL;
    }

    return filePath;
}

