#include <openssl/evp.h>
#include <string.h>

unsigned char* md4_hash(const char* input, int length) {
    unsigned char hash[16];
    unsigned char* output = (unsigned char*)malloc(16);
    EVP_MD_CTX mdctx;
    EVP_MD *md;
    unsigned char *d;
    size_t len;

    /* Create the MD4 context */
    if (!EVP_MD_CTX_create(&mdctx))
        return NULL;

    /* Set the MD4 algorithm */
    if (!(md = EVP_get_md(EVP_md4())))
        goto err;

    /* Add the input string to the MD4 context */
    if (1 != EVP_DigestInit_ex(&mdctx, md, NULL))
        goto err;
    if (!EVP_DigestUpdate(&mdctx, input, length))
        goto err;

    /* Get the hash value from the MD4 context */
    if (!EVP_DigestFinal_ex(&mdctx, output, &len))
        goto err;

    EVP_MD_CTX_destroy(&mdctx);
    free(output);
    return output;
err:
    free(output);
    return NULL;
}
