#include <numpy/ndarrayobject.h>
#include <numpy/numpy_configtemplate.h>

static void* my_udf(void *op) {
    PyArrayObject* arr = (PyArrayObject*) op;
    int axis = *(int*)PyArray_GetScalarVal(arr, 0);

    if(axis<0 || axis>=arr->nd){
        return NULL;  // out of bounds
    }

    npy_intp dims[arr->nd];
    for(int i=0; i<arr->nd; i++){
        dims[i] = (npy_intp)PyArray_GetShape(arr)[i];
    }

    if(axis == arr->nd-1){
        PyArrayObject* result = (PyArrayObject*)PyArray_Newshape(arr, dims, 1);
        return result;
    }

    npy_intp new_dims[arr->nd - 1];
    for(int i=0; i<axis; i++){
        new_dims[i] = dims[i];
    }
    new_dims[axis] += dims[axis+1];
    for(int i=axis + 1; i<arr->nd-1; i++){
        new_dims[i] = dims[i+1];
    }

    PyArrayObject* result = (PyArrayObject*)PyArray_Newshape(arr, new_dims, 1);
    return result;
}
