int countFilesInTreeFormat(const char *dirPath, const char *format) {
    int count = 0;
    DIR *dir = opendir(dirPath);
    if (dir == NULL) return 0;

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char filePath[PATH_MAX];
        snprintf(filePath, sizeof(filePath), "%s/%s", dirPath, ent->d_name);

        DIR *subDir = opendir(filePath);
        if (subDir != NULL) {
            count += countFilesInTreeFormat(filePath, format);
            closedir(subDir);
        } else {
            FILE *file = fopen(filePath, "r");
            if (file != NULL) {
                char line[1024];
                while (fgets(line, sizeof(line), file)) {
                    if (strstr(line, format) != NULL)
                        count++;
                }
                fclose(file);
            }
        }
    }

    closedir(dir);
    return count;
}

