struct dir_entry {
    char* name;
    struct dir_entry* parent;
};

char* resolve_path(const char* path) {
    static char current_dir[1024];
    strcpy(current_dir, ".");

    if (path[0] == '/') {
        strcpy(current_dir, path);
    } else {
        strcat(current_dir, "/");
        strcat(current_dir, path);
    }

    return current_dir;
}

struct dir_entry* traverse_directory(const char* root, const char* path) {
    struct dir_entry* current = NULL;
    char* resolved_path = resolve_path(path);

    struct dir_entry** table = (struct dir_entry**)malloc(1024 * sizeof(struct dir_entry*));
    int size = 0;

    void (*visit)(const char*, struct dir_entry*) = NULL;

    visit_directory(root, path, &current, &table, &size, visit);

    free(table);

    return current;
}

void visit_directory(const char* dir_path, const char* path, struct dir_entry** current_dir, struct dir_entry*** table, int* size, void (*visit)(const char*, struct dir_entry*)) {
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir(dir_path)) == NULL) {
        return;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char* dir_entry_path = malloc(strlen(path) + strlen(ent->d_name) + 2);
        strcpy(dir_entry_path, path);
        strcat(dir_entry_path, "/");
        strcat(dir_entry_path, ent->d_name);

        if (ent->d_type == DT_DIR) {
            struct dir_entry* new_dir = (*table)[(*size)++];
            new_dir->name = malloc(strlen(dir_entry_path));
            strcpy(new_dir->name, dir_entry_path);
            new_dir->parent = *current_dir;

            visit(dir_entry_path, new_dir);
        } else if (ent->d_type == DT_REG) {
            // Handle regular file
        }

        free(dir_entry_path);

        closedir(dir);
    }
}

