int parse_buffer(char *buffer, struct filename_info *info) {
    char *start = buffer;
    char *end = buffer;
    while (*end != '\0') {
        if (*end == '\n' || *end == '\r') {
            end++;
            if (strlen(start) > 64) continue;
            info->name = start;
            info->length = strlen(info->name);
            start = end;
        } else {
            end++;
        }
    }
    return 1; // successful parse
