#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

int *socket_setup(int protocol, const char *path, const char *name) {
    int sockfd;
    struct sockaddr_un addr;

    // Create socket
    sockfd = socket(AF_UNIX, SOCK_STREAM, protocol);
    if (sockfd == -1) {
        return NULL;
    }

    // Set up address structure
    addr.sun_family = AF_UNIX;
    strcpy(addr.sun_path, path);
    unlink(path);  // Make sure the socket doesn't already exist
    addr.sun_len = sizeof(addr);

    // Bind to the Unix domain socket
    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        close(sockfd);
        return NULL;
    }

    // Listen for incoming connections
    if (listen(sockfd, 3) == -1) {
        close(sockfd);
        return NULL;
    }

    // Set up timeout for sending and receiving data
    int opt = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, &opt, sizeof(opt));
    setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &opt, sizeof(opt));

    // Accept incoming connection
    int connfd = accept(sockfd, NULL, NULL);
    if (connfd == -1) {
        close(sockfd);
        return NULL;
    }

    // Return the connected socket
    return &connfd;
}

