#include <openssl/evp.h>
#include <string.h>

EVP_MD_CTX* generateKey(char* password) {
    EVP_MD_CTX* ctx;
    unsigned char md[EVP_MAX_MD_SIZE];
    int len = strlen(password);
    unsigned char* pass = (unsigned char*)malloc(len+1);
    memcpy(pass, password, len);
    pass[len] = '\0';

    ctx = EVP_MD_CTX_new();
    if (!EVP_DigestInit_ex(ctx, EVP_md5(), NULL)) {
        OPENSSL_free(pass);
        return NULL;
    }
    EVP_DigestUpdate(ctx, pass, strlen(password));
    EVP_DigestFinal(ctx, md, &len);
    OPENSSL_free(pass);

    const EVP_MD* md_type = EVP_md5();
    unsigned char key[EVP_MAX_KEY_LENGTH];
    int key_len = 0;

    if (!EVP_BytesToKey(md_type, NULL, md, len, pass, len, 1, key, &key_len)) {
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    EVP_MD_CTX_free(ctx);
    return (EVP_MD_CTX*)malloc(sizeof(EVP_MD_CTX));
}

