int init_and_reset_adapter(int dev_fd) {
    // Clear link configuration flags
    ioctl(dev_fd, SIOCGIFLINK, NULL);

    // Reset SFP initialization
    struct ifreq ifr;
    strcpy(ifr.ifr_name, "sfp0");
    ioctl(dev_fd, SIOCIFGETSFP, &ifr);
    memset(&ifr, 0, sizeof(struct ifreq));
    ioctl(dev_fd, SIOCIFSETSFP, &ifr);

    // Configure adapter for use
    struct ifreq ifr2;
    strcpy(ifr2.ifr_name, "eth0");
    ioctl(dev_fd, SIOCSIFFLAGS, &ifr2);
    ioctl(dev_fd, SIOCDIFADDR, NULL);
    ioctl(dev_fd, SIOCGIFMTU, NULL);

    return 0;
}
