#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define WARNING_MESSAGE "Warning: Response code is not 2xx.\n"
#define ERROR_COUNTER_MUTEX_NAME "ErrorCounterMutex"
#define MAX_RESPONSE_CODE_LENGTH 10

int error_counter = 0;
pthread_mutex_t error_counter_mutex;

void *parse_response_and_check_code(void *response) {
    char response_code[MAX_RESPONSE_CODE_LENGTH];
    // assume the following function parses the HTTP response
    // and extracts the response code into response_code
    parse_http_response((char *)response, response_code);

    pthread_mutex_lock(&error_counter_mutex);

    if(strncmp(response_code, "2", 1) != 0) {
        error_counter++;
        printf(WARNING_MESSAGE);
    }

    pthread_mutex_unlock(&error_counter_mutex);
    return NULL;
}

void init_error_counter_mutex() {
    int err = pthread_mutex_init(&error_counter_mutex, NULL);
    if(err) {
        fprintf(stderr, "Error initializing mutex: %s\n", strerror(err));
        exit(EXIT_FAILURE);
    }
}
```

Here's a brief explanation of how this code works:

1. The `parse_response_and_check_code` function takes a pointer to the HTTP response as an argument.
2. It calls `parse_http_response` (which is not implemented here) to extract the response code from the HTTP response and stores it in the `response_code` variable.
3. It then checks if the response code starts with "2". If it does, it doesn't do anything. If it doesn't, it increments an error counter and prints a warning message to the console.
4. To ensure thread-safety, it uses a mutex to lock and unlock access to the `error_counter` variable.
5. The `init_error_counter_mutex` function is used to initialize the mutex before the program starts parsing responses.

Please note that you will need to implement your own `parse_http_response` function to parse the HTTP response and extract the response code.

