void *create_huge_page_file(void *addr) {
    int pid = getpid();
    char file_name[20];
    sprintf(file_name, "/huge_page_file_%d", pid);

    int fd = open(file_name, O_RDWR | O_CREAT | O_TMPFILE, 0644);
    if (fd < 0) return (void *)-1;

    void *mmap_addr = mmap(addr, sysconf(_SC_PAGESIZE), PROT_READ | PROT_WRITE,
                            MAP_SHARED | MAP_NORESERVE, fd, 0);
    if (mmap_addr == MAP_FAILED) {
        close(fd);
        return (void *)-1;
    }

    unlink(file_name);
    close(fd);

    return mmap_addr;
}

