void *process_string(const char *str, int cmd) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[16], iv[16];
    unsigned int len;
    void *cipher;

    switch (cmd) {
        case 1: // Encrypt
            ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
            cipher = EVP_CIPHER_CTX_get_cipher_ctx(ctx);
            break;
        case 2: // Decrypt
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
            cipher = EVP_CIPHER_CTX_get_cipher_ctx(ctx);
            break;
        default:
            return NULL;
    }

    EVP_CipherUpdate(ctx, &len, str);

    return cipher;
}
