int log_error(const char *format, ...) {
    va_list ap;
    va_start(ap, format);
    int len = vsnprintf(NULL, 0, format, ap);
    va_end(ap);

    if (len > 0) {
        va_start(ap, format);
        char *buffer = malloc(len + 1);
        vsnprintf(buffer, len + 1, format, ap);
        buffer[len] = '\0';
        fprintf(stderr, "%s\n", buffer);
        free(buffer);
        va_end(ap);
    }
    return 0;
}

