```
void traverseDir(const char *dirPath, int depth, void (*callback)(const char *, int)) {
    DIR *dp = opendir(dirPath);
    if (dp == NULL) return;

    struct dirent *ent;
    while ((ent = readdir(dp))) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
        char path[PATH_MAX];
        snprintf(path, PATH_MAX, "%s/%s", dirPath, ent->d_name);

        callback(path, depth);
        struct stat sb;
        if (stat(path, &sb) == -1) continue;

        if (S_ISDIR(sb.st_mode)) {
            traverseDir(path, depth + 1, callback);
        }
    }
    closedir(dp);
}

