#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    FILE *input = fopen(argv[1], "rb");
    if (!input) {
        fprintf(stderr, "Error opening input file %s\n", argv[1]);
        return 1;
    }

    FILE *output = fopen(argv[2], "wb");
    if (!output) {
        fprintf(stderr, "Error opening output file %s\n", argv[2]);
        fclose(input);
        return 1;
    }

    char *rules = argv[3];
    size_t rules_len = strlen(rules);

    // Read the input file
    unsigned char buffer[4096];
    while (fread(buffer, 1, sizeof(buffer), input) > 0) {
        // Parse the contents of the input file based on the given rules
        for (size_t i = 0; i < rules_len; i++) {
            if (buffer[i % sizeof(buffer)] == rules[i]) {
                fwrite(&buffer[i % sizeof(buffer)], 1, 1, output);
            }
        }
    }

    fclose(input);
    fclose(output);

    return 0;
}

