```
int send_ethernet_packet(unsigned short type, unsigned char* data, unsigned short dlen) {
    // Create Ethernet header
    unsigned char ether_header[14];
    ether_header[0] = 0xFF; // Destination MAC
    ether_header[1] = 0xFF;
    ether_header[2] = 0xFF;
    ether_header[3] = 0xFF;
    ether_header[4] = 0xFF;
    ether_header[5] = 0xFF;
    ether_header[6] = 0xFE; // Source MAC
    ether_header[7] = 0xFE;
    ether_header[8] = 0xDC;
    ether_header[9] = 0xDC;
    ether_header[10] = 0xB9;
    ether_header[11] = 0xB9;
    ether_header[12] = type >> 8; // Type
    ether_header[13] = type & 0xFF;

    // Pad data with zeros to a maximum size of 18 bytes
    unsigned char padded_data[18];
    memcpy(padded_data, data, dlen);
    memset(&padded_data[dlen], 0, 18 - dlen);

    // Create IP header
    unsigned char ip_header[20];
    ip_header[0] = 0x45; // Version and Header Length
    ip_header[1] = 0x00;
    ip_header[2] = 0x00;
    ip_header[3] = 0x01; // DSCP and ECN
    ip_header[4] = 0x08; // Total Length
    ip_header[5] = 0x00;
    ip_header[6] = 0x00;
    ip_header[7] = 0x40; // Identification
    ip_header[8] = 0x00;
    ip_header[9] = 0x00;
    ip_header[10] = 0x11; // Flags and Fragment Offset
    ip_header[11] = 0xEC;
    ip_header[12] = 0x04; // TTL
    ip_header[13] = 0x02; // Protocol
    ip_header[14] = 0x00; // Header Checksum
    ip_header[15] = 0x00;
    ip_header[16] = 0x50; // Source IP
    ip_header[17] = 0x4B;
    ip_header[18] = 0x41;
    ip_header[19] = 0x3C;

    // Send packet
    sendpacket(ether_header, padded_data, 20 + 18);

    return 0;
}
