size_t insert_string(const char* str, size_t pos, const char* sub) {
    size_t len = strlen(str);
    size_t sub_len = strlen(sub);
    size_t new_len = len + sub_len;

    if (pos > len) {
        return -1; // position out of bounds
    }

    char* new_str = malloc((new_len + 1) * sizeof(char));
    if (!new_str) {
        return -1; // memory allocation failed
    }

    strncpy(new_str, str, pos);
    strcpy(new_str + pos, sub);
    strncpy(new_str + pos + sub_len, str + pos, len - pos);
    new_str[new_len] = '\0';

    free(str);
    return new_len;
}
