#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int x;
    int y;
    int lifetime;
    struct blob *next;
} Blob;

Blob *create_blob(int x, int y, int lifetime) {
    Blob *new_blob = (Blob *)malloc(sizeof(Blob));
    new_blob->x = x;
    new_blob->y = y;
    new_blob->lifetime = lifetime;
    new_blob->next = NULL;
    return new_blob;
}

void update_blobs(Blob **head, int grid_size) {
    Blob *current = *head;
    while (current != NULL) {
        if (current->lifetime > 0) {
            current->lifetime--;
            if (current->lifetime == 0) {
                *head = remove_blob(head, current);
            }
        } else {
            int new_x = rand() % grid_size;
            int new_y = rand() % grid_size;
            current->x = new_x;
            current->y = new_y;
            current->lifetime = rand() % 10 + 1; // 1-10
        }
        current = current->next;
    }
}

Blob *remove_blob(Blob **head, Blob *node) {
    if (*head == node) {
        *head = node->next;
    } else {
        Blob *current = *head;
        while (current->next != node) {
            current = current->next;
        }
        current->next = node->next;
    }
    free(node);
    return *head;
}

void print_blobs(Blob *head, int grid_size) {
    Blob *current = head;
    while (current != NULL) {
        printf("(%d, %d)\n", current->x, current->y);
        current = current->next;
    }
}
