char* signedIntegerToString(char* str) {
    int len = strlen(str);
    char* result = malloc(len + 3); // 1 for sign, 1 for space, max of (len * 2) for digits and leading zeros
    if (str[0] == '-') {
        strcpy(result, "- ");
        len -= 1;
    } else if (*str == '+') {
        strcpy(result, "+ ");
        len -= 1;
    } else {
        strcpy(result, "   ");
    }
    sprintf(result + (strchr(" -+", str) ? 2 : 1), "%s%02d", str[0] ? "" : "", atoi(str));
    return result;
}
