#include <cuda_runtime.h>
#include <cublas_v2.h>

// Allocate matrix A on device
void initMatrixA(float **d_A, int m, int k) {
    cudaMalloc((void**)&d_A, m*k*sizeof(float));
    curandGenerator_t generator;
    curandCreateGenerator(&generator, CURAND_RNG_PSEUDO_DEFAULT);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < k; j++) {
            float val = curand_uniform(generator);
            ((float*)d_A)[i*k+j] = val;
        }
    }
    curandDestroyGenerator(generator);
}

// Allocate matrix B on device
void initMatrixB(float **d_B, int k, int n) {
    cudaMalloc((void**)&d_B, k*n*sizeof(float));
    for (int i = 0; i < k; i++) {
        for (int j = 0; j < n; j++) {
            ((float*)d_B)[i*n+j] = (float)(rand() / (double)RAND_MAX);
        }
    }
}

// Perform matrix multiplication using CUDA BLAS
void multiplyMatrices(float **d_A, int m, int k, float **d_B, int k, int n, float **d_C) {
    cublasHandle_t handle;
    cublasCreate(&handle);

    // Matrix multiplication
    cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k,
        1.0f, d_A, m, d_B, k,
        0.0f, d_C, m);

    cublasDestroy(handle);
}

// Free memory allocated by CUDA BLAS
void freeMatrices(float **d_A, int m, float **d_B, int k) {
    cudaFree(d_A);
    cudaFree(d_B);
}

int main() {
    int m = 1000;
    int k = 500;
    int n = 200;

    // Allocate matrix A on host
    float *h_A = new float[m*k];

    // Initialize matrix A on device
    float *d_A;
    initMatrixA(&d_A, m, k);

    // Allocate matrix B on host
    float *h_B = new float[k*n];

    // Initialize matrix B on device
    float *d_B;
    initMatrixB(&d_B, k, n);

    // Perform matrix multiplication using CUDA BLAS
    float *d_C;
    multiplyMatrices(&d_A, m, k, &d_B, k, n, &d_C);

    // Allocate result on host
    float *h_C = new float[m*n];

    // Copy result from device to host
    cudaMemcpy(h_C, d_C, m*n*sizeof(float), cudaMemcpyDeviceToHost);

    // Free memory allocated by CUDA BLAS
    freeMatrices(&d_A, m, &d_B, k);

    // Print result on host
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            printf("%f ", h_C[i*n+j]);
        }
        printf("\n");
    }

    return 0;
}
