char* add_parity_level(const char* path) {
    nvmlHandle_t handle;
    int result = nvmlInit(&handle);
    if (result != NVML_SUCCESS) {
        return strdup(path); // Return original path on error
    }

    uint64_t parity;
    char* device_path = strdup(path);
    char* raidz_config = malloc(strlen(device_path) + 16);
    strcpy(raidz_config, "nvlist_lookup_uint64(nvml_get_nvlist(handle), \"parity_level\", &parity);");
    // Do some magic here to get the actual parity level
    free(raidz_config);

    if (strlen(path) > 5 && strcmp(path + strlen(path) - 6, "/diskX") == 0) {
        sprintf(device_path + strlen(path), "_%llu", parity);
    }

    nvmlShutdown(handle);
    return device_path;
}

