#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} Vertex;

typedef struct {
    Vertex* vertices;
    int num_vertices;
} Graph;

void create_graph(Graph* graph) {
    printf("Enter the number of vertices: ");
    scanf("%d", &graph->num_vertices);
    graph->vertices = (Vertex*)malloc(graph->num_vertices * sizeof(Vertex));
    for (int i = 0; i < graph->num_vertices; i++) {
        graph->vertices[i].value = i;
    }
}

void display_graph(Graph* graph) {
    printf("Directed Graph:\n");
    for (int i = 0; i < graph->num_vertices; i++) {
        printf("%d ->", graph->vertices[i].value);
        for (int j = 0; j < graph->num_vertices; j++) {
            if (i != j) {
                printf(" %d", j);
            }
        }
        printf("\n");
    }
}

void modify_vertex(Graph* graph) {
    int vertex;
    printf("Enter the vertex to modify: ");
    scanf("%d", &vertex);
    if (vertex < 0 || vertex >= graph->num_vertices) {
        printf("Invalid vertex. Try again.\n");
        return;
    }
    printf("New value for vertex %d: ", vertex);
    int new_value;
    scanf("%d", &new_value);
    graph->vertices[vertex].value = new_value;
}

void insert_vertex(Graph* graph) {
    int num_edges;
    printf("Enter the number of edges for the new vertex: ");
    scanf("%d", &num_edges);
    Vertex* new_vertices = (Vertex*)malloc((graph->num_vertices + 1) * sizeof(Vertex));
    for (int i = 0; i < graph->num_vertices; i++) {
        new_vertices[i] = graph->vertices[i];
    }
    new_vertices[graph->num_vertices].value = graph->num_vertices;
    graph->num_vertices++;
    for (int i = 0; i <= graph->num_vertices; i++) {
        if (i < graph->num_vertices) {
            printf("%d ->", i);
            for (int j = 0; j < num_edges; j++) {
                int edge;
                printf(" %d", new_vertices[graph->num_vertices].value + j);
            }
            printf("\n");
        } else {
            printf("%d ->", graph->num_vertices);
            for (int j = 0; j < num_edges; j++) {
                int edge;
                printf(" %d", j);
            }
            printf("\n");
        }
    }
}

void free_graph(Graph* graph) {
    free(graph->vertices);
}
