```
int evp_cipher_process(EVP_CIPHER_CTX *ctx, unsigned char *key, unsigned char *data, int len) {
    unsigned char buffer[ctx->cipher->block_size];
    int block_len = ctx->cipher->block_size;
    int remaining = len;
    int out_len = 0;

    while (remaining > 0 || block_len > 0) {
        int bytes_to_read = (remaining < block_len) ? remaining : block_len;
        EVP_CipherUpdate(ctx, buffer, &bytes_to_read);
        memcpy(data + out_len, buffer, bytes_to_read);
        out_len += bytes_to_read;
        remaining -= bytes_to_read;
    }

    if (len > 0) {
        EVP_CipherFinal(ctx, data + out_len, &out_len);
        out_len += len - remaining;
    }

    return out_len;
}
