#include <stdlib.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        printf("Usage: %s <context> <command_path>\n", argv[0]);
        return -1;
    }

    int context = atoi(argv[1]);
    const char *command_path = argv[2];

    pid_t pid = getpid();
    size_t len = strlen(command_path);

    if (setpgid(context, pid) != 0) {
        perror("setpgid");
        return -1;
    }

    struct ifreq ifr;
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    strcpy(ifr.ifr_name, "eth0"); // Replace with your network interface name
    ifr.ifr_addr.sa_family = AF_INET;
    memcpy(&ifr.ifr_addr.sa_data[4], &len, sizeof(size_t));
    memcpy(&ifr.ifr_addr.sa_data[8], command_path, len);

    if (setsockopt(sock, IFFRAME, IFR_ADDR, &ifr, sizeof(ifr)) < 0) {
        perror("setsockopt");
        return -1;
    }

    close(sock);
    return 0;
}

