int lookup_hash(const char* key, reader_t read_func, iterator_t iter) {
    hash_node_t* node = NULL;
    int collisions = 0;

    while (iter(&node)) {
        if (!strcmp(key, node->key)) {
            if (node->value->active) {
                char value_str[1024];
                sprintf(value_str, "%s", read_func(node->value));
                return collisions;
            } else {
                return -1; // key found but not active
            }
        } else {
            collisions++;
        }
    }

    return -2; // key not found
}
