typedef struct {
    void* data;
    int size;
} AllocStruct;

AllocStruct* allocateBlocks(int TOTAL_ALLOCS, int MIN_ALLOC_SIZE, int MAX_ALLOC_SIZE) {
    srand(time(NULL));
    AllocStruct* allocs = (AllocStruct*)malloc(TOTAL_ALLOCS * sizeof(AllocStruct));
    if (!allocs) return NULL; // Allocation failed

    int totalSize = 0;
    for (int i = 0; i < TOTAL_ALLOCS; i++) {
        int size = rand() % (MAX_ALLOC_SIZE - MIN_ALLOC_SIZE + 1) + MIN_ALLOC_SIZE;
        void* data = malloc(size);
        if (!data) return NULL; // Allocation failed

        allocs[i].data = data;
        allocs[i].size = size;
        totalSize += size;
    }

    int* totalMemoryAllocated = (int*)malloc(sizeof(int));
    *totalMemoryAllocated = totalSize;

    int* numStructuresAllocated = (int*)malloc(sizeof(int));
    *numStructuresAllocated = TOTAL_ALLOCS;

    return allocs;
}
