#include <rte_ioat.h>
#include <rte_malloc.h>

int mem_copy(int dev_id, void *src_addr, void *dst_addr, uint32_t len) {
    int ret;
    struct rte_ioat_queue_entry entry;

    // Allocate memory buffers using a pool
    void *src_pool = rte_malloc(NULL, len, 0);
    void *dst_pool = rte_malloc(NULL, len, 0);

    // Fill the source buffer with random data
    unsigned char *src_data = src_addr;
    for (uint32_t i = 0; i < len; i++) {
        src_data[i] = rand() % 256;
    }

    // Enqueue a copy operation from the source buffer to the destination buffer
    ret = rte_ioat_enqueue_copy(dev_id, &entry, RTE_IOAT_OP_FROM_TO,
            src_addr, dst_addr, len);

    if (ret < 0) {
        printf("Enqueue copy failed: %d\n", ret);
    }

    // Free allocated memory buffers
    rte_free(src_pool);
    rte_free(dst_pool);

    return ret;
}

