void block_based_encryption(const uint8_t *test_vector, const uint8_t *key_schedule, size_t test_vector_length) {
    AES_KEY aes_key;
    AES_set_encrypt_key(key_schedule, 16, &aes_key);

    for (size_t i = 0; i < test_vector_length; i += AES_BLOCK_SIZE) {
        uint8_t block[AES_BLOCK_SIZE];
        memcpy(block, test_vector + i, AES_BLOCK_SIZE);

        uint8_t iv[AES_BLOCK_SIZE] = {0};
        uint64_t counter = i;

        for (size_t j = 0; j < AES_BLOCK_SIZE; j += sizeof(uint64_t)) {
            *(uint64_t*)&iv[j] = counter++;
        }

        AES_crypt_ctr(&aes_key, iv, block);

        memcpy(test_vector + i, block, AES_BLOCK_SIZE);
    }
}
