int
iso9660_read_path_table(struct iso9660_volume_descriptor *vd)
{
    struct iso9660_path_table_header *pth;
    size_t size;

    pth = (struct iso9660_path_table_header *)sysmalloc(sizeof(*pth), 1);
    if (!pth) return ENOMEM; // allocation failed

    size = vd->size - offsetof(struct iso9660_volume_descriptor, path_table);
    if (size < sizeof(*pth)) return EINVAL; // invalid volume descriptor

    memcpy(pth, &vd->path_table, size);

    return pth->record_count;
}

