import hashlib
import os

def set_key(key):
    key = hashlib.sha256(key.encode()).digest()
    return key[:16]

def block_cipher_ecb(block_size, rounds, key, message):
    encrypted_message = bytearray()
    for i in range(0, len(message), block_size):
        block = message[i:i+block_size]
        cipher_block = bytearray(rounds)
        for j in range(len(cipher_block)):
            cipher_block[j] = ord(block[(j)%len(block)])
            cipher_block[j] = ord(chr((cipher_block[j].bytecode ^ key[(j)%16])))
        encrypted_message.extend(cipher_block)
    return bytes(encrypted_message)

def block_cipher_cbc(block_size, rounds, key, message):
    encrypted_message = bytearray()
    iv = os.urandom(block_size//8)
    for i in range(0, len(message), block_size):
        block = message[i:i+block_size]
        cipher_block = bytearray(rounds)
        for j in range(len(cipher_block)):
            cipher_block[j] = ord(block[(j)%len(block)])
            if i == 0:
                cipher_block[j] = ord(chr((cipher_block[j].bytecode ^ iv[j%block_size//8])))
            else:
                cipher_block[j] = ord(chr((cipher_block[j].bytecode ^ encrypted_message[i-1+j%block_size//8])))
        encrypted_message.extend(cipher_block)
    return bytes(encrypted_message)

def block_cipher_cfb64(block_size, rounds, key, message):
    encrypted_message = bytearray()
    iv = os.urandom(block_size//8)
    for i in range(0, len(message)):
        if i < block_size:
            ciphered_block = bytearray()
            for j in range(len(ciphered_block)):
                ciphered_block[j] = ord(chr((ciphered_block[j].bytecode ^ iv[j%block_size//8])))
            encrypted_message.extend(ciphered_block)
        else:
            block = message[i:i+block_size]
            cipher_block = bytearray(rounds)
            for j in range(len(cipher_block)):
                cipher_block[j] = ord(block[(j)%len(block)])
                cipher_block[j] = ord(chr((cipher_block[j].bytecode ^ encrypted_message[i-1+j%block_size//8])))
            encrypted_message.extend(cipher_block)
    return bytes(encrypt_message)

def encrypt(message, key, mode):
    if mode == 'ecb':
        return block_cipher_ecb(16, 10, key, message)
    elif mode == 'cbc':
        return block_cipher_cbc(16, 10, key, message)
    elif mode == 'cfb64':
        return block_cipher_cfb64(8, 10, key, message)

def decrypt(message, key, mode):
    if mode == 'ecb':
        return block_cipher_ecb(16, 10, key, message)
    elif mode == 'cbc':
        return block_cipher_cbc(16, 10, key, message)
    elif mode == 'cfb64':
        return block_cipher_cfb64(8, 10, key, message)

def main():
    key = set_key(input('Enter the key: '))
    message = input('Enter the message: ')
    mode = input('Enter the encryption/decryption mode (ecb, cbc or cfb64): ')

    if mode == 'ecb':
        print('Encrypted message:', encrypt(message.encode(), key, mode).decode())
    elif mode == 'cbc':
        print('Encrypted message:', encrypt(message.encode(), key, mode).decode())
    elif mode == 'cfb64':
        print('Encrypted message:', encrypt(message.encode(), key, mode).decode())

    if mode == 'ecb':
        print('Decrypted message:', decrypt(encrypt(message.encode(), key, mode), key, mode).decode())
    elif mode == 'cbc':
        print('Decrypted message:', decrypt(encrypt(message.encode(), key, mode), key, mode).decode())
    elif mode == 'cfb64':
        print('Decrypted message:', decrypt(encrypt(message.encode(), key, mode), key, mode).decode())

if __name__ == "__main__":
    main()
```

