#include <stdio.h>
#include <stdlib.h>
#include <time.h>

unsigned char *compress_dataset(const char *input_file_path) {
    FILE *file = fopen(input_file_path, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    unsigned char *buffer = (unsigned char *)malloc(file_size);
    fread(buffer, 1, file_size, file);
    fclose(file);

    int i;
    for(i=0; i < file_size; i++){
        buffer[i] = rand() & 0xFF;
    }

    // calculate the required size of compressed data
    long int required_size = (file_size / 8) + (file_size % 8 != 0);
    unsigned char *compressed_data = (unsigned char *)malloc(required_size);

    // compress the data
    for(i=0; i < file_size; i += 8){
        compressed_data[i/8] = buffer[i/8];
        buffer[i/8] &= ~((1 << ((i%8)+1)) - 1);
        buffer[i/8] |= (buffer[i/8+1] & (1 << (i%8)));
    }

    free(buffer);

    return compressed_data;
}

