char *find_block_driver(const char *filename) {
    struct stat sb;
    char buffer[1024];
    sprintf(buffer, "/sys/block/%s", filename);
    int fd = open(buffer, O_RDONLY);
    if (fd < 0)
        return NULL;
    if (fstat(fd, &sb) < 0) {
        close(fd);
        return NULL;
    }
    char *driver = alloca(sb.st_size + 1);
    read(fd, driver, sb.st_size);
    close(fd);
    return driver;
}
