```c
int exponentialBackoffWithJitter(mqtt_context* ctx) {
    static int attempts = 1;
    static int maxAttempts = 8; // Adjust this value as per your requirements
    static int baseDelay = 1000; // Initial delay in milliseconds
    static int maxDelay = 64000; // Maximum delay in milliseconds

    if (attempts > maxAttempts) {
        return -1; // Connection failed after maximum attempts
    }

    int delay = baseDelay * (1 << (attempts - 1)); // Calculate the exponential backoff value
    int jitter = rand() % ((int)(delay / 4)); // Add a random jitter component

    delay += jitter;

    if (delay > maxDelay) {
        delay = maxDelay;
    }

    usleep(delay * 1000); // Sleep for the calculated delay

    // Make another attempt to establish the MQTT connection
    int status = mqtt_connect(ctx);

    if (status == 0) { // Connection successful, reset attempts and base delay
        attempts = 1;
        baseDelay = 1000; // Reset the initial delay value
    } else {
        attempts++; // Increment the attempt counter
    }

    return status;
}

