#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rsa.h>
#include <openssl/x509.h>
#include <json-c/json.h>

#define MAX_TOKEN_LENGTH 2048

void get_token(char* json_str, char* secret_key, char** token) {
    // Initialize OpenSSL
    RSA *rsa = NULL;
    X509 *x509 = NULL;

    // Load the private key from PEM file
    FILE *keyfile = fopen(secret_key, "rb");
    if (!keyfile) {
        printf("Error opening private key file.\n");
        return;
    }

    PEM_read_RSAPrivateKey(keyfile, &rsa, NULL, NULL);
    fclose(keyfile);

    // Load the public certificate from PEM file
    FILE *certfile = fopen(secret_key, "rb");
    if (!certfile) {
        printf("Error opening public certificate file.\n");
        return;
    }

    PEM_read_X509(certfile, &x509, NULL, NULL);
    fclose(certfile);

    // Verify the signature of the token
    json_object *json = json_object_from_json_string(json_str);
    if (!json) {
        printf("Error parsing JSON string.\n");
        return;
    }

    // Check the signature
    EVP_PKEY *pkey = EVP_PKEY_new_RSA(rsa);
    HMAC_CTX hmac_ctx;
    HMAC_CTX_init(&hmac_ctx);

    // Calculate the expected hash value
    unsigned char expected_hash[32];
    HMAC_CTX_setkey(&hmac_ctx, pkey->d, RSA_size(pkey));
    HMAC_Init_ex(&hmac_ctx, NULL, 0, NULL);
    HMAC_Update(&hmac_ctx, json_object_to_json_string(json), strlen(json_object_to_json_string(json)));
    HMAC_Final(&hmac_ctx, expected_hash);

    // Check the signature
    unsigned char actual_hash[32];
    HMAC_CTX_init(&hmac_ctx);
    HMAC_CTX_setkey(&hmac_ctx, pkey->d, RSA_size(pkey));
    HMAC_Init_ex(&hmac_ctx, NULL, 0, NULL);
    HMAC_Update(&hmac_ctx, json_str, strlen(json_str));
    HMAC_Final(&hmac_ctx, actual_hash);

    if (memcmp(expected_hash, actual_hash, 32)) {
        printf("Invalid signature.\n");
        return;
    }

    // Check the expiration time
    struct tm *expiration = NULL;
    json_object *exp = json_object_object_get(json, "exp");
    if (!json_object_is_type(exp, json_type_integer)) {
        printf("Expected 'exp' to be an integer.\n");
        return;
    }
    int64_t now = time(NULL);
    struct tm* current_time = localtime(&now);

    // Compare the expiration time
    long *expiration_time = (long*)json_object_get_string(exp);
    if (*expiration_time < mktime(current_time)) {
        printf("Token has expired.\n");
        return;
    }

    // Check the scope
    json_object *scope = json_object_object_get(json, "scope");
    if (!json_object_is_type(scope, json_type_string)) {
        printf("Expected 'scope' to be a string.\n");
        return;
    }
    char *token_scope = (char*)json_object_to_json_string(scope);

    // Check the scope
    if (strcmp(token_scope, "required_scope") != 0) {
        printf("Invalid scope.\n");
        return;
    }

    *token = json_object_to_json_string(json);
}

int main() {
    char* json_str = "your JSON string here";
    char* secret_key = "path/to/secret/key.pem";
    char* token;

    get_token(json_str, secret_key, &token);

    printf("Access token: %s\n", token);

    return 0;
}
