void heapSort(double* arr, int n) {
    for (int i = n/2 - 1; i >= 0; i--) {
        siftDown(arr, i, n);
    }
    for (int i = n-1; i > 0; i--) {
        double temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;
        siftDown(arr, 0, i);
    }
}

void siftDown(double* arr, int start, int end) {
    int root = start;
    while (1) {
        int leftChild = 2 * root + 1;
        int rightChild = 2 * root + 2;
        int largest = root;
        if (leftChild < end && arr[leftChild] > arr[largest])
            largest = leftChild;
        if (rightChild < end && arr[rightChild] > arr[largest])
            largest = rightChild;
        if (largest == root)
            return;
        double temp = arr[root];
        arr[root] = arr[largest];
        arr[largest] = temp;
        root = largest;
    }
}

int main() {
    double arr[] = {5.2, 3.1, 8.4, 0.9, 6.7};
    int n = sizeof(arr) / sizeof(double);
    heapSort(arr, n);
    for (int i = 0; i < n; i++) {
        printf("%f ", arr[i]);
    }
    return 0;
}

