char* fix_path(char* dir, size_t len_dir, const char* path) {
    char* result = malloc(len_dir + strlen(path) + 2);
    sprintf(result, "%s/%s", dir, path);
    if (result[0] == '/') {
        return result;
    }
    char* absolute_path = malloc(strlen(getcwd(NULL, 0)) + strlen(path) + 1);
    sprintf(absolute_path, "/%s%s", getcwd(NULL, 0), path);
    free(result);
    return absolute_path;
