#include <des.h>
#include <string.h>

void encrypt(unsigned char key[3], unsigned char plaintext[], unsigned char result[3][8]) {
    DES_key_schedule ks;
    DES_cblock ckey;
    int i, j;

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 1; j++) {
            ckey[j] = key[i];
        }
        DES_set_key(&ckey, &ks);
        int len = strlen((char *) plaintext);
        for (int k = 0; k + 8 <= len; k += 8) {
            DES_ecb_encrypt(&plaintext[k], &result[i][k/8], &ks, NULL);
        }
        if (k < len) {
            DES_ecb_encrypt(&plaintext[k], &((unsigned char *) result[i])[k/8], &ks, NULL);
        }
    }
}
