void MD4_CTX *md4_init(void) {
    void MD4_CTX *ctx;
    ctx = (void MD4_CTX *)malloc(sizeof(void MD4_CTX));
    ctx->buf = (unsigned char *)malloc(64);
    ctx->nbytes = 0;
    return ctx;
}

void md4_transform(unsigned long int a, unsigned long int b, unsigned long int c, unsigned long int d) {
    unsigned long int AA, BB, CC, DD;

    AA = (a & 0xF0000000) >> 24;
    BB = (a & 0x0F000000) >> 20;
    CC = (a & 0x00FF0000) >> 16;
    DD = a & 0xFFFF;

    unsigned long int t = (AA + BB) << 4 + CC;

    AA = (b & 0xF0000000) >> 24;
    BB = (b & 0x0F000000) >> 20;
    CC = (b & 0x00FF0000) >> 16;
    DD = b & 0xFFFF;

    t += ((BB + CC) << 4 | DD);

    AA = (c & 0xF0000000) >> 24;
    BB = (c & 0x0F000000) >> 20;
    CC = (c & 0x00FF0000) >> 16;
    DD = c & 0xFFFF;

    t += ((AA + CC) << 4 | BB);

    AA = (d & 0xF0000000) >> 24;
    BB = (d & 0x0F000000) >> 20;
    CC = (d & 0x00FF0000) >> 16;
    DD = d & 0xFFFF;

    t += ((AA + DD) << 4 | BB);

    a = (a & 0xFFFFFFFF) + ((t & 0xF0000000) >> 24);
    b = (b & 0xFFFFFFFF) + ((t & 0x0F000000) >> 20);
    c = (c & 0xFFFFFFFF) + ((t & 0xFF00000) >> 16);
    d = (d & 0xFFFFFFFF) + (t & 0xFFFF);

}

void MD4_update(void MD4_CTX *ctx, unsigned char *buf, int len) {
    while(len >= 64) {
        memcpy(ctx->buf, buf, 64);
        md4_transform((ctx->state[0]), (ctx->state[1]), (ctx->state[2]), (ctx->state[3]));
        ctx->nbytes += 64;
        buf += 64;
        len -= 64;
    }

    if(len > 0) {
        memcpy(ctx->buf, buf, len);
        ctx->nbytes += len;
    }
}

