#include <openssl/evp.h>
#include <string.h>

unsigned char* crypto_hash(const unsigned char* data, size_t len, int algo) {
    EVP_MD_CTX mdctx;
    unsigned char md_value[EVP_MAX_MD_SIZE];
    unsigned int md_len;

    if (EVP_DigestInit_ex(&mdctx, NULL, NULL)) {
        if (algo == 1) { // MD2
            EVP_MD_set_md(EVP_MD_CTX_new(), EVP_sha);
        } else if (algo == 2) { // MD4
            EVP_MD_set_md(EVP_MD_CTX_new(), EVP_md4);
        } else if (algo == 3) { // MD5
            EVP_MD_set_md(EVP_MD_CTX_new(), EVP_md5);
        } else if (algo == 4) { // SHA1
            EVP_MD_set_md(EVP_MD_CTX_new(), EVP_sha1);
        }

        if (EVP_DigestUpdate(&mdctx, data, len)) {
            EVP_DigestFinal_ex(&mdctx, md_value, &md_len);
        } else {
            return NULL;
        }
    } else {
        return NULL;
    }

    unsigned char* result = malloc(md_len + 1);
    memcpy(result, md_value, md_len);
    result[md_len] = '\0';
    EVP_MD_CTX_free(&mdctx);

    return result;
}
