```c
char *modify_filename(char *filename) {
    int num_digits = 0;
    char *file_type = NULL;

    // Find the position of the last dot in the filename
    char *dot_pos = strrchr(filename, '.');

    // If there is a dot, it means we have an extension
    if (dot_pos != NULL) {
        file_type = dot_pos + 1;
        num_digits = strlen(dot_pos - strspn(filename, "."));

        // Check if the number of digits at the end of the filename
        // is valid for an integer
        char *end_pos = dot_pos - 1;
        while (end_pos > filename && !isdigit(*end_pos)) {
            end_pos--;
        }

        num_digits = (dot_pos - end_pos) - 1;

        // Create a new filename with the modified extension
        char *new_filename = malloc(strlen(filename) + strlen(file_type) + 10);
        sprintf(new_filename, "%s_%04d.%s", filename, atoi(end_pos), file_type);

        free(filename);
        return new_filename;
    } else {
        // If there is no dot in the filename, it's a simple case
        char *new_filename = malloc(strlen(filename) + 10);
        sprintf(new_filename, "%s_0000.txt", filename);
        free(filename);
        return new_filename;
    }
}
