EVP_CIPHER_CTX *aes_cbc_cipher(int key_length) {
    EVP_CIPHER_CTX *cipher = NULL;
    switch (key_length / 8) {
        case 16:
            cipher = EVP_des_ecb();
            break;
        case 24:
            cipher = EVP_idea_cbc();
            break;
        case 32:
        case 40:
        case 48:
            if(key_length == 32){
                cipher = EVP_aes_128_cbc();
            } else if (key_length == 40) {
                cipher = EVP_aes_160_cbc();
            } else if (key_length == 48) {
                cipher = EVP_aes_192_cbc();
            }
            break;
        case 56:
        case 64:
            if(key_length == 56) {
                cipher = EVP_aes_224_cbc();
            } else if (key_length == 64) {
                cipher = EVP_aes_256_cbc();
            }
            break;
    }
    return cipher;
}
