#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void process_data(double **data_dbl, int **data_int, int rows, int cols) {
    FILE *fp;
    char filename[100];
    double sum = 0.0;

    // Calculate the mean of the double data
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            sum += data_dbl[i][j];
        }
    }
    double mean = sum / (rows * cols);

    // Calculate the sum of the integer data
    int total_int = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            total_int += data_int[i][j];
        }
    }

    // Generate filename based on mean and total integer value
    sprintf(filename, "output_%f_%d.txt", mean, total_int);

    fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error opening file!\n");
        return;
    }

    // Write double data to file with precision 5
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            fprintf(fp, "%5f ", data_dbl[i][j]);
        }
        fprintf(fp, "\n");
    }

    // Write integer data to file
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            fprintf(fp, "%d ", data_int[i][j]);
        }
        fprintf(fp, "\n");
    }

    fclose(fp);
}
