void selectAttack() {
    const int COOLDOWN = 9; // seconds
    const int MAX_ATTACKS = 2;
    const char* attacks[] = {"attack1", "attack2"};

    static bool isCooldown = true;

    if (isCooldown) {
        srand(static_cast<unsigned>(time(0))); // seed the random number generator
        int attackIndex = rand() % MAX_ATTACKS; // select a random attack

        std::cout << attacks[attackIndex] << std::endl;
        isCooldown = false; // start cooldown period
    }

    else {
        --COOLDOWN;

        if (COOLDOWN == 0) {
            isCooldown = true;
        }
    }
}

```cpp
OctreeNode* octreeInit(int featureSize, int numLeafNodes, int dataCapacity) {
    OctreeNode* root = new OctreeNode(featureSize);
    if (root == nullptr) return nullptr;

    root->capacity = 1 << featureSize; // Update capacity of the octree

    if (numLeafNodes > root->capacity) {
        return nullptr; // Capacity is too small to hold this many leaf nodes
    }

    int numLevels = 1;
    while ((1 << numLevels) < numLeafNodes) {
        numLevels++;
    }

    // Allocate memory for the prefix leafs array
    root->prefixLeaves = new OctreeNode*[root->capacity];
    if (root->prefixLeaves == nullptr) return nullptr;

    // Initialize the prefix leafs array
    for (int i = 0; i < root->capacity; i++) {
        root->prefixLeaves[i] = nullptr;
    }

    // Allocate memory for the data array
    root->data = new void*[numLeafNodes];
    if (root->data == nullptr) return nullptr;

    // Initialize the data array
    for (int i = 0; i < numLeafNodes; i++) {
        root->data[i] = nullptr;
    }

    return root;
}
