    openBaton->setDataBits(dataBits);
    openBaton->setBufferSize(bufferSize);
    openBaton->setParity(parity);
    openBaton->setStopBits(stopBits);
    if (rtscts) {
        openBaton->setRTSCTS(true);
    } else {
        openBaton->setRTSCTS(false);
    }
    if (xon) {
        openBaton->setXON(true);
    } else {
        openBaton->setXON(false);
    }
    if (xoff) {
        openBaton->setXOFF(true);
    } else {
        openBaton->setXOFF(false);
    }
    if (xany) {
        openBaton->setXANY(true);
    } else {
        openBaton->setXANY(false);
    }
    return openBaton;
}
