#include <vector>
#include <algorithm>

std::pair<int, bool> findBestCombination(std::vector<std::pair<int, bool>>& pairs, int target) {
    std::pair<int, bool> bestCombination = {{0, false}};
    for (int i = 1; i <= target; ++i) {
        std::vector<std::pair<int, bool>> possibleCombinations;
        for (const auto& pair : pairs) {
            if (!pair.second && pair.first <= i - bestCombination.first) {
                possibleCombinations.push_back({pair.first, true});
            }
        }
        if (!possibleCombinations.empty()) {
            int maxSum = 0;
            std::vector<std::pair<int, bool>> bestPossibleCombination;
            for (const auto& pair : possibleCombinations) {
                int sum = pair.first + bestCombination.first;
                if (sum > maxSum && sum <= target) {
                    maxSum = sum;
                    bestPossibleCombination = {pair};
                }
            }
            if (!bestPossibleCombination.empty()) {
                bestCombination = {maxSum, true};
                for (const auto& pair : bestPossibleCombination) {
                    pairs.erase(std::remove(pairs.begin(), pairs.end(), pair), pairs.end());
                }
            }
        }
    }
    return bestCombination;
}

