#include <vector>
#include <set>
#include <random>

std::set<int> duplicateSet(const std::set<int>& orig) {
    std::set<int> newSet;
    for (int elem : orig) {
        newSet.insert(elem);
    }
    return newSet;
}

bool setsEqual(const std::set<int>& set1, const std::set<int>& set2) {
    if (set1.size() != set2.size()) {
        return false;
    }
    for (const auto& elem : set1) {
        if (!set2.count(elem)) {
            return false;
        }
    }
    return true;
}

std::vector<int> createSetAndCheck(const std::mt19937& gen) {
    int numElements = gen() % 10 + 1; // Random number of elements
    std::vector<int> vec(numElements);
    std::random_device rd;
    std::uniform_int_distribution<> dis(0, 100); // Generate random numbers between 0 and 100

    for (int i = 0; i < numElements; ++i) {
        vec[i] = dis(gen);
    }

    std::set<int> set(vec.begin(), vec.end());

    if (!std::is_sorted(set.begin(), set.end())) {
        return {}; // Set is not sorted
    }
    if (!setsEqual(set, duplicateSet(set))) {
        return {}; // Sets are not equal
    }

    return vec;
}

