    if (!mouse.init()) return false;

    // Initialize font
    Font font;
    if (!font.init()) return false;

    fclose(logFile);
    remove("graphicsLog.txt");
    rename("newGraphicsArchive.dat", "graphicsArchive.dat");

    return true;
}

