#include <iostream>
#include <string>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>

using namespace std;

int establishConnection(string IPaddress, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return -1;
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, IPaddress.c_str(), &serv_addr.sin_addr) <= 0) {
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        return -1;
    }

    return sock;
}

void sendCommand(int sock, string command) {
    int len = command.length();
    char buffer[len + 1];
    strcpy(buffer, command.c_str());

    if (send(sock, buffer, len, 0) < 0) {
        cerr << "Error sending command." << endl;
        return;
    }
}

string receiveResponse(int sock) {
    char buffer[1024];

    int bytesRead = recv(sock, buffer, 1023, 0);
    if (bytesRead < 0) {
        cerr << "Error receiving response." << endl;
        return "";
    }

    string response(buffer, bytesRead);

    return response;
}

int main() {
    string IPaddress = "192.168.1.100";
    int port = 1234;

    int sock = establishConnection(IPaddress, port);
    if (sock < 0) {
        cerr << "Error establishing connection." << endl;
        return -1;
    }

    while (true) {
        string command;
        cout << "Enter a command (or 'q' to quit): ";
        cin >> command;

        if (command == "q") {
            break;
        }

        sendCommand(sock, command);

        string response = receiveResponse(sock);
        cout << "Response: " << response << endl;
    }

    close(sock);

    return 0;
}
