void testSetIndexedPropertiesToExternalArrayData(Isolate* isolate) {
  Local<String> key = String::NewFromUtf8(isolate, "key");
  Local<Array> externalData = Array::New(isolate, 3);
  int32_t arr[3] = {1, 2, 3};
  v8::Local<v8::Value> values[3];
  for (int i = 0; i < 3; i++) {
    values[i] = Number::New(isolate, arr[i]);
  }
  externalData->Set(0, values[0]);
  externalData->Set(1, values[1]);
  externalData->Set(2, values[2]);

  Local<Object> obj = Object::New(isolate);
  obj->SetIndexedPropertiesToExternalArrayData(key, externalData);

  CHECK_EQ(obj->GetIndexedPropertyNames()->Length(), 3);
  for (int i = 0; i < 3; i++) {
    v8::Local<v8::Value> value = obj->GetIndexedProperty(i);
    CHECK_EQ(value->Type(), v8::Int32::kType);
    int32_t expectedValue = arr[i];
    CHECK_EQ(int32_t::NewFrom(v8::Integer::New(isolate, value)), Number::New(isolate, expectedValue));
  }

  // Free the external data
  for (int i = 0; i < 3; i++) {
    delete values[i];
  }
}

