#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/ec.h>
#include <openssl/rand.h>

unsigned char* ecies_encrypt(unsigned char *plaintext, unsigned int plaintext_len, unsigned char *private_key, unsigned char *public_key, unsigned char *encrypted_key) {
    EVP_PKEY *pub_key = d2i_ECPKParameters(NULL, &public_key);
    EVP_PKEY *priv_key = d2i_ECPKParameters(NULL, &private_key);

    EC_KEY *ec_key = EC_KEY_new_by_curve_name(NID_secp160r);
    if (!EC_KEY_set_public_key(ec_key, pub_key)) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }
    EC_KEY_set_private_key(ec_key, priv_key);

    unsigned char shared_secret[64];
    EVP_PKEY* derived_key = ECDH_compute_key(NULL, &shared_secret, ec_key, pub_key);
    if (!derived_key) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }

    const EVP_CIPHER *aes_cipher = EVP_get_cipherbyname("AES-128-CBC");
    if (!aes_cipher) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }

    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char* encrypted_data;

    // Generate random IV
    RAND_bytes(iv, sizeof(iv));

    // Create a new AES context
    EVP_CIPHER_CTX *aes_ctx = EVP_CIPHER_CTX_new();
    if (!EVP_CipherInit_ex(aes_ctx, aes_cipher, NULL, shared_secret, 16)) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }
    EVP_CIPHER_CTX_set_iv(aes_ctx, iv);

    // Encrypt the plaintext
    unsigned char* ciphertext = OPENSSL_malloc(plaintext_len + AES_BLOCK_SIZE);
    if (!EVP_EncryptInit_ex(aes_ctx, NULL, NULL, shared_secret, 16)) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }
    int len = EVP_EncryptUpdate(aes_ctx, ciphertext, &len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(aes_ctx, ciphertext + len, &len);

    // Calculate the MAC
    const EVP_MD *ripemd160_md = EVP_get_digestbyname("RIPEMD-160");
    unsigned char* mac = OPENSSL_malloc(EVP_MAX_MD_SIZE);
    unsigned int mac_len;
    if (!EVP_DigestInit_ex(NULL, ripemd160_md, NULL)) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }
    EVP_DigestUpdate(NULL, shared_secret, 16);
    EVP_DigestFinal_ex(NULL, mac, &mac_len);

    // Combine the ciphertext and MAC
    unsigned char* encrypted_data = OPENSSL_malloc(len + mac_len);
    memcpy(encrypted_data, ciphertext, len);
    memcpy(encrypted_data + len, mac, mac_len);

    // Clean up
    EVP_CIPHER_CTX_free(aes_ctx);
    OPENSSL_free(ciphertext);
    OPENSSL_free(mac);

    return encrypted_data;
}

