char** loadMap(const std::string& mapStr) {
    size_t rows = 0;
    size_t cols = 0;
    size_t pos = 0;

    // Calculate number of rows and columns from the string representation
    while (pos < mapStr.size()) {
        if (mapStr[pos] == '\n') {
            ++rows;
            pos += 1; // Skip newline character
        } else if (mapStr[pos] != ',') { // Assuming delimiter is comma
            cols = std::stoi(&mapStr[pos]);
            break;
        }
        ++pos;
    }

    if (cols == 0) {
        return nullptr; // Invalid input
    }

    char** map = new char*[rows];
    for (size_t i = 0; i < rows; ++i) {
        map[i] = new char[cols];

        pos = 0;
        while (pos < mapStr.size()) {
            if (mapStr[pos] == '\n') {
                break;
            }

            size_t endPos = pos;
            while (endPos + 1 < mapStr.size() && mapStr[endPos + 1] != ',') {
                ++endPos;
            }
            std::string tile = mapStr.substr(pos, endPos - pos + 1);
            std::transform(tile.begin(), tile.end(), tile.begin(), ::tolower); // Convert to lowercase for simplicity

            // Initialize tile values based on the string representation
            if (tile == "empty" || tile == "") {
                std::fill_n(&map[i][0], cols, '\0');
            } else if (tile == "wall") {
                // Fill with wall character or value
            } else if (tile == "floor") {
                // Fill with floor character or value
            } else {
                return nullptr; // Invalid tile value
            }

            pos = endPos + 1;
        }
    }

    return map;
}
