std::map<std::string, struct Page*> getPagePool() {
    static std::map<std::string, struct Page*> pagePool;

    struct Page* createPage(const std::string& id, void* data) {
        struct Page* page = (struct Page*)malloc(sizeof(struct Page));
        page->id = id;
        page->data = data;
        pagePool[id] = page;
        return page;
    }

    struct Page* getPage(const std::string& id) {
        auto it = pagePool.find(id);
        if (it == pagePool.end()) {
            return nullptr;
        }
        return it->second;
    }

    void deletePage(const std::string& id) {
        auto it = pagePool.find(id);
        if (it != pagePool.end()) {
            pagePool.erase(it);
            free(it->second);
        }
    }

    return pagePool;
}

