int load_data(int num_keys, const char **keys, int key_size, FILE *db) {
    int i;
    for (i = 0; i < num_keys; i++) {
        fwrite(keys[i], key_size, 1, db);
        fflush(db); // commit changes
        if(ftell(db) >= 4096) { // assume a minimum block size of 4096 bytes
            rewind(db);
            fseek(db, ftello(db) - 4096, SEEK_SET); // move to the last full block
        }
    }
    return 0;
}
