Here's how you can achieve this. This function uses the `iconv_open` function to get the default encoding of the system and then converts it into a string.

```c
#include <stdlib.h>
#include <iconv.h>
#include <string.h>

char* getCodepage() {
    iconv_t cd = iconv_open("", "ASCII");
    size_t inb_len = 1024;
    char *inbuf = malloc(inb_len);
    if (!cd || !inbuf) return NULL;

    int result = iconv(cd, (char**)&inbuf, &inb_len, "", 0);

    if(result == (size_t)-1) {
        free(inbuf);
        iconv_close(cd);
        return NULL;
    }

    char *codepage = strtok(inbuf, ";");
    free(inbuf);
    iconv_close(cd);
    return codepage;
}
```

Please note that this function only works on platforms where the default encoding is a valid input for `iconv_open`, which includes most Unix-like systems. On Windows, you would need to use the Windows API functions like `GetSystemDefaultLCID` and then convert the returned LCID into a codepage name.

