std::vector<std::vector<int>> createAdjacencyList(const std::pair<typename std::iterator_traits<Iter>::iterator_type, typename std::iterator_traits<Iter>::iterator_type>& range) {
    int numVertices = 0;
    for (auto it = range.first; it != range.second; ++it) {
        if (*it > numVertices) {
            numVertices = *it + 1;
        }
    }

    std::vector<std::vector<int>> adjacencyList(numVertices);
    for (int i = 0; i < numVertices; ++i) {
        adjacencyList[i].reserve(1); // Reserve space for the head of the list
    }

    int currentVertex = 0;
    for (auto it = range.first; it != range.second; ++it, ++currentVertex) {
        adjacencyList[currentVertex].push_back(*it);
    }

    return adjacencyList;
}
