#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SEGMENTS 1000
#define MAX_COORDINATES 4

typedef struct {
    double x1, y1;
    double x2, y2;
} LineSegment;

LineSegment path[MAX_SEGMENTS];
int numSegments = 0;
char fillType[10];

void closePath() {
    if (numSegments == 0) return;

    // Calculate the last line segment
    path[numSegments].x1 = path[0].x2;
    path[numSegments].y1 = path[0].y2;
    path[numSegments].x2 = path[1].x1;
    path[numSegments].y2 = path[1].y1;

    numSegments++;
}

char* drawPath() {
    char* output = (char*)malloc(1024 * sizeof(char));
    sprintf(output, "M%.2f %.2f", path[0].x1, path[0].y1);
    for(int i = 0; i < numSegments - 1; i++) {
        sprintf(output + strlen(output), "L%.2f %.2f", path[i+1].x2, path[i+1].y2);
    }
    sprintf(output + strlen(output), "L%.2f %.2f Z", path[0].x1, path[0].y1);

    return output;
}

int isSimple() {
    if (numSegments <= 3) return 1; // A path with less than or equal to 3 segments is always simple

    double area = 0;
    for(int i = 0; i < numSegments; i++) {
        area += (path[i].x2 * (path[(i+1)%numSegments].y1 - path[i%numSegments].y2) -
                 path[i].y2 * (path[(i+1)%numSegments].x1 - path[i%numSegments].x2));
    }

    return fabs(area) < 0.001;
}

int main() {
    int i;

    // Initialize the first line segment
    path[0].x1 = 100; path[0].y1 = 200;
    path[0].x2 = 150; path[0].y2 = 250;

    numSegments++;

    for(i = 1; i < MAX_SEGMENTS-1; i++) {
        // Add more line segments
        path[i].x1 = 100 + (i*10); path[i].y1 = 200;
        path[i].x2 = 150 + (i*10); path[i].y2 = 250;

        numSegments++;
    }

    closePath();

    char *output = drawPath();
    printf("Drawing path with fill type: %s\n", output);
    free(output);

    if(isSimple()) {
        printf("The path is simple.\n");
    } else {
        printf("The path is not simple.\n");
    }

    return 0;
}

