```cpp
int estimateStorage(double threshold, int numAngles) {
    const int bytesPerKB = 1024;
    const int bytesPerMB = 1048576;
    const int bytesPerGB = 1073741824;
    const int bytesPerTB = 1099511627776;

    double storagePerSequence = threshold / (numAngles * M_PI); // assume PI constant

    long long totalBytes = static_cast<long long>(storagePerSequence);

    if (totalBytes >= bytesPerTB) {
        return ceil(totalBytes / (double)bytesPerTB);
    } else if (totalBytes >= bytesPerGB) {
        return ceil(totalBytes / (double)bytesPerGB);
    } else if (totalBytes >= bytesPerMB) {
        return ceil(totalBytes / (double)bytesPerMB);
    } else if (totalBytes >= bytesPerKB) {
        return ceil(totalBytes / (double)bytesPerKB);
    } else {
        return static_cast<int>(totalBytes);
    }
}

