#include <miniupnp.h>

void get_upnp_devices(struct upnp_device_list* devices) {
    struct upnp_dev_desc *dev;
    int i;

    // Initialize UPnP library
    upnpc_init();

    // Get all UPnP devices on the network
    for (i = 0; i < UPNPC_MAX_DEVICES; i++) {
        dev = upnpc_get_device(i);
        if (!dev)
            break;
        // Check if the device is a valid UPnP device
        if (upnpc_dev_is_valid(dev)) {
            devices->count++;
            devices->devices[devices->count-1] = malloc(sizeof(struct upnp_device));
            strcpy(devices->devices[devices->count-1]->description, dev->desc);
            strcpy(devices->devices[devices->count-1]->friendly_name, dev->fn);
            free(dev);
        }
    }

    // Clean up
    upnpc_cleanup();
}
