void drawCurve(float* controlPoints, int numControlPoints, float lineWidth, float lineColor[3], int numSegments) {
    glBegin(GL_LINE_STRIP);
    for (int i = 0; i < numControlPoints; i++) {
        glVertex2f(controlPoints[i * 2] + controlPoints[(i + 1 == numControlPoints ? 0 : i + 1) * 2], 
            controlPoints[i * 2 + 1] + controlPoints[(i + 1 == numControlPoints ? 0 : i + 1) * 2 + 1]);
    }
    glEnd();

    glColor3fv(lineColor);
    glLineWidth(lineWidth);

    glBegin(GL_LINE_STRIP);
    float* start = &controlPoints[0];
    float* end = &controlPoints[numControlPoints * 2 - 2];
    for (int i = 0; i < numSegments; i++) {
        glVertex2f(start[0] + (end[0] - start[0]) * i / (numSegments - 1), 
            start[1] + (end[1] - start[1]) * i / (numSegments - 1));
    }
    glEnd();
}
