std::vector<char> encryptWideString(const std::wstring& wideStr) {
    int size = wideStr.length() * 2; // assuming each Unicode character is 2 bytes long
    std::vector<char> encryptedData(size);

    for (int i = 0; i < wideStr.length(); ++i) {
        wchar_t wChar = wideStr[i];
        char* cChar = reinterpret_cast<char*>(&wChar); // convert Unicode to ASCII

        memcpy(&encryptedData[i * 2], cChar, 2); // copy the bytes into the new array
    }

    return encryptedData;
}

