```c
char* formatSignedInt(int n) {
    char *result = (char *)malloc(81);
    int length = 0;
    if (n < 0) {
        result[length++] = '-';
        n = -n;
    }
    int i = 0;
    do {
        result[length++] = '0' + (n % 10);
        n /= 10;
        if (++i > 3 && n > 0) {
            result[length++] = ',';
            n = 1;
            i = 0;
        }
    } while (n > 0);
    for (; length < 78; ) {
        result[--length] = '\n';
        for (int j = 80; j > length; --j) {
            if (j <= 77) {
                result[--j] = ' ';
            } else {
                result[--j] = result[length];
            }
        }
    }
    result[length--] = '\0';
    return result;
}
