char* validateFilePath(char* filePath) {
    char* result = (char*)malloc(strlen(filePath)+1);
    strcpy(result, filePath);

    // Check if the path contains a colon (":") followed by at least one more character
    int i;
    for(i=0; i<strlen(filePath); i++) {
        if(filePath[i] == ':') {
            if(i+1 < strlen(filePath)) {
                return result;
            } else {
                break;
            }
        }
    }

    // If we didn't find a colon, check the path doesn't start with "."
    for(i=0; i<strlen(filePath); i++) {
        if(filePath[i] == '.') {
            if(i == 0) {
                printf("Error: The file path cannot start with a dot (.)\n");
                free(result);
                return NULL;
            } else {
                break;
            }
        }
    }

    printf("Error: Invalid file path\n");
    free(result);
    return NULL;
}

