int splitUnicodeString(char *str) {
    int i = 0;
    int count = 0;
    int length = 0;
    char **strings = (char **)uprv_malloc(sizeof(char *) * strlen(str));
    int *stringLengths = (int *)uprv_malloc(sizeof(int) * strlen(str));

    while (*str != '\0') {
        if (!isCanonSegmentStarter(*str)) {
            length++;
            str++;
        } else {
            strings[count] = (char *)uprv_malloc((length + 1) * sizeof(char));
            memcpy(strings[count], (str - length), length * sizeof(char));
            strings[count][length] = '\0';
            stringLengths[count] = length;
            count++;
            length = 0;
        }
    }

    if (length > 0) {
        strings[count] = (char *)uprv_malloc((length + 1) * sizeof(char));
        memcpy(strings[count], str - length, length * sizeof(char));
        strings[count][length] = '\0';
        stringLengths[count] = length;
        count++;
    }

    return count;
}
