#include <miniupnpc.h>
#include <stdlib.h>

char** discoverUpnpDevices(char* multicastAddress, char* miniupnpcPath) {
    struct upnp_device_list *deviceList = NULL;
    int errorCode;

    // Initialize the UPnP discovery process
    if ((errorCode = upnpInit()) != 0) {
        fprintf(stderr, "Error initializing UPnP: %s\n", upnpError(errorCode));
        return NULL;
    }

    // Set the multicast address and port for the discovery process
    upnpc_set_multicast_addr((char*)multicastAddress);

    // Perform the UPnP device discovery
    if ((errorCode = upnpDiscover(miniupnpcPath, &deviceList)) != 0) {
        fprintf(stderr, "Error discovering UPnP devices: %s\n");
        free(deviceList);
        return NULL;
    }

    // Create a list of discovered devices
    char** devices = (char**)malloc((deviceList->num_devices + 1) * sizeof(char*));
    for (int i = 0; i < deviceList->num_devices; i++) {
        devices[i] = strdup(deviceList->devices[i]->name);
    }
    devices[deviceList->num_devices] = NULL;

    // Free the UPnP discovery list
    free_device_list(deviceList);

    return devices;
}

