int*
reversedList(int* first, ...)
{
    va_list ap;
    int* list = NULL;

    va_start(ap, first);
    int count = 0;
    while (1)
    {
        void* p = va_arg(ap, void*);
        if (!p) break;
        list = realloc(list, sizeof(int*) * ++count);
        *(int**)&list[count-1] = p;
    }
    va_end(ap);

    return list;
}

