char* strip_whitespace(char* str) {
    if (str == NULL)
        return NULL;

    int len = strlen(str);
    int new_len = 0;
    char* new_str = malloc((len + 1) * sizeof(char));

    for (int i = 0; i < len; i++) {
        if (!isspace(str[i])) {
            new_str[new_len++] = str[i];
        }
    }

    new_str[new_len] = '\0';

    return new_str;
}

