struct Node {
    int val;
    struct Node* left;
    struct Node* right;
};

Node* buildTree(int n, int* c) {
    Node* nodes = new Node[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &nodes[i].val);
        if ((c[i*2] >= 0 && c[i*2+1] >= 0) || (c[i*2] == -1 && c[i*2+1] == -1)) {
            nodes[i].left = &nodes[c[i*2]];
            if (c[i*2] >= 0)
                nodes[c[i*2]].val = nodes[i].val;
        }
        if ((c[i*2+1] >= 0) || (c[i*2+1] == -1)) {
            nodes[i].right = &nodes[c[i*2+1]];
            if (c[i*2+1] >= 0)
                nodes[c[i*2+1]].val = nodes[i].val;
        }
    }
    Node* root;
    for (int i = 0; i < n; i++) {
        if (nodes[i].left == NULL && nodes[i].right == NULL) {
            root = &nodes[i];
            break;
        }
    }
    return root;
}
