physx::PxScene* SaveScene(const std::string& filename) {
    physx::PxSceneDesc sceneDesc;
    physx::PxPhysics* physics = GetPhysics();
    sceneDesc.gravity = physx::PxVec3(0.0f, -9.81f, 0.0f);
    sceneDesc.flags = physx::PxSceneFlag::eALLOW_SLEEPING | 
                       physx::PxSceneFlag::eENABLE_CCD;
    physics->createScene(sceneDesc);

    // Create a new simulation
    physx::PxSimulation* sim = physics->getSimulation();

    // Set the active state of cloth and soft body simulations
    sim->setClothActive(true);
    sim->setSoftBodyActive(true);

    // Save the scene to a file using a specified file path
    std::ofstream file(filename, std::ios::binary);
    if (file) {
        physx::PxScene* savedScene = physics->getScene();
        file.write(reinterpret_cast<char*>(&savedScene), sizeof(physx::PxScene));
        return savedScene;
    }
    return nullptr;
