void VerifyFramebufferPixels(GLuint frameBufferId, GLuint commandBufferId, GLsizei width, GLsizei height) {
    GLenum pixelFormat = GL_RGBA; // Adjust according to your framebuffer format
    GLint pixelType = GL_UNSIGNED_BYTE; // Adjust according to your framebuffer type

    glBindFramebuffer(GL_FRAMEBUFFER, frameBufferId);
    glReadPixels(0, 0, width, height, pixelFormat, pixelType, NULL);

    unsigned char* expectedPixels = new unsigned char[width * height * (pixelFormat == GL_RGBA ? 4 : pixelType == GL_UNSIGNED_SHORT ? 2 : 1)];
    glGetBufferSubData(commandBufferId, 0, width * height * (pixelFormat == GL_RGBA ? 4 : pixelType == GL_UNSIGNED_SHORT ? 2 : 1), expectedPixels);

    for (int i = 0; i < width * height; i++) {
        unsigned char* pixel = reinterpret_cast<unsigned char*>(&expectedPixels[i * (pixelFormat == GL_RGBA ? 4 : pixelType == GL_UNSIGNED_SHORT ? 2 : 1)]);
        // Verify the pixels here, for example:
        if (pixel[0] != expectedPixelValue || pixel[1] != expectedPixelValue || ... ) {
            std::cout << "Verification failed!" << std::endl;
            return;
        }
    }

    delete[] expectedPixels;

    std::cout << "Verification passed." << std::endl;
}
