void generateLevel(int x1, int y1, int x2, int y2, int *doorFlag) {
    if (x1 >= x2 || y1 >= y2) return;

    int dx = rand() % ((x2 - x1) / 2) + 1;
    int dy = rand() % ((y2 - y1) / 2) + 1;

    *doorFlag = rand() % 2;

    int x3 = x1 + dx;
    int y3 = y1;
    int x4 = x1;
    int y4 = y1 + dy;

    int x5 = x1 + dx;
    int y5 = y1;
    int x6 = x1;
    int y6 = y1 + dy;

    // draw the wall
    printf("  %d, %d  |   ", x3, y4);
    for (int i = x4; i < x5; i++) {
        printf("%s", "|");
    }
    printf("  %d, %d\n", x6, y4);

    // draw the floor
    for (int j = y1 + dy; j > y3; j--) {
        printf("  %d, %d  |   ", x3, j);
        for (int i = x4; i < x5; i++) {
            printf("%s", "|");
        }
        printf("  %d, %d\n", x6, j);
    }

    generateLevel(x1, y1, x3, y3, doorFlag);
    generateLevel(x4, y1, x6, y4, doorFlag);

    if (*doorFlag) {
        printf("*");
    }
}

```c++
TypeHandle GetFunctionPointerTypeHandle(FunctionPointerType* pType, bool bCanonical)
{
    TypeList* pTypeList = (TypeList*)malloc(sizeof(TypeList));
    if (!pTypeList) return TypeHandle::Empty;

    // Allocate space for the list of type handles
    pTypeList->returnTypeHandle = ReadLoadedTypeHandles(pType->returnType, bCanonical);
    if (!pTypeList->returnTypeHandle) {
        free(pTypeList); // Free the memory we allocated
        return TypeHandle::Empty;
    }

    for (int i = 0; i < pType->paramCount; i++) {
        pTypeList->paramTypeHandles[i] = ReadLoadedTypeHandles(pType->params + i, bCanonical);
        if (!pTypeList->paramTypeHandles[i]) {
            // Free the memory we allocated
            for (int j = 0; j < i; j++)
                free((void*)pTypeList->paramTypeHandles[j]);
            free(pTypeList);            
            return TypeHandle::Empty;
        }
    }

    return pTypeList->typeHandle;
}
