public static byte[] generatePpmImage(PageDocument document, int pageNumber, int width, int height) {
    // Get the page from the document
    Page page = document.getPage(pageNumber);

    // Create an empty BufferedImage
    BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

    // Draw the page on the BufferedImage
    Graphics2D g2d = image.createGraphics();
    try {
        page.draw(g2d);
    } finally {
        g2d.dispose();
    }

    // Write the image data to a byte array
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    ImageIO.write(image, "PPM", bos);

    return bos.toByteArray();
}

