        // Update the position of the text to be printed
        int newX = static_cast<int>(transformationMatrix[0][0] * x + transformationMatrix[1][0] * y);
        int newY = static_cast<int>(transformationMatrix[2][0] * x + transformationMatrix[3][0] * y);

