#include <openssl/err.h>
#include <openssl/kdf.h>

int derive_key(char* password, char* salt, int iteration_count) {
    EVP_PBE_ALGOR alg;
    const unsigned char* pass = (const unsigned char*)password;
    const unsigned char* sl = (const unsigned char*)salt;

    if ((alg.id = EVP_PBEAlgorithms()) != 0x0103) return 0; // PBKDF2-HMAC-SHA1

    unsigned char* derived_key = OPENSSL_malloc(sizeof(unsigned char) * 32);
    unsigned char iv[16];
    unsigned int key_len, iv_len;
    BURN_CTX ctx;

    if (!EVP_PBE_derive(&ctx, &alg, pass, strlen(password), sl, strlen(salt),
                        iteration_count, 32, derived_key, &key_len,
                        16, iv, &iv_len)) {
        OPENSSL_free(derived_key);
        return 0;
    }

    // Use the key and IV
    printf("Derived key: ");
    for (int i = 0; i < key_len; i++) {
        printf("%02x", derived_key[i]);
    }
    printf("\n");
    printf("IV: ");
    for (int i = 0; i < iv_len; i++) {
        printf("%02x", iv[i]);
    }
    printf("\n");

    OPENSSL_free(derived_key);
    return 1;
}
