        std::cout << "Saved to XML: " << filename + ".xml" << std::endl;
    } else {
        std::cerr << "Failed to open XML file." << std::endl;
    }

    // Binary format
    std::ofstream binaryFile(filename + ".bin", std::ios::binary);
    if (binaryFile.is_open()) {
        for (int i : data) {
            binaryFile.write(reinterpret_cast<char*>(&i), sizeof(int));
        }
        std::cout << "Saved to Binary: " << filename + ".bin" << std::endl;
    } else {
        std::cerr << "Failed to open Binary file." << std::endl;
    }

    // COLLADA Physics 1.4.1 format
    std::ofstream colladaFile(filename + ".dae");
    if (colladaFile.is_open()) {
        colladaFile << "<?xml version=\"1.0\" encoding=\"UTF-8\"?><!DOCTYPE COLLADA SYSTEM \"http://www.collada.org/2005/08/COLLADASchema\">";
