#include <chrono>

double generateRandomImage(int width, int height) {
    std::vector<float> image(width * height);

    auto start = std::chrono::high_resolution_clock::now();

    // Method 1: Direct indexing
    for (int i = 0; i < width * height; ++i) {
        image[i] = static_cast<float>(rand()) / RAND_MAX;
    }

    auto end = std::chrono::high_resolution_clock::now();
    double durationMethod1 = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();

    // Method 2: Boundary clamping
    for (int i = 0; i < width * height; ++i) {
        image[i % width] += static_cast<float>(rand()) / RAND_MAX;
    }

    end = std::chrono::high_resolution_clock::now();
    double durationMethod2 = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();

    // Method 3: Scalar access
    for (int i = 0; i < width * height; ++i) {
        image[i / width] += static_cast<float>(rand()) / RAND_MAX;
    }

    end = std::chrono::high_resolution_clock::now();
    double durationMethod3 = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    // Print the execution times
    std::cout << "Method 1 (Direct indexing): " << durationMethod1 << " microseconds" << std::endl;
    std::cout << "Method 2 (Boundary clamping): " << durationMethod2 << " microseconds" << std::endl;
    std::cout << "Method 3 (Scalar access): " << durationMethod3 << " microseconds" << std::endl;

    return durationMethod1 + durationMethod2 + durationMethod3;
}
