```c
void flipImageVertical(int **image, int format) {
    size_t rows = 0;
    size_t cols = 0;

    // Calculate total number of pixels in the image
    for (int i = 0; i < image[0]; i++) {
        if (format == 1) { // RGB
            cols++;
        } else if (format == 2) { // RGBA
            cols++;
        }
    }

    rows = sizeof(image) / sizeof(image[0]);

    int *tempImage = new int[rows * cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            // Copy pixel data from input array to temporary array
            if (format == 1) { // RGB
                tempImage[i * cols + j] = image[rows - 1 - i][j];
            } else if (format == 2) { // RGBA
                tempImage[i * cols + j] = image[rows - 1 - i][j];
            }
        }
    }

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            // Copy pixel data from temporary array to input array
            if (format == 1) { // RGB
                image[rows - 1 - i][j] = tempImage[i * cols + j];
            } else if (format == 2) { // RGBA
                image[rows - 1 - i][j] = tempImage[i * cols + j];
            }
        }
    }

    delete[] tempImage;
}
