void testMatrixProjection(int numSamples, int tableSize, int dimension) {
    using namespace Eigen;

    // Create a random matrix and vector
    MatrixXd matrix(tableSize, dimension);
    for (int i = 0; i < tableSize; ++i)
        matrix.row(i).setRandom();

    VectorXd vector(dimension);
    for (int i = 0; i < dimension; ++i)
        vector(i) = static_cast<double>(rand()) / RAND_MAX;

    // Perform the matrix projection operation
    MatrixXd projectedTable = (matrix * matrix.transpose()).eval().colwise().sum();

    // Compute the reference implementation
    VectorXd projectedVector = (projectedTable * vector).head(tableSize);

    // Compare the results of the two implementations
    for (int i = 0; i < tableSize; ++i) {
        if (std::abs(projectedVector(i) - static_cast<double>(rand()) / RAND_MAX) > 1e-6) {
            std::cerr << "Error in matrix projection operation: input values do not match." << std::endl;
            return;
        }
    }

    // Print a log message with the inputs and outputs
    std::cout << "Matrix size: (" << tableSize << ", " << dimension << ")" << std::endl;
    std::cout << "Number of samples: " << numSamples << std::endl;
    std::cout << "Projected vector: " << projectedVector << std::endl;
}

