char* format_string(const char* path, int line, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);

    int len = vsnprintf(NULL, 0, fmt, args);
    if (len < 0) {
        va_end(args);
        return NULL; // Error handling
    }

    char* str = malloc(len + 1);
    if (!str) {
        va_end(args);
        return NULL; // Memory allocation failed
    }

    vsnprintf(str, len + 1, fmt, args);
    va_end(args);

    int real_len = strlen(str);
    if (real_len > len) {
        // String exceeds allocated memory
        free(str);
        str = malloc(real_len + 1);
        if (!str) {
            return NULL; // Memory allocation failed
        }
        strcpy(str, fmt);
    }

    return str;
}

