#include <iostream>
#include <string>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Custom message queue class
class MessageQueue {
private:
    std::queue<std::string> messages;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void push(const std::string& msg) {
        std::unique_lock<std::mutex> lock(mtx);
        messages.push(msg);
        lock.unlock();
        cv.notify_one();
    }

    bool try_pop(std::string& msg) {
        std::unique_lock<std::mutex> lock(mtx);
        if (messages.empty()) {
            return false;
        }
        msg = messages.front();
        messages.pop();
        return true;
    }
};

// Custom worker thread class
class WorkerThread {
public:
    void operator()(int conn_fd) const {
        MessageQueue queue;

        // Loop until connection is terminated
        while (true) {
            std::string message;
            if (!queue.try_pop(message)) {
                // If the queue is empty, wait for a new message
                std::unique_lock<std::mutex> lock(queue.mtx);
                queue.cv.wait(lock);
            }

            // Process the received message
            std::cout << "Received message: " << message << std::endl;

            // Send response back to client
            if (send(conn_fd, message.c_str(), message.size(), 0) < 0) {
                std::cerr << "Error sending response" << std::endl;
                break; // Connection terminated, exit loop
            }
        }

        // Close the connection
        ::close(conn_fd);
    }
};

// TCP server class
class TCPServer {
public:
    TCPServer(int port) : port_(port), stopped_(false) {}

    void start() {
        std::thread worker_thread([this]() {
            while (!stopped_) {
                int conn_fd = ::accept(listen_fd_, (struct sockaddr*)NULL, NULL);
                if (conn_fd < 0) {
                    std::cerr << "Error accepting connection" << std::endl;
                    return; // Exit thread
                }

                // Create a new worker thread to handle the connection
                WorkerThread worker_thread(conn_fd);
                worker_thread(); // Start the worker thread
            }
        });

        // Listen for incoming connections
        int listen_fd_ = ::socket(AF_INET, SOCK_STREAM, 0);
        if (listen_fd_ < 0) {
            std::cerr << "Error creating socket" << std::endl;
            return; // Exit program
        }

        struct sockaddr_in addr_;
        addr_.sin_family = AF_INET;
        addr_.sin_port = htons(port_);
        inet_pton(AF_INET, "127.0.0.1", &addr_.sin_addr);

        if (::bind(listen_fd_, (struct sockaddr*)&addr_, sizeof(addr_)) < 0) {
            std::cerr << "Error binding socket" << std::endl;
            return; // Exit program
        }

        if (::listen(listen_fd_, 10) < 0) {
            std::cerr << "Error listening on port" << std::endl;
            return; // Exit program
        }

        worker_thread.detach(); // Detach the thread from this thread

        while (!stopped_) {
            // Wait for connections
            ::usleep(10000);
        }
    }

    void stop() {
        stopped_ = true;
    }

private:
    int port_;
    bool stopped_;
    int listen_fd_;
};

int main(int argc, char* argv[]) {
    TCPServer server(8080);
    server.start();
    return 0;
}
