    } else if(geometryColumn != NULL && fidColumn == NULL) {
        sprintf(buffer + strlen(buffer), "%s", geometryColumn);
    } else if(geometryColumn == NULL && fidColumn != NULL) {
        sprintf(buffer + strlen(buffer), "%s", fidColumn);
    }

    sprintf(buffer + strlen(buffer), ") VALUES (NULL, ");

    if(geometryColumn != NULL || fidColumn != NULL) {
        sprintf(buffer + strlen(buffer), "NULL, ");
    }

    sprintf(buffer + strlen(buffer), ");");

