double optimize_modularity(graph& g, double max_passes, double epsilon) {
    double current_modularity = 0.0;
    double best_modularity = 0.0;

    for (int i = 0; i < max_passes; ++i) {
        // Perform one pass of node rearrangement
        rearrange_nodes(g);

        // Calculate the modularity of the graph after this pass
        current_modularity = calculate_modularity(g);

        if (current_modularity > best_modularity) {
            best_modularity = current_modularity;
        } else if (std::abs(current_modularity - best_modularity) < epsilon) {
            break; // Improvement is small, stop optimizing
        }
    }

    return best_modularity;
}
