#include "jpeglib.h"
#include <stdlib.h>
#include <stdio.h>

JPGImage* decompressJPEG(unsigned char *buffer, int height, int width) {
    JDIMENSION w = (JDIMENSION)width;
    JDIMENSION h = (JDIMENSION)height;
    struct jpeg_decompress_struct cinfo;
    JSAMPARRAY p;

    /* setup the client data */
    cinfo.err = jpeg_std_error(&jerr);
    cinfo.client_data = NULL;

    /* Read file header section. We already know height, width */
    if (jpeg_create_decompress(&cinfo) != JDIMENSION_SUCCESS)
        return NULL;

    cinfo.image_width = w;
    cinfo.image_height = h;

    if (!jpeg_read_header(cinfo, TRUE))
        return NULL;

    /* Decompress the data */
    if (!cinfo.finished)
        (void) jpeg_start_decompress(&cinfo);

    int row_size = cinfo.output_width * 3; // RGB
    unsigned char *pixels;
    pixels = malloc(row_size * h);

    p = CALLOC(h, 1, sizeof(JSAMPARRAY));
    for(int i=0; i<h; i++) {
        p[i] = &pixels[row_size*i];
    }

    /* Read the image data */
    while (cinfo.output_scanline < cinfo.height) {
        unsigned char *scanline;
        scanline = CALLOC(cinfo.output_width, sizeof(JSAMPLE));
        (void) cinfo.mem->src->data_unt[0].next_input_line(p[cinfo.output_scanline], cinfo.output_width);
        for(int j=0; j<cinfo.output_width; j++) {
            p[cinfo.output_scanline][j*3] = scanline[j];
            p[cinfo.output_scanline][j*3+1] = scanline[j];
            p[cinfo.output_scanline][j*3+2] = scanline[j];
        }
        FREE(scanline);
        cinfo.output_scanline++;
    }

    cinfo.exit_status = JDIMENSION_SUCCESS;

    /* Finish decompression */
    if (cinfo.output_scanline >= cinfo.height) {
        while (cinfo.next_output_sample < 4 * cinfo.width) {
            (void) cinfo.mem->src->data_unt[0].next_input_line(NULL, 1);
            cinfo.next_output_sample++;
        }
        jpeg_finish_decompress(&cinfo);
    }

    return NULL;
}
