char *generateQuery(const char* url, int depth) {
    static char query[256]; // Ensure sufficient space for query string
    sprintf(query, "host:%s&depth=%d&", url, depth);

    if (!strchr(url, '?')) {  // Non-CGI
        strcat(query, "non_cgi=true&");
    }
    if (strlen(url) > 1 && url[1] != '/') {  // Has a filename
        strcat(query, "has_filename=true&");
    }
    if (strstr(url, "#") == NULL && strstr(url, "?")) {  // Has a permalink
        strcat(query, "has_permalink=true&");
    }
    if (rand() % 2) {  // Randomly score the URL
        strcat(query, "random_score=true&");
    }

    return query;
}

