#include <iostream>
#include <fstream>
#include <vector>

uint8_t** loadDescriptors(const std::vector<std::string>& filePaths, bool includeAlpha) {
    int numFiles = filePaths.size();
    int maxDim1Size = 0;
    int maxDim2Size = 0;

    for (const auto& filePath : filePaths) {
        std::ifstream file(filePath);
        int dim1Size, dim2Size;
        file >> dim1Size >> dim2Size;
        if (dim1Size > maxDim1Size || dim2Size > maxDim2Size) {
            maxDim1Size = dim1Size;
            maxDim2Size = dim2Size;
        }
    }

    int totalDescriptors = numFiles * maxDim1Size * maxDim2Size;
    if (includeAlpha) totalDescriptors *= 3; // 2D + alpha

    uint8_t** descriptors = new uint8_t*[numFiles];
    for (int i = 0; i < numFiles; ++i) {
        descriptors[i] = new uint8_t[maxDim1Size * maxDim2Size];
    }

    int descriptorIndex = 0;
    for (const auto& filePath : filePaths) {
        std::ifstream file(filePath);
        int dim1Size, dim2Size;
        file >> dim1Size >> dim2Size;

        for (int i = 0; i < dim1Size; ++i) {
            for (int j = 0; j < dim2Size; ++j) {
                if (!includeAlpha) {
                    file.read((char*) &descriptors[i][j], sizeof(uint8_t));
                } else {
                    uint8_t alpha;
                    file >> alpha;
                    file.read((char*) &descriptors[descriptorIndex++][i][j], sizeof(uint8_t));
                }
            }
        }
    }

    return descriptors;
}

