int main() {
    char input[1000];
    fgets(input, sizeof(input), stdin);
    int rows = strlen(input);
    int cols = 1;
    for (int i = 0; i < rows; i++) {
        if (input[i] == '\n') break;
        cols += strcspn(&input[i], " ") + 1;
    }
    char board[rows][cols];
    memset(board, ' ', sizeof(board));
    int row = 0;
    for (int i = 0; i < rows; i++) {
        if (input[i] == '\n') {
            row++;
            continue;
        }
        cols = 1;
        for (int j = i; input[j] != ' '; j++) {
            if (input[j] == 'R') {
                board[row][cols - 1] = '/';
                row % 2 ? row++ : row--;
            }
            cols += strcspn(&input[j], " ") + 1;
        }
    }
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%c", board[i][j]);
        }
        printf("\n");
    }
    return 0;
}

```c
int buildGraph(char **edges, int n, int **graph) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            graph[i][j] = 0;
        }
    }

    for (char *edge = edges[0]; edge != NULL && *edge != '\0'; edge = NULL) {
        char *token = strtok(edge, " ->,");
        int u = atoi(token);
        token = strtok(NULL, " ->,");
        int v = atoi(token);

        graph[u][v] = 1;
        graph[v][u] = 1;
    }

    return connectedComponents(graph, n);
}

int connectedComponents(int **graph, int n) {
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (!isVisited(i, graph, n)) {
            dfs(i, graph, n);
            count++;
        }
    }

    return count;
}

int isVisited(int node, int **graph, int n) {
    for (int i = 0; i < n; i++) {
        if (graph[i][node] == 1) {
            return 1;
        }
    }
    return 0;
}

void dfs(int node, int **graph, int n) {
    for (int i = 0; i < n; i++) {
        if (graph[node][i] == 1 && !isVisited(i, graph, n)) {
            dfs(i, graph, n);
        }
    }
}

