```c++
string convertHostAddress(const HostAddress& address) {
    string result;
    uint16_t temp[4];

    if (address.isIPv4()) {
        for (int i = 0; i < 4; i++) {
            temp[i] = ntohs(((uint16_t*)&(address.getIP()))[i]);
        }

        for (int i = 0; i < 4; i++) {
            char buffer[5];
            sprintf(buffer, "%d.", temp[i]);
            result.append(buffer);
        }

        if (!result.empty()) {
            result.pop_back(); // remove the last dot
        }
    } else if (address.isIPv6()) {
        for (int i = 0; i < 8; i++) {
            temp[i] = ntohs(((uint16_t*)&(address.getIP()))[i]);
        }

        for (int i = 0; i < 8; i++) {
            char buffer[5];
            sprintf(buffer, "%x:", temp[i]);
            result.append(buffer);
        }

        if (!result.empty()) {
            result.pop_back(); // remove the last colon
        }
    } else {
        return "empty";
    }

    return result;
}
