#include <stdlib.h>
#include <stdio.h>
#include <math.h>

typedef struct {
    int r, g, b;
} Color;

void plasmaEffect(unsigned char* image, double width, double height, double roughness) {
    int pixelSize = 3; // size of each pixel in bytes
    int imageSize = width * height * 3; // total number of pixels
    unsigned char* pixels = (unsigned char*)image;

    Color colormap[256]; // colors for the plasma effect

    // initialize the colormap with some random colors
    srand(time(NULL));
    for(int i = 0; i < 256; i++) {
        colormap[i].r = rand() % 256;
        colormap[i].g = rand() % 256;
        colormap[i].b = rand() % 256;
    }

    // calculate the center of each section
    double sectionsX = width / 2.0;
    double sectionsY = height / 2.0;
    int sectionWidth = (int)width / 2.0;
    int sectionHeight = (int)height / 2.0;

    for(int y = 0; y < height; y++) {
        for(int x = 0; x < width; x++) {
            // calculate the distance from each pixel to the center of each section
            double distToSection1X = abs((double)x - sectionsX);
            double distToSection1Y = (double)y;
            double distToSection2X = (double)x;
            double distToSection2Y = abs((double)y - sectionsY);
            double distToSection3X = width - distToSection1X;
            double distToSection3Y = distToSection1Y;
            double distToSection4X = distToSection2X;
            double distToSection4Y = height - distToSection2Y;

            // apply the plasma effect to each pixel
            int sectionIndex = 0;
            if(distToSection1X < roughness && distToSection1Y < roughness) {
                sectionIndex = 0;
            } else if(distToSection2X < roughness && distToSection2Y < roughness) {
                sectionIndex = 1;
            } else if(distToSection3X < roughness && distToSection3Y < roughness) {
                sectionIndex = 2;
            } else {
                sectionIndex = 3;
            }

            // calculate the new color values for each pixel
            double centerX, centerY;
            switch(sectionIndex) {
                case 0:
                    centerX = sectionsX + (cos((double)x / width * 2.0 * M_PI) * distToSection1X) / roughness;
                    centerY = sectionsY + (sin((double)y / height * 2.0 * M_PI) * distToSection1Y) / roughness;
                    break;
                case 1:
                    centerX = sectionsX + (sin((double)x / width * 2.0 * M_PI) * distToSection2X) / roughness;
                    centerY = sectionsY + (cos((double)y / height * 2.0 * M_PI) * distToSection2Y) / roughness;
                    break;
                case 2:
                    centerX = width - sectionsX - (sin((double)x / width * 2.0 * M_PI) * distToSection3X) / roughness;
                    centerY = height - sectionsY - (cos((double)y / height * 2.0 * M_PI) * distToSection3Y) / roughness;
                    break;
                case 3:
                    centerX = width - sectionsX + (cos((double)x / width * 2.0 * M_PI) * distToSection4X) / roughness;
                    centerY = height - sectionsY + (sin((double)y / height * 2.0 * M_PI) * distToSection4Y) / roughness;
                    break;
            }

            // calculate the distance from each pixel to its center
            double distanceFromCenterX = centerX - (double)x;
            double distanceFromCenterY = centerY - (double)y;

            // generate a random value for each color channel
            double randomValue = (rand() % 256) / 255.0;

            // calculate the new color values using the plasma effect
            int index = (y * width * 3) + (x * 3);
            pixels[index] = colormap[(int)(((distanceFromCenterX + distanceFromCenterY) * 0.5 + randomValue) * 255.0)].r;
            pixels[index + 1] = colormap

