#include <iostream>
#include <lcbsdk/lcb.h>
#include <string>
#include <vector>

int main(int argc, char** argv) {
    if (argc < 5) {
        std::cerr << "Usage: " << argv[0] << " <server_address> <username> <password> <bucket_name> [query]" << std::endl;
        return 1;
    }

    lcb_create_st creds;
    creds.vbucket_names = NULL;
    creds.vbucket_count = 0;
    creds.username = argv[2];
    creds.password = argv[3];

    lcb_t instance;
    int ret = lcb_create(&instance, &creds);
    if (ret != LCB_SUCCESS) {
        std::cerr << "Failed to create Couchbase instance: " << lcb_strerror(ret) << std::endl;
        return 1;
    }

    lcb_connect(instance, argv[1]);

    while (lcb_wait_for_state2(instance, LCB_CONNECTED) != LCB_SUCCESS) {
        // Wait for the connection to establish
    }

    lcb_create_bucket_st bucket_creds;
    bucket_creds.name = argv[4];
    bucket_creds.create_if_missing = 1;

    ret = lcb_create_bucket(instance, &bucket_creds);
    if (ret != LCB_SUCCESS) {
        std::cerr << "Failed to create bucket: " << lcb_strerror(ret) << std::endl;
        return 1;
    }

    while (lcb_wait_for_state2(instance, LCB_BUCKET_CREATED) != LCB_SUCCESS) {
        // Wait for the bucket creation to complete
    }

    lcb_query_st query;
    char* query_str = argc >= 6 ? argv[5] : "SELECT * FROM default";
    query.query = query_str;
    query.nkeys = 0;
    query.keys = NULL;

    ret = lcb_query(instance, &query);
    if (ret != LCB_SUCCESS) {
        std::cerr << "Failed to execute query: " << lcb_strerror(ret) << std::endl;
        return 1;
    }

    while (lcb_wait_for_state2(instance, LCB_QUERY_READY) != LCB_SUCCESS) {
        // Wait for the query results
    }

    lcb_response_query_st* response = static_cast<lcb_response_query_st*>(lcb_get_query_response(instance));
    if (response->error == LCB_SUCCESS) {
        std::cout << "Query results:" << std::endl;
        for (int i = 0; i < response->num_rows; ++i) {
            lcb_row_result_st* row = &response->rows[i];
            for (int j = 0; j < row->ncols; ++j) {
                std::cout << row->cols[j].val.s << " ";
            }
            std::cout << std::endl;
        }
    } else {
        std::cerr << "Query failed: " << lcb_strerror(response->error) << std::endl;
    }

    lcb_destroy(instance);

    return 0;
}

