unsigned int getCellIdentifier(int x, int y) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<unsigned int> dis(0, 10000);

    unsigned int identifier = 0;

    // Normalize coordinates
    if (x < 0) x += 10;
    else if (x >= 10) x -= 10;
    if (y < 0) y += 5;
    else if (y >= 5) y -= 5;

    // Calculate identifier
    for (int i = 0; i < 4; ++i) {
        int digit = ((x >> i) & 1) * 2 + ((y >> i) & 1);
        identifier *= 10;
        identifier += dis(gen) % 10 + digit;
    }

    return identifier;
}
