int extractTokens(const std::string& buffer, const std::string& delimiter, const std::string& specialValue, std::vector<std::string>& tokens) {
    size_t pos = 0;
    int tokenCount = 0;

    while ((pos = buffer.find(delimiter, pos)) != std::string::npos) {
        std::string token = buffer.substr(0, pos);
        if (token != specialValue) {
            tokens.push_back(token);
            tokenCount++;
        }
        pos += delimiter.size();
    }

    return tokenCount;
}
