#include <string.h>
#include <md5.h>

int check_and_hash(char *data, int length) {
    unsigned char md[16];
    char hash[33];

    if (length < 1) return -2;
    if (length > 128*1024*1024) return -3;

    MD5_CTX c;
    MD5Init(&c);
    MD5Update(&c, data, length);
    MD5Final(md, &c);

    for (int i = 0; i < 16; i++) {
        char buf[3];
        sprintf(buf, "%02x", md[i]);
        strcat(hash, buf);
    }

    return 0;
}

```c
void cl_exec_kernel(int* input_data, int* output_data, int* temp_storage, size_t num_elements) {
    // Create OpenCL context and command queue
    cl_context = clCreateContextFromType(
        NULL,
        CL_DEVICE_TYPE_GPU,
        NULL,
        NULL,
        &error_code);
    cl_command_queue = clCreateCommandQueue(cl_context, NULL, 0, &error_code);

    // Allocate memory on the device for input_data, output_data and temp_storage
    cl_mem d_input_data = clCreateBuffer(
        cl_context,
        CL_MEM_READ_ONLY,
        num_elements * sizeof(int),
        NULL,
        &error_code);
    cl_mem d_output_data = clCreateBuffer(
        cl_context,
        CL_MEM_WRITE_ONLY,
        num_elements * sizeof(int),
        NULL,
        &error_code);
    cl_mem d_temp_storage = clCreateBuffer(
        cl_context,
        CL_MEM_READ_WRITE,
        num_elements * sizeof(int),
        NULL,
        &error_code);

    // Copy input data from host memory to device memory
    clEnqueueWriteBuffer(cl_command_queue, d_input_data, CL_TRUE, 0, num_elements * sizeof(int), input_data, 0, NULL);
    clEnqueueWriteBuffer(cl_command_queue, d_temp_storage, CL_TRUE, 0, num_elements * sizeof(int), temp_storage, 0, NULL);

    // Set kernel arguments
    clSetKernelArg(kernel, 0, sizeof(cl_mem), &d_input_data);
    clSetKernelArg(kernel, 1, sizeof(cl_mem), &d_output_data);
    clSetKernelArg(kernel, 2, sizeof(cl_mem), &d_temp_storage);

    // Execute the kernel
    size_t global_size = num_elements;
    size_t local_size = 256;
    clEnqueueNDRangeKernel(
        cl_command_queue,
        kernel,
        1,
        nullptr,
        &global_size,
        &local_size,
        0,
        NULL);
    clFinish(cl_command_queue);

    // Copy output data from device memory to host memory
    clEnqueueReadBuffer(
        cl_command_queue,
        d_output_data,
        CL_TRUE,
        0,
        num_elements * sizeof(int),
        output_data,
        0,
        NULL);

    // Release OpenCL resources
    clReleaseMemObject(d_input_data);
    clReleaseMemObject(d_output_data);
    clReleaseMemObject(d_temp_storage);
    clReleaseCommandQueue(cl_command_queue);
    clReleaseContext(cl_context);
}
