#include <iostream>
#include <chrono>
#include <random>

struct SenderState {
    int packetNumber;
    int maxPacketRate;
    std::chrono::high_resolution_clock::time_point startMonitoring;
    double rttSum = 0.0;
    int packetLossCount = 0;
};

void sendPackets(SenderState& state, int packetNumber) {
    if (packetNumber >= state.maxPacketRate * 1.7) {
        if (!state.startMonitoring) {
            std::cout << "RTT monitoring started." << std::endl;
            state.startMonitoring = std::chrono::high_resolution_clock::now();
        }
    } else if (state.startMonitoring) {
        auto now = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(now - state.startMonitoring);
        double rtt = static_cast<double>(duration.count()) / 1000.0;
        state.rttSum += rtt;
        if (packetNumber % state.maxPacketRate == 0) {
            double packetLossRate = static_cast<double>(state.packetLossCount) / packetNumber;
            std::cout << "RTT: " << state.rttSum / (packetNumber - 1) << " ms, Packet Loss Rate: " << packetLossRate * 100 << "%" << std::endl;
        }
    }

    if (state.startMonitoring && packetNumber >= state.maxPacketRate * (2.2 + static_cast<double>(rand()) / RAND_MAX)) {
        auto now = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(now - state.startMonitoring);
        double rtt = static_cast<double>(duration.count()) / 1000.0;
        state.rttSum += rtt;
        if (packetNumber % state.maxPacketRate == 0) {
            double packetLossRate = static_cast<double>(state.packetLossCount) / packetNumber;
            std::cout << "RTT: " << state.rttSum / (packetNumber - 1) << " ms, Packet Loss Rate: " << packetLossRate * 100 << "%" << std::endl;
        }
        state.startMonitoring = nullptr;
    }

    if (!state.startMonitoring && packetNumber % state.maxPacketRate == 0) {
        double packetLossRate = static_cast<double>(state.packetLossCount) / packetNumber;
        std::cout << "RTT: " << state.rttSum / (packetNumber - 1) << " ms, Packet Loss Rate: " << packetLossRate * 100 << "%" << std::endl;
    }
}
