#include <random>
#include <string>
#include <vector>

std::pair<std::vector<std::string>, size_t> generateRandomStrings(size_t numStrings, const std::vector<std::string>& baseStrings, double p) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::bernoulli_distribution dist(p);

    std::vector<std::string> randomStrings;
    size_t totalSize = 0;

    for (size_t i = 0; i < numStrings; ++i) {
        std::string randomString;

        bool first = true;
        for (const auto& baseString : baseStrings) {
            if (dist(gen)) {
                if (!first) {
                    randomString += ' ';
                }
                first = false;
                randomString += baseString;
            }
        }

        randomStrings.push_back(randomString);
        totalSize += randomString.size();
    }

    return {randomStrings, totalSize};
}

