#include <random>
#include <algorithm>

int nearTarget(int* set, int n, int target) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    int sum = 0;
    int count = 0;

    for (int i = 0; i < n; ++i) {
        if (dis(gen) < static_cast<double>(target - set[i]) / target) {
            sum += set[i];
            ++count;
        }
    }

    return std::abs(target - sum);
}

