```c
char* loadSoundFile(const char* path) {
    DIR* dir = opendir(path);
    if(dir == NULL) {
        // directory not found
        return "Error: Directory not found.";
    }

    struct dirent* ent;
    while((ent = readdir(dir)) != NULL) {
        if(strncmp(ent->d_name, "sound_", 6) == 0 && strcmp(&ent->d_name[6], ".wav") == 0) {
            char* filePath = (char*)malloc(strlen(path) + strlen(ent->d_name) + 2);
            strcpy(filePath, path);
            strcat(filePath, "/");
            strcat(filePath, ent->d_name);
            closedir(dir);

            FILE* file = fopen(filePath, "rb");
            if(file == NULL) {
                // file not found
                free(filePath);
                return "Error: File not found.";
            }

            fseek(file, 0, SEEK_END);
            int fileSize = ftell(file);
            rewind(file);

            char* soundData = (char*)malloc(fileSize + 1);
            fread(soundData, 1, fileSize, file);
            fclose(file);

            free(filePath);
            return soundData;
        }
    }

    closedir(dir);
    return "Error: File not found.";
}
