void printBuffer(void* buffer, FieldMetadata* metadata) {
    int size = metadata->size;
    bool isRepeated = (metadata->mode == REPEATED);

    switch(metadata->type) {
        case BIGINT:
            for(int i = 0; i < size; i++) {
                long long value;
                memcpy(&value, buffer + i * sizeof(long long), sizeof(long long));
                printf("BIGINT: %lld\n", value);
            }
            break;
        default:
            printf("Unsupported type.\n");
            return;
    }

    if(isRepeated) {
        switch(metadata->mode) {
            case REQUIRED:
                printf("REPEATED REQUIRED\n");
                break;
            case OPTIONAL:
                printf("REPEATED OPTIONAL\n");
                break;
            case REPEATED:
                printf("REPEATED REPEATED\n");
                break;
            default:
                printf("Invalid mode.\n");
                return;
        }
    } else {
        switch(metadata->mode) {
            case REQUIRED:
                printf("REQUIRED\n");
                break;
            case OPTIONAL:
                printf("OPTIONAL\n");
                break;
            default:
                printf("UNSPECIFIED MODE\n");
                return;
        }
    }
}
