GLuint createShader(const std::string& src) {
    GLuint shader = glCreateShader(GL_SHADER_TYPE); // GL_VERTEX_SHADER or GL_FRAGMENT_SHADER
    const char* shadersrc[1];
    shadersrc[0] = src.c_str();
    GLint lengths[1];
    lengths[0] = src.length();

    glShaderSource(shader, 1, shadersrc, lengths);
    glCompileShader(shader);

    GLint success;
    glGetShaderiv(shader, GL_COMPILE_STATUS, &success);
    if (!success) {
        GLsizei length = 0;
        GLchar *log = NULL;
        glGetShaderInfoLog(shader, 512, &length, log);
        std::cerr << "Error compiling shader: " << log << std::endl;
        glDeleteShader(shader);
        throw std::runtime_error("Failed to create shader");
    }
    return shader;
}
