template <typename T>
void testXOROperator(size_t N) {
    std::bit_set<T> bs1(N);
    std::bit_set<T> bs2(N);

    for (size_t i = 0; i < N; ++i)
        if (rand() & 1) // random 0 or 1
            bs1[i] = rand() & 1;
        else
            bs1[i] = 1 - (rand() & 1);

    for (size_t i = 0; i < N; ++i)
        if (rand() & 1) // random 0 or 1
            bs2[i] = rand() & 1;
        else
            bs2[i] = 1 - (rand() & 1);

    auto xored = bs1 ^ bs2;

    for (size_t i = 0; i < N; ++i)
        bs2 ^= bs1;

    if (!std::equal(bs1.begin(), bs1.end(), xored.begin()))
        std::cout << "XOR operator does not produce the same result.\n";
}
