std::vector<std::wstring> GetFilesInDirectory(const std::wstring& path, bool sort = false) {
    WIN32_FIND_DATA findData;
    HANDLE hFind;

    if (path.find("*") != std::wstring::npos || path.find("?") != std::wstring::npos) {
        std::vector<std::wstring> files;
        DWORD fileCount = 0;
        HANDLE hFile = FindFirstFile(path.c_str(), &findData);
        if (hFile != INVALID_HANDLE_VALUE) {
            do {
                if (!(findData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
                    files.push_back(findData.cFileName);
                }
                fileCount++;
            } while (FindNextFile(hFile, &findData));
            FindClose(hFile);
            if (!sort)
                return files;
        }

        std::vector<std::wstring> sortedFiles = files;
        std::sort(sortedFiles.begin(), sortedFiles.end());
        return sortedFiles;
    }

    WIN32_FIND_DATAW findDataW;
    HANDLE hFindW;

    hFindW = FindFirstFileExW(path.c_str(), FIND_FIRST_EX_LARGE_FOLDER, &findDataW, 0, 0, FALSE);
    if (hFindW != INVALID_HANDLE_VALUE) {
        do {
            if (!(findDataW.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
                files.push_back(findDataW.cFileName);
            }
            fileCount++;
        } while (FindNextFileExW(hFindW, FIND_NEXT_EX_LARGE_FOLDER, &findDataW, 0, 0, FALSE));
        FindCloseHandle(hFindW);
        if (!sort)
            return files;
    }

    std::vector<std::wstring> sortedFiles = files;
    std::sort(sortedFiles.begin(), sortedFiles.end());
    return sortedFiles;
}

