#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>
#include <openssl/hmac.h>

char* hmac_sha1_signature(const char* message, const char* secret_key) {
    unsigned char* output;
    int output_len;

    // Create an HMAC context using the SHA1 algorithm and the secret key
    HMAC_CTX ctx;
    HMAC_Init(&ctx, secret_key, strlen(secret_key), EVP_md5());
    HMAC_Update(&ctx, (const unsigned char*)message, strlen(message));
    HMAC_Final(&ctx, &output);

    // Get the length of the output
    output_len = (int)HMAC_get_block_size(ctx.md5_ctx);
    HMAC_CTX_free(ctx);

    // Convert the output to a base64-encoded string
    char* signature = (char*)malloc(output_len + 1);
    for(int i = 0; i < output_len; ++i)
        sprintf(&signature[i*2], "%02x", output[i]);
    signature[output_len * 2] = '\0';

    free(output);

    return signature;
}
