int test_memory_alignment(size_t size) {
    unsigned long long cache_line_size = get_cache_line_size();
    unsigned long long alignment = (size + cache_line_size - 1) & ~(cache_line_size - 1);

    void* mem = malloc(alignment);
    if (!mem)
        return NULL;

    printf("Allocated %zu bytes at address %p, expected alignment %llu\n", size, mem, alignment);

    for (int i = 0; i < 10; ++i) {
        void* addr = &((char*)mem)[i];
        if ((unsigned long long)addr % alignment != 0)
            return NULL;
    }

    free(mem);
    return mem;
}

```c
int compare_files(const char *file1, const char *file2) {
    FILE *fp1 = fopen(file1, "rb");
    FILE *fp2 = fopen(file2, "rb");

    if (!fp1 || !fp2) return 0;  // files can't be read

    while (1) {
        unsigned char b1, b2;

        fread(&b1, sizeof(b1), 1, fp1);
        fread(&b2, sizeof(b2), 1, fp2);

        if (!feof(fp1) && !feof(fp2)) {
            if (b1 != b2) return 0; // files are different
        } else {
            break;
        }
    }

    fclose(fp1);
    fclose(fp2);

    int result = feof(fp1) && feof(fp2); // files are the same

    return result;
}
