void insertAfter(const std::forward_list<std::string>& lst, const std::string& target, const std::string& toInsert) {
    auto it = lst.begin();
    bool found = false;
    while (it != lst.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }
    if (found) {
        it = lst.insert_after(it, toInsert);
    } else {
        lst.append(toInsert);
    }
}

