```c
#include <openssl/obj_mac.h>

bool isCertificateValid(ParsedCertificate* certificate, ParsedCertificate* issuer) {
    if (certificate->id.hashAlg != issuer->id.hashAlg) {
        return false;
    }

    int hashSize;
    switch (certificate->id.hashAlg) {
        case NID_sha1:
            hashSize = SHA_DIGEST_LENGTH;
            break;
        case NID_sha256:
            hashSize = SHA256_DIGEST_LENGTH;
            break;
        case NID_sha384:
            hashSize = SHA384_DIGEST_LENGTH;
            break;
        case NID_sha512:
            hashSize = SHA512_DIGEST_LENGTH;
            break;
        default:
            return false;
    }

    unsigned char* certHash = (unsigned char*) OPENSSL_malloc(hashSize);
    if (!certHash) {
        return false;
    }

    EVP_MD_CTX mdctx;
    EVP_MD *md = NULL;
    switch (certificate->id.hashAlg) {
        case NID_sha1:
            md = EVP_md_sha1();
            break;
        case NID_sha256:
            md = EVP_md_sha256();
            break;
        case NID_sha384:
            md = EVP_md_sha384();
            break;
        case NID_sha512:
            md = EVP_md_sha512();
            break;
    }

    if (!md) {
        OPENSSL_free(certHash);
        return false;
    }

    EVP_MD_CTX_init(&mdctx);
    EVP_DigestInit_ex(&mdctx, md, NULL);
    EVP_DigestUpdate(&mdctx, certificate->data, certificate->length);
    EVP_DigestFinal_ex(&mdctx, certHash, &hashSize);
    EVP_MD_CTX_cleanup(&mdctx);

    if (memcmp(certHash, certificate->signature, hashSize)) {
        OPENSSL_free(certHash);
        return false;
    }

    OPENSSL_free(certHash);
    return true;
}

