wchar_t* read_file(const char *path) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        return NULL; // file not found or unable to open for reading
    }

    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    wchar_t* contents = malloc((size_t)(fileSize + 1) * sizeof(wchar_t));
    if (contents == NULL) {
        fclose(file); // cannot allocate memory
        return NULL;
    }

    size_t bytesRead = fread(contents, sizeof(wchar_t), fileSize / sizeof(wchar_t), file);
    contents[fileSize] = L'\0'; // null-terminate the string

    if (ferror(file)) {
        free(contents);
        fclose(file); // error reading from file
        return NULL;
    }

    fclose(file);

    return contents;
}

