#include <random>

int findBestCombination(std::vector<std::pair<int, bool>>& pairs, int target) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    int max_value = -1;
    for (int i = 0; i < 1000000; ++i) { // iterate many times
        int current_value = 0;
        bool selection[static_cast<int>(pairs.size())];
        std::fill_n(selection, pairs.size(), false);

        for (const auto& pair : pairs) {
            if (!selection[pair.first] && dis(gen)) { // random selection criteria
                selection[pair.first] = true;
                current_value += pair.second;
            }
        }

        if (current_value <= target && current_value > max_value) {
            max_value = current_value;
        }
    }

    return max_value;
}
