```cpp
#include <iostream>
#include <cstdlib>
#include <ctime>

int** convolution(int** image, int filter_size, int max_pool_kernel_size, int stride) {
    // Get the dimensions of the input image
    int height = sizeof(image) / sizeof(image[0]);
    int width = sizeof(image[0]) / sizeof(image[0][0]);

    // Initialize the output buffer
    int** output;
    output = new int*[height];
    for (int i = 0; i < height; i++) {
        output[i] = new int[width];
    }

    // Randomly initialize filter and bias
    srand(time(0));
    int** filter;
    filter = new int*[(filter_size * stride)];
    for (int i = 0; i < (filter_size * stride); i++) {
        filter[i] = new int[(filter_size * stride)];
    }
    float r;
    for (int i = 0; i < (filter_size * stride); i++) {
        for (int j = 0; j < (filter_size * stride); j++) {
            r = (float)rand() / RAND_MAX;
            filter[i][j] = int(r * 10 + 1);
        }
    }

    // Initialize bias
    float* bias;
    bias = new float[1];
    for (int i = 0; i < 1; i++) {
        r = (float)rand() / RAND_MAX;
        bias[i] = int(r * 10 + 1);
    }

    // Perform convolution operation
    for (int i = 0; i < height - filter_size + 1; i++) {
        for (int j = 0; j < width - filter_size + 1; j++) {
            int sum = 0;
            for (int k = 0; k < filter_size; k++) {
                for (int l = 0; l < filter_size; l++) {
                    sum += image[i + k][j + l] * filter[k][l];
                }
            }
            output[i][j] = sum + bias[0];
        }
    }

    // Perform max pooling operation
    int pool_height = height - (max_pool_kernel_size - 1) * stride;
    int pool_width = width - (max_pool_kernel_size - 1) * stride;
    for (int i = 0; i < pool_height; i++) {
        for (int j = 0; j < pool_width; j++) {
            int max_val = output[i][j];
            for (int k = 0; k < max_pool_kernel_size; k++) {
                for (int l = 0; l < max_pool_kernel_size; l++) {
                    if (output[i + k * stride][j + l * stride] > max_val) {
                        max_val = output[i + k * stride][j + l * stride];
                    }
                }
            }
            output[i][j] = max_val;
        }
    }

    // Deallocate the memory
    for (int i = 0; i < height; i++) {
        delete[] output[i];
    }
    delete[] output;

    for (int i = 0; i < (filter_size * stride); i++) {
        delete[] filter[i];
    }
    delete[] filter;

    for (int i = 0; i < 1; i++) {
        delete[] bias;
    }

    return output;
}
