#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char **parse_tokens(char *str) {
    int len = strlen(str);
    char *token = malloc(len + 1);
    char **tokens = NULL;
    int token_count = 0;

    for (int i = 0; i < len; i++) {
        if (str[i] == ' ' || str[i] == '\t' || str[i] == '\n') {
            // ignore whitespace
            continue;
        }

        if ((str[i] >= '0' && str[i] <= '9') ||
            (str[i] == '-' && i + 1 < len && (str[i + 1] >= '0' && str[i + 1] <= '9'))) {
            // extract number or negative number
            token = &str[i];
            int j = 0;
            for (; i < len; i++) {
                if ((str[i] >= '0' && str[i] <= '9') || str[i] == '-') {
                    token[j++] = str[i];
                } else if (j > 0) {
                    break;
                }
            }
            token[j] = '\0';
            tokens = realloc(tokens, sizeof(char *) * ++token_count);
            tokens[token_count - 1] = malloc(strlen(token) + 1);
            strcpy(tokens[token_count - 1], token);

        } else if (str[i] == '\"') {
            // extract quoted string
            token = &str[i];
            i++;
            j = 0;
            for (; i < len; i++) {
                if (str[i] == '\"') {
                    break;
                }
                token[j++] = str[i];
            }
            token[j] = '\0';
            tokens = realloc(tokens, sizeof(char *) * ++token_count);
            tokens[token_count - 1] = malloc(strlen(token) + 1);
            strcpy(tokens[token_count - 1], token);

        } else {
            // ignore other characters
            continue;
        }
    }

    return tokens;
}
