    if (!fastSepAccessArray) {
        perror("Memory allocation failed for fastSepAccessArray");
        free(fastPrefixArray);
        exit(1);
    }

    uint32_t* fastLenArray = (uint32_t*)malloc(numFieldPerRow * sizeof(uint32_t));
    if (!fastLenArray) {
        perror("Memory allocation failed for fastLenArray");
        free(fastSepAccessArray);
        free(fastPrefixArray);
        exit(1);
    }

    // Initialize arrays
    for (size_t i = 0; i < numFieldPerRow; i++) {
        fastPrefixArray[i] = 0;
        fastSepAccessArray[i] = 0;
        fastLenArray[i] = 0;
