int compare(const char *s1, const char *s2) {
    int result = 0;
    while (*s1 && *s2) {
        if (islower(*s1)) {
            s1++;
            while (*s1 && isupper(*s1)) {
                s1++;
            }
        }
        else if (isupper(*s1)) {
            s1++;
            while (*s1 && islower(*s1)) {
                s1++;
            }
            *s1 = tolower(*s1);
        }
        if (tolower(*s1) == tolower(*s2)) {
            s1++;
            s2++;
            result++;
        }
        else break;
    }
    return result;
}

