#include <iostream>
#include <sstream>
#include <stdexcept>

struct Option {
    std::string name;
    std::string value;
};

void parseOptions(const std::string& input, Option options[]) {
    size_t pos = 0;
    size_t commaPos;

    for (size_t i = 0; i < 2; ++i) {
        commaPos = input.find(',', pos);
        if (commaPos == std::string::npos || commaPos >= input.size()) {
            throw std::runtime_error("Malformed options string");
        }

        size_t equalPos = input.find('=', pos, commaPos - pos);
        if (equalPos == std::string::npos) {
            throw std::runtime_error("Malformed option: " + input.substr(pos));
        }

        Option opt;
        opt.name = input.substr(pos, equalPos - pos);
        opt.value = input.substr(equalPos + 1, commaPos - equalPos - 1);

        options[i] = opt;

        pos = commaPos + 1;
    }
}
