#include <vector>
#include <cstdlib>

void percolationStep(std::vector<int>* sites, double probability, int timeStep) {
    if (sites->size() == 0) return;

    int randomIndex = rand() % sites->size();
    int siteValue = (*sites)[randomIndex];

    // Apply percolation rule based on site's index and time step
    // For example:
    if ((siteValue & (1 << (timeStep % 2))) != 0) {
        siteValue &= ~(1 << (timeStep % 2));
    } else if (rand() / static_cast<double>(RAND_MAX) < probability) {
        siteValue |= (1 << (timeStep % 2));
    }

    (*sites)[randomIndex] = siteValue;
}
