#include <string>
#include <vector>
#include <algorithm>
#include <cctype>

std::vector<std::string> extractUrlComponents(const std::string& url) {
    std::vector<std::string> components;
    size_t colonPos = url.find(':');
    if (colonPos != std::string::npos) {
        components.push_back(url.substr(0, colonPos));
        url.erase(0, colonPos + 1);
    } else {
        components.push_back("");
    }

    size_t slashPos = url.find('/');
    while (slashPos != std::string::npos) {
        if (url.size() - 1 > slashPos && isalnum(url[slashPos + 1])) {
            break;
        }
        size_t dashPos = url.find('-');
        if (dashPos != std::string::npos) {
            components.push_back(url.substr(0, dashPos));
            url.erase(0, dashPos);
            continue;
        }
        components.push_back(url.substr(0, slashPos));
        url.erase(0, slashPos + 1);
        break;
    }

    size_t colonPortPos = url.find(':');
    if (colonPortPos != std::string::npos) {
        components.push_back(url.substr(0, colonPortPos));
        url.erase(0, colonPortPos + 1);
    } else {
        components.push_back("0";
    }

    return components;
}
