int run_command_background(const char* cmd) {
    pid_t pid = fork();
    if (pid < 0) {
        return 0;
    } else if (pid == 0) { // child process
        dup2(STDIN_FILENO, STDIN_FILENO);
        dup2(STDOUT_FILENO, STDOUT_FILENO);
        dup2(STDERR_FILENO, STDERR_FILENO);
        setpgid(0, 0);
        execlp(cmd, cmd, NULL);
        return 1;
    } else { // parent process
        wait(NULL);
        return 1;
    }
}

