#define MAX_DATE_LENGTH 12
typedef struct {
    int day;
    int month;
    int year;
} Date;

Date parse_date(char* date) {
    char* p = strtok(date, ".");
    return (Date){ atoi(p), atoi(strtok(NULL, ".")), atoi(strtok(NULL, ".")) };
}

int haab_days_between(Date start, Date end) {
    int days[13] = {0, 31, 60, 90, 120, 151, 181, 212, 243, 274, 304, 334};
    return (end.year - start.year) * 365 + days[end.month] - days[start.month] - start.day;
}

int main() {
    Date current = {0, 0, 0};
    while (1) {
        char line[MAX_DATE_LENGTH];
        if (!fgets(line, MAX_DATE_LENGTH, stdin)) break;
        line[strcspn(line, "\n")] = '\0';
        Date date = parse_date(line);
        printf("%d\n", haab_days_between(current, date));
        current = date;
    }
    return 0;
}
