```
int consumeAudioData(float** audioBuffer, int* bufferPosition, float* sampleRate, int framesToRead) {
    int totalFramesRead = 0;

    while (totalFramesRead < framesToRead) {
        if (*bufferPosition >= *sampleRate) {
            break; // Buffer is empty
        }

        int currentFrameCount = min(framesToRead - totalFramesRead, *bufferPosition);

        for (int i = 0; i < currentFrameCount; ++i) {
            // Apply delay calculation based on sample rate and number of frames read so far
            audioBuffer[0][totalFramesRead + i] += (framesToRead - i) / (*sampleRate * (1.0f / currentFrameCount));
        }

        totalFramesRead += currentFrameCount;
        (*bufferPosition) -= currentFrameCount;
    }

    return totalFramesRead;
}

