std::shared_ptr<TorControlConnection> setupHiddenService(const std::string& private_key) {
    TorControlConnection conn = TorControlConnection();
    if (!conn.Connect()) {
        return nullptr;
    }

    // Set up the onion address
    std::string command = "ADD_ONION " + private_key + "\r\n";
    if (!conn.Write(command.c_str())) {
        conn.Close();
        return nullptr;
    }

    // Wait for the onion to be available
    int attempts = 0;
    while (attempts < 10) {
        std::string status = conn.Read();
        if (status.find("ONION AVAILABLE") != std::string::npos) {
            break;
        }
        sleep(1);
        attempts++;
    }

    // Configure the proxy for onion addresses
    command = "SETCONF OnionRouterPort 9050\r\n";
    if (!conn.Write(command.c_str())) {
        conn.Close();
        return nullptr;
    }

    // Authenticate with the Tor control port (may fail)
    try {
        conn.Write("AUTHENTICATE\r\n");
        conn.Read(); // Wait for the response
    } catch (...) {
        std::cerr << "Authentication failed, but we'll still proceed.\n";
    }

    return &conn;
}
