#include <iostream>
#include <string>
#include <sstream>
#include <algorithm>

std::string hmacSha256(const std::string& message, const std::string& secret) {
    std::stringstream ss;
    if (!HmacSha256(message, secret, ss)) {
        return "";
    }
    return ss.str();
}

bool HmacSha256(const std::string& message, const std::string& secret, std::stringstream& ss) {
    unsigned char key[65];
    for (int i = 0; i < 64; ++i) {
        key[i] = static_cast<unsigned char>(secret[i]);
    }
    key[64] = '\0';

    const EVP_MD* md = EVP_sha256();
    HMAC_CTX ctx;
    HMAC_CTX_init(&ctx);
    HMAC_Init_ex(&ctx, key, secret.size(), md, NULL);
    unsigned char hash[EVP_MAX_DIGEST_SIZE];
    int length = 0;

    if (HMAC_Update(&ctx, reinterpret_cast<const unsigned char*>(message.c_str()), message.size()) == 1 &&
        HMAC_Final(&ctx, hash, &length) == 1) {
        for (int i = 0; i < length; ++i) {
            ss << std::hex << (int)(hash[i]);
        }
    } else {
        return false;
    }

    HMAC_CTX_cleanup(&ctx);
    return true;
}
