```cpp
float** computeDifferences(int LLBytes, int height) {
    float** arr = new float*[LLBytes];
    for (int i = 0; i < LLBytes; i++) {
        arr[i] = new float[height];
    }

    for (int i = 0; i < LLBytes; i++) {
        for (int j = 0; j < height; j++) {
            if (i == 0) { // top row, no North
                arr[i][j] = 0;
            } else if (i == LLBytes - 1) { // bottom row, no South
                arr[i][j] = 0;
            } else {
                arr[i][j] = (arr[i-1][j] - arr[i+1][j]); // North-South difference
            }
        }
    }

    for (int i = 0; i < LLBytes; i++) {
        for (int j = 0; j < height; j++) {
            if (i == 0 || j == 0) { // top-left corner, no West and North
                arr[i][j] = 0;
            } else if (i == LLBytes - 1 || j == height - 1) { // bottom-right corner, no East and South
                arr[i][j] = 0;
            } else {
                arr[i][j] += (arr[i-1][j-1] - arr[i-1][j+1] - arr[i+1][j-1] + arr[i+1][j+1]); // North-East-South-West difference
            }
        }
    }

    for (int i = 0; i < LLBytes; i++) {
        for (int j = 0; j < height; j++) {
            if (i == 0) { // top row, no West
                arr[i][j] /= 2;
            } else if (i == LLBytes - 1) { // bottom row, no East
                arr[i][j] /= 2;
            }
        }
    }

    return arr;
}
