#include <iostream>
#include <fstream>
#include <vector>

using namespace std;

struct DataPoint {
    double x, y;
};

double linearRegression(const vector<DataPoint>& data) {
    int n = data.size();
    double sum_x = 0, sum_y = 0, sum_xy = 0, sum_x2 = 0;

    for (const auto& point : data) {
        sum_x += point.x;
        sum_y += point.y;
        sum_xy += point.x * point.y;
        sum_x2 += point.x * point.x;
    }

    double m = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x);
    double b = (sum_y - m * sum_x) / n;

    return m;
}

int main() {
    ifstream file("data.txt");
    vector<DataPoint> data;

    if (!file.is_open()) {
        cout << "File not found!" << endl;
        return 1;
    }

    int n;
    file >> n;

    for (int i = 0; i < n; ++i) {
        DataPoint point;
        file >> point.x >> point.y;
        data.push_back(point);
    }

    double m = linearRegression(data);

    cout << "Number of data points: " << n << endl;
    cout << "Linear Regression Coefficient (m): " << m << endl;

    return 0;
}

