void dynamicArray(int** arr, int& size, int newElement) {
    int* newArr = new int[size + 1];
    if (newArr == nullptr) {
        cout << "Memory not allocated. Array size exceeded." << endl;
        return;
    }

    for (int i = 0; i < size; i++) {
        newArr[i] = arr[i];
    }
    newArr[size] = newElement;

    if (arr != nullptr) {
        delete[] arr;
    }

    arr = newArr;
    size++;
}

