std::list<Alert> getSessionAlerts(Session& session, bool flag) {
    // Save the state of the session object
    session.saveState();

    // Create an empty list to store alert objects
    std::list<Alert> alerts;

    while (true) {
        // Pop an alert object from the session object
        Alert alert = session.popAlert();

        if (alert.isEmpty()) break; // No more alerts

        // Add the alert object to the list
        alerts.push_back(alert);
    }

    return alerts;
}
