Mesh deepCopy(const Mesh& m) {
    int numVertices = m.numVertices;
    Vertex** vertices = new Vertex*[numVertices];
    for (int i = 0; i < numVertices; ++i) {
        vertices[i] = new Vertex(*m.vertices[i]);
    }

    int numIndices = m.numIndices;
    int* indices = new int[numIndices];
    std::copy(m.indices, m.indices + numIndices, indices);

    return Mesh(vertices, numVertices, indices, numIndices);
}
