std::allocator<char> testAllocator;

void printAllocations(int verb) {
    const int sizes[] = { 1, 2, 3, 4, 5 };
    const char* names[] = { "One", "Two", "Three", "Four", "Five" };

    for (int i = 0; i < sizeof(sizes) / sizeof(int); ++i) {
        if (!verb)
            std::cout << names[i] << ": ";
        auto ptr = testAllocator.allocate(sizes[i]);
        if (verb) {
