#include <cuda_runtime.h>
#include <Eigen/Dense>

__global__ void matvec_kernel(int* A, float* v, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        v[idx] = 0.0f;
        for (int i = 0; i < N; i++) {
            v[idx] += A[idx*N+i]*v[i];
        }
    }
}

void sparse_matrix_eigenvectors(int** A, int N, float** eigenvalues, float** eigenvectors) {
    int* dev_A;
    cudaMalloc((void**)&dev_A, sizeof(int)*N*N);
    cudaMemcpy(dev_A, *A, sizeof(int)*N*N, cudaMemcpyHostToDevice);

    int numNonZeroElements = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (A[i][j] != 0) {
                numNonZeroElements++;
            }
        }
    }

    float* dev_v, *h_v;
    h_v = new float[N];
    cudaMalloc((void**)&dev_v, sizeof(float)*N);
    cudaMemcpy(dev_v, h_v, sizeof(float)*N, cudaMemcpyHostToDevice);

    Eigen::EigenSolver<Eigen::MatrixXf> es(Eigen::Map<Eigen::MatrixXf>(dev_A, N, N));
    eigenvalues[0] = new float[es.info().eigenvectors().rows()];
    eigenvectors[0] = new float[es.info().eigenvectors().cols()];

    for (int i = 0; i < es.info().eigenvectors().rows(); i++) {
        cudaMemcpy(eigenvalues[0]+i, &es.eigenvalues()(i), sizeof(float), cudaMemcpyDeviceToHost);
        cudaMemcpy(eigenvectors[0], es.info().eigenvectors().col(i).data(), sizeof(float)*N, cudaMemcpyDeviceToHost);
    }

    delete[] h_v;
    cudaFree(dev_A);
    cudaFree(dev_v);

    int minEigenvalue = *std::min_element(&eigenvalues[0][0], &eigenvalues[0][numNonZeroElements]);
    int maxEigenvalue = *std::max_element(&eigenvalues[0][0], &eigenvalues[0][numNonZeroElements]);

    cout << "Interval of eigenvalues: [" << minEigenvalue << ", " << maxEigenvalue << "]" << endl;
}

