void format_double_json_value(json_object *json_obj, char *printbuf) {
    double val = json_object_get_double(json_obj);
    if (isnan(val)) {
        snprintf(printbuf, sizeof(char) * 16, "NaN");
    } else if (isinf(val)) {
        if (val > 0) {
            snprintf(printbuf, sizeof(char) * 10, "Infinity");
