#include <openssl/evp.h>
#include <openssl/aes.h>

int derive_key(const char *password, const char *salt, int rounds, int method) {
    EVP_PKEY *pkey = NULL;
    unsigned char *pwd = (unsigned char *) password;
    unsigned char *sld = (unsigned char *) salt;
    unsigned char *key = NULL;
    unsigned char *iv = NULL;
    int key_len = 0;
    int iv_len = 0;

    if (!(pkey = EVP_PKEY_new())) {
        return 0; // failure
    }

    if (!EVP_DeriveBytes(pkey, method, pwd, strlen(password), sld, strlen(salt))) {
        EVP_PKEY_free(pkey);
        return 0; // failure
    }

    switch (method) {
        case 0: // PBKDF2-HMAC-SHA1
            if (!PKCS5_PBKDF2(pwd, strlen(password), sld, strlen(salt), rounds, 32, &key, &iv)) {
                EVP_PKEY_free(pkey);
                return 0; // failure
            }
            break;
        case 1: // PBKDF2-HMAC-SHA256
            if (!PKCS5_PBKDF2_HMAC_SHA256(pwd, strlen(password), sld, strlen(salt), rounds, 32, &key, &iv)) {
                EVP_PKEY_free(pkey);
                return 0; // failure
            }
            break;
        default:
            EVP_PKEY_free(pkey);
            return 0; // failure
    }

    key_len = AES_KEY_size(0);
    iv_len = AES_BLOCK_SIZE;

    if (AES_set_encrypt_key(key, key_len, NULL) || AES_set_decrypt_iv(iv, iv_len, NULL)) {
        EVP_PKEY_free(pkey);
        OPENSSL_free(key);
        OPENSSL_free(iv);
        return 0; // failure
    }

    EVP_PKEY_free(pkey);

    return 1; // success
}
