#include <unistd.h>
#include <stdlib.h>
#include <string.h>

char* read_stdout(int child_pid) {
    char buffer[1024];
    int chars_read;
    FILE* pipe = fopen("/dev/fd/" + itoa(child_pid), "r");
    char* output = NULL;
    size_t total_chars = 0;

    while ((chars_read = fread(buffer, 1, 1024, pipe)) > 0) {
        buffer[chars_read] = '\0';
        output = realloc(output, (total_chars + chars_read + 1) * sizeof(char));
        memcpy((output + total_chars), buffer, chars_read);
        total_chars += chars_read;
    }

    fclose(pipe);

    if (!output) output = strdup("");
    else output[total_chars] = '\0';

    return output;
}

