int initAudioUnit(float sampleRate) {
    // Allocate memory for the buffer
    AudioBufferList* buffer = new AudioBufferList();

    // Set up the audio stream format
    buffer->mNumberBuffers = 1;
    buffer->mBuffers[0].mNumberChannels = 2; // Stereo
    buffer->mBuffers[0].mDataByteSize = sampleRate * 4; // Assuming 32-bit float samples
    buffer->mBuffers[0].mFormatID = kAudioFormatLinearPCM;
    buffer->mBuffers[0].mFormatFlags = kAudioFormatFlagIsSignedInteger | kAudioFormatFlagIsPacked;

    // Set up the audio unit's scope and reset the processing state
    AURenderCallbackStruct inputCallback;
    inputCallback.inputProc = NULL;
    inputCallback.inputProcRefCon = this;
    AudioUnitSetProperty(audioUnit, kAudioUnitProperty_MonitorBasedProc,
                          kAudioUnitScope_Global, 0, &inputCallback, sizeof(AURenderCallbackStruct));

    // Reset the audio unit's processing state
    AudioUnitReset(audioUnit, false);

    // Check if any errors occurred during initialization
    if (error != noErr) {
        return error;
    }

    return 0;
}
