float* compute_normals(float* points, int n) {
    float* normals = alloca(n * sizeof(float));
    for (int i = 0; i < n - 2; i++) {
        float dx = points[i*3+1] - points[(i+1)*3+1];
        float dy = points[i*3+2] - points[(i+1)*3+2];
        float length = sqrtf(dx*dx + dy*dy);
        normals[i*3+0] = dx / length;
        normals[i*3+1] = dy / length;
        normals[i*3+2] = 0.0f;
    }
    return normals;
}

