int receiveAndReply(int sockfd) {
    char buffer[256];
    int bytesReceived;
    int userId;
    char *pData = buffer;

    // Receive message from socket
    bytesReceived = recv(sockfd, buffer, 255, 0);

    if (bytesReceived < 0) {
        return -1; // Error receiving data
    }

    // Extract user ID from message
    userId = *(int *)pData;
    pData += sizeof(int); // Move pointer to start of message

    // Append reply to message
    sprintf(pData, "Your ID is %d", userId);

    // Calculate size of reply message
    int dataSize = strlen(pData) + 1;

    // Send reply back to sender
    BREPLYX(sockfd, &dataSize);
}

