int** bfs(int **graph, int numNodes, int startNode) {
    if (numNodes <= 0 || graph == NULL || startNode < 0 || startNode >= numNodes) {
        return NULL;
    }

    int* visited = (int*)malloc((numNodes) * sizeof(int));
    for (int i = 0; i < numNodes; i++) {
        visited[i] = 0;
    }

    int* queue = (int*)malloc(numNodes * sizeof(int));
    int front = 0, rear = 0;

    int** path = (int**)malloc((numNodes) * sizeof(int*));
    for (int i = 0; i < numNodes; i++) {
        path[i] = (int*)malloc((numNodes + 1) * sizeof(int));
    }

    int dist[numNodes];
    for (int i = 0; i < numNodes; i++) {
        if (i == startNode)
            dist[i] = 0;
        else
            dist[i] = INT_MAX;
    }

    path[0][0] = -1;
    path[0][1] = startNode;

    queue[rear++] = startNode;
    visited[startNode] = 1;

    while (front != rear) {
        int current = queue[front++];
        for (int i = 0; i < numNodes; i++) {
            if (graph[current][i] && !visited[i]) {
                if (dist[i] > dist[current] + 1) {
                    dist[i] = dist[current] + 1;
                    path[i][0] = current;
                    queue[rear++] = i;
                    visited[i] = 1;
                }
            }
        }
    }

    int* shortestPath = (int*)malloc((numNodes - 1) * sizeof(int));
    int len = 0, current = startNode;
    while (current != -1) {
        shortestPath[len++] = current;
        current = path[current][0];
    }
    shortestPath[len] = -1;

    for (int i = 0; i < numNodes; i++) {
        free(path[i]);
    }
    free(path);
    free(queue);
    free(visited);

    return shortestPath;
}

