int estimateStorage(double threshold, int numSequences) {
    double estimatedBytes = 1024 * pow(2, (log(threshold) / log(2.0)) + log(numSequences) / log(2.0));
    int estimatedKB = static_cast<int>(estimatedBytes / 1024);
    if (estimatedKB >= 1073741824) {
        return estimatedBytes / 1099511627776;
    } else if (estimatedKB >= 1048576) {
        return estimatedBytes / 1024 / 1024;
    } else if (estimatedKB >= 1024) {
        return estimatedBytes / 1024;
    }
    printf("Estimated storage required: %.2f TB for %d sequences with threshold %f.\n", estimatedBytes / 1099511627776, numSequences, threshold);
    return static_cast<int>(estimatedBytes / 1099511627776);
}
