int kNNsearch(const std::vector<Eigen::Vector3f>& points, const Eigen::Vector3f& queryPoint, float queryRadius, int K) {
  flann::Matrix<float>(points.size(), 3) matrix;
  for (size_t i = 0; i < points.size(); ++i) {
    matrix[i][0] = points[i](0);
    matrix[i][1] = points[i](1);
    matrix[i][2] = points[i](2);
  }

  flann::AutoregressiveIndexParams params;
  params.buildMethod = flann::KDTree;
  flann::Index idx(&matrix, 3, flann::MEAN, flann::Euclidean<float>());
  idx.build(params);

  int numNeighbors = idx.knnSearch(queryPoint[0], queryPoint[1], queryPoint[2], K, 1);
  return numNeighbors;
}
