#include <stdio.h>
#include <stdlib.h>

typedef struct TrieNode {
    char c;
    int count;
    struct TrieNode* failure;
    struct TrieNode** children;
} TrieNode;

TrieNode* create_node(char c) {
    TrieNode* node = (TrieNode*)malloc(sizeof(TrieNode));
    node->c = c;
    node->count = 0;
    node->failure = NULL;
    node->children = (TrieNode**)calloc(128, sizeof(TrieNode*)); // assuming ASCII characters
    return node;
}

int insert_node(TrieNode** root, char* str, int index) {
    if (*root == NULL) {
        *root = create_node(str[index]);
    }
    else {
        TrieNode* node = *root;
        while (node->children[(int)(str[index] - '0')] == NULL) {
            node->children[(int)(str[index] - '0')] = create_node(str[index]);
            node = node->children[(int)(str[index] - '0')];
        }
        node->count++;
    }
}

void count_occurrences(TrieNode* root, int* occurrences) {
    for (int i = 0; i < 128; i++) {
        if (root->children[i] != NULL) {
            occurrences[i]++;
        }
    }
}

int main() {
    char str[] = "hello";
    TrieNode* root = NULL;
    int index = 0;
    while (str[index]) {
        insert_node(&root, str, index);
        index++;
    }
    int occurrences[128] = {0};
    count_occurrences(root, occurrences);
    for (int i = 0; i < 128; i++) {
        printf("%c: %d\n", (char)(i + '0'), occurrences[i]);
    }
    return 0;
}
