int reduce_list(int* entries, int n_entries) {
    int* unique_entries = NULL;
    int n_unique_entries = 0;

    // Check for empty list
    if (n_entries == 0) {
        return 0;
    }

    // Create a hash table to keep track of unique entries
    bool* is_unique = calloc(n_entries, sizeof(bool));
    for (int i = 0; i < n_entries; i++) {
        is_unique[i] = true;
    }

    // Iterate over the list and eliminate duplicates
    for (int i = 1; i < n_entries; i++) {
        if (entries[i] == entries[i-1]) {
            is_unique[i] = false;
        }
    }

    // Create a new array to store unique entries
    int* temp_entries = NULL;
    for (int i = 0; i < n_entries; i++) {
        if (is_unique[i]) {
            n_unique_entries++;
        }
    }
    if ((temp_entries = calloc(n_unique_entries, sizeof(int))) == NULL) {
        return -1;
    }

    // Sort the unique entries
    int j = 0;
    for (int i = 0; i < n_entries; i++) {
        if (is_unique[i]) {
            temp_entries[j] = entries[i];
            j++;
        }
    }
    qsort(temp_entries, n_unique_entries, sizeof(int), compare);

    // Update the unique_entries pointer
    free(is_unique);
    is_unique = NULL;
    for (int i = 0; i < n_entries; i++) {
        if (!is_unique[i]) {
            entries[i] = temp_entries[j-1];
            j--;
        }
    }
    free(temp_entries);

    return n_unique_entries;
}

int compare(const void* a, const void* b) {
    int* i = (int*)a;
    int* j = (int*)b;
    if (*i > *j) {
        return 1;
    } else if (*i < *j) {
        return -1;
    }
    return 0;
}
