int parse_endpoint(char* endpoint_id) {
    int len = strlen(endpoint_id);
    char* token = strtok(endpoint_id, "/");

    if (token == NULL || strcmp(token, "endpoint") != 0) {
        return -1; // invalid input
    }

    token = strtok(NULL, "/");
    if (token == NULL || sscanf(token, "%d", &len) != 1 || len < 1) {
        return -2; // invalid input
    }

    char* format;
    if (asprintf(&format, "/%s/%d", token, len) == -1) {
        return -3; // allocation error
    }

    free(format);
    return 0; // success
}
