```c
#include <inttypes.h>

uint64_t waystochoose(uint8_t n, uint8_t m, int8_t *memo) {
    if (m > n)
        return 0;
    else if (n == 0 || m <= 1)
        return 1;
    else if (memo[n*26 + m] != -1)
        return memo[n*26 + m];

    uint64_t ways = waystochoose(n-1, m-1, memo) * (2*n);
    for (int8_t i = 'A'; i <= 'Z'; ++i) {
        if (n > 0 && !strchr("AEIOUY", i)) 
            ways += waystochoose(n-1, m-1, memo);
    }

    memo[n*26 + m] = ways;
    return ways;
}
