#include <thread>
#include <vector>

void renderImage(Camera& camera, ViewModel& view_model, std::vector<std::vector<Color>>& image) {
    int width = image.size();
    int height = image[0].size();

    // Create a thread pool to parallelize the rendering process
    size_t num_threads = 4;
    std::vector<std::thread> threads(num_threads);

    for (int i = 0; i < width; ++i) {
        for (int j = 0; j < height; ++j) {
            int index = i * width + j;
            Color pixel_color;

            // Use a thread pool to calculate the color of each pixel
            auto thread_func = [&] {
                auto x = camera.GetPixelX(index);
                auto y = camera.GetPixelY(index);
                pixel_color = camera.GetPixelColor(x, y, view_model);
            };
            threads[i % num_threads].emplace([=, &index, &pixel_color]() mutable { thread_func(); });
        }
    }

    // Wait for all the threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    // Now that we have the pixel colors, put them into the 2D array
    for (int i = 0; i < width; ++i) {
        for (int j = 0; j < height; ++j) {
            int index = i * width + j;
            image[i][j] = threads[index % num_threads].get().pixel_color;
        }
    }
}
