char *parse_name_value(char *str) {
    char *name = str;
    char *value = str;

    while (*str == ' ') {
        str++;
    }

    if (*str == '\0') return NULL;

    char *end_name = str;
    while (*end_name != ':') {
        if (*end_name == '\0') return NULL;
        end_name++;
    }

    *end_name = '\0';
    name = str;
    value = end_name + 1;

    while (*value == ' ') {
        value++;
    }

    return name;
}

