void aggregateIntegers(int key, int* integers, int n, char* buffer) {
    int len = snprintf(buffer, 256, "AGGREGATED-OUTPUT[%d]: ", key);
    if (len < 0 || len >= 256) {
        return; // error message would be too large
    }
    for (int i = 0; i < n; i++) {
        int tempLen = snprintf(buffer + len, 256 - len, "%d", integers[i]);
        if (tempLen < 0 || tempLen >= 256 - len) {
            return; // error message would be too large
        }
        if (i < n-1) {
            len += strlen(buffer + len);
            int commaLen = snprintf(buffer + len, 256 - len, ", ");
            if (commaLen < 0 || commaLen >= 256 - len) {
                return; // error message would be too large
            }
            len += commaLen;
        }
    }
}

