#include <vector>
#include <algorithm>
#include <random>

std::vector<std::vector<float>> createRandomInputMatrix(int batchSize, int dim1, int dim2, bool isDense, bool isSequence) {
    std::vector<std::vector<float>> inputMatrix;

    if (isSequence) {
        for (int i = 0; i < batchSize; i++) {
            std::vector<float> sequenceVector(dim2);
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_real_distribution<float> dis(0.0, 1.0);

            for (int j = 0; j < dim2; j++) {
                sequenceVector[j] = dis(gen);
            }

            inputMatrix.push_back(sequenceVector);
        }
    } else if (isDense) {
        for (int i = 0; i < batchSize; i++) {
            std::vector<float> denseVector(dim1 * dim2);
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_real_distribution<float> dis(0.0, 1.0);

            for (int j = 0; j < dim1 * dim2; j++) {
                denseVector[j] = dis(gen);
            }

            inputMatrix.push_back(denseVector);
        }
    } else { // sparse data
        for (int i = 0; i < batchSize; i++) {
            std::vector<float> sparseVector(dim1 * dim2, 0.0f);
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_real_distribution<float> dis(0.0, 1.0);

            for (int j = 0; j < dim1 * dim2; j++) {
                if ((rand() % 2) == 0) { // random chance to make the entry non-zero
                    sparseVector[j] = dis(gen);
                }
            }

            inputMatrix.push_back(sparseVector);
        }
    }

    return inputMatrix;
}

