#include <stdlib.h>
#include <stdio.h>

void topic_modeling(double **wp, double **dp, int *nc, int *nv, double ***probs) {
    int i, j, k;
    int wtot = 0; // total number of words in the vocabulary
    int ztot[nc]; // total number of words in each topic

    for (i = 0; i < nc; i++) {
        ztot[i] = 0;
        for (j = 0; j < nv; j++) {
            if (dp[j][i] > 0) {
                wtot++;
                break;
            }
        }
    }

    *probs = (double **)malloc(wtot * sizeof(double *));
    (*probs)[0] = (double *)malloc((nc + 1) * sizeof(double));
    for (k = 1; k <= wtot; k++) {
        (*probs)[k] = &((*probs)[0][k]);
    }

    for (i = 0; i < wtot; i++) {
        double sumdp = 0;
        for (j = 0; j < nc; j++) {
            (*probs)[i][j] = dp[i / (nc + 1)][j];
            sumdp += dp[i / (nc + 1)][j];
        }
        if (sumdp > 0) {
            for (j = 0; j < nc; j++) {
                (*probs)[i][j] /= sumdp;
            }
        }
    }

    double ztot_sum = 0;
    for (i = 0; i < wtot; i++) {
        ztot_sum += dp[i / (nc + 1)][i % (nc + 1)];
    }
    printf("ztot_sum: %f\n", ztot_sum);

    free((*probs)[0]);
    free(*probs);
}
