#include <vector>
#include <cmath>

std::vector<std::vector<double>> addBorder(const std::vector<std::vector<double>>& arr, double border) {
    int rows = arr.size();
    int cols = arr[0].size();

    // Create a new array with the correct size
    std::vector<std::vector<double>> result(rows + 2, std::vector<double>(cols + 2));

    // Fill the result array with the input values and border value
    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= cols; ++j) {
            if (border == 0.0) {
                result[i][j] = arr[i - 1][j - 1];
            } else {
                result[i][j] = arr[i - 1][j - 1] + border;
            }
        }
    }

    return result;
}

