int parseBinaryFile(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // error opening file
    }

    int numBlocks = 0;
    fseek(file, 0, SEEK_END);
    int fileSize = ftell(file);
    rewind(file);

    while (ftell(file) < fileSize) {
        unsigned char blockMarker[4];
        fread(blockMarker, 1, 4, file);
        if (!memcmp(blockMarker, "BLOC", 4)) {
            numBlocks++;
        }
    }

    int *blockIndices = malloc(numBlocks * sizeof(int));
    if (blockIndices == NULL) {
        return -2; // error allocating memory
    }

    fseek(file, 0, SEEK_END);
    int fileSizeAgain = ftell(file);

    for (int i = 0; i < numBlocks; i++) {
        int blockIndex;
        fread(&blockIndex, sizeof(int), 1, file);
        blockIndices[i] = blockIndex;
    }

    fclose(file);

    return numBlocks;
}
