#include <vector>
#include <cmath>

std::vector<std::vector<unsigned char>> applyGaussianFilter(int rows, int cols, int kernelRows, int kernelCols, const std::vector<std::vector<float>>& kernel) {
    std::vector<std::vector<unsigned char>> filteredImage(rows, std::vector<unsigned char>(cols));
    float sum = 0.0f;
    for (int i = 0; i < kernelRows; ++i) {
        for (int j = 0; j < kernelCols; ++j) {
            sum += kernel[i][j];
        }
    }

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            float pixelValue = 0.0f;
            for (int x = -1; x <= 1; ++x) {
                int row = i + x;
                if (row < 0 || row >= rows) continue;
                for (int y = -1; y <= 1; ++y) {
                    int col = j + y;
                    if (col < 0 || col >= cols) continue;

                    float kernelValue = 0.0f;
                    for (int k = -1; k <= 1; ++k) {
                        int rowKernel = i + x + k;
                        if (rowKernel < 0 || rowKernel >= rows) continue;
                        for (int l = -1; l <= 1; ++l) {
                            int colKernel = j + y + l;
                            if (colKernel < 0 || colKernel >= cols) continue;

                            pixelValue += static_cast<float>(filteredImage[rowKernel][colKernel]) * kernel[k+1][l+1] / sum;
                        }
                    }
                }
            }
            filteredImage[i][j] = static_cast<unsigned char>(pixelValue);
        }
    }

    return filteredImage;
}

