void setupRealSense(Camera *camera) {
  rs2::configure(camera->get_device());
  camera->start();

  // Get the first colorizer
  auto pc = realsense::pointcloud2("depth_point_cloud", *camera);
  pc.start();

  rs2::video_frame_colorize *colorizer;
  colorizer = camera->query_stream(rts2::stream::color).front();

  // Allocate memory for frame buffers
  rs2::frame buffer;
  pc.set_buffer(buffer);

  // Advertise topics
  ros::NodeHandle nh;

  // Publish the point cloud data
  ros::Publisher pub_cloud = nh.advertise<sensor_msgs::PointCloud2>("depth_point_cloud", 10);
  pc.pub_ = &pub_cloud;

  // Publish the image data
  ros::Publisher pub_image = nh.advertise<sensor_msgs::Image>("rgb_image", 10);
  colorizer->pub_ = &pub_image;
}

