void addBlit(int width, int height, int x, int y, int* pixels, float* alpha) {
    for (int yoff = 0; yoff < height; ++yoff) {
        int pixelOffset = y * width + x;
        for (int xoff = 0; xoff < width; ++xoff) {
            if (pixelOffset >= 0 && pixelOffset < width*pixels.size()) {
                pixels[pixelOffset] += alpha[yoff*width + xoff];
            }
            pixelOffset++;
        }
    }
}
