template <typename T>
std::variant& operator=(T&& RHS) {
    using Index = std::tuple_size<decltype(std::index_sequence())>::value - 1;
    if constexpr (std::is_same_v<T, std::remove_reference_t<decltype(*std::addressof(RHS))>>) {
        if (std::holds_alternative<std::remove_reference_t<decltype(*std::addressof(RHS))>>(*this))
            std::get<std::remove_reference_t<decltype(*std::addressof(RHS))>>>(*this) = RHS;
        else
            throw std::invalid_argument("Unsupported type");
    } else {
        static_assert(std::is_same_v<T, T>, "Invalid use of std::variant assignment operator");
    }
    return *this;
}

