void isPairwiseConnected(vector<int>& v1, vector<int>& v2) {
    vector<int> parent(10001); // assuming max element in both vectors is 10000
    for(int i=0; i<parent.size(); i++) {
        parent[i] = i;
    }

    for(int i=0; i<v1.size(); i++) {
        int x = v1[i];
        for(int j=0; j<v2.size(); j++) {
            if(x == v2[j]) {
                int y = v2[j];
                while(parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                while(parent[y] != y) {
                    parent[y] = parent[parent[y]];
                    y = parent[y];
                }
                if(x == y) {
                    cout << "Connected";
                } else {
                    cout << "Not Connected";
                }
            }
        }
    }
}
