std::pair<std::vector<std::string>, int> generateStrings(const std::string& baseString, int minInt, int maxInt) {
    std::vector<std::string> result;
    int totalSize = 0;

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minInt, maxInt);

    for (int i = 0; i < 10; ++i) {
        std::ostringstream oss;
        oss << baseString << dis(gen);
        result.push_back(oss.str());
        totalSize += result.back().size();
    }

    return {result, totalSize};
}
