    printf("Thread has acquired the lock.\n");

    for(i=0; i<10; i++) {
        // Simulate some work
        usleep(10000);
    }

    printf("Thread is releasing the lock...\n");
    pthread_mutex_unlock(mutex);
    printf("Thread has released the lock.\n");

    return NULL;
}

int main() {
    pthread_mutex_t mutex;

    pthread_mutex_init(&mutex, NULL);

    pthread_t thread;

    pthread_create(&thread, NULL, &thread_func, &mutex);

    // Simulate some work
    usleep(1000000);

    printf("Main is releasing the lock...\n");
    pthread_mutex_unlock(&mutex);
    printf("Main has released the lock.\n");

    return 0;
}

