#include <stdio.h>
#include <stdlib.h>

void parseIndexFile(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL)
        return;

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    char *buffer = malloc((size_t)fileSize + 1);
    if (buffer == NULL)
        return;

    fread(buffer, 1, fileSize, file);
    buffer[fileSize] = '\0';

    fclose(file);

    int maxPieces = 0;
    for (int i = 0; i < fileSize; i++) {
        char pieceType = buffer[i];
        if (pieceType == 'P') {
            int piecesCount = 0;
            while (i + 1 < fileSize && buffer[i+1] >= '0' && buffer[i+1] <= '9') {
                piecesCount *= 10;
                piecesCount += buffer[i+1] - '0';
                i++;
            }
            if (piecesCount > maxPieces)
                maxPieces = piecesCount;
        }
    }

    free(buffer);
}
