#include <bitset>
#include <random>

std::bitset<64>& setBits(std::bitset<64>& bits, double probability) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::bernoulli_distribution d(probability);

    for (size_t i = 0; i < 64; ++i)
        bits[i] = static_cast<std::uint8_t>(d(gen));

    return bits;
}

