```cpp
bool canAllocateMemory(void* memBlock, size_t pageSize, std::vector<void*>& existingMemBlocks) {
    size_t memBlockStart = (size_t)memBlock;
    for (auto& existingMemBlock : existingMemBlocks) {
        size_t existingMemBlockStart = (size_t)existingMemBlock;
        if (memBlockStart >= existingMemBlockStart + ((size_t)existingMemBlock + pageSize - 1) / pageSize * pageSize) continue;
        if (memBlockStart + pageSize <= existingMemBlockStart) return false;
        size_t overlapSize = std::min((size_t)memBlock + pageSize - memBlockStart, existingMemBlockStart + pageSize - (size_t)existingMemBlock);
        if (overlapSize > 0) return false;
    }
    return true;
}
