int format_and_call_callback(const char *format, ...) {
    va_list args;
    va_start(args, format);

    int len = vsnprintf(NULL, 0, format, args);
    if (len < 0) return -1;

    char *buf = NULL;
    if ((buf = malloc(len + 1)) == NULL)
