#include <map>
#include <vector>
#include <algorithm>

std::vector<std::pair<int, int>> sortedOutputCounts(const std::map<int, int>& statistics, const std::vector<int>& counts) {
    std::vector<std::pair<int, int>> outputCounts;
    for (int i = 0; i < counts.size(); ++i) {
        outputCounts.push_back({i, counts[i]});
    }
    std::sort(outputCounts.begin(), outputCounts.end(),
              [&statistics](const auto& a, const auto& b) -> bool {
                  return statistics.find(a.second)->second > statistics.find(b.second)->second;
              });
    return outputCounts;
}

