#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 9
#define MAX_TEXT_LENGTH 1000

void encrypt(char *text, char *key) {
    for (int i = 0; i < strlen(text); i++) {
        if (text[i] >= 'a' && text[i] <= 'z') {
            text[i] = key[(text[i] - 'a') % KEY_SIZE];
        } else if (text[i] >= 'A' && text[i] <= 'Z') {
            text[i] = toupper(key[(text[i] - 'A') % KEY_SIZE]);
        }
    }
}

int main() {
    char text[MAX_TEXT_LENGTH + 1], key[KEY_SIZE + 1];

    printf("Enter the text to encrypt: ");
    fgets(text, MAX_TEXT_LENGTH + 1, stdin);
    text[strlen(text) - 1] = '\0'; // remove newline character

    printf("Enter the encryption key (up to %d characters): ", KEY_SIZE);
    fgets(key, KEY_SIZE + 1, stdin);
    key[KEY_SIZE] = '\0'; // null-terminate the string

    encrypt(text, key);

    printf("Encrypted text: %s\n", text);

    return 0;
}
