public static Dictionary<string, string> ExtractParameters(string xmlString)
{
    Dictionary<string, string> parameters = new Dictionary<string, string>();
    using (TextReader reader = new MemoryStream(Encoding.UTF8.GetBytes(xmlString)).CreateReader())
    {
        XmlReaderSettings settings = new XmlReaderSettings();
        settings.IgnoreWhitespace = true;
        settings.IgnoreComments = true;
        settings.IgnoreCase = true;

        using (XmlReader xmlReader = XmlReader.Create(reader, settings))
        {
            bool inHeader = true;
            while (xmlReader.Read())
            {
                if ((xmlReader.NodeType == XmlNodeType.Element) && (xmlReader.Name == "header"))
                {
                    inHeader = false;
                }
                else if (!inHeader && (xmlReader.NodeType == XmlNodeType.Element) && (xmlReader.Name == "parameter"))
                {
                    string value = "";
                    while (xmlReader.Read())
                    {
                        if ((xmlReader.NodeType == XmlNodeType.Text))
                        {
                            value = xmlReader.Value;
                            break;
                        }
                    }
                    parameters.Add(xmlReader.GetAttribute("name"), value);
                }
            }
        }
    }
    return parameters;
}
