public static double[,] GenerateRandomDisplacementField(int width, int height, int stepSize)
{
    Random random = new Random();
    double[,] displacementField = new double[width, height];

    for (int x = 0; x < width; x += stepSize)
    {
        for (int y = 0; y < height; y += stepSize)
        {
            double dx = (random.NextDouble() * 2 - 1) * random.NextDouble();
            double dy = (random.NextDouble() * 2 - 1) * random.NextDouble();

            if (x + stepSize > width)
                dx = (width - x - 1) * (dx / (stepSize));
            else
                dx = dx;

            if (y + stepSize > height)
                dy = (height - y - 1) * (dy / (stepSize));
            else
                dy = dy;

            displacementField[x, y] = Math.Sqrt(dx * dx + dy * dy);
        }
    }

    return displacementField;
}

