public static T[,] GenerateRandomMatrix<T>(int rows, int cols, T min, T max) where T : struct
{
    var matrix = new T[rows, cols];
    var random = new Random();
    for (int i = 0; i < rows; i++)
    {
        for (int j = 0; j < cols; j++)
        {
            matrix[i, j] = (T)Convert.ChangeType(min + (max - min) * (random.NextDouble()), typeof(T));
        }
    }
    return matrix;
}

