public IActionResult UpdateEntity([FromBody]UpdateEntityRequest request)
{
    if (request == null || !ModelState.IsValid)
    {
        return BadRequest(ModelState);
    }

    var existingEntity = _dbContext.Entities.Find(request.Id);

    if (existingEntity != null)
    {
        try
        {
            _dbContext.Entry(existingEntity).CurrentValues.SetValues(request);
            _dbContext.SaveChanges();
        }
        catch (Exception ex)
        {
            ModelState.AddModelError("UpdateEntity", "Error updating entity");
            return BadRequest(ModelState);
        }

        return new GridOperation()
        {
            Entity = existingEntity,
            OperationType = GridOperationType.Update
        };
    }

    ModelState.AddModelError("UpdateEntity", "Entity not found");
    return BadRequest(ModelState);
}

