```csharp
public static string DecryptBase64(string base64EncryptedMessage, string tripleDesKey, string initializationVector)
{
    byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
    byte[] decryptedBytes;
    using (Aes encryptor = Aes.Create())
    {
        encryptor.Key = Encoding.UTF8.GetBytes(tripleDesKey);
        encryptor.IV = Encoding.UTF8.GetBytes(initializationVector);

        using (MemoryStream ms = new MemoryStream(encryptedBytes))
        {
            using (CryptoStream cs = new CryptoStream(ms, encryptor.CreateDecryptor(), CryptoStreamMode.Read))
            {
                byte[] decryptedBuffer = new byte[encryptedBytes.Length];
                int readCount = cs.Read(decryptedBuffer, 0, encryptedBuffer.Length);
                decryptedBytes = decryptedBuffer.Take(readCount).ToArray();
            }
        }
    }

    return Encoding.UTF8.GetString(decryptedBytes);
}

