public static object PerformOperationWithShardRandomness(List<IShard> shards, bool checkIntegrity)
{
    ISpreadReadonlyTransaction transaction = _cloudTable.ExecuteTransaction();

    try 
    {
        IPartitionResolver resolver = new PartitionResolver(shards);
        Ipartition partition = resolver.GetPartitionForQuery("id = @id", new Dictionary<string, object>{{"id", Guid.NewGuid().ToString()}});

        ISharedConsistentHashingStore store = partition.GetSharedStore();

        IShard randomShard = shards[new System.Random().Next(0, shards.Count)];
        object result = store.ExecutePartitionedQuery("query", new Dictionary<string, object>{{"param1", "value1"}, {"param2", 123}});

        if (checkIntegrity)
        {
            transaction.Start();

            foreach (var shard in shards)
            {
                try 
                {
                    ISharedConsistentHashingStore store = partition.GetSharedStore();

                    object integrityResult = store.ExecutePartitionedQuery("integrityQuery", new Dictionary<string, object>{{"param1", "value1"}, {"param2", 123}});

                    if (result != integrityResult)
                    {
                        throw new Exception("Integrity check failed");
                    }
                } 
                catch (Exception ex) 
                {
                    transaction.Abort();
                    throw;
                }
            }

            transaction.Commit();
        }

        return result;
    } 
    catch (Exception ex) 
    {
        transaction.Abort();
        throw;
    }

    finally
    {
        transaction.Dispose();
    }
}
