public byte[] ExecuteQuery(IDbConnection connection, string commandText, DbBehavior behavior)
{
    using (var command = connection.CreateCommand())
    {
        command.CommandText = commandText;
        command.CommandType = CommandType.Text;

        if (behavior == DbBehavior.Read)
        {
            return ReadCommand(command);
        }
        else
        {
            return WriteCommand(command);
        }
    }
}

private byte[] ReadCommand(IDbCommand command)
{
    using (var reader = command.ExecuteReader())
    {
        if (reader.Read())
        {
            var buffer = new byte[reader.GetBytes(0, 0, null, 0, int.MaxValue)];
            reader.GetBytes(0, 0, buffer, 0, buffer.Length);
            return buffer;
        }
        else
        {
            return new byte[0];
        }
    }
}

private byte[] WriteCommand(IDbCommand command)
{
    using (var ms = new MemoryStream())
    {
        command.ExecuteNonQuery();
        return ms.ToArray();
    }
}

