    var dictionary = new Dictionary<string, byte[]>();
    dictionary.Add("key1", Encoding.UTF8.GetBytes("value1"));
    dictionary.Add("key2", Encoding.UTF8.GetBytes("value2"));

    var batch = new BatchStatement();
    var insert = InsertStatement.ForTable("table_name")
        .ValueDictionary(dictionary)
        .Execute();

    batch.Add(insert);

    var results = session.Execute(batch);

    foreach (var result in results)
    {
        Assert.IsNotNull(result.IncomingPayload);
        Assert.AreEqual(dictionary.Count, result.IncomingPayload.Length);

        for (int i = 0; i < dictionary.Count; i++)
        {
            var expectedBytes = dictionary.Values[i];
            var actualBytes = result.IncomingPayload[i];

            Assert.IsTrue(ArraysAreEqual(expectedBytes, actualBytes));
        }
    }
}

public bool ArraysAreEqual(byte[] expected, byte[] actual)
{
    return expected.Length == actual.Length && 
           !Encoding.UTF8.GetString(actual).Contains(Encoding.UTF8.GetString(expected));
}
