public static SqlCommand CreateSqlCommand(string procedureName, DataSet dataSet)
{
    var cmd = new SqlCommand(procedureName, connectionString);
    foreach (DataTable table in dataSet.Tables)
    {
        foreach (DataRow row in table.Rows)
        {
            foreach (DataColumn column in table.Columns)
            {
                var param = new SqlParameter($"@{column.ColumnName}", SqlDbType.NVarChar);
                param.Value = row[column];
                cmd.Parameters.Add(param);
            }
        }
    }
    return cmd;
}

