public static void StartProcess(ProcessStartInfo startInfo)
{
    using (var process = Process.Start(startInfo))
    {
        var trackingFolder = @"C:\Tracking";
        if (!Directory.Exists(trackingFolder))
            throw new InvalidOperationException("Tracking folder does not exist");

        File.WriteAllText(Path.Combine(trackingFolder, "processId.txt"), process.Id.ToString());

        var sentinelProcessStartInfo = new ProcessStartInfo
        {
            FileName = "Sentinel.exe",
            CreateNoWindow = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            WorkingDirectory = trackingFolder
        };
        using (var sentinelProcess = Process.Start(sentinelProcessStartInfo))
        {
            sentinelProcess.WaitForExit(int.Parse(startInfo.Arguments));
            if (!File.Exists(Path.Combine(trackingFolder, "processId.txt")))
                File.Delete(Path.Combine(trackingFolder, "processId.txt"));
        }
    }
}
