public static Font CreateFontFromXml(Device device, string fontName)
{
    Assembly assembly = typeof(Device).Assembly;
    Stream stream = assembly.GetManifestResourceStream(fontName + ".xml");
    XmlDocument doc = new XmlDocument();
    doc.Load(stream);
    XmlNode node = doc.SelectSingleNode("/font[@name='" + fontName + "']");
    int fontSize = int.Parse(node["fontSize"].InnerText);
    float width = float.Parse(node["width"].InnerText);
    float height = float.Parse(node["height"].InnerText);
    return new Font(device, fontSize, width, height);
}
