public static void RotateObjectBy90Degrees(Quaternion otherDirection, IntersectionType type)
{
    Quaternion rotation = Quaternion.identity;

    if (type == IntersectionType.TopLeft || type == IntersectionType.BottomRight)
    {
        rotation *= Quaternion.Euler(0f, 90f, 0f);
    }
    else
    {
        rotation *= Quaternion.Euler(0f, -90f, 0f);
    }

    if (!otherDirection.IsIdentity())
    {
        rotation *= otherDirection;
    }

    transform.rotation = rotation;
}
