using System;
using System.Security.Cryptography;

public static string DecryptMessage(string cipherText, string key)
{
    byte[] iv = new byte[8];
    byte[] encryptedBytes = Convert.FromBase64String(cipherText);
    using (Aes aes = Aes.Create())
    {
        aes.Key = Convert.FromBase64String(key).Take(aes.Key.Length).ToArray();
        aes.IV = iv;
        ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using (MemoryStream ms = new MemoryStream(encryptedBytes))
        {
            using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                byte[] decryptedBytes = new byte[cs.Length];
                cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
    }
}

