public static Matrix<LabPixel> GenerateRandomMatrix(int width, int height)
{
    var matrix = new Matrix<LabPixel>(width, height);
    var ptr = Marshal.AllocHGlobal(matrix.Stride * height);

    for (int i = 0; i < height; i++)
    {
        var labPixelPtr = (LabPixel*)Marshal.StructureToPtr(matrix[i], IntPtr.Zero);
        Marshal.Copy(labPixelPtr, 0, ptr + (i * matrix.Stride), sizeof(LabPixel));
    }

    return matrix;
}
