public ActionResult ProcessRequest(HttpRequest req)
{
    string key = $"{req.HttpMethod}{req.Url.AbsolutePath}";
    CacheEntry entry;

    if (cache.TryGetValue(key, out entry))
    {
        return new ContentResult { Content = entry.Value, ContentType = "application/json" };
    }

    // Handle GET requests
    if (req.HttpMethod == "GET")
    {
        string result = GetResultFromDatabase();
        cache.Add(key, new CacheEntry(result), TimeSpan.FromMinutes(30));
        return new ContentResult { Content = result, ContentType = "application/json" };
    }

    // Handle POST requests
    else if (req.HttpMethod == "POST")
    {
        string data = req.Form["data"];
        string result = ProcessPostData(data);
        cache.Add(key, new CacheEntry(result), TimeSpan.FromMinutes(30));
        return new ContentResult { Content = result, ContentType = "application/json" };
    }

    // Handle other requests
    else
    {
        return new HttpStatusCodeResult(405);
    }
}

public class CacheEntry
{
    public string Value { get; set; }

    public CacheEntry(string value)
    {
        Value = value;
    }
}

