    private readonly IEventPublisher _publisher;

    public Publisher(string topic, IEventPublisher publisher)
    {
        _topic = topic;
        _publisher = publisher;
    }

    public void PublishRandomly()
    {
        Random random = new Random();
        for (int i = 0; i < 10; i++)
        {
            try
            {
                byte[] message = new byte[random.Next(100, 500)];
                random.NextBytes(message);
                _publisher.Publish(_topic, message);
            }
            catch (Exception ex)
            {
                Assert.Fail("Publish failed with: " + ex.Message);
            }
        }
    }
}

