        {
            // Handle username already exists scenario
            Response.Redirect("/users/exists", true);
        }
        else if (ex.Message.Contains("password mismatch"))
        {
            // Handle password mismatch scenario
            Response.Redirect("/users/passwordmismatch", true);
        }
        else
        {
            // Handle general error scenario
            Response.Redirect("/error", true);
        }

        return;
    }

    // Successful registration scenario
    if (returnUrl != null)
    {
        Response.Redirect(returnUrl, true);
    }
    else
    {
        Response.Redirect("/", true); // Redirect to home page
    }
}

