public static void ConnectTanks(object[,] grid)
{
    for (int i = 0; i < grid.GetLength(0); i++)
    {
        for (int j = 0; j < grid.GetLength(1); j++)
        {
            if (grid[i, j] is Tank tank && !tank.IsSink)
            {
                List<Tank> connectedTanks = new List<Tank>();
                while (!connectedTanks.Any())
                {
                    int dx = new Random().Next(-1, 2);
                    int dy = new Random().Next(-1, 2);

                    int newX = Math.Max(0, Math.Min(grid.GetLength(0) - 1, i + dx));
                    int newY = Math.Max(0, Math.Min(grid.GetLength(1) - 1, j + dy));

                    if (grid[newX, newY] is Tank tankToConnect)
                    {
                        if (!tankToConnect.IsSink && !connectedTanks.Contains(tankToConnect))
                        {
                            connectedTanks.Add(tankToConnect);
                            tank.Connect(tankToConnect);
                        }
                    }
                }
            }
        }
    }
}
