public static string ExpandString(string s, XmlAttribute attribute)
{
    var expander = new ExpandoObject().GetDynamicValue();
    string result;
    using (var writer = new StringWriter())
    {
        var settings = new XmlWriterSettings { Indent = true };
        using (var xmlWriter = XmlWriter.Create(writer, settings))
        {
            xmlWriter.WriteStartAttribute(attribute.Name, attribute.NamespaceURI);
            expander.SetProperty(s, s);
            xmlWriter.WriteString(s);
            xmlWriter.WriteEndAttribute();
        }
        result = writer.ToString();
    }
    return result;
}
