public static void CreateViews(IList list, XmlDocument xmlDoc)
{
    XmlNodeList views = xmlDoc.SelectNodes("/views/view");
    Type viewType = list.GetType();
    string defaultView = null;
    int rowLimit = 0;

    foreach (XmlNode viewNode in views)
    {
        string viewName = viewNode["name"].InnerText;
        string viewTypeStr = viewNode["type"].InnerText;
        XmlNode fieldsNode = viewNode["fields"];

        if (viewType.Name == viewTypeStr && list is IEnumerable)
        {
            ViewProperties viewProps = new ViewProperties();
            viewProps.Name = viewName;
            viewProps.Type = viewTypeStr;
            List<Field> fields = new List<Field>();

            foreach (XmlNode fieldNode in fieldsNode.SelectNodes("field"))
            {
                Field field = new Field(fieldNode["name"].InnerText, fieldNode["description"].InnerText);
                fields.Add(field);
            }

            View view = new View(viewProps, fields);

            // Set default view
            if (string.IsNullOrEmpty(defaultView))
                defaultView = viewName;

            // Set row limit
            int.TryParse(viewNode["rowLimit"].InnerText, out rowLimit);

            list.Views.Add(view);
        }
    }

    list.DefaultView = defaultView;
    list.RowLimit = rowLimit;
}

public class ViewProperties
{
    public string Name { get; set; }
    public string Type { get; set; }
}

public class Field
{
    public string Name { get; set; }
    public string Description { get; set; }

    public Field(string name, string description)
    {
        Name = name;
        Description = description;
    }
}
