def interact_with_database(session):
    while True:
        print("Enter one of the following options:")
        print("1. Create filter")
        print("2. Get named query")
        print("3. Create SQL query")
        print("4. Clear session")
        print("5. Retrieve objects from database")
        print("6. Exit")

        option = input("Option: ")

        if option == "1":
            filters = session.get_filters()
            for filter_ in filters:
                print(filter_)
        elif option == "2":
            named_queries = session.get_named_queries()
            for query in named_queries:
                print(query)
        elif option == "3":
            query = input("Enter SQL query: ")
            result_proxy = session.query(query)
            for rowproxy in result_proxy:
                print(rowproxy)
        elif option == "4":
            session.clear()
        elif option == "5":
            query = input("Enter query: ")
            objects = session.query(query)
            for obj in objects:
                print(obj)
        elif option == "6":
            break
        else:
            print("Invalid option. Please try again.")

