public static void DeleteTrackableItem(string itemCode, int groupId)
{
    try
    {
        using (SqlConnection connection = new SqlConnection("Your Connection String"))
        {
            connection.Open();

            string deleteQuery = "DELETE FROM TrackableItems WHERE ItemCode = @itemCode AND GroupID = @groupId";
            SqlCommand command = new SqlCommand(deleteQuery, connection);
            command.Parameters.AddWithValue("@itemCode", itemCode);
            command.Parameters.AddWithValue("@groupId", groupId);

            int rowsAffected = command.ExecuteNonQuery();
            if (rowsAffected > 0)
            {
                string logQuery = "DELETE FROM TrackableItemLogs WHERE ItemCode = @itemCode AND GroupID = @groupId";
                SqlCommand logCommand = new SqlCommand(logQuery, connection);
                logCommand.Parameters.AddWithValue("@itemCode", itemCode);
                logCommand.Parameters.AddWithValue("@groupId", groupId);

                rowsAffected = logCommand.ExecuteNonQuery();
            }
        }
    }
    catch (SqlException ex)
    {
        // Handle the error
        Console.WriteLine("Error: " + ex.Message);
    }
}
