```csharp
public static string DecryptDES(string encryptedText, byte[] key)
{
    DESCryptoServiceProvider des = new DESCryptoServiceProvider();
    des.Key = key;
    des.Mode = CipherMode.ECB;
    ICryptoTransform transform = des.CreateDecryptor();

    byte[] buffer = Convert.FromBase64String(encryptedText);
    MemoryStream ms = new MemoryStream(buffer);
    CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Read);
    byte[] decryptedBuffer = new byte[buffer.Length];
    int readCount = cs.Read(decryptedBuffer, 0, decryptedBuffer.Length);

    return Encoding.ASCII.GetString(decryptedBuffer, 0, readCount);
}

