public async Task ProcessStart(string fileName)
{
    using (Process process = new Process())
    {
        process.StartInfo.FileName = fileName;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardInput = true;
        process.OutputDataReceived += (sender, data) => { if (!string.IsNullOrEmpty(data.Data)) Console.WriteLine(data.Data); };
        process.Exited += (sender, e) => { process.Dispose(); };

        using (StreamReader reader = new StreamReader(process.StandardOutput.BaseStream))
        {
            process.Start();
            process.BeginOutputReadLine();

            while ((string line = await reader.ReadLineAsync()) != null)
            {
                if (!string.IsNullOrEmpty(line))
                    Console.WriteLine(line);
            }
        }

        ProcessThread t = process.StartInfo.FileName.Contains("cmd") ? new ProcessThread(process) : null;
        using (StreamReader reader2 = new StreamReader(Console.OpenStandardInput()))
        {
            while ((string line = await reader2.ReadLineAsync()) != null)
            {
                if (!string.IsNullOrEmpty(line))
                    process.StandardInput.BaseStream.Write(Encoding.UTF8.GetBytes(line), 0, line.Length);
            }
        }

        if (t != null) t.Start();
    }
}
