public static T ParseXmlAttribute<T>(byte[] xmlData, string nodeName, string attributeName) where T : struct
{
    XmlDocument xmlDoc = new XmlDocument();
    xmlDoc.LoadXml(Encoding.UTF8.GetString(xmlData));
    XmlNode node = xmlDoc.DocumentElement.SelectSingleNode(nodeName);
    if (node != null)
    {
        XmlAttribute attribute = node.Attributes[attributeName];
        if (attribute != null)
        {
            return (T)Convert.ChangeType(attribute.Value, typeof(T));
        }
    }
    throw new Exception("Node or Attribute not found");
}

