public static int ExecuteQuery(SqlConnection conn, string query, object[] parameters = null)
{
    int affectedRows = 0;
    using (SqlCommand cmd = new SqlCommand(query, conn))
    {
        if (parameters != null)
        {
            foreach (SqlParameter param in parameters.Select(p => new SqlParameter("@p" + p.GetHashCode().ToString(), p)))
            {
                cmd.Parameters.Add(param);
            }
        }
        affectedRows = cmd.ExecuteNonQuery();
    }
    return affectedRows;
}

