public static IDataReader ExecuteReader(string connectionString, CommandType commandType, string commandText, params SqlParameter[] commandParameters)
{
    using (DbConnection conn = DbFactory.CreateConnection())
    {
        conn.ConnectionString = connectionString;
        conn.Open();

        DbCommand cmd = conn.CreateCommand();
        cmd.CommandText = commandText;
        cmd.CommandType = commandType;

        foreach (SqlParameter param in commandParameters)
        {
            cmd.Parameters.Add(param);
        }

        try
        {
            return cmd.ExecuteReader();
        }
        catch (Exception ex)
        {
            conn.Close();
            throw new Exception("Error executing SQL command", ex);
        }
    }
}

