public static void UpdateXmlConfig(string filePath, string existingSectionName, string newSectionName)
{
    XDocument doc = XDocument.Load(filePath);
    XElement root = doc.Root;
    IEnumerable<XElement> existingSection = root.XPathSelectElements($"section[@name='{existingSectionName}']");
    if (!existingSection.Any())
        throw new Exception("Existing section not found");

    XElement newSection = new XElement("section");
    newSection.Add(new XAttribute("name", newSectionName));
    foreach (var setting in existingSection.Last().ElementsAfterSelf())
    {
        setting.Remove();
    }
    existingSection.Last().AddAfterSelf(newSection);
}
