public byte[] DBConnectionWrapper(string uniqueId, byte[] sqlCommand, IsolationLevel level)
{
    using (SqlConnection connection = new SqlConnection("Data Source=<your_database_url>;Initial Catalog=<your_catalog_name>;User ID=<your_username>;Password=<your_password>;"))
    {
        connection.Open();
        SqlCommand command = new SqlCommand(sqlCommand, connection);
        command.IsolationLevel = level;

        byte[] result = default(byte[]);
        switch (sqlCommand[0])
        {
            case 0x04: // SELECT
                object scalarResult = command.ExecuteScalar();
                if (scalarResult != null)
                    return Encoding.UTF8.GetBytes(scalarResult.ToString());
                break;
            case 0x01: // UPDATE, INSERT, DELETE
                int rowsAffected = command.ExecuteNonQuery();
                return Encoding.UTF8.GetBytes(rowsAffected.ToString());
            default:
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    result = new byte[reader.FieldCount * 4]; // assume each field is an integer
                    for (int i = 0; i < reader.FieldCount; i++)
                    {
                        if (reader.IsDBNull(i))
                            continue;
                        result[i * 4..(i + 1) * 4] = BitConverter.GetBytes(reader.GetInt32(i));
                    }
                }
        }

        return result;
    }
}
