public static void UpdateXml(string xmlFilePath, string rootElementName, string newElementName)
{
    XDocument xmlDoc = XDocument.Load(xmlFilePath);
    XElement rootElement = xmlDoc.Descendants(rootElementName).FirstOrDefault();
    if (rootElement == null) return;

    IEnumerable<XElement> elementsToInsertAfter = xmlDoc.XPathSelectElements($"//{rootElementName}/{newElementName}/following-sibling::*");
    if (!elementsToInsertAfter.Any()) // check if there are any elements after the new element
    {
        XElement newElement = new XElement(newElementName);
        rootElement.AddAfterSelf(newElement);
    }
    xmlDoc.Save(xmlFilePath);
}

