public List<List<object>> RetrieveDataFromSqlServer(string serverName, string databaseName, string tableName)
{
    List<List<object>> results = new List<List<object>>();
    try
    {
        // Create connection and command objects
        SqlConnection connection = new SqlConnection($"Server={serverName};Database={databaseName};Integrated Security=True;");
        SqlCommand command = new SqlCommand("SELECT * FROM " + tableName, connection);

        // Open the connection
        connection.Open();

        // Execute the query and retrieve results
        SqlDataReader reader = command.ExecuteReader();
        while (reader.Read())
        {
            List<object> row = new List<object>();
            for (int i = 0; i < reader.FieldCount; i++)
            {
                row.Add(reader[i]);
            }
            results.Add(row);
        }

        // Close the connection
        connection.Close();
    }
    catch (Exception ex)
    {
        throw;
    }

    return results;
}

