public List<KeyValuePair<string, string>> LoadConfiguration(string filename)
{
    List<KeyValuePair<string, string>> config = new List<KeyValuePair<string, string>>();
    XmlDocument doc = new XmlDocument();
    doc.Load(filename);
    XmlElement root = doc.DocumentElement;
    foreach (XmlNode node in root.ChildNodes)
    {
        if (node.NodeType == XmlNodeType.Element && node.HasChildNodes)
        {
            XmlNode childNode = node.FirstChild;
            config.Add(new KeyValuePair<string, string>(childNode.Name, childNode.InnerText));
        }
    }
    return config;
}

