private static byte[] DecryptAescbc(byte[] ciphertext, byte[] encryptionKey, byte[] iv, int blockSize)
{
    using (var decryptor = Aes.CreateDecryptor(encryptionKey, iv))
    {
        using (var ms = new MemoryStream(ciphertext))
        {
            var decryptBuffer = new byte[blockSize];
            int readBytes;
            var decryptedData = new byte[ciphertext.Length];
            int offset = 0;

            do
            {
                readBytes = decryptor.TransformFinalBlock(decryptBuffer, 0, blockSize);
                Array.Copy(decryptBuffer, 0, decryptedData, offset, readBytes);
                offset += readBytes;
            } while (readBytes == blockSize);

            return decryptedData;
        }
    }
}

