public static string EncryptDES(string input, string key)
{
    DESCryptoServiceProvider des = new DESCryptoServiceProvider();
    byte[] iv = des.IV;
    byte[] passwordBytes = ASCIIEncoding.ASCII.GetBytes(key);
    PasswordDeriveBytes pdb = new PasswordDeriveBytes(passwordBytes, new MD5CryptoServiceProvider());
    byte[] keyBytes = pdb.GetBytes(56);

    des.Key = keyBytes.Take(des.KeyLength).ToArray();

    MemoryStream ms = new MemoryStream();
    CryptoStream cs = new CryptoStream(ms, des.CreateEncryptor(), CryptoStreamMode.Write);
    StreamWriter sw = new StreamWriter(cs);
    sw.WriteLine(input);

    return Convert.ToBase64String(ms.ToArray());
}
