public static XmlDocument GenerateXml(Type type)
{
    XmlDocument xml = new XmlDocument();
    XmlElement root = xml.CreateElement("root");
    xml.AppendChild(root);

    foreach (PropertyInfo prop in type.GetProperties())
    {
        XmlElement element = xml.CreateElement(prop.Name);
        root.AppendChild(element);

        XmlizedClassAttribute classAttr = 
            Attribute.GetCustomAttribute(prop.GetCustomAttributes(typeof(XmlizedClassAttribute), false),
                                            default(XmlizedClassAttribute));

        if (classAttr != null)
        {
            foreach (XmlElement child in classAttr.GenerateXml(prop))
            {
                element.AppendChild(child);
            }
        }

        XmlizedSqlstringIDClassAttribute sqlAttr = 
            Attribute.GetCustomAttribute(prop.GetCustomAttributes(typeof(XmlizedSqlstringIDClassAttribute), false),
                                            default(XmlizedSqlstringIDClassAttribute));

        if (sqlAttr != null)
        {
            foreach (XmlElement child in sqlAttr.GenerateXml(prop))
            {
                element.AppendChild(child);
            }
        }
    }

    return xml;
}

