public static List<TravelItem> ExtractGeocacheCoordinates(string resourceName)
{
    string html = Resources.ResourceManager.GetString(resourceName);
    var travelItems = new List<TravelItem>();

    var htmlDoc = new HtmlDocument();
    htmlDoc.LoadHtml(html);

    foreach (var node in htmlDoc.DocumentNode.SelectNodes("//table[@class='logentry']"))
    {
        foreach (var row in node.SelectNodes("tr/td[1]//text()").Select((x, i) => new { Value = x, Index = i }))
        {
            if (row.Index == 3)
            {
                var coordinates = row.Value.Split(new[] { " N" }, StringSplitOptions.None)[0].Trim();
                var dateLogged = node.SelectNodes("tr/td[4]//text()").FirstOrDefault().Value;

                travelItems.Add(new TravelItem
                {
                    Coordinates = new CoordinatePair(double.Parse(coordinates.Substring(0, coordinates.IndexOf(' '))),
                                                     double.Parse(coordinates.Substring(coordinates.IndexOf(' ') + 1).Trim())),
                    DateLogged = dateLogged
                });
            }
        }
    }

    return travelItems;
}

public class TravelItem
{
    public CoordinatePair Coordinates { get; set; }
    public string DateLogged { get; set; }
}

