using System;
using System.Security.Cryptography;
using System.Text;

public static string EncryptDes(string plainText)
{
    byte[] bytes = ASCIIEncoding.UTF8.GetBytes(plainText);
    DESCryptoServiceProvider des = new DESCryptoServiceProvider();
    des.Key = ASCIIEncoding.ASCII.GetBytes("MySecretKey");
    des.Mode = CipherMode.ECB;
    des.Padding = PaddingMode.PKCS7;

    MemoryStream mstream = new MemoryStream();
    CryptoStream cStream = new CryptoStream(mstream, des.CreateEncryptor(), CryptoStreamMode.Write);
    cStream.Write(bytes, 0, bytes.Length);
    cStream.Flush();
    byte[] encryptedBytes = mstream.ToArray();

    return Convert.ToBase64String(encryptedBytes);
}

