public async Task<int> GetNextVersionNumberAsync(int streamId, int count, int currentVersion)
{
    using (var connection = new SqlConnection("Your Connection String"))
    {
        await connection.OpenAsync();

        var command = new SqlCommand("SELECT Version FROM StreamVersions WHERE StreamId = @StreamId AND Version > @CurrentVersion ORDER BY Version ASC OFFSET 0 ROWS FETCH NEXT @Count ROWS ONLY", connection);

        command.Parameters.AddWithValue("@StreamId", streamId);
        command.Parameters.AddWithValue("@CurrentVersion", currentVersion);
        command.Parameters.AddWithValue("@Count", count);

        using (var reader = await command.ExecuteReaderAsync())
        {
            if (await reader.ReadAsync())
            {
                return (int)reader["Version"];
            }
            else
            {
                return -1;
            }
        }
    }
}
