IF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysjobsteps WHERE job_name = 'Service' AND step_name = 'QueueListener')
BEGIN
    DECLARE @queue_name sysname, @service_name sysname;

    SET @queue_name = 'MyQueue';
    SET @service_name = 'MyService';

    IF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysjobsteps WHERE job_name = @service_name AND step_name = 'QueueListener')
    BEGIN
        EXEC sp_add_job @job_name = @service_name, 
                        @enabled = 1, 
                        @notify_level_eventlog = 0, 
                        @notify_level_email = 2, 
                        @notify_level_page = 2;

        EXEC sp_add_jobstep @job_name = @service_name, 
                            @step_name = 'QueueListener', 
                            @cmd = 'powershell -File C:\Path\To\Script.ps1', 
                            @type = 'tsql';

        EXEC sp_add_schedule @job_name = @service_name, 
                              @schedule_name = 'Daily', 
                              @enabled = 1;

        EXEC sp_attach_schedule_to_job @job_name = @service_name, 
                                         @schedule_name = 'Daily';
    END

    IF NOT EXISTS (SELECT 1 FROM msdb.dbo.sysqueueholders WHERE queueholder_name = @queue_name)
    BEGIN
        EXEC sp_create_queue @name = @queue_name;
    END

    IF NOT EXISTS (SELECT 1 FROM msdb.dbo.queue_monitors WHERE queue_monitor_name = @service_name + '_monitor')
    BEGIN
        EXEC sp_add_queue_monitor @queue_name = @queue_name, 
                                  @monitor_type = 'post_query_notification', 
                                  @job_name = @service_name;
    END
END

