    {
        return View("List");
    }

    var user = (MyUser)System.Web.HttpContext.Current.User;
    if (!user.IsAuthorizedToEdit())
    {
        TempData["ErrorMessage"] = "You don't have permission to edit this record.";
        return RedirectToAction("List");
    }

    using (var db = new MyDbContext())
    {
        var record = db.Records.Find(id);
        if (record == null)
        {
            ModelState.AddModelError("id", "Record not found.");
            return View("List");
        }

        record.Name = name;
        record.Quantity = quantity;

        try
        {
            db.SaveChanges();
            TempData["SuccessMessage"] = "Record updated successfully.";
            return RedirectToAction("List");
        }
        catch (Exception ex)
        {
            ModelState.AddModelError("id", "Error updating record: " + ex.Message);
            return View("List");
        }
    }
}
