```csharp
public void RunExternalProcess(string executablePath, string arguments)
{
    using (var process = new Process())
    {
        process.StartInfo.FileName = executablePath;
        process.StartInfo.Arguments = arguments;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;

        if (process.Start())
        {
            var output = new StringBuilder();
            var error = new StringBuilder();

            using (var reader = process.StandardOutput)
            {
                reader.ReadToEnd().TrimEnd().CopyTo(output, 4096);
            }

            using (var errorReader = process.StandardError)
            {
                errorReader.ReadToEnd().TrimEnd().CopyTo(error, 4096);
            }

            process.WaitForExit();

            if (!string.IsNullOrEmpty(executablePath) && !string.IsNullOrEmpty(arguments))
            {
                // Display a popup window
                System.Windows.Forms.MessageBox.Show(output.ToString(), "Standard Output", MessageBoxButtons.OK, MessageBoxIcon.Information);

                if (error.Length > 0)
                {
                    System.Windows.Forms.MessageBox.Show(error.ToString(), "Standard Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }
            }
        }
    }
}

