using System;
using System.IO;
using System.Security.Cryptography;
using System.Linq;

public static List<Resource> ComputeMd5Hashes(List<resourceTuple> resources)
{
    var result = new List<Resource>();

    foreach (var resource in resources)
    {
        using (var md5 = MD5.Create())
        {
            var hash = md5.ComputeHash(resource.Item1);
            var hashString = BitConverter.ToString(hash).Replace("-", "").ToLower();
            result.Add(new Resource(hashString, resource.Item1, resource.Item2));
        }
    }

    return result;
}

public class Resource
{
    public string Hash { get; set; }
    public byte[] Bytes { get; set; }
    public string MimeType { get; set; }

    public Resource(string hash, byte[] bytes, string mimeType)
    {
        Hash = hash;
        Bytes = bytes;
        MimeType = mimeType;
    }
}

public struct resourceTuple
{
    public byte[] Item1 { get; set; }
    public string Item2 { get; set; }

    public resourceTuple(byte[] item1, string item2)
    {
        Item1 = item1;
        Item2 = item2;
    }
}

