public static void CopyFiles(string sourceDir, string targetDir, string[] includedExtensions, string[] excludedExtensions)
{
    Directory.CreateDirectory(targetDir);

    foreach (string file in Directory.GetFiles(sourceDir))
    {
        FileInfo fileInfo = new FileInfo(file);
        if (includedExtensions.Contains(fileInfo.Extension.ToLower()) 
            && !excludedExtensions.Any(ext => ext.ToLower().Equals(fileInfo.Extension)))
        {
            Process.Start(new ProcessStartInfo
            {
                FileName = "copy",
                Arguments = "/y \"" + file + "\" \"" + Path.Combine(targetDir, fileInfo.Name) + "\""
            });
        }
    }
}

