public static string DecryptDes(string hexMessage)
{
    if (string.IsNullOrEmpty(hexMessage))
        throw new ArgumentNullException("hexMessage");

    try
    {
        byte[] buffer = Convert.FromHexString(hexMessage);
        using (DESCryptoServiceProvider desCrypto = new DESCryptoServiceProvider())
        {
            desCrypto.Key = ASCIIEncoding.ASCII.GetBytes("my_secret_key");
            desCrypto.Mode = CipherMode.ECB;
            using (MemoryStream ms = new MemoryStream(buffer))
            {
                CryptoStream cs = new CryptoStream(ms, desCrypto.CreateDecryptor(), true);
                byte[] decryptedBytes = new byte[buffer.Length];
                int bytesRead = 0;
                while ((readBytes = cs.Read(decryptedBytes, 0, buffer.Length)) > 0)
                    ;
                return Encoding.ASCII.GetString(decryptedBytes).TrimEnd('\0');
            }
        }
    }
    catch (Exception ex)
    {
        if (ex is FormatException || ex is CryptographicException)
            throw new ArgumentException("Invalid hexadecimal message");
        else
            throw;
    }
}

