    static void Main()
    {
        string filePath = "path_to_your_xml_file.xml";
        XmlDocument doc = new XmlDocument();
        doc.Load(filePath);

        Dictionary<string, int> artistsAlbums = new Dictionary<string, int>();

        string query = "/root/album/artist/text()"; // XPath query
        XmlNodeList nodes = doc.SelectNodes(query);

        foreach (XmlNode node in nodes)
        {
            string artistName = node.InnerText;
            if (!artistsAlbums.ContainsKey(artistName))
                artistsAlbums.Add(artistName, 0);

            int albumCount = GetAlbumCount(doc, artistName);
            artistsAlbums[artistName] = albumCount;
        }

        // Print the results
        foreach (var pair in artistsAlbums)
        {
            Console.WriteLine($"{pair.Key} - {pair.Value}");
        }
    }

    static int GetAlbumCount(XmlDocument doc, string artistName)
    {
        string query = $"//root/album[artist='{artistName'}]/@name"; // XPath query
        XmlNodeList nodes = doc.SelectNodes(query);

        return nodes.Count;
    }
}

