    {
        string applicationPath = @"C:\Path\To\Application.exe"; // Replace with your actual app path
        string newVersionPath = Path.Combine(updateLocation, "NewVersion.exe");

        if (File.Exists(applicationPath))
        {
            File.Delete(applicationPath);
