    public static void ExtractTextFromPdf(string inputPdfPath, string outputPdfPath)
    {
        using (PdfReader reader = new PdfReader(inputPdfPath))
        {
            StringBuilder textBuilder = new StringBuilder();
            for (int page = 1; page <= reader.GetNumberOfPages(); page++)
            {
                PdfTextExtractor textExtractor = PdfTextExtractor.CreateSimpleTextExtractionContext(reader);
                string text = textExtractor.TextFromPage(page);
                textBuilder.AppendLine(text);
            }

            using (PdfDocument pdfDoc = new PdfDocument())
            {
                pdfDoc.Add(new Paragraph(textBuilder.ToString()));
                pdfDoc.Save(outputPdfPath);

                System.Diagnostics.Process.Start(outputPdfPath); // Open the file
            }
        }
    }
}
