public static string UpdateXmlFile(string filePath, string removeXPath, string insertAfterXPath)
{
    XmlDocument doc = new XmlDocument();
    doc.Load(filePath);

    XmlNodeList nodesToRemove = doc.SelectNodes(removeXPath);
    foreach (XmlNode node in nodesToRemove)
    {
        node.ParentNode.RemoveChild(node);
    }

    XmlNodeList nodesToInsertAfter = doc.SelectNodes(insertAfterXPath);
    foreach (XmlNode node in nodesToInsertAfter)
    {
        XmlElement newNode = doc.CreateElement("newNode");
        node.AppendChild(newNode);
    }

    StringContent content = new StringContent(doc.OuterXml);
    return content.ReadAsStringAsync().Result;
}
