public static string UpdateXmlFile(string filePath, string existingElementXPath, XName newElementName, string afterElementXPath)
{
    using (var fileStream = File.OpenRead(filePath))
    {
        var doc = XDocument.Load(fileStream);
        var root = doc.Root;
        var existingElement = root.XPathSelectElement(existingElementXPath);
        if (existingElement == null) return doc.ToString();
        var afterElement = root.XPathSelectElement(afterElementXPath);
        if (afterElement == null) return doc.ToString();
        existingElement.AddAfterSelf(new XElement(newElementName));
    }
    return doc.ToString();
}

