public static XmlDocument CreateXmlFromObject(object obj)
{
    XmlDocument doc = new XmlDocument();
    foreach (PropertyInfo prop in obj.GetType().GetProperties())
    {
        if (prop.GetCustomAttribute(typeof(XmlizedPropertyAttribute)) != null)
        {
            XmlizedPropertyAttribute attr = prop.GetCustomAttribute<XmlizedPropertyAttribute>();
            XmlElement node = doc.CreateElement(attr.Path);
            if (prop.PropertyType.GetInterface(typeof(IExportToXmlable).Name) != null)
            {
                IExportToXmlable exportable = (IExportToXmlable)prop.GetValue(obj);
                node.InnerXml = exportable.ExportToXml();
            }
            else
            {
                node.InnerText = prop.GetValue(obj).ToString();
            }
            doc.DocumentElement.Append(node);
        }
    }
    return doc;
}

