public class HashAlgorithmWrapper
{
    public string Name { get; private set; }
    public System.Security.Cryptography.HashAlgorithm Algorithm { get; private set; }

    public HashAlgorithmWrapper(string name, System.Security.Cryptography.HashAlgorithm algorithm)
    {
        Name = name;
        Algorithm = algorithm;
    }

    public byte[] CalculateHash(string inputString)
    {
        using (var ms = new MemoryStream())
        {
            var streamWriter = new StreamWriter(ms);
            streamWriter.Write(inputString);
            streamWriter.Flush();
            streamWriter.Dispose();

            ms.Position = 0;

            return Algorithm.ComputeHash(ms);
        }
    }

    public static HashAlgorithmWrapper MD5()
    {
        return new HashAlgorithmWrapper("MD5", System.Security.Cryptography.MD5.Create());
    }

    public static HashAlgorithmWrapper SHA1()
