public static void LoadAndSaveCookies(string inputFile, string outputFile)
{
    using (var inputStream = File.OpenRead(inputFile))
    {
        var cookies = new List<HttpCookie>();
        inputStream.Read(new byte[4], 0, 4); // Skip cookie count
        int cookieCount;
        BitConverter.ToInt32(inputStream.ToArray(), 0).TryConvert(out cookieCount);

        for (int i = 0; i < cookieCount; i++)
        {
            var cookie = new HttpCookie();
            inputStream.Read(cookieHeader, 0, cookieHeader.Length);
            cookie.Name = ASCIIEncoding.ASCII.GetString(cookieHeader, 0, 256).TrimEnd(new char[] { '=' }).Split('=')[0];
            cookie.Value = ASCIIEncoding.ASCII.GetString(cookieHeader, 0, 256).Split('=')[1].TrimEnd(new char[] { ';' });
            cookies.Add(cookie);
        }

        using (var outputStream = File.Create(outputFile))
        {
            var cookieBytes = new List<byte>();
            foreach (var cookie in cookies)
            {
                var cookieByteData = Encoding.ASCII.GetBytes($"{cookie.Name}={cookie.Value};");
                cookieBytes.AddRange(BitConverter.GetBytes(cookieByteData.Length));
                cookieBytes.AddRange(cookieByteData);
            }
            cookieBytes.AddRange(BitConverter.GetBytes(cookies.Count));
            outputStream.Write(cookieBytes.ToArray(), 0, cookieBytes.Count);
        }
    }
}

