public static XDocument UpdateConfigurationFile(string configFilePath, string newSearchProviderXml, string insertAfterXPath)
{
    XDocument config = XDocument.Load(configFilePath);
    XElement searchProvidersSection;
    try
    {
        searchProvidersSection = config.Descendants("searchProviders").FirstOrDefault();
    }
    catch (InvalidOperationException)
    {
        searchProvidersSection = new XElement("searchProviders");
        config.Add(searchProvidersSection);
    }

    if (!string.IsNullOrEmpty(newSearchProviderXml))
    {
        XDocument newSearchProviderDoc = XDocument.Parse(newSearchProviderXml);
        XElement newSearchProviderElement = newSearchProviderDoc.Root;
        int insertIndex = searchProvidersSection.ElementsAfterXPath(insertAfterXPath).Count();
        searchProvidersSection.InsertAt(insertIndex, newSearchProviderElement);
    }

    return config;
}

