public static Dictionary<string, object> GetCipherProperties(string algorithm)
{
    var properties = new Dictionary<string, object>();

    switch (algorithm.ToLower())
    {
        case "aes":
            properties["KeySize"] = 128;
            properties["BlockSize"] = 16;
            properties["IVLength"] = 16;
            properties["FeedbackSize"] = 0;
            properties["Mode"] = CipherMode.CBC;
            properties["Padding"] = PaddingMode.PKCS7;
            properties["LegalBlockSizes"] = new int[] { 16 };
            properties["LegalKeySizes"] = new int[] { 128, 192, 256 };
            break;
        case "des":
            properties["KeySize"] = 64;
            properties["BlockSize"] = 8;
            properties["IVLength"] = 8;
            properties["FeedbackSize"] = 0;
            properties["Mode"] = CipherMode.CBC;
            properties["Padding"] = PaddingMode.PKCS7;
            properties["LegalBlockSizes"] = new int[] { 8 };
            properties["LegalKeySizes"] = new int[] { 64, 128 };
            break;
        case "des3":
            properties["KeySize"] = 192;
            properties["BlockSize"] = 8;
            properties["IVLength"] = 8;
            properties["FeedbackSize"] = 0;
            properties["Mode"] = CipherMode.CBC;
            properties["Padding"] = PaddingMode.PKCS7;
            properties["LegalBlockSizes"] = new int[] { 8 };
            properties["LegalKeySizes"] = new int[] { 192 };
            break;
        case "blowfish":
            properties["KeySize"] = 448;
            properties["BlockSize"] = 64;
            properties["IVLength"] = 8;
            properties["FeedbackSize"] = 0;
            properties["Mode"] = CipherMode.CBC;
            properties["Padding"] = PaddingMode.PKCS7;
            properties["LegalBlockSizes"] = new int[] { 64 };
            properties["LegalKeySizes"] = new int[] { 128, 192, 224, 256, 384, 448 };
            break;
        case "twofish":
            properties["KeySize"] = 736;
            properties["BlockSize"] = 16;
            properties["IVLength"] = 16;
            properties["FeedbackSize"] = 0;
            properties["Mode"] = CipherMode.CBC;
            properties["Padding"] = PaddingMode.PKCS7;
            properties["LegalBlockSizes"] = new int[] { 16, 32 };
            properties["LegalKeySizes"] = new int[] { 128, 192, 224, 256, 384, 512, 576, 608, 736 };
            break;
        default:
            throw new ArgumentException("Invalid algorithm", nameof(algorithm));
    }

    return properties;
}

