public static T ReadLastObjectFromFile<T>(string filePath) where T : MarshalByRefObject
{
    if (!File.Exists(filePath))
        return default(T);

    FileStream fs = File.Open(filePath, FileMode.Open);
    BinaryFormatter bf = new BinaryFormatter();
    T lastObject = default(T);

    using (fs)
    {
        for (int i = 0; ; i++)
        {
            try
            {
                object o = bf.Deserialize(fs);
                if (!(o is T))
                    throw new InvalidOperationException("All objects in the file must be of type " + typeof(T).Name);

                lastObject = (T)o;
            }
            catch (EndOfStreamException)
            {
                return lastObject;
            }
        }
    }
}

