    if (systemSettingsNode != null)
    {
        foreach (XmlNode settingNode in systemSettingsNode.ChildNodes)
        {
            Console.WriteLine($"{settingNode.Name}: {settingNode.InnerText}");
        }
    }

    while (true)
    {
        Console.Write("Enter the name of a custom setting to update, or 'q' to quit: ");
        string settingName = Console.ReadLine();

        if (string.Equals(settingName, "q", StringComparison.OrdinalIgnoreCase))
            break;

        XmlNode updatedSettingNode = systemSettingsNode.SelectSingleNode(settingName);
        if (updatedSettingNode == null)
        {
            Console.WriteLine("Invalid setting name. Try again.");
            continue;
        }

        Console.Write($"Enter the new value for {settingName}: ");
        string newValue = Console.ReadLine();
        updatedSettingNode.InnerText = newValue;

        xmlDoc.Save(directoryPath + "\\config.xml");
    }
}

