        {
            object value = null;
            if (propertyInfo.PropertyType.GetInterface(typeof(IExportToXmlable).Name) != null)
            {
                var xmlable = Activator.CreateInstance(propertyInfo.PropertyType);
                ((IExportToXmlable)xmlable).ImportFromXml(element.OuterXml);
                value = xmlable;
            }
            else
