using System;
using System.Security.Cryptography;
using System.Text;

public static void TestSymmetricEncryption(Aes aes)
{
    byte[] key = aes.Key;
    int blockSize = aes.BlockSize / 8;
    int effectiveKeyBits = 0;
    for (int i = 0; i < aes.LegalKeySizes.Length; i++)
    {
        if (key.Length * 8 <= aes.LegalKeySizes[i].MinSize)
        {
            effectiveKeyBits = aes.LegalKeySizes[i].MinSize;
            break;
        }
    }

    byte[] plaintext = Encoding.UTF8.GetBytes("This is a test");
    byte[] encrypted = aes.CreateEncryptor()
                            .TransformFinalBlock(plaintext, 0, plaintext.Length);
    byte[] decrypted = aes.CreateDecryptor()
                           .TransformFinalBlock(encrypted, 0, encrypted.Length);

    bool areEqual = AreArraysEqual(plaintext, decrypted);
    if (!areEqual)
        throw new Exception("Encryption and decryption not inverse");

    byte[] zeroPadded = PadToBlockSize(encrypted);
    byte[] zeroDecrypted = aes.CreateDecryptor()
                              .TransformFinalBlock(zeroPadded, 0, zeroPadded.Length);

    areEqual = AreArraysEqual(decrypted, zeroDecrypted);
    if (!areEqual)
        throw new Exception("Zero padding decryption failed");

    void PadToBlockSize(byte[] input)
    {
        int blockSize = aes.BlockSize / 8;
        byte[] padded = new byte[blockSize];
        Array.Copy(input, 0, padded, Math.Min(input.Length, blockSize));
        return padded;
    }

    bool AreArraysEqual(byte[] a1, byte[] a2)
    {
        if (a1.Length != a2.Length) return false;
        for (int i = 0; i < a1.Length; i++)
            if (a1[i] != a2[i]) return false;
        return true;
    }
}

