public static double[] mutateValue(Random random, double value, double stdDev) {
    double mutatedValue = value + (random.nextGaussian() * stdDev);
    List<Double> discreteValues = new ArrayList<>();

    for(double i = 0; i <= mutatedValue; i += 1.0) {
        discreteValues.add(i);
    }

    return new double[]{mutatedValue, discreteValues.stream().mapToDouble(Double::doubleValue).toArray()};
}

