public static String generateJson(Object obj) {
    if (obj == null) {
        return "null";
    }

    StringBuilder json = new StringBuilder();
    json.append("{");

    switch (obj.getClass().getName()) {
        case "OBJECT":
            OBJECT objObject = (OBJECT) obj;
            json.append("\"first_name\":\"" + objObject.getFirstName() + "\",");
            json.append("\"last_name\":\"" + objObject.getLastName() + "\",");
            json.append("\"ssn\":\"" + objObject.getSsn() + "\"");
            break;
        case "GEO_POINT":
            GEO_POINT geoPoint = (GEO_POINT) obj;
            json.append("\"lat\":\"" + geoPoint.getLatitude() + "\",");
            json.append("\"lon\":\"" + geoPoint.getLongitude() + "\"");
            break;
        case "GEO_SHAPE":
            // implement JSON generation for GEO_SHAPE
            break;
        default:
            json.append(obj.toString());
    }

    if (json.length() > 1) {
        json.deleteCharAt(json.length() - 1);
    } else {
        return "null";
    }

    json.append("}");

    return json.toString();
}
