import java.security.SecureRandom;
import java.util.Random;

public class Main {
    public static String generatePassword(int length) {
        final String lowercase = "abcdefghijklmnopqrstuvwxyz";
        final String uppercase = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        final String digits = "0123456789";
        final String special = "!@#$%^&*()_+-={}[]|<>?,./~`";

        Random random = new SecureRandom();
        StringBuilder password = new StringBuilder();

        // Add a mix of lowercase, uppercase and digits
        for(int i = 0; i < length - 3; i++) {
            int randIndex;
            if(i < length / 3) {
                randIndex = random.nextInt(lowercase.length());
            } else if(i > length / 2) {
                randIndex = random.nextInt(digits.length());
            } else {
                randIndex = random.nextInt(uppercase.length());
            }
            password.append(lowercase.charAt(randIndex));
        }

        // Add a mix of special characters at the end
        for(int i = 0; i < 3; i++) {
            int randIndex = random.nextInt(special.length());
            password.append(special.charAt(randIndex));
        }

        return password.toString();
    }
}

```java
public static <T> T getRandomValue(Random rand, Class<T> type) {
    if (type.equals(byte.class)) {
        return (T)(byte)rand.nextInt(Byte.MAX_VALUE);
    } else if (type.equals(short.class)) {
        return (T)(short)rand.nextInt(Short.MAX_VALUE);
    } else if (type.equals(int.class)) {
        return (T)rand.nextInt();
    } else if (type.equals(long.class)) {
        return (T)(long)rand.nextLong();
    } else if (type.equals(float.class)) {
        return (T)(float)rand.nextFloat();
    } else if (type.equals(double.class)) {
        return (T)rand.nextDouble();
    } else if (type.equals(char.class)) {
        int val = rand.nextInt(Character.MAX_VALUE);
        return (T)(char)(val + 1); // '0' is the first printable character
    } else if (type.equals(String.class)) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rand.nextInt(10) + 1; i++) {
            int charCode = rand.nextInt(Character.MAX_VALUE);
            sb.append((char)(charCode + 1)); // '0' is the first printable character
        }
        return (T)sb.toString();
    } else if (DecimalType.class.isAssignableFrom(type)) {
        BigDecimal val = new BigDecimal(rand.nextDouble()).setScale(2, RoundingMode.HALF_UP);
        return (T)(Object)val;
    } else {
        throw new RuntimeException("Unsupported type: " + type.getName());
    }
}

