import org.junit.Assert;
import org.lucene.index.Term;
import org.lucene.search.IndexSearcher;
import org.lucene.search.Query;

public void compareNumericFields(IndexReader reader1, IndexReader reader2) throws IOException {
    Term term = new Term("field_name", "document_id");
    Query query1 = new TermQuery(term);
    Query query2 = new TermQuery(term);

    IndexSearcher searcher1 = new IndexSearcher(reader1);
    IndexSearcher searcher2 = new IndexSearcher(reader2);

    TopDocs topdocs1 = searcher1.search(query1, 10);
    TopDocs topdocs2 = searcher2.search(query2, 10);

    for (ScoreDoc first = topdocs1.scoreDocs.length - 1; first >= 0; --first) {
        Document document1 = reader1.document(topdocs1.scoreDocs[first].doc);
        Document document2 = reader2.document(topdocs2.scoreDocs[first].doc);

        NumericField field1 = (NumericField) document1.get("numeric_field");
        NumericField field2 = (NumericField) document2.get("numeric_field");

        Assert.assertThat(field1.longValue(), org.hamcrest.core.Is.is(field2.longValue()));
    }

    int count1 = reader1.maxDoc();
    int count2 = reader2.maxDoc();

    Assert.assertEquals(count1, count2);
}

