import java.util.*;

public static void processPairs(List<Pair> pairs) {
    int processed = 0;
    Random random = new Random();
    while (processed < pairs.size() * 25 / 100) { // Process 25% of the list
        Pair currentPair = pairs.get(processed);
        System.out.println("Processing pair: " + currentPair.getRandomInteger() + ", " + currentPair.isBooleanValue());
        if (processed == pairs.size() - 1) {
            System.out.println("This is the last pair.");
        } else {
            int prevIndex = random.nextInt(processed + 1);
            Pair prevPair = pairs.get(prevIndex);
            System.out.println("Moving to previous pair index: " + prevIndex);
            pairs.set(processed, prevPair);
            pairs.set(prevIndex, currentPair);
        }
        processed++;
    }
}
