private static final Random RAND = new Random();
private static final int MAX_OPERATIONS = 2;

public void simulate(Node node) {
    int actualHearts = node.getHeartbeatCount();
    int actualClears = node.getPrimaryClearCount();

    for (int i = 0; i < MAX_OPERATIONS; i++) {
        double randomValue = RAND.nextDouble();
        if (randomValue < 0.5) {
            node.reportHeartbeat();
        } else if (randomValue < 1.0) {
            node.clearPrimary();
        }
    }

    int expectedHearts = actualHearts + (int) Math.floor(MAX_OPERATIONS * 0.5);
    int expectedClears = actualClears + (int) Math.floor(MAX_OPERATIONS * 0.5);

    System.out.println("Expected heartbeat: " + expectedHearts);
    System.out.println("Actual heartbeat: " + node.getHeartbeatCount());
    System.out.println("Difference in heartbeats: " + (expectedHearts - node.getHeartbeatCount()));

    System.out.println("Expected clears: " + expectedClears);
    System.out.println("Actual clears: " + node.getPrimaryClearCount());
    System.out.println("Difference in clears: " + (expectedClears - node.getPrimaryClearCount()));
}

