import java.io.IOException;
import java.net.InetSocketAddress;
import java.util.ArrayList;
import java.util.List;

public List<InetSocketAddress> createInetAddressList(List<String> hostPorts, String username, String password, int serverID, boolean enrichmentConnection, String driverLocation, String driverName, int connectionTimeout) {
    List<InetSocketAddress> inetAddresses = new ArrayList<>();
    for (String hostPort : hostPorts) {
        String[] parts = hostPort.split(":");
        if (parts.length != 2) {
            throw new ArrayIndexOutOfBoundsException("Invalid input format: " + hostPort);
        }
        try {
            int port = Integer.parseInt(parts[1].trim());
            inetAddresses.add(new InetSocketAddress(parts[0], port));
        } catch (NumberFormatException e) {
            throw new ArrayIndexOutOfBoundsException("Invalid port number: " + parts[1]);
        }
    }
    return inetAddresses;
}

