```java
import javax.crypto.Cipher;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.IvParameterSpec;
import java.security.spec.KeySpec;
import java.security.spec.PBEPParameterSpec;
import java.util.Base64;

public static String generateAESKeyAndEncryptDecrypt(String password, byte[] salt) throws Exception {
    KeySpec keySpec = new PBEKeySpec(password.toCharArray(), salt, 65536, 128);
    SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
    byte[] keyBytes = factory.generateSecret(keySpec).getEncoded();

    IvParameterSpec iv = new IvParameterSpec(new byte[16]); // CBC requires an initialization vector
    KeySpec aesKeySpec = new javax.crypto.spec.SecretKeySpec(keyBytes, "AES");

    Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
    cipher.init(Cipher.ENCRYPT_MODE, (javax.crypto.Key) aesKeySpec, iv);

    String dataToEncrypt = "Hello, World!";
    byte[] plainText = dataToEncrypt.getBytes();
    byte[] encryptedData = cipher.doFinal(plainText);
    String encryptedString = Base64.getEncoder().encodeToString(encryptedData);

    // Decrypt the data
    cipher.init(Cipher.DECRYPT_MODE, (javax.crypto.Key) aesKeySpec, iv);
    byte[] decryptedData = cipher.doFinal(Base64.getDecoder().decode(encryptedString));
    String decryptedString = new String(decryptedData);

    return encryptedString;
}
