import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.random.RandomDataGenerator;

public List<Object> modifyList(List<Object> original) {
    RandomDataGenerator generator = new RandomDataGenerator();
    double stdDev = 0.2 * original.size();
    List<Object> modified = new ArrayList<>();

    for (Object obj : original) {
        if (generator.nextBoolean()) {
            // generate a random value from Gaussian distribution
            double val = generator.generateGaussian(0, stdDev);
            // use this value to create a new object
            Object newObj = null;  // implementation depends on the type of objects in the list
            modified.add(newObj);
        } else {
            modified.add(obj);
        }
    }

    // return all possible discrete values that can be obtained by calling the method multiple times
    List<Object> discreteValues = new ArrayList<>();
    for (int i = 0; i < Math.pow(2, original.size()); i++) {
        List<Object> valueList = new ArrayList<>(original);
        for (int j = 0; j < original.size(); j++) {
            if ((i >> j) % 2 == 1) {
                // replace the object at index j with a new one
                valueList.set(j, null);  // implementation depends on the type of objects in the list
            }
        }
        discreteValues.add(valueList);
    }

    return modified;
}

