public SortedBinaryDocValues performComparison(Random random, LeafReaderContext context, IndexFieldData field1, IndexFieldData field2, Preprocessor preprocessor) {
    List<BytesRef> results = new ArrayList<>();

    for (int i = 0; i < field1.docCount(); i++) {
        int docID = field1.docID(i);

        BytesRef value1 = (BytesRef) field1.value(i);
        BytesRef value2 = (BytesRef) field2.value(i);

        if (preprocessor != null) {
            value1 = preprocessor.processBytesRef(value1);
            value2 = preprocessor.processBytesRef(value2);
        }

        int[] comparisons = new int[field1.docCount()];
        for (int j = 0; j < field1.docCount(); j++) {
            int otherDocID = field1.docID(j);

            BytesRef otherValue1 = (BytesRef) field1.value(j);
            BytesRef otherValue2 = (BytesRef) field2.value(j);

            if (preprocessor != null) {
                otherValue1 = preprocessor.processBytesRef(otherValue1);
                otherValue2 = preprocessor.processBytesRef(otherValue2);
            }

            int comparison = BinaryComparator.INSTANCE.compare(value1, value2, otherValue1, otherValue2);
            comparisons[j] = comparison;
        }

        Arrays.sort(comparisons);

        for (int j = 0; j < field1.docCount(); j++) {
            if (comparisons[j] == 0) {
                results.add(value1);
            } else if (comparisons[j] > 0) {
                while (j + 1 < field1.docCount() && comparisons[j] >= 0) {
                    j++;
                }
                results.add((BytesRef) field1.value(j));
                break;
            }
        }
    }

    return new SortedBinaryDocValues(results);
}
