    URL url = classloader.getResource(resourceUrl);
    if (url != null) {
        return url.openStream();
    }
    else {
        try {
            url = new URL(resourceUrl);
            return url.openStream();
        } catch (MalformedURLException e) {
            throw new RuntimeException(e);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

