class Graph {
    private int vertices;
    private int edges;
    private AtomicLong completedThreads;

    public Graph(int vertices, int edges) {
        this.vertices = vertices;
        this.edges = edges;
        this.completedThreads = new AtomicLong(0);
    }

    public void traverseVertex(int vertex) {
        try {
            Thread.sleep(1000); // Simulate work
            System.out.println("Thread " + Thread.currentThread().getId() + ": Traversed vertex " + vertex);
            completedThreads.incrementAndGet();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Graph graph = new Graph(5, 10);

        for (int i = 0; i < graph.vertices; i++) {
            Thread thread = new Thread(() -> graph.traverseVertex(i));
            thread.start();
        }

        while (graph.completedThreads.get() < graph.vertices) {
            // Wait for all threads to complete
            Thread.sleep(100);
        }

        System.out.println("Number of vertices: " + graph.vertices);
        System.out.println("Number of edges: " + graph.edges);
        System.out.println("Completed threads: " + graph.completedThreads.get());
    }
}

