```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ProcessReturnInfo {
    private int exitCode;
    private String stdout;
    private String stderr;

    public ProcessReturnInfo(int exitCode, String stdout, String stderr) {
        this.exitCode = exitCode;
        this.stdout = stdout;
        this.stderr = stderr;
    }

    // Getters
    public int getExitCode() {
        return exitCode;
    }

    public String getStdout() {
        return stdout;
    }

    public String getStderr() {
        return stderr;
    }
}

public class Main {

    public static ProcessReturnInfo executeCommand(String command) throws IOException, InterruptedException {
        Runtime runtime = Runtime.getRuntime();
        Process process = runtime.exec(command);

        BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder stdoutBuilder = new StringBuilder();
        String line;
        while ((line = stdoutReader.readLine()) != null) {
            stdoutBuilder.append(line).append("\n");
        }

        BufferedReader stderrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        StringBuilder stderrBuilder = new StringBuilder();
        while ((line = stderrReader.readLine()) != null) {
            stderrBuilder.append(line).append("\n");
        }

        int exitCode = process.waitFor();

        process.destroy();

        return new ProcessReturnInfo(exitCode, stdoutBuilder.toString(), stderrBuilder.toString());
    }
}
