```java
public class JsonGenerator {
    public static String generateJson(Object obj) {
        StringBuilder json = new StringBuilder();
        generateJson(obj, json, 0);
        return "{\"" + obj.getClass().getSimpleName() + "\":" + json.toString().replaceFirst("^[{}]", "") + "}";
    }

    private static void generateJson(Object obj, StringBuilder sb, int depth) {
        if (obj == null) {
            sb.append("null");
            return;
        }
        if (depth > 0) {
            sb.append(", ");
        }
        if (obj instanceof String) {
            sb.append("\"").append(obj).append "\"");
        } else if (obj instanceof Boolean) {
            sb.append(obj);
        } else if (obj instanceof Integer || obj instanceof Long || obj instanceof Double || obj instanceof Float) {
            sb.append(obj);
        } else if (obj instanceof Character) {
            sb.append("\"").append(obj).append "\"");
        } else if (obj.getClass().isArray()) {
            sb.append("[");
            Object[] array = (Object[]) obj;
            for (int i = 0; i < array.length; i++) {
                generateJson(array[i], sb, depth + 1);
                if (i < array.length - 1) {
                    sb.append(",");
                }
            }
            sb.append("]");
        } else {
            sb.append("{");
            java.lang.reflect.Field[] fields = obj.getClass().getDeclaredFields();
            for (int i = 0; i < fields.length; i++) {
                try {
                    fields[i].setAccessible(true);
                    Object value = fields[i].get(obj);
                    if (value != null) {
                        sb.append("\"").append(fields[i].getName()).append("\":");
                        generateJson(value, sb, depth + 1);
                    }
                } catch (IllegalAccessException e) {
                    throw new RuntimeException(e);
                }
            }
            sb.append("}");
        }
    }
}

