import java.util.List;
import java.util.Map;
import java.util.HashMap;

public Map<Object, Double> normalizeWeights(List<Map.Entry<Object, Double>> weightedItems, Function<Map.Entry<Object, Double>, Double> weightFunction) {
    double totalWeight = 0.0;

    for (Map.Entry<Object, Double> item : weightedItems) {
        totalWeight += item.getValue();
    }

    Map<Object, Double> normalizedWeights = new HashMap<>();

    for (Map.Entry<Object, Double> item : weightedItems) {
        double weight = weightFunction.apply(item);
        normalizedWeights.put(item.getKey(), weight / totalWeight);
    }

    return normalizedWeights;
}

