        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            SAXParser saxParser = factory.newSAXParser();

            // Create a handler for parsing and error reporting
            XMLHandler handler = new XMLHandler();
            InputSource inputSource = new InputSource(xmlFile);
            saxParser.parse(inputSource, handler);

        } catch (Exception e) {
            System.out.println("Error parsing XML file: " + e.getMessage());
        }
    }
}

class XMLHandler extends org.xml.sax.helpers.DefaultHandler {

    public void error(SAXException e) {
        System.out.println("SAX Exception: " + e.getMessage());
    }

    public void fatalError(SAXException e) throws SAXException {
        System.out.println("Fatal Error parsing XML file: " + e.getMessage());
        throw e;
    }
}
