import java.util.Arrays;
import java.util.Random;

class DisjointPairCounter {
    public static int countDisjointPairs(int[] arr) {
        if (arr == null || arr.length <= 1) return 0;

        UnionFind uf = new UnionFind(arr.length);
        long start = System.nanoTime();

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (uf.find(i, arr[i]) != uf.find(j, arr[j])) {
                    System.out.println((System.nanoTime() - start) / 1000000.0 + " ms");
                    System.out.println("Disjoint pair found: (" + i + ", " + j + ")");
                }
            }
        }

        return (int) ((System.nanoTime() - start) / 1000000.0);
    }
}

class UnionFind {
    private int[] parent;
    private Random rand = new Random();

    public UnionFind(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    public int find(int x, int val) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], val);
        }
        return parent[x];
    }

    public void union(int x, int y, int val) {
        int rootX = find(x, val);
        int rootY = find(y, val);

        if (rootX != rootY) {
            if (rand.nextInt(2) == 0) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
            }
        }
    }
}

