RectF getRandomCrop(RectF drawableBounds, RectF viewportBounds) {
    float drawableAspect = (float) drawableBounds.width() / drawableBounds.height();
    float viewportAspect = (float) viewportBounds.width() / viewportBounds.height();

    // Calculate the maximum possible crop rectangle based on aspect ratios
    float maxCropWidth;
    float maxCropHeight;
    if (drawableAspect > viewportAspect) {
        maxCropWidth = viewportBounds.width();
        maxCropHeight = maxCropWidth / drawableAspect;
    } else {
        maxCropHeight = viewportBounds.height();
        maxCropWidth = maxCropHeight * drawableAspect;
    }

    // Randomly scale the crop rectangle
    float scaleFactor = (float) Math.random();
    scaleFactor = Math.max(scaleFactor, 0.5f); // Minimum size constraint

    float cropWidth = maxCropWidth * scaleFactor;
    float cropHeight = maxCropHeight * scaleFactor;

    // Calculate the x and y offsets for the crop rectangle
    float xOffset = (float) Math.random() * (drawableBounds.width() - cropWidth);
    float yOffset = (float) Math.random() * (drawableBounds.height() - cropHeight);

    return new RectF(
        drawableBounds.centerX() - cropWidth / 2f + xOffset,
        drawableBounds.centerY() - cropHeight / 2f + yOffset,
        drawableBounds.centerX() + cropWidth / 2f,
        drawableBounds.centerY() + cropHeight / 2f
    );
}

