public void connectToRemoteAddress(String host, int port) throws Exception {
    java.nio.channels.SocketChannel channel = java.nio.channels.spi.AbstractPlainSocketImpl-channel( new InetSocketAddress(host, port));
    try {
        if (!channel.connect(new InetSocketAddress(host, port)).isConnected()) {
            throw new IOException("Failed to connect to " + host + ":" + port);
        }
        while (true) {
            java.nio.channels.SelectionKey key = channel.keyFor(channel.selector());
            switch (key.readyOps()) {
                case SelectionKey.OP_CONNECT:
                    if (!channel.isConnectionEstablished()) {
                        channel.finishConnect();
                        System.out.println("Connected to " + host + ":" + port);
                    }
                    break;
                case SelectionKey.OP_READ:
                    byte[] buffer = new byte[1024];
                    int bytesRead = channel.read(buffer);
                    if (bytesRead == -1) {
                        System.out.println("Disconnected from " + host + ":" + port);
                        return;
                    } else {
                        System.out.println("Received: " + new String(buffer, 0, bytesRead));
                    }
                    break;
                case SelectionKey.OP_WRITE:
                    byte[] writeBuffer = new byte[1024];
                    // Write logic
                    channel.write(writeBuffer);
                    break;
            }
        }
    } catch (IOException e) {
        System.out.println("Exception while connecting to " + host + ":" + port + ": " + e.getMessage());
    }
}
