public void configureOpenAPIWithKeycloak(OpenAPI openAPI) {
    SecurityScheme oidcSecurityScheme = new OpenAPISecurityScheme();
    oidcSecurityScheme.setName("oidc");
    oidcSecurityScheme.setDescription("OpenID Connect with Keycloak");
    oidcSecurityScheme.setType(SecuritySchemeType.OAUTH2);

    String issuerUrl = "https://your-keycloak-instance.com/auth/realms/your-realm";
    String clientId = "your-client-id";
    String clientSecret = "your-client-secret";

    AuthorizationFlow authenticationFlow = new OpenAPIAuthorizationFlow();
    authenticationFlow.setOAuth2("oidc");
    oidcSecurityScheme.setFlows(Collections.singletonList(authenticationFlow));

    TokenEndpoint tokenEndpoint = new OpenAPITokenEndpoint();
    tokenEndpoint.setAuthorizeUrl(issuerUrl + "/auth/realms/" + "your-realm" + "/protocol/openid-connect/token");
    tokenEndpoint.setAccessTokenUrl(issuerUrl + "/auth/realms/" + "your-realm" + "/protocol/openid-connect/token");

    oidcSecurityScheme.setTokenEndpoint(tokenEndpoint);

    TokenRequest tokenRequest = new OpenAPITokenRequest();
    tokenRequest.setBody(new HashMap<String, String>());
    tokenRequest.setFormParameters(new ArrayList<OpenAPIParameter>());
    tokenRequest.setQuery(new HashMap<String, String>());

    tokenRequest.getAuthorization().add("grant_type=authorization_code");
    tokenRequest.getAuthorization().add("code=" + clientId);
    tokenRequest.getAuthorization().add("redirect_uri=" + "your-redirect-uri");

    oidcSecurityScheme.setTokenRequest(tokenRequest);

    // Adding nonce parameter to prevent CSRF attacks
    tokenRequest.getQuery().put("nonce", UUID.randomUUID().toString());

    openAPI.addSecurityItem(new OpenAPISecurityRequirement());
    openAPI.addSecuritySchemes(oidcSecurityScheme.getName(), oidcSecurityScheme);
}

