import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.security.SecurityScheme;

public void configureOpenAPISecurity(OpenAPI openAPI, String keycloakRealmPath) {
    SecurityScheme oidcSecurityScheme = new SecurityScheme()
            .type(SecurityScheme.Type.OAUTH2)
            .flows(new OAuth2Flow().authorizationUrl("https://your-keycloak-instance.com/auth/realms/" + keycloakRealmPath + "/protocol/openid-connect/auth")
                    .tokenUrl("https://your-keycloak-instance.com/auth/realms/" + keycloakRealmPath + "/protocol/openid-connect/token"))
            .scopes(new ArrayList<>());

    openAPI.addSecurityItem(new OpenAPI.SecurityRequirement().name("oidc"));

    SecurityScheme oauth2SecurityScheme = new SecurityScheme()
            .type(SecurityScheme.Type.OAUTH2)
            .flows(new OAuth2Flow().authorizationUrl("https://your-keycloak-instance.com/auth/realms/" + keycloakRealmPath + "/protocol/openid-connect/oauth-code")
                    .tokenUrl("https://your-keycloak-instance.com/auth/realms/" + keycloakRealmPath + "/protocol/openid-connect/token"))
            .scopes(new ArrayList<>())
            .flow(OAuth2Flow.OAUTH2_1_0)
            .extensions(new HashMap<String, Object>().put("oauth2.0AuthorizationCodeFlow", new OAuth2_0_Authorization_Code_Flow()
                    .authorizationUrl("https://your-keycloak-instance.com/auth/realms/" + keycloakRealmPath + "/protocol/openid-connect/oauth-code")
                    .tokenUrl("https://your-keycloak-instance.com/auth/realms/" + keycloakRealmPath + "/protocol/openid-connect/token"))
            );

    openAPI.addSecurityItem(new OpenAPI.SecurityRequirement().name("oauth2"));

}

