public void assertPointSetsEqual(PointSet set1, PointSet set2, double tolerance) {
    for (PointDocument doc : set1) {
        PointDocument doc2 = set2.get(doc.getId());
        if (!doc2.equals()) continue;

        int[] coords1 = doc.getCoordinates();
        int[] coords2 = doc2.getCoordinates();
        if (coords1.length != coords2.length) {
            throw new AssertionError("Number of coordinates mismatched for document " + doc.getId());
        }

        for (int i = 0; i < coords1.length; i++) {
            if (Math.abs(coords1[i] - coords2[i]) > tolerance) {
                throw new AssertionError("Coordinate values exceeded tolerance for document " + doc.getId() + ": (" + coords1[i] + ", " + coords2[i] + ")");
            }
        }
    }
}
