public void sendEmail(boolean success, Activity activity) {
    WeakReference<Activity> activityWeakRef = new WeakReference<>(activity);
    if (success) {
        Runnable runnable = () -> {
            Intent intent = new Intent(Intent.ACTION_SENDTO);
            intent.setData(Uri.parse("mailto:"));
            intent.putExtra(Intent.EXTRA_SUBJECT, "Method Succeeded");
            try {
                activityWeakRef.get().startActivity(intent);
            } catch (Exception e) {
                Log.e("Error", "Failed to start email intent");
            }
        };
        activityWeakRef.get().runOnUiThread(runnable);
    } else {
        Intent intent = new Intent(Intent.ACTION_SENDTO);
        intent.setData(Uri.parse("mailto:"));
        intent.putExtra(Intent.EXTRA_SUBJECT, "Method Failed");
        try {
            activityWeakRef.get().startActivity(intent);
        } catch (Exception e) {
            Log.e("Error", "Failed to start email intent");
        }
    }
}

