public class Main {
    public static void main(String[] args) {
        Gson gson = new GsonBuilder().create();
        JsonArray jsonArray = new JsonArray();

        Random random = new Random();
        List<JsonEvent> events = new ArrayList<>();

        for (int i = 0; i < 10; i++) {
            JsonEvent event = new JsonEvent(random.nextInt(100) + 1, Math.round(random.nextGaussian()));
            events.add(event);

            JsonObject jsonObject = new JsonObject();
            jsonObject.addProperty("header", event.getMessageNumber());
            jsonObject.addProperty("body", event.get GaussianValue());
            jsonArray.add(jsonObject);
