import java.util.ArrayList;
import java.util.List;

public List<SensorData> generateSensorData(List<LocationTime> locationTimes, List<double[]> stdDevs, double stepPerSec) {
    List<SensorData> sensorDataList = new ArrayList<>();
    for (LocationTime locationTime : locationTimes) {
        SensorData sensorData = new SensorData();
        sensorData.setTimestamp(locationTime.getTimestamp());
        sensorData.setType("ACC");

        double[] readings = new double[3];
        for (int i = 0; i < 3; i++) {
            double randomValue = Math.random() * stdDevs.get(i).length;
            int index = (int) (randomValue % stdDevs.get(i).length);
            readings[i] = stdDevs.get(i)[index] + Math.random() * stepPerSec;
        }

        sensorData.setData(readings);

        sensorDataList.add(sensorData);
    }

    return sensorDataList;
}

