public boolean getDelegationToken(String url, int port) throws IOException {
    try (KerberosClient client = new KerberosClient(url, port)) {
        URI uri = URI.create("https://" + url + ":" + port);
        KerberosTicket ticket = client.getTicket(uri);
        return ticket != null;
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new IOException("Interrupted while retrieving delegation token", e);
    }
