import java.io.*;
import java.util.*;

class CustomObject implements Serializable {
    int d;
    double x;
    float y;
    boolean z;

    public CustomObject(int d, double x, float y, boolean z) {
        this.d = d;
        this.x = x;
        this.y = y;
        this.z = z;
    }
}

public class Main {
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        CustomObject obj = new CustomObject(10, 20.5, (float) 30.6, true);

        // Serialization
        FileOutputStream fileOut = new FileOutputStream("output.ser");
        ObjectOutputStream out = new ObjectOutputStream(fileOut);
        out.writeObject(obj);
        out.close();
        fileOut.close();

        // Deserialization
        FileInputStream fileIn = new FileInputStream("output.ser");
        ObjectInputStream in = new ObjectInputStream(fileIn);
        CustomObject objDeserialized = (CustomObject)in.readObject();
        in.close();
        fileIn.close();

        System.out.println("Original object d: " + obj.d);
        System.out.println("Original object x: " + obj.x);
        System.out.println("Original object y: " + obj.y);
        System.out.println("Original object z: " + obj.z);

        System.out.println("Deserialized object d: " + objDeserialized.d);
        System.out.println("Deserialized object x: " + objDeserialized.x);
        System.out.println("Deserialized object y: " + objDeserialized.y);
        System.out.println("Deserialized object z: " + objDeserialized.z);
    }
}

