import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.Scanner;

public class Server {

    public static void main(String[] args) throws IOException {
        int port = 8000; // specify the port number
        String address = "localhost"; // specify the host name or IP

        Selector selector = Selector.open();
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.bind(new InetSocketAddress(address, port));
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        System.out.println("Server started. Listening on " + address + ":" + port);

        Scanner scanner = new Scanner(System.in);

        while (true) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isValid() && key.isAcceptable()) {
                    ServerSocketChannel ssc = (ServerSocketChannel) key.channel();
                    ServerSocket serverSocket = ssc.socket();
                    BufferedReader in = new BufferedReader(new InputStreamReader(serverSocket.accept().socket().getInputStream()));
                    System.out.println("New connection from " + serverSocket.getInetAddress());

                    while (true) {
                        String inputLine;
                        try {
                            inputLine = in.readLine();
                            if (inputLine != null) {
                                System.out.println("Received: " + inputLine);
                                if (inputLine.equalsIgnoreCase("exit")) {
                                    System.out.println("Exiting...");
                                    break;
                                } else if (inputLine.startsWith("send")) {
                                    String message = inputLine.substring(5);
                                    in.write((message + "\n").getBytes());
                                    in.flush();
                                }
                            }
                        } catch (IOException e) {
                            System.out.println("Error handling client request: " + e.getMessage());
                            break;
                        }

                    }

                }
            }
            selector.selectedKeys().clear();

            String command = scanner.nextLine();
            if (command.equalsIgnoreCase("exit")) {
                System.out.println("Exiting...");
                break;
            } else if (command.startsWith("send")) {
                String message = command.substring(5);
                for (SelectionKey key : selector.keys()) {
                    ServerSocketChannel ssc = (ServerSocketChannel) key.channel();
                    BufferedReader in = new BufferedReader(new InputStreamReader(ssc.socket().getInputStream()));
                    in.write((message + "\n").getBytes());
                    in.flush();
                }
            }

        }

        scanner.close();

    }
}

