import javax.crypto.*;
import java.security.*;
import java.nio.ByteBuffer;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        // Generate AES encryption key using specified algorithm and key size
        KeyGenerator keygen = KeyGenerator.getInstance("AES");
        keygen.init(256); // 256-bit key
        SecretKey secretKey = keygen.generateKey();

        // Initialize Cipher for CTR mode of operation
        Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
        IvParameterSpec iv = new IvParameterSpec(new byte[16]); // 128-bit IV
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, iv);

        // Input message to encrypt
        String inputMessage = "Hello, World!";

        // Encrypt input message using generated key and CTR mode of operation
        byte[] encryptedBytes = cipher.doFinal(inputMessage.getBytes());

        // Convert encrypted bytes to hexadecimal format
        StringBuilder hexString = new StringBuilder();
        for (byte b : encryptedBytes) {
            String hex = Integer.toHexString(b & 0xFF);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }

        System.out.println("Encrypted message in hexadecimal format: " + hexString.toString());
    }
}

