import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public byte[] concatHashes(byte[] data) {
    MessageDigest md5 = getMessageDigest("MD5");
    MessageDigest md2 = getMessageDigest("MD2");

    md5.update(data);
    byte[] md5Bytes = getDigestBytes(md5);

    md2.update(data);
    byte[] md2Bytes = getDigestBytes(md2);

    byte[] result = new byte[md5Bytes.length + md2Bytes.length];
    System.arraycopy(md5Bytes, 0, result, 0, md5Bytes.length);
    System.arraycopy(md2Bytes, 0, result, md5Bytes.length, md2Bytes.length);

    return result;

}

private MessageDigest getMessageDigest(String algorithm) {
    try {
        return MessageDigest.getInstance(algorithm);
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

private byte[] getDigestBytes(MessageDigest digest) {
    digest.digest();
    return digest.digest();
}

