public class Main {
    public static Uri downLoadFile(String urlStr) throws MalformedURLException, IOException {
        URL url = new URL(urlStr);
        HttpURLConnection con = (HttpURLConnection) url.openConnection();
        con.setRequestMethod("GET");
        con.setConnectTimeout(5000); // set connect timeout to 5 seconds

        if(con.getResponseCode() != 200) { 
            return null; 
        }

        InputStream input = con.getInputStream();
        File file = new File("path_to_your_file.txt"); // set your desired path and filename
        FileOutputStream output = new FileOutputStream(file);
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = input.read(buffer)) != -1) {
            output.write(buffer, 0, bytesRead);
        }
        output.close();
        input.close();

        return Uri.fromFile(file); // Return the file's URI
    }
}

public static <T> ByteArrayOutputStream serializeAndDeserialize(T obj) {
    try {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        oos.writeObject(obj);
        oos.close();

        ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());
        ObjectInputStream ois = new ObjectInputStream(bis);
        T deserializedObj = (T) ois.readObject();
        ois.close();

        return bos;
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
}

