import java.io.IOException;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.ExecutionException;

public class NonBlockingSocket {
    public static void main(String[] args) throws IOException, InterruptedException, ExecutionException {
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();
        channel.connect("localhost", 8080, new CompletionHandler<AsynchronousSocketChannel, Void>() {
            @Override
            public void completed(AsynchronousSocketChannel ch, Void att) {
                try {
                    byte[] message = "Hello from client!".getBytes();
                    channel.write(message);
                    System.out.println("Message sent successfully");
                } catch (IOException e) {
                    System.err.println("Error sending message: " + e.getMessage());
                }
            }

            @Override
            public void failed(Throwable exc, Void att) {
                System.err.println("Connection failed: " + exc.getMessage());
            }
        });
    }
}

