import org.apache.zookeeper.ZooKeeper;
import org.apache.zookeeper.server.NIOServerSocketFactory;
import org.apache.zookeeper.server.ServerCnxnFactory;

public class Main {
    public static void main(String[] args) {
        int port = 2181;
        int startPort = 2181;
        int endPort = 2190;
        String dataDir = "/tmp/myzookeeper";

        ServerCnxnFactory serverCnxnFactory = new NIOServerSocketFactory();

        for (int p : getAvailablePorts(startPort, endPort)) {
            try {
                ZooKeeperServer zkServer = new ZooKeeperServer(dataDir, new InetSocketAddress(p));
                zkServer.setServerCnxnFactory(serverCnxnFactory);
                zkServer.setTickTime(2000);
                zkServer.setMinSessionTimeout(15000);
                zkServer.setMaxSessionTimeout(30000);
                zkServer.start();
            } catch (BindException e) {
                // Ignore BindException
            }
        }
    }

    private static List<Integer> getAvailablePorts(int startPort, int endPort) {
        List<Integer> availablePorts = new ArrayList<>();
        for (int port = startPort; port <= endPort; port++) {
            try {
                ServerSocket socket = new ServerSocket(port);
                socket.close();
                availablePorts.add(port);
            } catch (IOException e) {
                // Port not available, skip
            }
        }
        return availablePorts;
    }
}

