    connector.getFilterChain().addLast("heartbeat", new HeartbeatFilter());

    DefaultSessionConfig config = new DefaultSessionConfig();
    config.setMaxReadBufferSize(2048);
    config.setSoLingerTime(1000);

    connector.getSessionConfig().setDefault(config);

    executor = Executors.newFixedThreadPool(MAX_POOL_SIZE); // set MAX_POOL_SIZE as needed

    connector.setWorkerPoolExecutor(executor);

    IoAcceptor acceptor = connector.asynConnect(host, port, 30000);
    IoSession session = null;
    try {
        session = acceptor.await();
    } catch (IOException e) {
        // handle connection failure
    }

    return session;
}
