        ProcessBuilder builder = new ProcessBuilder("keytool", "-genkeypair",
                "-storetype", "jks",
                "-keyalg", "RSA",
                "-alias", hostname,
                "-validity", "360",
                "-keysize", "2048",
                "-storepass", "password123",
                "-keystore", keystorePath);

        builder.redirectErrorStream(true);
        Process process = builder.start();

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.out.println("Failed to generate the keystore.");
        } else {
            System.out.println("Keystore generated successfully.");
        }

        tempDir.delete();
    }
}
