import java.io.*;
import java.util.*;

public class Main {

    static class HMM {
        double[][] transitionMatrix;
        double[][] emissionMatrix;
        double[] pi;

        public HMM() {}

        public void readModel(String filename) throws IOException {
            try (BufferedReader br = new BufferedReader(new FileReader(filename))) {
                String line;
                String[] parts;
                int i = 0, j = 0;

                // Read transition matrix
                line = br.readLine();
                parts = line.split(" ");
                transitionMatrix = new double[parts.length][parts.length];
                for (int k = 0; k < parts.length; k++) {
                    parts[k] = parts[k].trim();
                    String[] rowParts = parts[k].split(",");
                    for (j = 0; j < rowParts.length; j++) {
                        transitionMatrix[i][j] = Double.parseDouble(rowParts[j]);
                    }
                    i++;
                }

                // Read emission matrix
                line = br.readLine();
                parts = line.split(" ");
                emissionMatrix = new double[parts.length][parts.length];
                for (int k = 0; k < parts.length; k++) {
                    parts[k] = parts[k].trim();
                    String[] rowParts = parts[k].split(",");
                    for (j = 0; j < rowParts.length; j++) {
                        emissionMatrix[i][j] = Double.parseDouble(rowParts[j]);
                    }
                    i++;
                }

                // Read pi
                line = br.readLine();
                parts = line.split(" ");
                pi = new double[parts.length];
                for (i = 0; i < parts.length; i++) {
                    pi[i] = Double.parseDouble(parts[i].trim());
                }
            }
        }

        public Map<String, String> tagText(String text) {
            Map<String, String> tags = new HashMap<>();

            // Initialize trellis
            int nStates = transitionMatrix.length;
            int[][] trellis = new int[nStates][text.length()];
            double[][] probabilities = new double[nStates][text.length()];

            // Iterate over the text and fill in the trellis
            for (int i = 0; i < text.length(); i++) {
                String word = text.substring(i, i+1);
                int nWords = emissionMatrix[0].length;
                int maxTagIndex = -1;

                for (int j = 0; j < nStates; j++) {
                    double sum = 0.0;
                    for (int k = 0; k < nWords; k++) {
                        if (word.equals(" ") || word.equals(punctuation[k])) {
                            if (punctuation[k].equals(word)) {
                                sum += pi[j] * emissionMatrix[j][k];
                            }
                        } else {
                            sum += pi[j] * emissionMatrix[j][k] * probability(word, k);
                        }
                    }

                    // If this is the first word, set the trellis and probabilities to the initial state
                    if (i == 0) {
                        trellis[j][i] = j;
                        probabilities[j][i] = sum;
                    } else {
                        int maxIndex = 0;
                        double maxValue = -1.0;

                        for (int l = 0; l < nStates; l++) {
                            if (maxValue < probabilities[l][i-1] * transitionMatrix[l][j] + sum) {
                                maxValue = probabilities[l][i-1] * transitionMatrix[l][j] + sum;
                                maxIndex = l;
                            }
                        }

                        trellis[j][i] = maxIndex;
                        probabilities[j][i] = maxValue;
                    }

                    // If this is the last word and we're in the final state, set the tag to the output word
                    if (i == text.length() - 1 && j == nStates - 1) {
                        tags.put(word, punctuation[maxTagIndex]);
                    }
                }
            }

            return tags;
        }
    }

    public static void main(String[] args) throws IOException {
        HMM hmm = new HMM();
        hmm.readModel("model.txt");
        Map<String, String> tags = hmm.tagText("This is a test sentence.");
        System.out.println(tags);
    }
}

