public static Socket createSocket(String host, int port) throws IOException {
    SSLContext sslContext = SSLContext.getInstance("TLS");
    TrustManager trustManager = new X509TrustManager() {
        public void checkClientTrusted(X500Principal principal, CertificationPath paths) {}
        public void checkServerTrusted(X500Principal principal, CertificationPath paths) {}
        public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
    };
    sslContext.init(null, new TrustManager[]{trustManager}, null);
    SSLSocketFactory sslSocketFactory = sslContext.getSocketFactory();
    Socket socket = sslSocketFactory.createSocket(host, port);
    ((SSLSocket)socket).startHandshake();
    return socket;
}

