public class Main {
    public static List<String> getMacAddresses() throws IOException {
        Process process = Runtime.getRuntime().exec("netsh interface ip show config");

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        List<String> macAddresses = new ArrayList<>();

        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("MAC address")) {
                int start = line.indexOf("MAC address") + 14;
                int end = line.length();
                macAddresses.add(line.substring(start, end - 1).trim());
            }
        }

        return macAddresses;
    }
