import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.zip.GZInputStream;

import org.apache.http.HttpResponse;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.protocol.BasicHttpContext;
import org.apache.http.util.EntityUtils;

public HttpResponse sendPostRequest(String endpoint, String requestBody, String token) {
    HttpClient client = HttpClients.custom().build();
    HttpPost post = new HttpPost(endpoint);
    post.addHeader("Authorization", "Bearer " + token);

    if (requestBody != null && requestBody.length() > 0) {
        byte[] requestBytes = requestBody.getBytes();
        ByteArrayOutputStream bos = new ByteArrayOutputStream(requestBytes.length);
        GZInputStream gzis = new GZInputStream(new ByteArrayInputStream(requestBytes));
        try {
            byte[] buffer = new byte[1024];
            int len;
            while ((len = gzis.read(buffer)) != -1) {
                bos.write(buffer, 0, len);
            }
            StringEntity entity = new StringEntity(bos.toString());
            post.setEntity(entity);
        } catch (IOException e) {
            // handle exception
        } finally {
            try {
                bos.close();
                gzis.close();
            } catch (IOException e) {
                // handle exception
            }
        }
    }

    if (rateLimiter != null && rateLimiter.maximumRequestsPerSecond > 0) {
        RateLimiter rate = new RateLimiter(rateLimiter.maximumRequestsPerSecond);
        while (!rate.isReady()) {
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                // handle exception
            }
        }
    }

    HttpResponse response = client.execute(post, new BasicHttpContext());
    return response;
}

