import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.xml.bind.DatatypeConverter;

public class HashFunction {

    public static String calculateHash(String input, String algorithm) {
        try {
            MessageDigest messageDigest = MessageDigest.getInstance(algorithm.toUpperCase());
            byte[] hashBytes = messageDigest.digest(input.getBytes("UTF-8"));
            return DatatypeConverter.printHexBinary(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            return "Unsupported algorithm: " + algorithm;
        }
    }

    public static void main(String[] args) {
        String input = "Hello, World!";
        String algorithm = "md5";
        System.out.println("Hash value for input '" + input + "' using algorithm '" + algorithm + "' is: " + calculateHash(input, algorithm));
    }
}
