import java.io.*;
import java.security.*;

public String generateMD5Hash(String filePath) {
    try (InputStream inputStream = new FileInputStream(filePath);
         DigestInputStream digestInputStream = new DigestInputStream(inputStream, MessageDigest.getInstance("MD5"))) {
        byte[] buffer = new byte[1024];
        int bytesRead;
        StringBuilder hashString = new StringBuilder();

        while ((bytesRead = digestInputStream.read(buffer)) != -1) {
            for (int i = 0; i < bytesRead; i++) {
                hashString.append(Integer.toHexString((buffer[i] & 0xFF) | 0x100));
            }
            System.out.println("Processing file...");
        }

        String hashValue = hashString.toString();
        File md5File = new File(filePath.replaceFirst("\\.[^.]+$", "") + ".md5");
        try (PrintWriter writer = new PrintWriter(md5File)) {
            writer.write(hashValue);
        }
    } catch (Exception e) {
        System.out.println("Error generating MD5 hash: " + e.getMessage());
    }
    return "";
}

