public String createOrUpdateObject(String userName, String url, boolean isAdmin, String algorithm) {
    try {
        MessageDigest md = MessageDigest.getInstance(algorithm);
        String data = userName + url;
        byte[] digestBytes = md.digest(data.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : digestBytes) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        String uniqueId = hexString.toString();

        // Create or update the object in the database using the unique identifier
        MyDAO dao = new MyDAO();
        Object obj = new Object(uniqueId, userName, url, isAdmin);
        dao.createOrUpdateObject(obj);

        return uniqueId;
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

