    } catch (NoSuchAlgorithmException e) {
        // handle exception
    }

    if (change.getTimestamp() != null) {
        md5.update(change.getTimestamp().getBytes());
    }
    if (change.getRowVersion() != null) {
        md5.update(change.getRowVersion().getBytes());
    }
    if (change.getAccountID() != null) {
        md5.update(change.getAccountID().getBytes());
    }

    for (Revision revision : ProjectState.getProject().getRevisions()) {
        md5.update(revision.getRevisionID().getBytes());
    }

    byte[] result = md5.digest();
    for (int i = 0; i < result.length; i++) {
        eTag.append(Integer.toHexString((result[i] & 0xFF) | 0x100));
    }

    return eTag.toString();
}

