import java.net.Socket;

public class SocketSender {

    public static void sendToHost(String host, int port, String messageBuffer) throws IOException {
        try (Socket socket = new Socket(InetAddress.getByName(host), port)) {
            // Set keepalive
            ((java.net.SocksSocketImpl)socket.impl).setKeepAlive(true);

            byte[] buffer = messageBuffer.getBytes();
            while (true) {
                socket.getOutputStream().write(buffer);
                if (!flushRequestReceived()) {
                    break;
                }
                // Re-send the message buffer on flush request
                socket.getOutputStream().write(buffer);
            }
        } catch (IOException e) {
            // Handle exception here
        }
    }

    private static boolean flushRequestReceived() throws IOException {
        // Add code to detect and handle flush requests here
        return false;
    }
}
