public static Socket createSocket(String host, int port, boolean useSSL) throws IOException {
    Socket socket = null;
    if (useSSL) {
        // Create an SSL socket
        SSLSocketFactory sslFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
        socket = sslFactory.createSocket(host, port);
        ((SSLSocket) socket).setSoTimeout(30000); // Set read timeout to 30 seconds
    } else {
        // Create a non-SSL socket
        socket = new Socket(host, port);
        socket.setSoTimeout(30000); // Set read timeout to 30 seconds
    }

    // Initialize the connection using the specified pattern
    if (socket instanceof SSLSocket) {
        ((SSLSocket) socket).startHandshake();
    } else {
        socket.connect(new InetSocketAddress(host, port));
    }

    return socket;
}
