public static DatagramConnector setupDatagramConnection(String connectionURI) {
    DatagramConnector connector = new DatagramConnector();
    try {
        URI uri = new URI(connectionURI);
        InetSocketAddress address = new InetSocketAddress(uri.getHost(), uri.getPort());
        connector.setSocketAddress(address);
        // Set the processor count (assuming 4 is a good value)
        connector.setProcessorCount(4);
        // Create a thread pool executor with a fixed number of threads
        ThreadFactory factory = Executors.defaultThreadFactory();
        ThreadGroup group = new ThreadGroup("Datagram Connection Threads");
        connector.setExecutor(Executors.newFixedThreadPool(4, factory, group));
    } catch (URISyntaxException e) {
        throw new RuntimeException(e);
    }
    // Throw an exception if the transfer exchange is set to true
    if (...) {
        throw new IllegalArgumentException("Transfer exchange not supported for datagram connections");
    }
    return connector;
}

