import akka.actor.ActorSystem;
import akka.io.IO;
import akka.io.Tcp;

public class ActorDiscovery {
    public static void main(String[] args) throws Exception {
        final ActorSystem system = ActorSystem.create("Discovery");
        final ActorRef listener = system.actorOf(TcpListener.props("localhost", 9999));
        listener.tell(new TcpCommand("127.0.0.1", 1234), actor);
    }
}

class TcpListener extends UntypedActor {
    @Override
    public void onReceive(Object message) throws Exception {
        if (message instanceof ActorRef) {
            final ActorRef connection = (ActorRef) message;
            IO.Tcp.listen(connection, "localhost", 9999).listen(() -> new TcpHandler());
        } else {
            unhandled(message);
        }
    }
}

class TcpHandler extends UntypedActor {
    @Override
    public void onReceive(Object message) throws Exception {
        if (message instanceof ActorRef) {
            final ActorRef connection = (ActorRef) message;
            connection.tell(new TcpCommand("127.0.0.1", 1234), actor);
        } else {
            unhandled(message);
        }
    }
}

class TcpCommand extends UntypedActorAbstraction {
    private final String host;
    private final int port;

    public TcpCommand(String host, int port) {
        this.host = host;
        this.port = port;
    }

    @Override
    public void onReceive(Object message) throws Exception {
        // Send a discovery message to the remote address via TCP.
        IO.Tcp.connect(getSystem().actorOf(Tcp.getSimpleConnectionContext()), host, port).tell(new TcpMessage(), getSelf());
    }
}

class TcpMessage extends UntypedActorAbstraction {
    @Override
    public void onReceive(Object message) throws Exception {
        // Handle the discovery response from the remote address.
    }
}
