    LoginContext loginContext = getLoginContext();

    try {
        // Establish connection with remote server using Kerberos authentication
        socket.connect(new InetSocketAddress(host, port));

        if (isLocalHostAddress(host)) {
            // Bind the socket to a local address if the host name is a valid local address
            ((AbstractSocket) socket).bind(new InetSocketAddress("localhost", port));
        }

        // Set connection timeout and ping interval
        socket.setSoTimeout(10000); // 10 seconds
        socket.setPingInterval(5000); // 5 seconds

    } catch (IOException | InterruptedException e) {
        throw new IOException("Error establishing connection: " + e.getMessage());
    } finally {
        try {
            loginContext.logout();
        } catch (LoginException e) {
            // Handle the exception
        }
    }

    return socket;
