public boolean startProcess(String command, List<String> args) {
    try {
        ProcessBuilder builder = new ProcessBuilder(command);
        for (String arg : args) {
            builder.argument(arg);
        }
        Process process = builder.start();

        Watchdog watchdog = new Watchdog(process);
        Thread thread = new Thread(watchdog);
        thread.setDaemon(true);
        thread.start();

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new Exception("Process exited with code " + exitCode);
        }

        return true;
    } catch (IOException | InterruptedException e) {
        System.out.println("Error starting process: " + e.getMessage());
        return false;
    }
}

class Watchdog implements Runnable {
    private Process process;

    public Watchdog(Process process) {
        this.process = process;
    }

    @Override
    public void run() {
        try {
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.out.println("Process exited with code " + exitCode);
            }
        } catch (InterruptedException e) {
            System.out.println("Error monitoring process: " + e.getMessage());
        } finally {
            process.destroy();
        }
    }
}
