public class SignCode {
  public static byte[] signFile(String codeFile, String password) throws Exception {
    File keystore = new File("keystore.jks"); // Replace with your keystore file
    char[] keyPass = (password != null && !password.isEmpty()) ? password.toCharArray() : "".toCharArray();
    KeyStore ks = KeyStore.getInstance("JKS");
    ks.load(new FileInputStream(keystore), keyPass);

    String alias = "myAlias"; // Replace with the alias of your signing certificate
    byte[] signedCode = Sign.sign(ks, alias, codeFile);
    return signedCode;
  }
}
