public static byte[] encryptData(byte[] data, byte[] key) throws Exception {
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
    SecretKeySpec skeySpec = new SecretKeySpec(key, "AES");
    IvParameterSpec ivSpec = new IvParameterSpec(new byte[cipher.getBlockSize()]);
    cipher.init(Cipher.ENCRYPT_MODE, skeySpec, ivSpec);
    byte[] encryptedData = cipher.doFinal(data);
    return concat(encryptedData, ivSpec.getIV());
}

public static byte[] concat(byte[] a1, byte[] a2) {
    int a1Length = a1.length;
    byte[] result = new byte[a1Length + a2.length];
    System.arraycopy(a1, 0, result, 0, a1Length);
    System.arraycopy(a2, 0, result, a1Length, a2.length);
    return result;
}

