import java.io.*;
import java.util.*;

public Map<String, Byte> mergeMaps(Map<String, String> stringMap, InputStream inputStream) {
    Map<String, Byte> byteMap = new HashMap<>();

    try (DataInputStream dataInputStream = new DataInputStream(inputStream)) {
        Map<String, String> deserializedMap = new HashMap<>();

        for (int i = 0; i < dataInputStream.readInt(); i++) {
            String key = dataInputStream.readUTF();
            int valueLength = dataInputStream.readInt();
            byte[] valueBytes = new byte[valueLength];
            dataInputStream.readFully(valueBytes);
            deserializedMap.put(key, new String(valueBytes));
        }

        for (Map.Entry<String, String> entry : stringMap.entrySet()) {
            if (!deserializedMap.containsKey(entry.getKey())) {
                byteMap.put(entry.getKey(), entry.getValue().getBytes().get(0));
            } else {
                byte[] bytes = (entry.getValue() + deserializedMap.get(entry.getKey())).getBytes();
                byteMap.put(entry.getKey(), bytes[0]);
            }
        }

        for (Map.Entry<String, String> entry : deserializedMap.entrySet()) {
            if (!stringMap.containsKey(entry.getKey())) {
                byteMap.put(entry.getKey(), entry.getValue().getBytes().get(0));
            } else {
                byte[] bytes = (stringMap.get(entry.getKey()) + entry.getValue()).getBytes();
                byteMap.put(entry.getKey(), bytes[0]);
            }
        }
    } catch (IOException e) {
        // Handle exception
    }

    return byteMap;
}

