public int getHash(String str, String hashFunction) {
    if (hashFunction.equals("MD5")) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
        byte[] bytes = str.getBytes();
        BigInteger bigInt = new BigInteger(1, md.digest(bytes));
        return Math.abs(bigInt.intValue());
    } else if (hashFunction.equals("SHA-256")) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
        byte[] bytes = str.getBytes();
        BigInteger bigInt = new BigInteger(1, md.digest(bytes));
        return Math.abs(bigInt.longValue());
    } else if (hashFunction.equals("CRC32")) {
        CyclicReduction crc = new CyclicReduction();
        int hashValue = crc.getCRC(str);
        return hashValue;
    } else {
        throw new RuntimeException("Unsupported Hash Function");
    }
}

class CyclicReduction {
    public int getCRC(String str) {
        CRC32 crc = new CRC32();
        crc.update(str.getBytes());
        return (int) crc.getValue();
    }
}

