public Map<String, Object> getWalkMap(String filePath) {
    File file = new File(filePath);
    String extension = filePath.substring(filePath.lastIndexOf('.') + 1).toLowerCase();

    if (!file.exists()) {
        return null; // or throw an exception
    }

    Map<String, Object> walkMap;
    try (FileInputStream fis = new FileInputStream(file)) {
        switch (extension) {
            case "objv":
                walkMap = getViewModelFromObjV(fis);
                break;
            case "objp":
                walkMap = getPathsModelFromObjP(fis);
                break;
            case "jrd3m": // assuming this is the correct extension
                try (ObjectInputStream ois = new ObjectInputStream(fis)) {
                    walkMap = (Map<String, Object>) ois.readObject();
                } catch (ClassNotFoundException e) {
                    return null; // or throw an exception
                }
                break;
            default:
                return null; // or throw an exception
        }
    } catch (IOException e) {
        return null; // or throw an exception
    }

    return walkMap;
}

