import java.io.File;
import java.io.IOException;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import org.xml.sax.Attributes;
import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;

public class XMLPrefixExtractor {

    public static void main(String[] args) throws Exception {
        File dir = new File("path_to_your_xml_files");
        FrequencyHandler frequencyHandler = new FrequencyHandler();
        SAXParserFactory saxParserFactory = SAXParserFactory.newInstance();
        saxParserFactory.setNamespaceAware(true);
        saxParser saxParser = saxParserFactory.newSAXParser();

        for (File file : dir.listFiles()) {
            if (file.getName().endsWith(".xml")) {
                saxParser.parse(file.getAbsolutePath(), frequencyHandler);
            }
        }

        System.out.println("Prefixes and their frequencies:");
        for (String prefix : frequencyHandler.getPrefixes()) {
            System.out.println(prefix + ": " + frequencyHandler.getFrequency(prefix));
        }
    }
}

class FrequencyHandler extends DefaultHandler {

    private String currentPrefix;
    private int currentCount;

    private final StringBuilder prefixBuilder = new StringBuilder();
    private final StringBuilder countBuilder = new StringBuilder();

    private final java.util.HashMap<String, Integer> prefixesAndCounts = new java.util.HashMap<>();

    @Override
    public void startElement(String uri, String localName, String qname, Attributes attributes) {
        if (localName.equals("prefix")) {
            currentPrefix = qname;
            prefixBuilder.setLength(0);
            countBuilder.setLength(0);
        }
    }

    @Override
    public void characters(char[] ch, int start, int length) {
        String text = new String(ch, start, length).trim();
        if (currentPrefix != null) {
            if (prefixBuilder.length() > 0) {
                prefixBuilder.append(' ');
                countBuilder.append(' ');
            }
            prefixBuilder.append(text);
            currentCount++;
        }
    }

    @Override
    public void endElement(String uri, String localName, String qname) {
        if (localName.equals("prefix")) {
            int frequency = getFrequency();
            prefixesAndCounts.put(currentPrefix, frequency);
            currentPrefix = null;
            currentCount = 0;
        }
    }

    private int getFrequency() {
        return currentCount;
    }

    public String[] getPrefixes() {
        return prefixesAndCounts.keySet().toArray(new String[0]);
    }

    public int getFrequency(String prefix) {
        return prefixesAndCounts.getOrDefault(prefix, 0);
    }
}

