import javax.xml.bind.DatatypeConverter;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public int hash(Map<String, String> paths, String module, boolean createSymlinks, boolean createHeaderMap) {
    StringBuilder sb = new StringBuilder();

    sb.append(module);
    if (createSymlinks) {
        sb.append("1");
    } else {
        sb.append("0");
    }
    if (createHeaderMap) {
        sb.append("1");
    } else {
        sb.append("0");
    }

    try {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] hashBytes = DatatypeConverter.parseHexBinaryString(sb.toString().getBytes()).getBytes();
        md.update(hashBytes);
        byte[] resultHash = md.digest();

        StringBuilder hexString = new StringBuilder();
        for (int i = 0; i < resultHash.length; i++) {
            String hex = Integer.toHexString(0xff & resultHash[i]);
            if(hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }

        return Integer.parseInt(hexString.toString(), 16);
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

