import org.apache.http.HttpResponse;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.HttpClients;

public Map<String, String> sendMessageToServer() {
    // Create a new map to store device values
    Map<String, String> deviceValues = new HashMap<>();

    // Add device values to the map (this example adds "OS" and "CPU")
    deviceValues.put("OS", System.getProperty("os.name"));
    deviceValues.put("CPU", System.getProperty("os.arch"));

    // Create an HTTP client
    HttpClient client = HttpClients.createDefault();

    // Create a POST request with the device values as JSON
    HttpPost request = new HttpPost("http://example.com/send_message");
    String jsonDeviceValues = deviceValues.toString();
    StringEntity entity = new StringEntity(jsonDeviceValues, "application/json");
    request.setEntity(entity);

    try {
        // Send the request and get the response
        HttpResponse response = client.execute(request);
    } catch (Exception e) {
        // Handle any exceptions that occur during the request
        System.out.println("Error sending message: " + e.getMessage());
    }

    return deviceValues;
}
