import javax.crypto.Cipher;
import javax.crypto.KeyFactory;
import javax.crypto.NoSuchPadException;
import java.security.InvalidKeyException;
import java.security.KeyFactory;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.spec.X509EncodedKeySpec;

public String encrypt(String plaintext, String publicKeyString) throws Exception {
    KeyFactory kf = KeyFactory.getInstance("RSA");
    X509EncodedKeySpec x509PubKey = new X509EncodedKeySpec(Base64.decode(publicKeyString));
    PublicKey pubKey = kf.generatePublic(x509PubKey);

    Cipher cipher = Cipher.getInstance("RSA/ECB/PKCS1Padding");
    cipher.init(Cipher.ENCRYPT, pubKey);

    byte[] encryptedBytes = cipher.doFinal(plaintext.getBytes());
    return new String(Base64.encode(encryptedBytes));
}

