public int executeCommand(InputStream inputStream, OutputStream outputStream, Optional<Long> timeout) {
    try {
        Process process = Runtime.getRuntime().exec(new String[0]);

        if (inputStream != null) {
            process.getOutputStream().write(inputStream.readAllBytes());
            process.getOutputStream().close();
        }
        process.getInputStream().close();
        process.getOutputStream().close();

        int exitCode;
        if (timeout.isPresent()) {
            try {
                process.waitFor(timeout.get(), TimeUnit.MILLISECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                process.destroy();
                return -1; // Return error code
            }
        } else {
            process.waitFor();
        }

        exitCode = process.exitValue();

        if (!process.isAlive()) {
            process.destroy();
        }

        return exitCode;
    } catch (IOException | InterruptedException e) {
        throw new RuntimeException("Error executing command", e);
    } finally {
        try {
            process.destroy();
        } catch (Exception ignored) {}
    }
}

