#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

int main() {
    FILE *fp = stdin;
    char buffer[BUFFER_SIZE];
    char *argv[2];

    while (fgets(buffer, BUFFER_SIZE, fp) != NULL) {
        buffer[strcspn(buffer, "\n")] = '\0'; // remove trailing newline
        char *command = strtok(buffer, " ");
        if (!strcmp(command, "")) continue; // skip empty lines

        argv[0] = command;
        argv[1] = NULL;

        FILE *child = popen("bash -c", "w");
        if (fprintf(child, "%s\n", buffer) < 0)
            perror("Writing to pty");
        if (pclose(child) < 0)
            perror("Popen");

        printf("%s", buffer);
    }

    return 0;
}

