    Key key = new SecretKeySpec(companyService.getSecretKey(), "Blowfish");

    try {
        Cipher cipher = Cipher.getInstance("Blowfish/ CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key, ByteBuffer.wrap(iv));
        byte[] encryptedBytes = cipher.doFinal(input.getBytes());
