public static String encryptMessage(String message, String encodingScheme, boolean uppercase) {
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.reset();
        byte[] messageBytes;
        if (uppercase) {
            messageBytes = message.toUpperCase().getBytes(encodingScheme);
        } else {
            messageBytes = message.getBytes(encodingScheme);
        }
        byte[] encryptedBytes = md.digest(messageBytes);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < encryptedBytes.length; i++) {
            int val = ((int) encryptedBytes[i]) & 0xff;
            if (val <= 9) {
                sb.append(val);
            } else {
                sb.append((char) ('a' + (val - 10)));
            }
        }
        return sb.toString();
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

