import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Md5Filter implements java.io.FilterInputStream {
    private MessageDigest md;
    private int frequency;

    public Md5Filter(int frequency) throws NoSuchAlgorithmException {
        this.frequency = frequency;
        md = MessageDigest.getInstance("MD5");
    }

    public byte[] filter(byte[] data) {
        byte[] result = new byte[16];
        for (int i = 0; i < data.length; i += frequency) {
            int length = Math.min(frequency, data.length - i);
            md.update(data, i, length);
        }
        return md.digest();
    }
}

