public static void openFileOrDirectory(File file) {
    try {
        Desktop desktop = Desktop.isDesktopSupported() ? Desktop.create() : null;
        if (desktop != null && desktop.isSupported()) {
            desktop.open(file);
        } else {
            String osName = System.getProperty("os.name").toLowerCase();
            if (file.isDirectory()) {
                if (osName.startsWith("mac")) {
                    Runtime.getRuntime().exec("open " + file.getAbsolutePath());
                } else if (osName.startsWith("win")) {
                    Runtime.getRuntime().exec("explorer /n,/" + file.getAbsolutePath());
                }
            } else {
                if (osName.startsWith("mac")) {
                    Runtime.getRuntime().exec("open -t " + file.getAbsolutePath());
                } else if (osName.startsWith("win")) {
                    Runtime.getRuntime().exec("start \"" + file.getAbsolutePath() + "\"");
                }
            }
        }
    } catch (IOException e) {
        JOptionPane.showMessageDialog(null, "Error opening file or directory: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
    }
}

