```java
public static boolean uploadFile(String url, File file) {
    int attempts = 0;
    while (attempts < 3) {
        try {
            URL connect = new URL(url);
            HttpURLConnection con = (HttpURLConnection) connect.openConnection();
            con.setDoOutput(true);
            con.setRequestMethod("POST");
            con.setRequestProperty("Content-Type", "application/octet-stream");
            con.setRequestProperty("Content-Length", String.valueOf(file.length()));
            con.connect();

            OutputStream os = con.getOutputStream();
            byte[] bytes = new byte[1024];
            FileInputStream fis = new FileInputStream(file);
            int bytesRead;
            while ((bytesRead = fis.read(bytes)) != -1) {
                os.write(bytes, 0, bytesRead);
            }
            fis.close();
            os.flush();
            os.close();

            if (con.getResponseCode() == 200) {
                return true;
            } else {
                System.out.println("Upload failed with response code " + con.getResponseCode());
            }
        } catch (Exception e) {
            System.out.println("Upload failed. Retrying...");
        }
        attempts++;
    }
    return false;
}

