import org.apache.http.*;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.conn.ssl.SSLConnectionSocketFactory;
import org.apache.http.conn.ssl.SSLContexts;
import org.apache.http.conn.ssl.X509HostnameVerifier;
import org.apache.http.impl.client.BasicCredentialsProvider;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClientBuilder;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.params.*;

public class Main {

    public static void main(String[] args) throws Exception {
        // Create a RequestConfig with the desired settings
        RequestConfig requestConfig = RequestConfig.custom()
                .setProxy(new HttpHost("proxy-host", 8080))
                .build();

        // Create a BasicCredentialsProvider with a username and password
        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        credentialsProvider.setCredentials(new BasicNameValuePair("username", "your-username"),
                new BasicNameValuePair("password", "your-password"));

        // Create a Registry and register the SSL and Plain connection factories
        Registry registry = SSLContexts.createSystemDefault().getRegistry();
        registry.register("https", new SSLConnectionSocketFactory(SSLContexts.createSystemDefault(), X509HostnameVerifier.INSTANCE));
        registry.register("http", new PlainConnectionSocketFactory());

        // Create a CloseableHttpClient using the HttpClientBuilder and the custom RequestConfig, CredentialsProvider, and Registry
        CloseableHttpClient client = HttpClients.custom()
                .setDefaultRequestConfig(requestConfig)
                .setCredentialsProvider(credentialsProvider)
                .setSocksProxyRegistry(registry)
                .build();

        // Make a GET request to a URL using the CloseableHttpClient
        HttpGet get = new HttpGet("https://example.com");
        HttpResponse response = client.execute(get);

        // Get the response entity and convert it to a string
        HttpEntity entity = response.getEntity();
        String responseString = EntityUtils.toString(entity);

        System.out.println(responseString);
    }
}

```java
public static void executeCommand(String cmd) throws IOException {
    String[] command = cmd.split(" ");
    for (int i = 0; i < command.length; i++) {
        if (command[i].matches("^@?.*\\..*$")) {
            // Windows shell script, escape the '@' character
            command[i] = command[i].replace("@", "@^");
        }
    }

    Runtime runtime = Runtime.getRuntime();
    Process process = runtime.exec(command[0]);
    new StreamWriter(process.getOutputStream()).write(String.join(" ", command).concat("\r\n"));
    new StreamWriter(process.getOutputStream()).flush();
    process.getOutputStream().close();

    BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream()));
    String line;
    StringBuilder output = new StringBuilder();
    while ((line = input.readLine()) != null) {
        output.append(line).append("\n");
    }
    input.close();
    process.waitFor();

    if (!output.toString().trim().equals("")) {
        System.out.println(output.toString());
    } else {
        System.out.println("No output.");
    }

    int exitVal = process.exitValue();
    if (exitVal != 0) {
        System.out.println("Exit value: " + exitVal);
    }
}

