        // Load the XML file into a Document object
        // For simplicity, assume this is already done and stored in 'document'
        XPath xpath = XPathFactory.newInstance().newXPath();
        String expression = "//" + groupName + "/" + propertyName;
        XPathExpression pathExpression = xpath.compile(expression);
        Node node = (Node) pathExpression.evaluate(document, XPathConstants.NODE);
        if(node != null) {
            node.setText(newValue); // set the new value
            return true; // modification successful
        }
    } catch (Exception e) {
        return false; // modification failed due to an error
    }
    return false; // property not found or other error
}
