    for (VertexBuilder vertexBuilder : vertexBuilders) {
        String sourceId = vertexBuilder.getSourceId();
        String targetId = vertexBuilder.getTargetId();

        if (!edgeMap.containsKey(sourceId + "_" + targetId)) {
            String edgeHash = getEdgeHash(sourceId, targetId);
            edgeMap.put(sourceId + "_" + targetId, edgeHash);

            edges.add(String.format("CREATE EDGE %s-%s {hash: '%s'}",
                    sourceId, targetId, edgeHash));
        }
    }

    return edges;
}

