import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.nio.ByteBuffer;

public char[] byteToHex(byte[] b) {
    Mac md = null;
    try {
        SecretKey skey = new SecretKeySpec(new byte[0], "HmacMD5");
        Key k = skey;
        md = Mac.getInstance("HmacMD5", "BC");
        md.init(k);
        ByteBuffer buffer = ByteBuffer.wrap(b);
        byte[] digest = new byte[16];
        byte[] output = new byte[buffer.remaining()];
        buffer.get(output);

        md.update(output);
        byte[] result = md.doFinal();
        StringBuilder sb = new StringBuilder();
        for (byte b1 : result) {
            String hexString = Integer.toHexString(b1 & 0xFF);
            if(hexString.length() == 1){
                sb.append('0');
            }
            sb.append(hexString);
        }
        return sb.toString().toCharArray();

    } catch (Exception e) {
        throw new RuntimeException(e);
    } finally {
        try {
            md.reset();
            md.destroy();
        } catch (Exception e2) {
            // ignored
        }
    }
}

