import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Main {
    private static final String ALGORITHMS = "MD5,SHA-1,SHA-256,SHA-384,SHA-512";

    public static void main(String[] args) {
        String input = "Hello";
        for (String algorithm : ALGORITHMS.split(",")) {
            System.out.println("Hash of '" + input + "' using " + algorithm + ": " + getHash(input, algorithm));
        }
    }

    private static String getHash(String input, String algorithm) {
        try {
            MessageDigest md = MessageDigest.getInstance(algorithm);
            byte[] messageBytes = input.getBytes();
            md.update(messageBytes);
            byte[] hashBytes = md.digest();

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                // Convert the byte to hex and append it
                String hex = Integer.toHexString(b | 0x100);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}

