import java.time.ZonedDateTime;
import java.time.temporal.ChronoUnit;
import java.util.*;

public String mergeSegments(List<Map<String, ZonedDateTime>> segments) {
    if (segments.isEmpty()) {
        return "";
    }

    // Sort the segments by start time
    segments.sort((a, b) -> a.get("start").compareTo(b.get("start")));

    // Initialize the merged interval with the first segment
    ZonedDateTime start = segments.get(0).get("start");
    ZonedDateTime end = segments.get(0).get("end");

    for (Map<String, ZonedDateTime> segment : segments) {
        if (ZonedDateTime.now().until(segment.get("start"), ChronoUnit.SECONDS) < 1) {
            // Handle overlapping start time
            start = segment.get("start");
        }
        end = end.to(ZonedDateTime::truncatedTo).until(segment.get("end"), ChronoUnit.SECONDS) > 0 ? segment.get("end") : end;
    }

    return String.format("%s-%s", start, end);
}

