public class AESKeyGenerator {
    public static Object[] generateAESKey(int keySize, String paddingScheme) throws Exception {
        KeyGenerator kgen = KeyGenerator.getInstance("AES");
        kgen.init(keySize, new SecureRandom());
        SecretKeyFactory kf = SecretKeyFactory.getInstance("AES");
        KeySpec ks = kf.getKeySpec(kgen.generateKey(), "javax.crypto.spec.SecretKeySpec");

        AlgorithmParameters params = AlgorithmParameters.getInstance();
        params.put("AES", paddingScheme);

        Cipher cipher = Cipher.getInstance("AES/" + paddingScheme);
        cipher.init(cipher.ENCRYPT_MODE, kf.generateSecret(ks), new SecureRandom());

        return new Object[]{kf.generateSecret(ks), cipher};
    }
