public void displayConfigFileContents(HttpServletRequest request, HttpServletResponse response, String filePath) throws ServletException, IOException {
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(filePath));
        StringBuilder configContent = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            configContent.append(line).append("<br>");
        }
        reader.close();
        response.setContentType("text/plain");
        PrintWriter writer = response.getWriter();
        writer.println(configContent.toString());
    } catch (FileNotFoundException e) {
        response.setStatus(HttpServletResponse.SC_NOT_FOUND);
        writer.println("Error: Configuration file not found.");
        logger.error("Error reading configuration file", e);
    } catch (IOException e) {
        response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
        writer.println("Error: Unable to read configuration file contents.");
        logger.error("Error reading configuration file", e);
    } finally {
        if (reader != null) {
            try {
                reader.close();
            } catch (IOException ignored) {}
        }
    }
}

