function asyncReduce(arr, initValue, callback) {
  let currentValue = initValue;
  (async () => {
    for await (let num of arr) {
      try {
        currentValue = await callback(currentValue, num);
      } catch (err) {
        throw err;
      }
    }
    return currentValue;
  })().then((result) => result).catch((err) => console.error(err));
}

