function generateCSS(filePath) {
  const stylus = require('stylus');
  const fs = require('fs');
  const path = require('path');

  let filesToProcess = [];
  try {
    fs.readdirSync(filePath).forEach(file => {
      if (file.endsWith('.styl')) {
        filesToProcess.push(path.join(filePath, file));
      }
    });
  } catch (error) {
    console.error(`Error reading directory: ${error}`);
    return;
  }

  const css = '';
  for (const file of filesToProcess) {
    try {
      const stylusFile = fs.readFileSync(file, 'utf8');
      const result = stylus.render(stylusFile);
      css += result;
    } catch (error) {
      console.error(`Error processing ${file}: ${error}`);
    }
  }

  const destinationDir = path.dirname(filePath);
  try {
    fs.writeFileSync(`${destinationDir}/styles.css`, css);
  } catch (error) {
    console.error(`Error writing to destination directory: ${error}`);
  }
}

