function findMatch(arr, userAgent) {
  return arr.reduce((match, obj) => {
    if (obj.qualifier && !userAgent.match(new RegExp(obj.qualifier))) {
      return match;
    }
    return match || userAgent.match(new RegExp(obj.pattern)) ? obj : null;
  }, null);
}

