function serveStaticFile(request, response, filePath) {
  const fileExists = fs.existsSync(filePath);

  if (!fileExists) {
    response.writeHead(404, {'Content-Type': 'text/plain'});
    response.end('File not found');
    console.log(`Failed to find file at ${filePath}`);
  } else if (request.method === 'GET') {
    const fileBuffer = fs.readFileSync(filePath);
    response.writeHead(200, {'Content-Type': mime.getType(filePath)});
    response.end(fileBuffer);
    console.log(`Served file at ${filePath} with HTTP GET`);
  } else if (request.method === 'HEAD') {
    response.writeHead(200, {'Content-Type': mime.getType(filePath)});
    response.end('');
    console.log(`Served file at ${filePath} with HTTP HEAD`);
  } else if (request.method === 'POST' || request.method === 'PUT' || request.method === 'DELETE') {
    response.writeHead(405, {'Content-Type': 'text/plain'});
    response.end('Method not allowed');
    console.log(`Failed to serve file at ${filePath} due to invalid method`);
  } else if (request.method === 'OPTIONS') {
    const allowedMethods = ['GET', 'HEAD'];
    response.writeHead(200, {'Allow': allowedMethods.join(', ')});
    response.end('');
    console.log(`Served options for file at ${filePath}`);
  } else if (request.method === 'PROPFIND' || request.method === 'PROPPATCH' || request.method === 'MOVE') {
    response.writeHead(405, {'Content-Type': 'text/plain'});
    response.end('Method not allowed');
    console.log(`Failed to serve file at ${filePath} due to invalid method`);
  } else if (request.method === 'PUT' && request.headers['if-match']) {
    const lastModified = fs.statSync(filePath).mtime.getTime();
    response.writeHead(200, {'Last-Modified': lastModified});
    response.end('');
    console.log(`Served PUT options for file at ${filePath}`);
  } else if (request.method === 'DELETE' && request.headers['if-match']) {
    const lastModified = fs.statSync(filePath).mtime.getTime();
    response.writeHead(200, {'Last-Modified': lastModified});
    response.end('');
    console.log(`Served DELETE options for file at ${filePath}`);
  } else {
    response.writeHead(301, {'Location': request.url});
    response.end('File moved');
    console.log(`Redirected to ${request.url} with HTTP 301`);
  }
}

function createCompareAndFormat(formatStr) {
  const compareFn = new Function('a', 'b', `return ${formatStr.replace('{}', 'a').replace('{}', 'b').split('').sort().join('').indexOf(${formatStr.split('').sort().join('')})}`);
  const formatFn = new Function('val', `let minX = val.x, minY = val.y, maxX = val.x, maxY = val.y;
  for (const p of Object.keys(val)) {
    if (p !== 'x' && p !== 'y') {
      if (val[p] < minX) minX = val[p];
      else if (val[p] > maxX) maxX = val[p];
      if (val[p] < minY) minY = val[p];
      else if (val[p] > maxY) maxY = val[p];
    }
  }`);
  return { compareFn, formatFn };
}

function checkFilesAndDirs() {
  const fs = require('fs');
  const requiredFiles = ['file1.txt', 'file2.txt'];
  const requiredDirs = ['dir1', 'dir2'];

  function traverseDir(currentPath) {
    let filesExist = true;
    let dirsExist = true;

    fs.readdirSync(currentPath).forEach((fileOrDir) => {
      const filePath = `${currentPath}/${fileOrDir}`;
      if (fs.statSync(filePath).isDirectory()) {
        dirsExist = traverseDir(filePath);
      } else if (requiredFiles.includes(fileOrDir)) {
        filesExist = true;
      } else {
        filesExist = false;
      }
    });

    return filesExist && dirsExist;
  }

  return traverseDir('.');
}

