function isValidDirectoryTree(fs, path, options) {
  let dir = fs.readdirSync(path);
  for (let file of dir) {
    let filePath = `${path}/${file}`;
    if (!fs.statSync(filePath).isFile()) {
      let subDir = isValidDirectoryTree(fs, filePath, options);
      if (!subDir) return false;
    }
  }
  if (!options.create && !fs.existsSync(path)) return false;
  for (let dirName of fs.readdirSync(path)) {
    let dirPath = `${path}/${dirName}`;
    let stats = fs.statSync(dirPath);
    if (stats.isDirectory()) {
      let subDir = isValidDirectoryTree(fs, dirPath, options);
      if (!subDir) return false;
    }
  }
  return true;

