function getValue(config, key) {
  const value = config[key];
  if (typeof value === 'undefined') {
    const dir = process.cwd();
    let file;
    for (let i = 0; i < 3; i++) {
      file = `${dir}/config.js`;
      if (fs.existsSync(file)) {
        require(file);
        value = global.config[key];
        break;
      }
      dir = path.dirname(dir);
    }
    if (typeof value === 'undefined') {
      const pkg = fs.readFileSync(`${dir}/package.json`).toString();
      try {
        const packageConfig = JSON.parse(pkg).config;
        value = packageConfig[key];
      } catch (e) {}
    }
  }
  config[key] = value;
  return value;

