  let digitsInGroup = 0;
  for (let i = 0; i < length; i++) {
    if ((i + 1) % options.groupSize === 0 && i !== length - 1) {
      digitsInGroup++;
      groupOffset += escapeRegex(options.groupSeparator);
    }
  }

  return {length: length, groupOffset: groupOffset};
}

function compileLessFiles(directory) {
  let cssFiles = {};

  (function walk(dir) {
    fs.readdirSync(dir).forEach(file => {
      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory()) return walk(filePath); // recursive call for directories
      if (!file.endsWith('.less')) return; // skip non-Less files

      const cssName = file.replace('.less', '.css');
      less.renderFile(filePath, { relativeUrls: true }, (err, css) => {
        if (err) throw err;
        cssFiles[cssName] = filePath;
      });
    });
  })(directory);

  return cssFiles;

function countAndJumpAlerts(duration, searchString) {
    let alertCount = 0;
    let jumpTarget = '';

    for (let i = 0; i <= duration; i++) {
        if (configFile[i].includes(searchString)) {
            alertCount++;
            if (!jumpTarget) {
                jumpTarget = `#${i}`;
            }
        }
    }

    return { count: alertCount, target: jumpTarget };
}

const fs = require('fs');
const path = require('path');
const sass = require('sass');
const ts = require('typescript');
const concat = require('concat');
const _ = require('lodash');

const rootDir = 'path/to/root/directory';

fs.readdir(rootDir, (err, files) => {
  if (err) throw err;

  files.forEach(file => {
    const filePath = path.join(rootDir, file);

    // Delete files that match a certain pattern
    if (_.includes(files, `*.old`)) {
      fs.unlink(filePath, () => console.log(`Deleted ${file}`));
    }

    // Insert text into files
    const textToInsert = 'new content';
    fs.appendFile(filePath, `\n${textToInsert}`, (err) => {
      if (err) throw err;
      console.log(`Inserted text into ${file}`);
    });

    // Compile Sass to CSS
    if (_.includes(files, `*.scss`)) {
      const sassFilePath = filePath.replace('.scss', '.css');
      sass.compile(filePath, (err, result) => {
        fs.writeFileSync(sassFilePath, result.css);
        console.log(`Compiled ${file} to ${sassFilePath}`);
      });
    }

    // Compile TypeScript to JavaScript
    if (_.includes(files, `*.ts`)) {
      const tsFilePath = filePath.replace('.ts', '.js');
      ts.compile(filePath, (err, source) => {
        fs.writeFileSync(tsFilePath, source);
        console.log(`Compiled ${file} to ${tsFilePath}`);
      });
    }

    // Concatenate files
    if (_.includes(files, `*.js`)) {
      const concatenatedFile = 'concatenated.js';
      concat([filePath], concatenatedFile, (err) => {
        if (err) throw err;
        console.log(`Concatenated ${file} to ${concatenatedFile}`);
      });
    }
  });
});

function doesMatch(selector, operator, value) {
  var result = Sizzle(selector);
  if (!result.length) return false;
  for (var i = 0; i < result.length; i++) {
    var attrValue = Sizzle.attr(result[i], selector.replace(/\./g, ""));
    switch (operator) {
      case "=":
        return attrValue === value;
      case "!=":
        return attrValue !== value;
      // Add more operators as needed...
      default:
        throw new Error("Invalid operator");
    }
  }
  return false;
}

function traverseDir(path, fileNamesToCheck) {
  fs.readdir(path, (err, files) => {
    if (err) throw err;
    files.forEach(file => {
      const filePath = path + '/' + file;
      fs.stat(filePath, (statErr, stat) => {
        if (statErr) throw statErr;
        if (stat.isDirectory()) {
          traverseDir(filePath, fileNamesToCheck);
        } else {
          fileNamesToCheck.forEach(fileNameToCheck => {
            if (stat.isDirectory()) {
              console.log(`File not found in ${filePath} for ${fileNameToCheck}`);
            } else {
              const filePathNoExt = filePath.substring(0, filePath.lastIndexOf('.'));
              if (fileNamesToCheck.includes(filePathNoExt)) {
                console.log(`Found file ${filePathNoExt} in ${filePath}`);
              } else {
                console.log(`File not found in ${filePath} for ${fileNameToCheck}`);
              }
            }
          });
        }
      });
    });
};

