function dfs(grid, x0, y0) {
  const visited = [];
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[0].length; j++) {
      if (!grid[i][j].visited) {
        dfsHelper(grid, i, j);
      }
    }
  }

  function dfsHelper(grid, x, y) {
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    grid[x][y].state = 'visited';
    visited.push({x, y});
    for (const direction of directions) {
      let newX = x + direction[0];
      let newY = y + direction[1];
      if (
        newX >= 0 &&
        newX < grid.length &&
        newY >= 0 &&
        newY < grid[0].length &&
        !visited.find((pos) => pos.x === newX && pos.y === newY)
      ) {
        dfsHelper(grid, newX, newY);
      }
    }

    for (let i = 0; i < visited.length; i++) {
      const node = visited[i];
      if (Math.random() > 0.5) {
        grid[node.x][node.y].value = Math.floor(Math.random() * 100);
      }
    }
  }

  let count = 0;
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[0].length; j++) {
      if (!grid[i][j].visited) {
        dfsHelper(grid, i, j);
        count++;
        if (count >= 100) return;
      }
    }
  }
}

