function loadFiles(path, callback) {
  const fs = require('fs');
  const files = [];

  fs.readdir(path, (err, list) => {
    if (err) {
      callback(err);
    } else {
      list.forEach(file => {
        fs.readFile(`${path}/${file}`, 'utf8', (err, data) => {
          if (err) {
            callback(err);
          } else {
            files.push({ [file]: JSON.parse(data) });
          }
        });
      });

      setTimeout(() => {
        callback(null, { ...files.reduce((acc, file) => Object.assign(acc, file), {}) });
      }, 0);
    }
  });
}

