function grep(arr, fn) {
  var result = [];
  if(typeof(fn)=='string') 
    fn = new Function('i', 'x', 'return '+fn+';');

  for(var i=0; i<arr.length; i++) {
    var element = arr[i];
    if(typeof(fn)=='function' && fn.call(null, i, element)) {
      result.push(element);
    } else if (typeof(fn)=='string') {
      if(fn.call(null, i, element)) {
        result.push(element);
