function validateAndCreateFiles(dirPath, options) {
    const requiredFiles = options.requiredFiles;
    const requiredDirs = options.requiredDirs;

    try {
        fs.readdirSync(dirPath).forEach((file) => {
            if (requiredFiles.includes(file)) return;
            if (requiredDirs.some((dir) => file === dir + '/')) throw new Error(`Missing directory/file: ${file}`);
        });

        for (const file of requiredFiles) {
            if (!fs.existsSync(`${dirPath}/${file}`)) {
                fs.writeFileSync(`${dirPath}/${file}`, '');
            }
        }

        for (const dir of requiredDirs) {
            if (!fs.existsSync(`${dirPath}/${dir}/`)) {
                fs.mkdirSync(`${dirPath}/${dir}/`);
            }
        }
    } catch (err) {
        throw err;
    }
}

