function updateParticlePosition(event) {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  let particleX = 0;
  let particleY = 0;
  let speedX = 1 + Math.random() * 3;
  let speedY = 1 + Math.random() * 3;

  function getParticlePosition(event) {
    if (event.offsetX > canvas.width / 2) {
      particleX += speedX;
    } else if (event.offsetX < canvas.width / 2) {
      particleX -= speedX;
    }

    if (event.clientY > canvas.height / 2) {
      particleY += speedY;
    } else if (event.clientY < canvas.height / 2) {
      particleY -= speedY;
    }

    return {x: particleX, y: particleY};
  }

  function drawParticle() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(particleX, particleY, 5, 0, 2 * Math.PI);
    ctx.fillStyle = 'blue';
    ctx.fill();
  }

  document.addEventListener('mousemove', (event) => {
    const position = getParticlePosition(event);
    drawParticle();
  });
}

