function generateUUID() {
  var uuid = '';
  var i = 0;

  // 4 bytes for timestamp
  for (i=0; i<4; i++) {
    uuid += String((Math.random() * 256) | 0).substr(1);
  }

  // 2 bytes for clock sequence
  for (i=0; i<2; i++) {
    var random = Math.floor(Math.random() * 65536);
    uuid += String(random).substr(1);

    if(i == 0) {
      var highBitClockSequence = Date.now() >>> 16;
      uuid += String(highBitClockSequence).substr(1);
    }
  }

  // 6 bytes for node (machine ID)
  for (i=0; i<6; i++) {
    uuid += String((Math.random() * 65536) | 0).substr(1);
  }

  // 2 bytes for variant
  uuid += '4';

  // 6 bytes for name (should be nil)
  for (i=0; i<6; i++) {
    uuid += String((Math.random() * 65536) | 0).substr(1);
  }

  return uuid;
}

function findPackages(directory) {
  let packages = [];
  (function loop(dir) {
    fs.readdirSync(dir).forEach(file => {
      const filePath = path.join(dir, file);
      if (fs.lstatSync(filePath).isDirectory()) {
        loop(filePath);
      } else if (file.endsWith('.package')) {
        packages.push(file.replace('.package', ''));
      }
    });
  })(directory);
  return [...new Set(packages)].sort().flat();
}

