function autocomplete() {
  const searchInput = document.getElementById('search-input');
  const suggestionList = document.getElementById('suggestion-list');

  searchInput.addEventListener('input', async () => {
    const term = searchInput.value;
    if (term.length < 3) return;

    try {
      const response = await fetch('/autocomplete.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ term }),
      });

      if (!response.ok) throw new Error('Failed to load autocomplete suggestions');

      const data = await response.json();
      const template = Handlebars.compile('#{{product_name}} - ${{price}} ({{stock}} in stock)');
      suggestionList.innerHTML = '';

      data.forEach((product) => {
        const suggestionHTML = template(product);
        const suggestion = document.createElement('div');
        suggestion.className = 'suggestion';
        suggestion.innerHTML = suggestionHTML;
        suggestion.addEventListener('click', () => {
          searchInput.value = product.id;
          // Update the input field with the selected product's ID and UPC
          searchInput.dispatchEvent(new Event('input'));
        });
        suggestionList.appendChild(suggestion);
      });
    } catch (error) {
      console.error(error);
    }
  });

  searchInput.addEventListener('focusout', () => {
    suggestionList.innerHTML = '';
  });
}
