import re

def escape_unescape(input_string, replacement_map, escape):
    if escape:
        pattern = re.compile('[{' + re.escape(''.join(replacement_map.keys())) + '}]')
        return pattern.sub(lambda m: '\\' + replacement_map.get(m.group(0), m.group(0)), input_string)
    else:
        pattern = re.compile('\\\\([{}])'.format(''.join(replacement_map.keys())))
        return pattern.sub(lambda m: replacement_map.get(m.group(1), '\\' + m.group()), input_string)

