function decodeActiveSyncCodePage(wbxmlString) {
  const wbxml = require('wbxml');
  const xmlDoc = wbxml.parse(wbxmlString);
  let codePageData;

  // Find the <codepage> element
  xmlDoc.forEach((element) => {
    if (element.tagName === 'codepage') {
      codePageData = element.xmlText;
    }
  });

  return wbxml.decode(codePageData, { encoding: 'windows-1252' });
}
```
