function loadJobs(directory) {
  const fs = require('fs');
  const coffee = require('coffee-script/register');

  fs.readdir(directory, (err, files) => {
    if (err) return console.error(err);
    let jobs = files.filter(file => file.endsWith('.js') || file.endsWith('.coffee'));
    jobs.forEach(job => {
      try {
        const code = fs.readFileSync(`${directory}/${job}`, 'utf8');
        coffee.register(`${directory}/${job}`, code, job.replace(/\.js$/, '').replace(/\.coffee$/, ''));
      } catch (err) {
        console.error(err);
      }
    });
  });
}

