function sendResponse(dirPath, fileName, data, callback) {
  const fs = require('fs');
  const template = require('ejs');

  fs.readFile(`${dirPath}/${fileName}`, (err, fileContent) => {
    if (err) {
      callback({ status: 'Error', message: `File not found: ${fileName}` });
    } else {
      try {
        const renderedTemplate = template.render(fileContent.toString(), data);
        res.setHeader('Content-Type', 'text/html');
        res.write(renderedTemplate);
        res.end();
      } catch (error) {
        callback({ status: 'Error', message: `Failed to render template: ${error.message}` });
      }
    }
  });
}

function loadWaveform(url, callback) {
    var xhr = new XMLHttpRequest();
    xhr.open('GET', url, true);
    xhr.onload = function() {
        if (xhr.status === 200) {
            var waveformData = JSON.parse(xhr.responseText);
            var realParts = new Float32Array(waveformData.length);
            var imagParts = new Float32Array(waveformData.length);
            for (var i = 0; i < waveformData.length; i++) {
                realParts[i] = waveformData[i].real;
                imagParts[i] = waveformData[i].imag;
            }
            callback(realParts, imagParts);
        } else {
            console.error('Error loading waveform: ' + xhr.statusText);
        }
    };
    xhr.send();
}

