const { exec } = require('child_process');
const { spawn } = require('child_process');

function createDebianPackage(packageName) {
  const dpkgCmd = `dpkg-deb --build ${packageName} ${packageName}.deb`;
  exec(dpkgCmd, (error, stdout, stderr) => {
    if (error) {
      console.error(`exec error: ${error}`);
      return;
    }
    console.log(`Debian package created: ${packageName}.deb`);
  });
}

function createRedHatPackage(packageName) {
  const rpmbuildCmd = `rpmbuild -ba specfile.spec`;
  spawn(rpmbuildCmd, (error, stdout, stderr) => {
    if (error) {
      console.error(`exec error: ${error}`);
      return;
    }
    console.log(`Red Hat package created`);
  });
}

function createPackage(packageName) {
  try {
    createDebianPackage(packageName);
  } catch (e) {
    if (require('which')('rpmbuild')) {
      createRedHatPackage(packageName);
    } else {
      console.error('No rpmbuild command found');
    }
  }
}

