function createParticleSystem(m) {
  let canvas = document.getElementById('canvas');
  if (!canvas) {
    canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
  }
  let ctx = canvas.getContext('2d');
  ctx.font = '24px Arial';
  let textWidth = ctx.measureText(m).width;
  let img = new Image();
  img.onload = function() {
    ctx.drawImage(img, (canvas.width - textWidth) / 2, (canvas.height - 48) / 2);
  };
  img.src = `data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='${textWidth}' height='48'>${m}</svg>`;

  let particles = [];
  for (let i = 0; i < 100; i++) {
    particles.push({x: Math.random() * canvas.width, y: Math.random() * canvas.height, vx: 2*(Math.random()<0.5?1:-1), vy: 2*(Math.random()<0.5?1:-1)});
  }

  function explode() {
    for (let i = 0; i < particles.length; i++) {
      particles[i].vx += Math.random() * 2 - 1;
      particles[i].vy += Math.random() * 2 - 1;
    }
  };
  return { canvas, ctx, img, particles, explode };
}

function shuffleSlides(slides) {
    for (let i = 0; i < slides.length; i++) {
        let j = Math.floor(Math.random() * slides.length);
        let temp = slides[i];
        slides[i] = slides[j];
        slides[j] = temp;
    }
    return slides;
}

const memo = new Map();

function evaluateFunctions(funcsAndArgs) {
  const results = [];
  for (let i = 0; i < funcsAndArgs.length; i++) {
    let [func, ...args] = funcsAndArgs[i];
    try {
      const result = func(...args);
      if (!memo.has(result)) {
        memo.set(result, true);
      }
      results.push({ func, args, result });
    } catch (err) {
      console.error(`Error evaluating function ${func.name} with args ${args}:`, err);
    }
  }
  return results;
}

