function generateUniqueIdentifier(length, charset, existingIdentifiers) {
  let candidate;
  do {
    candidate = Array.from({ length }, () => Math.floor(Math.random() * charset.length)).map(() => charset.charAt(Math.floor(Math.random() * charset.length))).join('');
  } while (existingIdentifiers.includes(candidate));
  return candidate.substring(0, length);
}

