import re

def extract_names(text):
    pattern = r"([A-Z][a-z]+ [A-Z][a-z]+)|((?:[A-Za-z\. ]+)(?: Jr| Sr| III| IV| V| M.D| Ph.D| Esq))|((?:[A-Z][a-z]+)(?:, [A-Z][a-z]+ ?)?)"

    names = re.findall(pattern, text)

    extracted_names = {}

    for name in names:
        if len(name) > 1:
            if ',' not in name:
                extracted_names[name] = f"Text"
            else:
                refs = [i+1 for i, x in enumerate(text.split()) if name in x]
                extracted_names[name] = refs
        elif len(name) == 1 and isinstance(name[0], str):
            refs = [i+1 for i, x in enumerate(text.split()) if name[0] in x]
            extracted_names[name[0]] = refs

    return list(extracted_names.keys())
