zargl_pack = (format, values) => {
  const byte_sizes = {
    'b': 1,
    'B': 1,
    'h': 2,
    'H': 2,
    'i': 4,
    'I': 4,
    'q': 8,
    'Q': 8
  };

  let regex = new RegExp({
    pattern: /(?:(b|B|h|H|i|I|q|Q))\(([^)]+)\)/g,
    flags: 'gm'
  });

  let format_strings = [];
  while ((match = regex.exec(format))) {
    let byte_size = byte_sizes[match[1]];
    let value_count = parseInt(match[2].replace('}', ''));

    for (let i = 0; i < value_count; i++) {
      values.pop();
    }

    format_strings.push({byte_size, value_count});
  }

  let packed = [];
  for (let i = 0; i < format_strings.length; i++) {
    let { byte_size, value_count } = format_strings[i];
    for (let j = 0; j < value_count; j++) {
      packed.push(values.pop().toString(byte_size));
    }
  }

  return new Uint8Array(packed);
}

function setupEvent(event, element) {
  event.namespace = element.namespace;
  event.regExp = new RegExp(`^${element.namespace}(.*)$`);
  event.target = element;
  if (event.data) {
    event.data.type = event.data.type || "default";
  }
  return [event.name, event.namespace, ...event.arguments];
}

function generateIdentifier(key) {
  let cache = {};
  let counter = 0;

  function getPostfix() {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let postfix = '';
    for (let i = 0; i < 8; i++) {
      postfix += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return postfix;
  }

  function generateId(key) {
    let id;
    if (!cache[key]) {
      cache[key] = { counter: 0, postfix: getPostfix() };
    }

    if (cache[key].counter === 0) {
      id = key + cache[key].postfix;
    } else {
      id = key + cache[key].postfix + counter.toString();
    }
    cache[key].counter++;
    return id;
  }

  return generateId.bind(null);
}

