function getRandomGreeting() {
  const currentTime = new Date().getHours();
  const greetings = {
    morning: ["Good morning!", "Morning sunshine!"],
    afternoon: ["Afternoon delight!", "Hello there!"],
    evening: ["Good evening!", "Evening vibes!"]
  };

  let timeRange;

  if (currentTime >= 6 && currentTime <= 11) {
    timeRange = 'morning';
  } else if (currentTime > 11 && currentTime <= 17) {
    timeRange = 'afternoon';
  } else if (currentTime > 17 || currentTime < 6) {
    timeRange = 'evening';
  } else {
    timeRange = 'default';
  }

  return greetings[timeRange] ? greetings[timeRange][Math.floor(Math.random() * greetings[timeRange].length)] : "Default Greeting";
}

function updateNavigation() {
    const navItems = document.querySelectorAll('.nav-item');
    navItems.forEach(item => item.classList.remove('active'));

    const urlPathname = window.location.pathname;
    navItems.forEach(item => {
        const href = item.getAttribute('href').replace(/^\/+/, '');
        if (urlPathname.startsWith(href) || !href) {
            item.classList.add('active');
            const parents = Array.prototype.slice.call(item.parentNode.children);
            while (parents.length > 0 && !parents[0].classList.contains('active')) {
                parents[0].classList.add('active');
                parents.shift();
            }
        }
    });
}

