function parseSelector(selector) {
  const combinators = {
    '+': 'adjacent sibling combinator',
    '~': 'general sibling combinator',
    '>': 'child combinator',
    '<': 'parent combinator'
  };
  const regexps = [
    // Combinator
    /^([+\~><>])\s*(.*)/,
    // Class selector
    /\.([^\.\[\{\]]*)$/,
    // Attribute selector
    /([a-zA-Z_][^"'\s=]*)\[(.*?)\]/,
    // ID selector
    /\#([^\.\[\{\]]*)$/,
    // Tag name selector
    /^([^#\[\]\{\}\(\)]+)$/
  ];

  const parts = selector.trim().split(/(>\s*|,\s*)/g);

  const result = {};

  for (let i = 0; i < parts.length; i++) {
    let part = parts[i];
    for (let j = 0; j < regexps.length; j++) {
      const match = part.match(regexps[j]);
      if (match) {
        switch (regexps[j][0]) {
          case /^([+\~><>])\s*$/:
            result.combinator = combinators[match[1]];
            break;
          case /\.([^\.\[\{\]]*)\$/:
            result.classes = [match[1].trim()];
            break;
          case /([a-zA-Z_][^"'\s=]*)\[(.*?)\]/:
            const attrName = match[1].trim();
            const attrValue = match[2].trim();
            if (result.attributes == null) {
              result.attributes = {};
            }
            result.attributes[attrName] = attrValue;
            break;
          case /\#([^\.\[\{\]]*)\$/:
            result.id = match[1].trim();
            break;
          default:
            if (!result.tag) {
              result.tag = part.trim();
            } else {
              result.selectors.push(part.trim());
            }
        }
        part = part.replace(regexps[j][0], '');
      }
    }

    // Nested selector
    while (part && part.match(/^(\s*)\[/)) {
      const level = part.match(/^(\s*)\[/)[1].length;
      if (!result.nested[level]) {
        result.nested[level] = [];
      }
      result.nested[level].push(part.slice(1));
      part = part.slice(level);
    }

    // Comma-separated values
    while (part && part.match(/,\s*$/)) {
      const commaIndex = part.indexOf(',');
      if (commaIndex > 0) {
        const value = part.slice(0, commaIndex).trim();
        part = part.slice(commaIndex + 1);
        if (result.values == null) {
          result.values = [];
        }
        result.values.push(value);
      } else {
        part = part.trim();
      }
    }

    // Add current part to the result
    if (!part || !part.match(/^(\s*)\[/)) {
      if (!result.tag && !result.id) {
        result.tag = part;
      } else {
        if (result.selectors == null) {
          result.selectors = [];
        }
        result.selectors.push(part);
      }
    }
  }

  return result;

function jsonValidate(str) {
  var regEx = new RegExp(/^({|"[a-zA-Z0-9_]+":\s*\(\s*("[a-zA-Z0-9_]+")*,\s*)}$/);
  if (!regEx.test(str)) {
    throw new Error("Invalid JSON string");
  }
  try {
    return Function('"use strict";return ' + str + ')();
  } catch (e) {
    throw new Error("Invalid JSON string");
  }
}

