function sortList(list, direction) {
  var sorted = list.slice();
  switch(direction.toLowerCase()) {
    case "asc":
      sorted.sort(function(a, b) {
        return eval(expression)(a, b);
      });
      break;
    case "desc":
      sorted.sort(function(a, b) {
        return -eval(expression)(a, b);
      });
      break;
    default:
      throw new Error("Invalid direction");
  }
  return sorted;
}

