function concatBuffers(arr) {
  let result = Buffer.alloc(0);
  for (const buf of arr) {
    if (!Buffer.isBuffer(buf)) {
      throw new TypeError('All buffers must be Buffer objects');
    }
    const buffer = Buffer.from(buf);
    const offset = result.write(buffer, 0, buffer.length);
    result.resize(result.length + buffer.length - offset);
  }
  return result;

function traverseTree(tree, currentNode, path = '') {
  if (!currentNode) return;

  let currentPath = path ? `${path} -> ` : '';
  console.log(`Visiting node ${currentNode.id}: ${currentPath}`);

  if (currentNode.subIndices) {
    for (let i = 0; i < currentNode.subIndices.length; i++) {
      const subIndex = currentNode.subIndices[i];
      const subTree = tree.find(node => node.id === subIndex);
      traverseTree(tree, subTree, `${path} -> ${subIndex}`);
    }
  } else {
    loadSubIndices(currentNode.id).then(subIndices => {
      for (let i = 0; i < subIndices.length; i++) {
        const subIndex = subIndices[i];
        const subTree = tree.find(node => node.id === subIndex);
        traverseTree(tree, subTree, `${path} -> ${subIndex}`);
      }
    });
  }
}

