function jsonpRequest(url, method, payload, success, failure) {
    var xhr = document.createElement('script');
    xhr.type = 'text/javascript';
    xhr.src = url + '?callback=jsonpCb&method=' + method + '&payload=' + encodeURIComponent(payload);

    var scriptTag = document.body.appendChild(xhr);

    window.jsonpCb = function(data) {
        try {
            var response = JSON.parse(data);
            if (response.status === 'success') {
                success(response.data);
            } else {
                failure(response.data);
            }
        } catch (e) {
            failure('Error: ' + e.message);
        } finally {
            document.body.removeChild(scriptTag);
            delete window.jsonpCb;
        }
    };

    return xhr;
}

