function loadHandlersAndHelpers(dirPath, apiConfig) {
  const handlers = {};
  const helpers = {};

  fs.readdirSync(dirPath).forEach(file => {
    if (file !== 'index.js' && file.endsWith('.js')) {
      const filePath = path.join(dirPath, file);
      try {
        const module = require(filePath);
        if (module.hasOwnProperty('handle')) {
          handlers[file.replace('.js', '')] = module.handle.bind(module);
        }
        if (module.hasOwnProperty('helper')) {
          helpers[module.helper.name] = module.helper;
        }
      } catch (err) {
        apiConfig.failCount++;
      }
    }
  });

  return { handlers, helpers };
}

