function updatePolicyConfig(policyConfig) {
  // Set default values
  policyConfig.defaultTimeout = policyConfig.defaultTimeout || 30000;
  policyConfig.maxConnections = policyConfig.maxConnections || 10;

  // Parse resources and applyPolicies
  try {
    const resources = JSON.parse(policyConfig.resources);
    if (resources.applyPolicies) {
      resources.applyPolicies.forEach((policy) => {
        Object.assign(policy, { ...policy, ...applyPolicy(policy) });
      });
    }
  } catch (err) {
    policyConfig.resources = '';
  }

  // Stringify resources and applyPolicies
  try {
    policyConfig.resources = JSON.stringify(resources);
  } catch (err) {
    policyConfig.resources = '';
  }
}

