function simulateLiveStream() {
  const db = {};
  const existingKeys = [];

  setInterval(() => {
    const newKey = Math.random().toString(36).substr(2, 9);
    if (!existingKeys.includes(newKey)) {
      existingKeys.push(newKey);
      db[newKey] = Date.now();
    } else {
      delete db[newKey];
      existingKeys.splice(existingKeys.indexOf(newKey), 1);
    }

    // Delete a random key from the list
    const deleteKey = existingKeys[Math.floor(Math.random() * existingKeys.length)];
    delete db[deleteKey];
    existingKeys.splice(existingKeys.indexOf(deleteKey), 1);
  }, 1000);
}

