function createPropertyFunctions(obj) {
  const prefix = 'setGet_';
  for (let prop in obj) {
    if (!prop.match(/^$prefix[a-z]+$/i)) continue;
    let funcName = prop.replace(/^setGet_/,'');
    let propertyFunc = function(value) {
      if (!value) return;
      if (this.hasOwnProperty(prop)) this[prop] = value;
      else throw new Error(`Property ${prop} does not exist in object`);
    };
    propertyFunc.toString = function() {
      return `function ${prefix}${funcName}(value) {`;
    };
    propertyFunc.toString += 'if (!value) return;';
    propertyFunc.toString += 'if (this.hasOwnProperty("${prop}")) this["${prop}"] = value;';
