function processString(input) {
  let handlers = [
    [/^https?:\/\//i, (match) => match.replace(/^https?:\/\/|\/$/g, '')],
    [/\(.*?\)/g, (match) => match.replace(/\(|\)|/g, '')],
    [/(.*)/, (match) => eval(match)]
  ];

  for (let i = 0; i < handlers.length; i++) {
    let regex = handlers[i][0];
    let handler = handlers[i][1];

    if (regex.test(input)) {
      return handler(input);
    }
  }

  return input;
}

