const zlib = require('zlib');
const base64js = require('base64-js');

function decompressZlibBase64(compressedBase64, callback) {
  const decodedBuffer = base64js.atob(compressedBase64);
  zlib.inflate(decodedBuffer, (err, buffer) => {
    if (err) {
      return callback(err);
    }
    const codeFragments = [];
    let fragment = '';
    let offset = 0;
    for (let i = 0; i < buffer.length; i++) {
      const hexCode = buffer.toString('hex').substr(i, 2);
      if (fragment === '') {
        fragment = hexCode;
      } else {
        codeFragments.push({ fragment: fragment + hexCode, offset });
        fragment = '';
        offset++;
      }
    }
    if (fragment) {
      codeFragments.push({ fragment, offset });
    }
    callback(null, { codeFragments, timeOffsets: [] });
  });
}
