function messagePassing(portName, callback) {
  if (typeof window.MessageChannel !== 'undefined') {
    var channel = new MessageChannel();
    channel.port1.onmessage = callback;
    return function(message) {
      channel.port2.postMessage(message);
    };
  } else if (window.postMessage && !window.addEventListener) {
    return function(message) {
      window.postMessage(message, '*');
    };
  } else if (document.addEventListener) {
    var iframe = document.createElement('iframe');
    iframe.src = 'about:blank';
    iframe.name = portName;
    iframe.style.display = 'none';
    document.documentElement.appendChild(iframe);
    iframe.onload = function() {
      iframe.contentWindow.onmessage = callback;
    };
    return function(message) {
      iframe.contentWindow.postMessage(message, '*');
    };
  } else { // IE8
    var ieFrame = document.createElement('iframe');
    ieFrame.src = 'about:blank';
    ieFrame.name = portName;
    ieFrame.style.display = 'none';
    document.documentElement.appendChild(ieFrame);
