function createDraggable(obj, minX, maxX, leftBtn, rightBtn) {
    obj.style.position = 'absolute';
    obj.style.left = (obj.offsetLeft || 0) + 'px';
    obj.style.right = (obj.offsetTop || 0) + 'px';

    function onDragStart(e) {
        var startX = e.clientX;
        var endX = startX;
        var isDragging = false;

        function drag() {
            if (!isDragging) return;
            endX = e.clientX;
            obj.style.left = (endX - startX) + 'px';
            if (parseInt(obj.style.left) < minX) obj.style.left = minX + 'px';
            else if (parseInt(obj.style.left) > maxX) obj.style.left = maxX + 'px';

            setTimeout(drag, 10);
        }

        function endDrag() {
            isDragging = false;
        }

        e.preventDefault();
        isDragging = true;
        drag();

        document.addEventListener('mousemove', drag);
        document.addEventListener('mouseup', endDrag);

        return false;
    }

    function onDrag(e) {
        return onDragStart(e);
    }

    function onDragEnd() {
        document.removeEventListener('mousemove', drag);
        document.removeEventListener('mouseup', endDrag);
    }

    obj.onmousedown = onDragStart;
    leftBtn.onmousedown = onDragStart;
    rightBtn.onmousedown = onDragStart;

    obj.onmouseup = onDragEnd;
    leftBtn.onmouseup = onDragEnd;
    rightBtn.onmouseup = onDragEnd;
}

