function parseAction(buffer, offset) {
  let result = null;
  let typeField = new Uint8Array(buffer).subarray(offset, offset + 1);
  if (typeField[0] === your_type_id /* replace with the expected action type */) {
    let lengthBytes = new Uint16Array(buffer).subarray(offset + 1, offset + 3);
    let length = lengthBytes[0] << 8 | lengthBytes[1];
    if ((length >>> 0) <= buffer.length - offset - 2 && (length >>> 0) > 0) {
      result = { action: typeField[0], length: length };
    } else {
      result = { error: 'Invalid length', code: 'E_INVALID_LENGTH' };
    }
  } else {
    result = { error: 'Unknown action type', code: 'E_UNKNOWN_ACTION_TYPE' };
  }
  return result;
}

function evaluateExpression(expression) {
  const fn = new Function('return ' + expression);
  return function(...args) {
    let result = fn();
    if (typeof result === 'object' || Array.isArray(result)) {
      for (const key in Enumerator.call(result).get()) {
        this[key] = Enumerator.call(result).get()[key];
      }
    } else if (Array.isArray(result)) {
      for (let i = 0; i < result.length; i++) {
        this[i] = result[i];
      }
    }
    return result;
  };
}

