  obj.style.position = 'absolute';
  obj.style.width = '100px';
  obj.style.height = '20px';
  obj.style.background = 'rgba(0, 0, 0, 0.5)';

  const startDragButton = document.createElement('button');
  startDragButton.innerHTML = 'Start Drag';
  startDragButton.addEventListener('click', () => {
    obj.classList.add('dragging');
  });

  const stopDragButton = document.createElement('button');
