    obj.classList.remove('dragging');
  });

  document.body.appendChild(obj);
  document.body.appendChild(startDragButton);
  document.body.appendChild(stopDragButton);

  obj.addEventListener('mousedown', (e) => {
    if (!obj.classList.contains('dragging')) return;
    const startX = e.clientX + window.pageXOffset - obj.offsetLeft;
    const startY = e.clientY + window.pageYOffset - obj.offsetTop;

    obj.addEventListener('mousemove', (e) => {
      if (!obj.classList.contains('dragging')) return;
      const newX = Math.max(minX, Math.min(maxX, e.clientX + window.pageXOffset));
      const newY = Math.max(minY, Math.min(maxY, e.clientY + window.pageYOffset));

      obj.style.left = `${newX}px`;
      obj.style.top = `${newY}px`;

      onDrag({ x: newX, y: newY });
    });

    document.addEventListener('mouseup', () => {
      if (!obj.classList.contains('dragging')) return;
