#include <stdlib.h>
#include <string.h>

char* concatenateBuffers(char** buffers, int numBuffers) {
    int totalSize = 0;
    for (int i = 0; i < numBuffers; i++) {
        totalSize += strlen(buffers[i]) + 1; // Add space for null-terminator
    }

    char* result = (char*)malloc(totalSize);
    if (!result) return NULL; // Error allocating memory

    char* currentPos = result;
    for (int i = 0; i < numBuffers; i++) {
        strcpy(currentPos, buffers[i]);
        currentPos += strlen(buffers[i]) + 1; // Move to end of buffer
    }

    return result;
}
