function createPropTypeChecker(validationFn: (name: string, props: Record<string, any>) => void) {
  const propTypeCache = new Map<string, Record<string, any>>();

  return function(componentName: string, props: Record<string, any>): void {
    if (!propTypeCache.has(componentName)) {
      validationFn(componentName, props);
      propTypeCache.set(componentName, props);
    } else if (JSON.stringify(props) !== JSON.stringify(propTypeCache.get(componentName))) {
      throw new Error(`Invalid prop types for ${componentName}`);
    }
  };
}

