  function TrivialArray() {
    this.data = new Array.apply(null, {length: dim}).map(() => null);
  }

  TrivialArray.prototype.pick = function() {
    return JSON.parse(JSON.stringify(this.data));
  };

  TrivialArray.prototype.set = function(offset, value) {
    if (offset < 0 || offset >= this.data.length) {
      throw new Error("Index out of range");
    }
    this.data[offset] = value;
  };

  TrivialArray.prototype.valueOf = function() {
