function makeDraggableResizable(element) {
  let isDragging = false;
  let xOffset = 0;
  let yOffset = 0;

  element.addEventListener('mousedown', (e) => {
    if (e.target.tagName === 'BUTTON' || e.target.tagName === 'SVG') return;
    isDragging = true;
    xOffset = e.clientX - parseInt(window.getComputedStyle(element).left);
    yOffset = e.clientY - parseInt(window.getComputedStyle(element).top);
  });

  element.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    let left = `${xOffset + e.clientX}px`;
    let top = `${yOffset + e.clientY}px`;
    let newWidth = Math.max(0, parseInt(window.getComputedStyle(element).width)) + (e.clientX - xOffset);
    let newHeight = Math.max(0, parseInt(window.getComputedStyle(element).height)) + (e.clientY - yOffset);

    element.style.left = left;
    element.style.top = top;
    element.style.width = `${newWidth}px`;
    element.style.height = `${newHeight}px`;
  });

  element.addEventListener('mouseup', () => {
    isDragging = false;
  });

  element.addEventListener('touchstart', (e) => {
    if (!e.target.tagName === 'BUTTON' || !e.target.tagName === 'SVG') isDragging = true;
    xOffset = e.touches[0].clientX - parseInt(window.getComputedStyle(element).left);
    yOffset = e.touches[0].clientY - parseInt(window.getComputedStyle(element).top);
  });

  element.addEventListener('touchmove', (e) => {
    if (!isDragging) return;
    let left = `${xOffset + e.touches[0].clientX}px`;
    let top = `${yOffset + e.touches[0].clientY}px`;
    let newWidth = Math.max(0, parseInt(window.getComputedStyle(element).width)) + (e.touches[0].clientX - xOffset);
    let newHeight = Math.max(0, parseInt(window.getComputedStyle(element).height)) + (e.touches[0].clientY - yOffset);

    element.style.left = left;
    element.style.top = top;
    element.style.width = `${newWidth}px`;
    element.style.height = `${newHeight}px`;
  });

  element.addEventListener('touchend', () => {
    isDragging = false;
  });

  const alignLeftButton = document.getElementById('align-left-button');
  const alignRightButton = document.getElementById('align-right-button');

  alignLeftButton.addEventListener('click', (e) => {
    if (e.target.tagName !== 'BUTTON') return;
    element.style.left = '0px';
  });

  alignRightButton.addEventListener('click', (e) => {
    if (e.target.tagName !== 'BUTTON') return;
    let rect = element.getBoundingClientRect();
    element.style.left = `${window.innerWidth - rect.width}px`;
  });
}

