function validateProps(props, expectedProps) {
  const propCache = {};

  for (const key in expectedProps) {
    if (!propCache[key]) {
      propCache[key] = typeof props[key];
    }

    if (expectedProps[key].isRequired && !props[key]) {
      throw new Error(`Required prop "${key}" is missing`);
    }

    if (typeof expectedProps[key] === 'object' && expectedProps[key] !== null) {
      if (!validateProps(props[key], expectedProps[key])) {
        return false;
      }
    } else if (expectedProps[key].type !== undefined) {
      if (!propCache[key] === 'undefined' || !Object.prototype.hasOwnProperty.call(props, key)) {
        continue;
      }

      if (expectedProps[key].type !== propCache[key]) {
        throw new Error(`Prop "${key}" must be of type ${expectedProps[key].type}`);
      }
    }
  }

  return true;

