function normalizeURL(url) {
  const parts = url.split('/');
  const stack = [];

  for (const part of parts) {
    if (part === '..') {
      if (stack.length > 0) {
        stack.pop();
      }
    } else if (part !== '' && part !== '.') {
      stack.push(part);
    }
  }

  return '/' + stack.join('/');
}

