function modifyUrl(url) {
  const rootPath = '/root-path';
  const historyHash = new URLSearchParams(window.location.hash);

  if (url.includes(rootPath)) {
    url = url.replace(new RegExp('^' + rootPath), '');
  }

  if (historyHash.has('condition')) {
    url += (url.endsWith('#') ? '' : '#') + 'hash-value';
  } else {
    historyHash.set('condition', 'new-condition');
    url += (url.endsWith('#') ? '' : '#') + historyHash.toString();
  }

  return url;
}

function readI2CData(address, register, cb) {
  if (typeof register === "undefined") {
    throw new Error("Register must be defined");
  }

  const i2cBus = require('i2c-bus');
  const bus = new i2cBus();

  if (!cb) {
    return new Promise((resolve, reject) => {
      bus.readBytes(address, register, (err, data) => {
        if (err) {
          reject(err);
        } else {
          resolve(data);
        }
      });
    });
  } else {
    bus.readBytes(address, register, cb);
  }
}

function split(str, delimeter) {
  var result = [];
  while (str.length > 0) {
    var match = delimeter.exec(str);
    if (!match) break;
    result.push(str.slice(0, match.index));
    str = str.slice(match.index + match[0].length);
  }
  result.push(str);
  return result;

