def coroutine_system(coroutines, token):
    for cor in iter(coroutines):
        while True:
            try:
                value = next(cor)
                if value == token:
                    yield from [(cor, i) for i, _ in enumerate(coroutines)]
                    break
                return value
            except StopIteration:
