function postMessageHandler(callbacks) {
  window.addEventListener("message", function(event) {
    if (event.data === "SENTINEL") {
      event.source.postMessage("EXECUTE", "*");
    } else {
      callbacks.push(event.data);
    }
  });

  window.addEventListener("message", function(event) {
    if (event.data === "EXECUTE") {
      while (callbacks.length > 0) {
        event.source.postMessage(callbacks.shift(), "*");
      }
    }
  }, {once: true});
}

