function decodeBuffer(buffer) {
  let str = '';
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] >= 128) {
      if (i + 1 < buffer.length && buffer[i + 1] & 0x80) {
        i++;
      }
      str += String.fromCharCode((buffer[i] & 0x1f) << 6 | (buffer[i + 1] & 0x3f));
    } else {
      str += String.fromCharCode(buffer[i]);
    }
  }
  return str;
}

