function copyBytes(chunks, offset, length) {
  const result = Buffer.allocUnsafe(length);
  let pos = 0;
  for (const chunk of chunks) {
    const chunkOffset = Math.max(0, offset - pos);
    const chunkLength = Math.min(length, offset + length - pos);
    chunk.copy(result, pos, chunkOffset, chunkOffset + chunkLength);
    pos += chunkLength;
  }
  return result;

function bufferToString(buffer) {
  let decodedString = '';
  for (let i = 0; i < buffer.length; i++) {
    const byte = buffer[i];
    if (byte === 0) continue;
    switch (decodedString.length % 4) {
      case 0:
        decodedString += String.fromCharCode(byte);
        break;
      case 1:
      case 2:
      case 3:
        let charCode = ((buffer[i - 1] << 8 | buffer[i]) & 0x7FF) >>> 0;
        if (charCode < 0x10000) decodedString += String.fromCharCode(charCode);
        else decodedString += String.fromCharCode(0xD800 | ((charCode >> 10) & 0x3FF)) + String.fromCharCode(0xDC00 | (charCode & 0x3FF));
    }
  }
  return decodedString;

