  const token = localStorage.getItem('token');

  fetch(`${apiUrl}/${activityId}`, {
    method: 'PUT',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ attendanceStatus }),
  })
  .then(response => response.json())
  .then(data => console.log('Attendance updated successfully!'))
  .catch(error => console.error('Error updating attendance:', error));
}

function bufferClass(subject, encoding, noZero) {
  if (typeof subject === 'number' || typeof subject === 'string') {
    const buffer = new Uint8Array(subject.length);
    for (let i = 0; i < subject.length; i++) {
      buffer[i] = subject.charCodeAt(i);
    }
  } else if (Array.isArray(subject)) {
    const buffer = new Uint8Array(subject.length);
    for (let i = 0; i < subject.length; i++) {
      buffer[i] = subject[i];
    }
  } else {
    throw new Error('Invalid subject type');
  }

  function Buffer() {}
  Buffer.prototype.writeUInt8 = function(value, offset) {
    this[offset] = value & 0xff;
  };
  Buffer.prototype.writeUInt16LE = function(value, offset) {
    this[offset] = value & 0xff;
    this[offset + 1] = (value >>> 8) & 0xff;
  };
  Buffer.prototype.writeUInt32LE = function(value, offset) {
    this[offset] = value & 0xff;
    this[offset + 1] = (value >>> 8) & 0xff;
    this[offset + 2] = (value >>> 16) & 0xff;
    this[offset + 3] = (value >>> 24);
  };
  Buffer.prototype.writeBytes = function(buffer, offset) {
    for (let i = 0; i < buffer.length; i++) {
      this[i + offset] = buffer[i];
    }
  };

  return new Buffer();
}

function modifyAndBuildDebs(src_filename, dest_filename, arch) {
  const fs = require('fs');
  const dpkgDeb = require('dpkg-deb');

  let contents = fs.readFileSync(src_filename, 'utf8');
  contents = contents.replace('{{version}}', new Date().toISOString());
  contents = contents.replace('{{arch}}', arch);

  fs.writeFileSync(dest_filename, contents);

  if (require('which')('dpkg-deb')) {
    const packageContents = contents;
    const linux32Package = new dpkgDeb.Deb({
      'Control': `Description: A description of the package
Architecture: i386
Version: ${new Date().toISOString()}\n`,
      'control.tar.gz': Buffer.from(packageContents, 'utf8'),
      'data.tar.gz': Buffer.from('', 'utf8')
    });
    const linux64Package = new dpkgDeb.Deb({
      'Control': `Description: A description of the package
Architecture: amd64
Version: ${new Date().toISOString()}\n`,
      'control.tar.gz': Buffer.from(packageContents, 'utf8'),
      'data.tar.gz': Buffer.from('', 'utf8')
    });

    const packageFiles = [linux32Package, linux64Package];
    packageFiles.forEach(packageFile => {
      packageFile.create('package.deb');
    });
  } else {
    console.log("dpkg-deb not installed. Cannot build .deb packages.");
  }
}

