function parseMetaEvent(stream) {
  let buffer = new Buffer(1);
  stream.read(buffer, 0, 1);

  if (buffer[0] === 0xFF && buffer[1] === 0x00) { // Time signature
    let timeSignatureData = new Buffer(4);
    stream.read(timeSignatureData, 0, 4);
    let subtype = 'timeSignature';
    let numerator = timeSignatureData.readInt32LE(0);
    let denominator = timeSignatureData.readInt32LE(4);

    return { subtype, numerator, denominator };
  } else if (buffer[0] === 0xFF && buffer[1] === 0x02) { // Key signature
    let keySignatureData = new Buffer(2);
    stream.read(keySignatureData, 0, 2);
    let subtype = 'keySignature';
    let key = keySignatureData.readInt16LE(0);

    return { subtype, key };
  } else if (buffer[0] === 0xFF && buffer[1] === 0x01) { // Sequencer specific
    let sequencerSpecificData = new Buffer(stream.readUInt8());
    stream.read(sequencerSpecificData);
    let subtype = 'sequencerSpecific';
    let data = sequencerSpecificData;

    return { subtype, data };
  } else {
    throw new Error('Unknown meta event subtype');
  }
}

function getUniqueTokens(str1, str2) {
    let tokens = str1.split(' ');
    let uniqueTokens = [];

    for (let i = 0; i < tokens.length; i++) {
        let found = false;
        for (let j = 0; j < str2.split(' ').length; j++) {
            if (tokens[i] === str2.split(' ')[j]) {
                found = true;
                break;
            }
        }
        if (!found) {
            uniqueTokens.push(tokens[i]);
        }
    }

    return uniqueTokens.join(' ');
}

void* copyBytes(size_t n, void* list) {
    size_t total = 0;
    void* ptr = list;
    while (n > 0 && *(size_t*)ptr < n) {
        n -= *(size_t*)ptr;
        ptr = ((char*)ptr) + *(size_t*)ptr;
    }
    if (n > 0) return NULL; // not enough data
    size_t bytesLeft = n;
    void* result = Buffer.allocUnsafe(bytesLeft);
    ptr = list;
    while (bytesLeft > 0 && *reinterpret_cast<size_t*>(ptr) <= bytesLeft) {
        memcpy(result, ptr, *reinterpret_cast<size_t*>(ptr));
        bytesLeft -= *reinterpret_cast<size_t*>(ptr);
        ptr = ((char*)ptr) + *(size_t*)ptr;
    }
    if (bytesLeft > 0) {
        // remaining bytes left
        size_t leftBytes = *reinterpret_cast<size_t*>(ptr);
        if (leftBytes > bytesLeft) {
            leftBytes = bytesLeft;
        }
        memcpy(result + n - bytesLeft, ptr, leftBytes);
    }
    return result;

