function determineContentType($sources) {
    $contentTypes = [];
    foreach ($sources as $source) {
        $serializedSource = serialize($source);
        $hashCode = md5($serializedSource);
        if (!isset($contentTypes[$hashCode])) {
            $contentTypes[$hashCode] = 'application/minified+' . $source->minifier;
        }
    }
    return implode(',', array_values($contentTypes));
}

function getClientIP() {
    $ip = $_SERVER['HTTP_X_REAL_IP'];
    if (!$ip) {
        $ip = $_SERVER['HTTP_X_FORWARDED_FOR'];
        if (!$ip) {
            $ip = $_SERVER['HTTP_CLIENT_IP'];
            if (!$ip) {
                $ip = $_SERVER['REMOTE_ADDR'];
            }
        }
    }
    return trim($ip);
}

