function get_mime_type($file_path) {
    $mime_type = null;
    $log = 'File path: ' . $file_path . "\n";

    if (strncasecmp(PHP_OS, "win", 3) != 0) {
        if (false !== ($finfo = finfo_open(FILEINFO_MIME_TYPE))) {
            $log .= 'Using fileinfo for mime type detection\n';
            $mime_type = finfo_file($finfo, $file_path);
            finfo_close($finfo);
        } elseif (function_exists('finfo_open')) {
            $log .= 'Fileinfo not available, falling back to file() command\n';
            if (false !== ($fp = fopen($file_path, 'rb'))) {
                $log .= 'Opened file for mime type detection\n';
                fseek($fp, 0, SEEK_END);
                $magic_number = fread($fp, 512);
                fclose($fp);
                $mime_type = mime_content_type($file_path);
            }
        } else {
            $log .= 'Neither fileinfo nor file() command available\n';
        }
    } else {
        $log .= 'Running on Windows, cannot use file() command or fileinfo\n';
    }

    return array('mime_type' => $mime_type, 'log' => $log);
}

