function getHashedPassword($password, $algorithm = 'SSHA') {
    if (!in_array($algorithm, array('SSHA', 'SHA', 'SMD5'))) {
        $algorithm = 'SSHA';
    }

    switch ($algorithm) {
        case 'SSHA':
            $hashed_password = sha1($password . uniqid());
            break;
        case 'SHA':
            $hashed_password = hash('sha256', $password);
            break;
        case 'SMD5':
            $hashed_password = hash('md5', $password);
            break;
    }

    return "$algorithm hash: $hashed_password";
}

