function cacheTaskContent($task, $content = null, $isDownload = false) {
    if (!isset($task['url'])) {
        throw new Exception('Task URL is not defined');
    }

    $cacheDir = 'cache'; // replace with your actual cache directory
    if (!file_exists($cacheDir)) {
        throw new Exception('Cache directory does not exist');
    }

    $filePath = md5($task['url']) . ($isDownload ? '_download' : '');

    if (file_exists($cacheDir . '/' . $filePath . '.txt')) {
        $cachedContent = file_get_contents($cacheDir . '/' . $filePath . '.txt');
        return array('path' => $cacheDir . '/' . $filePath . '.txt', 'content' => $cachedContent);
    } else {
        if ($content === null) {
            throw new Exception('No content provided for caching');
        }

        file_put_contents($cacheDir . '/' . $filePath . '.txt', $content);
        return array('path' => $cacheDir . '/' . $filePath . '.txt', 'content' => $content);
    }
}

