function aes_encrypt($str, $key) {
    if (!extension_loaded('mcrypt')) return FALSE;
    mcrypt_set_iv_mode(MCRYPT_MODE_CBC);
    $iv = mcrypt_create_iv(mcrypt_get_block_size(MCRYPT_rijndael_256), MCRYPT_RAND);
    $block_size = mcrypt_get_block_size(MCRYPT_rijndael_256, MCRYPT_MODE_CFB);
    $result = mcrypt_encrypt(MCRYPT_rijndael_256, $key, $str, MCRYPT_MODE_CBC, $iv);
    return base64_encode($iv . $result);
}

