function validateSignature($token, $timestamp, $nonce, $signature) {
    $data = array('token' => $token, 'timestamp' => $timestamp, 'nonce' => $nonce);
    ksort($data);
    $str = implode('', array_values($data));
    $expectedSignature = sha1($str);
    return hash_equals($expectedSignature, $signature);
}

