  // Hash password
  $hashed_password = password_hash($data['password'], PASSWORD_DEFAULT);

  // Prepare statement
  $stmt = $conn->prepare("INSERT INTO users (name, username, password, email, cpf, address, number, complement, neighborhood, zip_code, city, state, phone, cell_phone) 
                          VALUES (:name, :username, :hashed_password, :email, :cpf, :address, :number, :complement, :neighborhood, :zip_code, :city, :state, :phone, :cell_phone)");

  // Bind parameters
