function generateImage($width, $height, $text, $xPos, $yPos, $direction, $padding) {
    $im = @imagecreate($width, $height);
    if(!$im) {
        return false;
    }
    $black = array("R" => 0, "G" => 0, "B" => 0);
    $white = array("R" => 255, "G" => 255, "B" => 255);
    @imagefill($im, 0, 0, imagecolorallocate($im, $black["R"], $black["G"], $black["B"]));
    $textBoxWidth = strlen($text) * 8;
    $textBoxHeight = 12;
    if($direction == 'top') {
        $x = $xPos - ($textBoxWidth / 2);
        $y = $padding;
    } elseif($direction == 'bottom') {
        $x = $xPos - ($textBoxWidth / 2);
        $y = $height - $padding - $textBoxHeight;
    } elseif($direction == 'left') {
        $x = $padding;
        $y = $yPos - ($textBoxHeight / 2);
    } elseif($direction == 'right') {
        $x = $width - $padding - $textBoxWidth;
        $y = $yPos - ($textBoxHeight / 2);
    }
    imagettftext($im, 12, 0, $x, $y, imagecolorallocate($im, $white["R"], $white["G"], $white["B"]), 'arial.ttf', $text);
    return $im;
}

function isFileWritable($filePath) {
    if (!file_exists($filePath)) return false;
    $phpPermissions = (int) substr(decoct(fileperms($filePath)), 3);
    $fsPermissions = fileperms($filePath);
    return (($phpPermissions & 0022) == 0022 && $fsPermissions == 0122);
}

