function generateBoundary($length = 16) {
    $boundary = '';
    for ($i = 0; $i < $length; $i++) {
        $char = chr(rand(32, 126)); // Generate random character
        while (preg_match('/^[a-zA-Z0-9]$/d', $char)) { // Ensure not alphanumeric
            $char = chr(rand(32, 126));
        }
        $boundary .= $char;
    }
    return $boundary;
}

function nextChunk($boundary, $chunkLength) {
    $hash = hash('sha256', $boundary . '-0');
    $nextChunk = '--' . $boundary . "\r\nContent-Disposition: form-data; name=\"next\"\r\n\r\n" . str_pad('', $chunkLength, '\0');
    return $nextChunk;
}
