```
function execute_query($query) {
  $mysqli = new mysqli('localhost', 'username', 'password', 'database');
  if ($mysqli->connect_error) {
    die('Connect Error: ' . $mysqli->connect_error);
  }

  $query_parts = explode(' ', $query);
  $action = $query_parts[0];

  if (in_array($action, array('INSERT INTO', 'UPDATE'))) {
    $table_name = str_replace(array('INSERT INTO ', 'UPDATE '), '', $query);
    $query_parts = explode(' ', $query);
    $columns = array();
    $values = array();

    for ($i = 0; $i < count($query_parts) - 1; $i++) {
      if (substr($query_parts[$i], 0, 7) == 'VALUES (' || substr($query_parts[$i], 0, 6) == 'SET ') {
        break;
      }

      $columns[] = $query_parts[$i];
    }

    for ($i = count($query_parts) - 1; $i > 0; $i--) {
      if (substr($query_parts[$i], 0, 7) == 'VALUES (' || substr($query_parts[$i], 0, 6) == 'SET ') {
        break;
      }

      $values[] = "'$query_parts[$i]'";
    }

    array_reverse($values);

    if ($action == 'INSERT INTO') {
      $mysqli->query("INSERT INTO auditoria (ip_address, timestamp) VALUES ('" . $_SERVER['REMOTE_ADDR'] . "', NOW())");

      $mysqli->query("INSERT INTO $table_name (" . implode(', ', $columns) . ") VALUES (" . implode(', ', $values) . ")");
    } else {
      $set_query = '';

      for ($i = 0; $i < count($columns); $i++) {
        if (strpos($query_parts[count($query_parts) - $i - 1], $columns[$i]) !== false) {
          if ($set_query != '') {
            $set_query .= ', ';
          }

          $set_query .= "$columns[$i] = '$values[$i]'";  
        }        
      }

      $mysqli->query("UPDATE $table_name SET $set_query WHERE " . implode(' AND ', array_slice($query_parts, 0, -1)));
    }

    $mysqli->close();
  } else {
    die('Invalid query');
  }
}

