RETURN VARCHAR2 AS
v_sql_text VARCHAR2(4000);
BEGIN
SELECT 'ALTER SESSION SET NLS_DATE_FORMAT=''DD-MON-YYYY'';
v_sql_text := v_sql_text || p_sql_text;
IF p_limit > 0 THEN
    v_sql_text := REPLACE(v_sql_text, 'ORDER BY', 'ORDER BY LIMIT ' || TO_CHAR(p_limit) || ' OFFSET ' || TO_CHAR(p_offset));
END IF;
RETURN v_sql_text;
