        password = VALUES(password),
        email = REPLACE(REPLACE(VALUES(email), "'", "\\'"), '"', '\"\"');

    SET v_result = 1;

    CREATE TABLE IF NOT EXISTS kin.`p_username` (
        id INT PRIMARY KEY AUTO_INCREMENT,
        `name` VARCHAR(255) NOT NULL
    );

    RETURN v_result;
END;

