function formatDiskUsage($diskUsage) {
    $lines = explode("\n", $diskUsage);
    $formattedOutput = array();
    foreach ($lines as $line) {
        list(, $device, $mountPoint, $size, $used, $available, $percentUsed) = explode(' ', $line);
        $formattedOutput[] = "$device: $mountPoint, used: ${used} (${percentUsed}%), available: ${available}";
    }
    return implode("\n", $formattedOutput);
}

