from functools import wraps
from urllib.parse import urlencode, urlparse, urlunparse
import hashlib
import os

class CachedURL:
    def __init__(self):
        self.cache = {}

    def get_url(self, name, params, absolute=False):
        key = self._generate_key(name, params, absolute)
        if key in self.cache:
            return self.cache[key]
        url = self._generate_url(name, params, absolute)
        self.cache[key] = url
        return url

    def _generate_key(self, name, params, absolute):
        context_info = {'absolute': absolute}
        for k, v in params.items():
            context_info[k] = v
        key = str(name) + '-' + str(hashlib.sha256(str(context_info).encode()).hexdigest())
        return key

    def _generate_url(self, name, params, absolute):
        query_string = urlencode(params)
        if not absolute:
            scheme = 'https'
            netloc = os.environ.get('SERVER_NAME', urlparse.urlparse('https://example.com').netloc)
        else:
            parsed_url = urlparse('https://example.com')
            scheme = parsed_url.scheme
            netloc = parsed_url.netloc

        path_parts = name.split('/')
        path = '/'.join(path_parts[1:])
        url = urlunparse((scheme, netloc, path, '', query_string, ''))
        return url

