function optimizeFulltextIndex($indexPath) {
    $debug = true;

    // Iterate over all subroots of the fulltext index
    foreach (DirectoryIterator::create($indexPath) as $fileInfo) {
        if ($fileInfo->isDir() && $fileInfo->getBasename() != '.') {
            $subrootPath = $fileInfo->getPathname();

            // Check for invalid subroots
            if ($debug) echo "Running 'ft_status' to check for invalid subroots on '$subrootPath':\n";
            system("ft_status -path $subrootPath 2>&1");

            // Optimize the fulltext index
            if ($debug) echo "Running 'ft_optimize' to optimize the fulltext index on '$subrootPath':\n";
            system("ft_optimize -path $subrootPath 2>&1");
        }
    }
}

