function ssh_exec($host, $username, $password) {
  $ssh = ssh2_connect($host);
  if (false === $ssh) {
    throw new Exception("Cannot connect to $host");
  }

  ssh2_auth_password($ssh, $username, $password);
  if (!ssh2_exec($ssh, 'pwd')) {
    throw new Exception("Failed to execute command");
  }

  $stream = ssh2_fetch_stream($ssh, SSH2_STREAM_OUT);
  if (!$stream) {
    throw new Exception("Failed to fetch stream");
  }

  $callback = function ($chunk) {
    echo $chunk;
  };

  stream_filter_register('php://filter', 'callback');
  stream_filter_push('php://filter', 'callback', $callback);

  stream_copy_to_stream($stream, php://filter);
}

