function databaseCreate($input = null, $output = null) {
    require_once 'vendor/autoload.php';
    use Doctrine\DBAL\Tools\Console\Helper\DatabaseHelper;
    use Symfony\Component\Console\Input\InputInterface;
    use Symfony\Component\Console\Output\OutputInterface;

    $dbParams = array(
        'url' => 'mysql://root:@localhost',
        'driverClass' => 'Doctrine\DBAL\Driver\PDOMysql\Driver'
    );

    $conn = DriverManager::getConnection($dbParams);
    $conn->getDatabasePlatform()->setViewsEnabled(true);

    // Drop database if it already exists
    $connection = $conn->connect();
    $stmt = $connection->prepare('DROP DATABASE IF EXISTS mydatabase');
    $stmt->execute();

    // Create the new database
    $stmt = $connection->prepare('CREATE DATABASE mydatabase CHARACTER SET utf8 COLLATE utf8_unicode_ci');
    $stmt->execute();

    // Load schema from schema.php file
    require_once 'schema.php';

    // Register tables and views in the doctrine metadata cache
    $conn->getSchemaManager()->dropSchema($conn->createSchema());
    $conn->getSchemaManager()->updateSchema($conn->createSchema());

    return 0;
}

