function initializeMemcached($config) {
  $memcached = new Memcached();

  if (!isset($config['save_path'])) {
    error_log('Error: Save path not configured in memcached configuration');
    return null;
  }

  $sanitizedSavePath = str_replace(array('\\', '"'), '', $config['save_path']);

  $memcached->setOption(Memcached::OPT_SASL_USERNAME, $config['username']);
  $memcached->setOption(Memcached::OPT_SASL_PASSWORD, $config['password']);
  $memcached->setOption(Memcached::OPT_COMPRESSION, true);

  if (isset($config['ip_match'])) {
    $memcached->setOption(Memcached::OPT_REMOVE_FAILED_SOCKETS, true);
    $memcached->setOption(Memcached::OPT_NO_BLOCK, false);

    foreach ($memcached->getServers() as $server) {
      $server->setAddress($config['ip_match']);
    }
  }

  return $memcached;
}

