function validateInput() {
    $maxUploadSize = 1048576; // 1 MB
    $allowedTypes = array('image/jpeg', 'text/plain');

    if (!isset($_SERVER['CONTENT_LENGTH'])) {
        return false;
    }

    $contentLength = (int) $_SERVER['CONTENT_LENGTH'];

    if ($contentLength > $maxUploadSize * 1024) { // convert to bytes
        return false;
    }

    foreach ($_FILES as $file => $info) {
        if ($info['error'] !== 0) {
            return false;
        }

        if (!in_array($info['type'], $allowedTypes)) {
            return false;
        }
    }

    return true;
}

