function processUserRequest() {
    $email = $_POST['email'];
    $password = $_POST['password'];

    // Validate password length and format
    if (strlen($password) < 8 || !preg_match('/^[a-zA-Z0-9]+$/', $password)) {
        header('Location: login.php?error=password');
        exit;
    }

    // Connect to database
    $db = mysqli_connect('localhost', 'username', 'password', 'database');

    if (!$db) {
        die('Could not connect to database!');
    }

    // Check if user exists
    $query = "SELECT * FROM users WHERE email = '$email'";
    $result = mysqli_query($db, $query);

    if (mysqli_num_rows($result) > 0) {
        $user = mysqli_fetch_assoc($result);
        if (password_verify($password, $user['password'])) {
            // Login successful
            session_start();
            $_SESSION['email'] = $email;
            header('Location: welcome.php');
            exit;
        } else {
            // Invalid password
            header('Location: login.php?error=password');
            exit;
        }
    } else {
        // Create new user
        $query = "INSERT INTO users (email, password) VALUES ('$email', '" . password_hash($password, PASSWORD_BCRYPT) . "')";
        mysqli_query($db, $query);
        header('Location: login.php?success=register');
        exit;
    }
}
