    $elements = array();
    while ($row = mysqli_fetch_assoc($result)) {
        $elements[] = $row;
    }

    // Find the element to delete and update its position
    foreach ($elements as $key => &$element) {
        if ($element['id'] == $contentId) {
            unset($elements[$key]);
            break;
        } elseif ($element['id'] > $contentId) {
            $element['position']--;
        }
    }

    // Update the positions of subsequent elements
    for ($i = 0; $i < count($elements); $i++) {
        $query = "UPDATE content_elements SET position = ? WHERE id = ?";
        mysqli_query($dbConn, $query, array($elements[$i]['position'] + 1, $elements[$i]['id']));
    }

    // Delete the original element
    $query = "DELETE FROM content_elements WHERE id = ?";
    mysqli_query($dbConn, $query, array($contentId));
}

