function processFileAndXml($filePath, $operation) {
  $fileContent = file_get_contents($filePath);
  preg_match('/\b(\d+)\b/', $fileContent, $matches);
  $value = (int)$matches[1];

  switch ($operation) {
    case 'add':
      $newValue = $value + 10;
      break;
    case 'subtract':
      $newValue = $value - 5;
      break;
    default:
      $newValue = $value;
  }

  $xmlContent = simplexml_load_file('path/to/xmlfile.xml');
  foreach ($xmlContent->children() as $child) {
    if ((string)$child == (string)$newValue) {
      return $child->attributes()->name;
    }
  }
  return null;
}

