function getSecureInput($prompt){
    $input = '';
    system('stty -echo; stty 8');
    while(true){
        echo $prompt;
        $tmp = trim(fgets(STDIN));
        if(empty($tmp)){
            continue;
        }
        $input = $tmp;
        break;
    }
    system('stty echo; stty sane');
    return $input;
}

