function createMap(locations) {
  const map = new google.maps.Map(document.getElementById("map"), {
    center: { lat: 37.0902, lng: -122.0844 },
    zoom: 12
  });

  const markerOptions = {
    icon: "https://maps.google.com/mapfiles/transparent.png",
    opacity: 0.6,
    title: ""
  };

  locations.forEach((location) => {
    if (location.category === "restaurant") {
      markerOptions.title += "Restaurant";
    } else if (location.category === "hotel") {
      markerOptions.title += "Hotel";
    } else if (location.category === "attraction") {
      markerOptions.title += "Attraction";
    }

    const marker = new google.maps.Marker({
      position: { lat: location.lat, lng: location.lng },
      map,
      ...markerOptions
    });
  });

  const menuDiv = document.createElement("div");
  menuDiv.innerHTML = `
    <h2>Categories:</h2>
    <ul>
      <li id="restaurant-button">Restaurant</li>
      <li id="hotel-button">Hotel</li>
      <li id="attraction-button">Attraction</li>
    </ul>
  `;

  document.body.appendChild(menuDiv);

  const buttons = document.querySelectorAll("#map ul li");
  buttons.forEach((button) => {
    button.addEventListener("click", (e) => {
      const category = e.target.textContent.toLowerCase();
      locations.forEach((location) => {
        if (category === "restaurant") {
          location.category === "restaurant"
            ? markerOptions.title !== "Restaurant"
              ? (markerOptions.title += " Restaurant")
              : (markerOptions.title = "")
            : "";
        } else if (category === "hotel") {
          location.category === "hotel"
            ? markerOptions.title !== "Hotel"
              ? (markerOptions.title += " Hotel")
              : (markerOptions.title = "")
            : "";
        } else if (category === "attraction") {
          location.category === "attraction"
            ? markerOptions.title !== "Attraction"
              ? (markerOptions.title += " Attraction")
              : (markerOptions.title = "")
            : "";
        }
      });
    });
  });

  const markers = locations.map((location) => {
    if (location.category === "restaurant") {
      return new google.maps.Marker({
        position: { lat: location.lat, lng: location.lng },
        map,
        ...markerOptions
      });
    } else if (location.category === "hotel") {
      markerOptions.title = "";
      return new google.maps.Marker({
        position: { lat: location.lat, lng: location.lng },
        map,
        ...markerOptions
      });
    } else if (location.category === "attraction") {
      markerOptions.title = "";
      return new google.maps.Marker({
        position: { lat: location.lat, lng: location.lng },
        map,
        ...markerOptions
      });
    }
  });
}

