function detectSecurityAttack($username, $maxAttempts = 5, $timeWindowMinutes = 10) {
    // Get failed login attempts for the user and IP address
    $failedAttempts = getFailedLoginAttempts($username);

    // Check if there are too many failed login attempts within the time window
    if (count($failedAttempts) > $maxAttempts || count(array_filter($failedAttempts, function($attempt) use ($timeWindowMinutes) {
        return time() - $attempt['timestamp'] <= $timeWindowMinutes * 60;
    })) > $maxAttempts) {
        // Set an attribute on the current user object indicating a security attack
        $_SESSION['user']->securityAttackDetected = true;

        return true; // Security attack detected
    }

    return false; // No security attack detected
}
