function pingback($remote_url) {
    $ch = curl_init($remote_url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_IPRESOLVE, CURL_RESOLV_DEFAULT);
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 1);
    sleep(1);

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        return "Error: " . curl_error($ch);
    }
    curl_close($ch);

    $pingback_enabled = preg_match('/<link rel="pingback"/', $response, $match) ? true : false;

    if (!$pingback_enabled) {
        return "Pingback not enabled at " . $remote_url;
    }

    $server_ip = gethostbyaddr(parse_url($remote_url)['host']);
    $user_agent = curl_version()['version'];

    return array('server_ip' => $server_ip, 'user_agent' => $user_agent);
}

