    if (!isset($request['name']) || strlen($request['name']) < 2) {
        return false;
    }
    if (!filter_var($request['email'], FILTER_VALIDATE_EMAIL)) {
        return false;
    }
    if (strlen($request['password']) < 8) {
        return false;
    }
    return true;
}

