function logScriptStats($logFile = 'php.log', $echoToConsole = false) {
    $startMemUsage = memory_get_usage();
    $startTime = microtime(true);

    $envVars = array();
    foreach ($_ENV as $key => $value) {
        $envVars[$key] = $value;
