    $endTime = microtime(true);
    $endMemUsage = memory_get_usage();

    $stats = "Execution Time: " . ($endTime - $startTime) . " seconds\n" .
              "Memory Usage: " . number_format($endMemUsage - $startMemUsage, 2) . " bytes\n";

    foreach ($envVars as $key => $value) {
        $stats .= "$key: $value\n";
    }

    if (!empty($output)) {
        $stats .= "\nOutput:\n" . $output;
    }

    file_put_contents($logFile, $stats . "\n", FILE_APPEND);

    if ($echoToConsole) {
        echo $stats . "\n";
    }
}

