function generateSlug($title) {
    $slug = preg_replace('/[^A-Za-z0-9-_/]/', '', strtolower(trim($title)));
    $slug = preg_replace('/_+/', '-', $slug);
    return trim($slug, '-');
}

function validateInput($data) {
    if (!isset($data['title']) || empty($data['title'])) {
        http_response_code(400);
        header('Location: ?error=Title is required');
        exit;
    }
    $slug = generateSlug($data['title']);
    if (strlen($slug) > 50) {
        http_response_code(400);
        header('Location: ?error=Slug length must be less than or equal to 50 characters');
        exit;
    }
    return $slug;
}

function redirect($slug, $message = '') {
    http_response_code(302);
    if (!empty($message)) {
        header('Location: ?success=' . urlencode($message));
    } else {
        header('Location: ' . $slug);
    }
    exit;
}
