function setupMap(locations) {
  const mapScript = document.createElement('script');
  mapScript.src = 'map.js';
  document.body.appendChild(mapScript);

  const markerScript = document.createElement('script');
  markerScript.src = 'markerwithlabel.js';
  document.body.appendChild(markerScript);

  $(document).ready(() => {
    const $mapContainer = $('#map-container');
    let map;
    let markers = [];

    function initMap() {
      map = new google.maps.Map($mapContainer[0], {
        center: { lat: 37.7749, lng: -122.4194 },
        zoom: 13
      });
    }

    function addMarkers(locations) {
      locations.forEach((location) => {
        const marker = new google.maps.Marker({
          position: location.coords,
          label: {
            text: location.name,
            color: 'black'
          }
        });

        markers.push(marker);
        marker.setMap(map);
      });
    }

    function initMasonry() {
      $mapContainer.masonry({
        columnWidth: 250,
        itemSelector: '.marker',
        gutter: 10
      });
    }

    google.maps.event.addDomListener(window, 'load', () => {
      initMap();
      addMarkers(locations);
      initMasonry();
    });

    $(window).resize(() => {
      $mapContainer.masonry('update');
    });
  });
}

