function authenticateWithOAuth($client_id, $client_secret, $redirect_uri) {
    if (!isset($_GET['code'])) {
        $auth_url = 'https://example.com/oauth/authorize?response_type=code&client_id=' . $client_id . '&redirect_uri=' . urlencode($redirect_uri);
        header('Location: ' . $auth_url);
        exit;
    }

    $code = $_GET['code'];
    $token_url = 'https://example.com/oauth/token';
    $data = array(
        'grant_type' => 'authorization_code',
        'code' => $code,
        'redirect_uri' => $redirect_uri,
        'client_id' => $client_id,
        'client_secret' => $client_secret
    );
    $ch = curl_init($token_url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
    $response = json_decode(curl_exec($ch), true);
    curl_close($ch);

    if (!isset($response['access_token'])) {
        // handle error
    }

    $_SESSION['access_token'] = $response['access_token'];

    $user_info_url = 'https://example.com/oauth/userinfo';
    $headers = array('Authorization: Bearer ' . $_SESSION['access_token']);
    $ch = curl_init($user_info_url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    $response = json_decode(curl_exec($ch), true);
    curl_close($ch);

    return $response;
}

`function shuffle<T>(list: [T], seed?: int): [T] {
    let rng = (seed === null) ? new Random() : new Random(seed);
    let result = [];
    for (let i in range(0, list.length)) {
        let j = rng.nextInt(list.length);
        let temp = list[i];
        list[i] = list[j];
        list[j] = temp;
        result.push(list[i]);
    }
    return result;

