  $stmt = $mysqli->prepare("INSERT INTO users SET username=?, email=?, password=?");
  $stmt->bind_param("sss", $username, $email, $hashedPass);
  if (!$stmt->execute()) {
    return "Error creating user account";
  }

  return 'Success';
}

