    $interfaces = array_map('ucfirst', $interfaceNames);
    $evalCode = "
        class $newClassName extends {$className} {
            use Illuminate\Support\Facades Faker\\Faker;
            " . implode("\n            ", array_map(function($interfaceName) {
                return "use Tests\\Testing\\{$interfaceName};";
            }, $interfaces)) . "
        };
