function handle_login($get_params, $post_params) {
    if (isset($get_params['checklogin'])) {
        if (isset($_SESSION['username'])) {
            $redirect_url = 'http://' . $_SERVER['HTTP_HOST'] . '/' . urldecode($get_params['redirect']);
            header('Location: ' . $redirect_url);
            exit;
        }
    }

    if (isset($post_params['email']) && isset($post_params['password'])) {
        $username = filter_var($post_params['email'], FILTER_SANITIZE_EMAIL);
        $password = trim($post_params['password']);

        // Database connection and query to verify credentials
        $db = new mysqli('localhost', 'user', 'pass', 'database');
        if ($db->connect_error) {
            return 'Error connecting to database';
        }
        $result = $db->query("SELECT * FROM users WHERE email='$username' AND password='" . md5($password) . "'");
        if (!$result->num_rows) {
            return 'Invalid credentials';
        }

        // Successful login, update redirect URL and log user in
        $_SESSION['username'] = $username;
        $redirect_url = 'http://' . $_SERVER['HTTP_HOST'] . '/' . urldecode($get_params['redirect']);
        foreach ($get_params as $key => $value) {
            if (strpos($value, '?') !== false) {
                list($param, $value) = explode('?', $value);
                $redirect_url .= '&' . $param . '=' . $value;
            } else {
                $redirect_url .= '&' . $key . '=' . $value;
            }
        }
        header('Location: ' . $redirect_url);
        exit;
    }

    return '';
}

