function updatePassword($username, $oldPassword, $newPassword) {
    require_once 'DAO.php';

    if (!$dao = new DAO()) {
        throw new Exception("Failed to connect to database");
    }

    if (!$user = $dao->getUserByUsername($username)) {
        throw new Exception("User not found");
    }

    if (!password_verify($oldPassword, $user['password'])) {
        throw new Exception("Invalid old password");
    }

    $strength = validatePasswordStrength($newPassword);

    if ($strength < 30) {
        throw new Exception("New password is too weak. Please choose a stronger one.");
    }

    $dao->updateUserPassword($username, $newPassword);
}

function validatePasswordStrength($password) {
    $strength = 0;

    // Check length
    if (strlen($password) > 8) {
        $strength += 20;
    }

    // Check for at least one uppercase letter
    if (preg_match('/[A-Z]/', $password)) {
        $strength += 10;
    }

    // Check for at least one digit
    if (preg_match('/\d/', $password)) {
        $strength += 10;
    }

    return $strength;
}
