function getSalesforceApiClient(config) {
    const { clientId, clientSecret, username, password } = config;
    const authUrl = 'https://login.salesforce.com/services/oauth2/token';
    const instanceUrl = 'https://your_instance_url.service.core.windows.net';

    return new Promise((resolve, reject) => {
        request.post({
            url: authUrl,
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            form: {
                grant_type: 'password',
                client_id: clientId,
                client_secret: clientSecret,
                username,
                password
            }
        }, (error, response, body) => {
            if (error) reject(error);
            else {
                const accessToken = JSON.parse(body).access_token;
                const apiClient = new SoapClient(instanceUrl + '/services/Soap/c?' + 'SOAPAPI32');

                request.get({
                    url: instanceUrl,
                    headers: { Authorization: `Bearer ${accessToken}` }
                }, (error, response, body) => {
                    if (error) reject(error);
                    else resolve(apiClient);
                });
            }
        });
    });
}

