function countdownUntil(dateString) {
  const targetDate = moment(dateString);
  let timeLeft;

  function updateCountdown() {
    const now = moment();
    timeLeft = targetDate.diff(now);

    if (timeLeft > 0) {
      document.getElementById('getting-started').innerHTML = timeLeft.format('HH:mm:ss');
      setTimeout(updateCountdown, 1000); // Update every 1 second
    } else {
      document.getElementById('getting-started').innerHTML = 'Time\'s up!';
    }
  }

  updateCountdown();
}

