function prepareInsert($conn, $columns, $values) {
    if (!isset($values['password'])) {
        $query = "INSERT INTO " . $columns['table'] . " (";
        foreach ($columns as $column => $value) {
            if ($column != 'password') {
                $query .= "$column, ";
            }
        }
        $query = rtrim($query, ", ") . ") VALUES (";
        foreach ($values as $key => $val) {
            if ($key != 'password') {
                $query .= "'" . $conn->real_escape_string($val) . "', ";
            }
        }
        $query = rtrim($query, ", ") . ")";
    } else {
        $hash = hash('sha256', $values['password']);
        unset($values['password']);
        $query = "INSERT INTO " . $columns['table'] . " (";
        foreach ($columns as $column => $value) {
            if ($column != 'password') {
                $query .= "$column, ";
            }
        }
        $query = rtrim($query, ", ") . ") VALUES (";
        foreach ($values as $key => $val) {
            $query .= "'" . $conn->real_escape_string($val) . "', ";
        }
        $query = rtrim($query, ", ") . "), ('$hash')";
    }
    return array(
        'result' => $conn->query($query),
        'last_id' => $conn->insert_id
    );
}

