def generate_candidates(generator_func, max_size=10, var_size=None):
    candidates = set()
    while len(candidates) < min(max_size, var_size or max_size):
        candidate = generator_func()
        if isinstance(candidate, str):  # check if candidate is a string
            candidate = {candidate}
        candidates.add(frozenset(candidate))
    assert all(len(cand) == max_size for cand in candidates)
    with open('candidates.txt', 'w') as f:
        for c in candidates:
            f.write(str(c) + '\n')
    return list(candidates)

