import hashlib
import json
from flask import request, Response

def get_cache_key(request):
    headers = {k: v for k, v in request.headers.items() if isinstance(v, str)}
    path = request.path
    cache_key = hashlib.md5(f'{json.dumps(headers)}{path}'.encode()).hexdigest()
    return cache_key

def get_response_from_cache(cache_file):
    try:
        with open(cache_file, 'r') as f:
            response_data = json.load(f)
            return Response(response_data['response'], mimetype='application/json')
    except FileNotFoundError:
        return None

def get_response(request):
    cache_key = get_cache_key(request)
    cache_file = f'cache/{cache_key}.json'

    if request.method == 'GET':
        response = get_response_from_cache(cache_file)
        if response is not None:
            return response

    # If it's not a GET request or the cache file doesn't exist, create a new one
    response_data = {'response': ''}  # assuming you want to store arbitrary data in the cache
    with open(cache_file, 'w') as f:
        json.dump(response_data, f)

    return Response('')

