import random
import sys

def random_sample(population, n=None, replace=False):
    if not population:
        return []
    if len(population) > sys.maxsize:
        max_samples = int(sys.maxsize ** 0.5)
    else:
        max_samples = int((sys.maxsize / 2) ** 0.5)
    if n is None:
        n = min(len(population), max_samples)
    elif n < 0:
        raise ValueError("Number of samples cannot be negative.")
    random.shuffle(population)
    return population[:n] if not replace else [random.choice(population) for _ in range(n)]

def parse_string(s):
    parts = s.split()
    if len(parts) != 5:
        raise ValueError("Invalid input string")
    obj = {}
    try:
        obj['type'] = eval(parts[0])
        obj['intensity'] = int(eval(parts[1]))
        obj['size'] = int(eval(parts[2]))
        obj['generation'] = int(eval(parts[3]))
        obj['choice'] = int(eval(parts[4]))
    except (ValueError, SyntaxError):
        raise ValueError("Invalid input string")
    return obj

