import requests

def download_file_in_parts(file_url, max_part_size):
    response = requests.get(file_url)
    file_size = len(response.content)

    if max_part_size < 1024: 
        raise ValueError("Part size too small. Must be at least 1KB")

    num_parts = -(-file_size // max_part_size)  # Ceiling division
    if num_parts > 1000:
        raise ValueError("Too many parts. Maximum limit exceeded")

    part_sizes = [max_part_size] * (num_parts - 1) + [file_size % max_part_size]

    for i, part_size in enumerate(part_sizes):
        start = i * max_part_size
        end = start + part_size
        yield response.content[start:end]

    for chunk in requests.get(file_url).iter_content(max_part_size):
        for i, part_size in enumerate(part_sizes):
            if len(chunk) <= part_size:
                yield chunk[:part_size]
                break
            else:
                yield chunk[:part_size]
                chunk = chunk[part_size:]

