import itertools

def batched_cycles(data, batch_size, cycles):
    for _ in range(cycles):
        batches = [list(x) for x in zip(*[data[i::batch_size] for i in range(batch_size)]))
        if not all(len(b) == len(batches[0]) for b in batches):
            raise ValueError("Batches have different lengths")
        yield tuple(map(list, itertools.zip_longest(*batches)))
    raise StopIteration

