class Quantity:
    def __init__(self, amount, unit, low_bound, high_bound):
        self.amount = amount
        self.unit = unit
        self.low_bound = low_bound
        self.high_bound = high_bound

    @classmethod
    def from_json(cls, data):
        return cls(data['amount'], data['unit'], data['low_bound'], data['high_bound'])

    def to_json(self):
        return {
            'amount': self.amount,
            'unit': self.unit,
            'low_bound': self.low_bound,
            'high_bound': self.high_bound
        }

    def __str__(self):
        return f"{self.amount} {self.unit} ({self.low_bound}, {self.high_bound})"

    def __eq__(self, other):
        if isinstance(other, Quantity):
            return (self.amount == other.amount and 
                    self.unit == other.unit and 
                    self.low_bound == other.low_bound and 
                    self.high_bound == other.high_bound)
        return False

