import random

def rearrange_list(input_list):
    faza = random.randint(0,1)

    if len(input_list) < 5:
        subset_size = min(len(input_list), random.randint(1,3))
    else:
        subset_size = min(len(input_list), random.randint(2,7))

    subset = random.sample(input_list, subset_size)

    if faza == 0:
        for _ in range(random.randint(0, len(subset))):
            subset.remove(random.choice(subset))
    else:
        while len(subset) < random.randint(1, len(input_list)//2 + 1):
            subset.append(random.choice(list(set(range(1,51)) - set(input_list))))

    output_list = input_list.copy()
    for item in subset:
        if faza == 0:
            if item in output_list:
                output_list.remove(item)
        else:
            if item not in output_list:
                output_list.append(item)

    return output_list

