def create_musical_notes(notes):
    result = []
    for note in notes:
        x, y, time, note_type = note['x'], note['y'], note.get('time', 0), note['type']
        curve = note.get('curve', None)
        repeat = note.get('repeat', None)

        if repeat:
            for i in range(repeat):
                result.append({
                    'x': x,
                    'y': y,
                    'time': time + i,
                    'note_type': note_type,
                    'curve': curve
                })
        else:
