import random
import string
def generate_random_string(prefix, maxlen, domain):
    if prefix == 'mail':
        random_str = ''.join(random.choice(string.ascii_lowercase + '_') for _ in range(maxlen - len(domain) - 1)) + domain
    elif prefix == 'string' or prefix not in ['mail', 'string']:
        random_str = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(maxlen))
    else:
        raise ValueError("Invalid prefix, should be 'mail' or 'string'")
    return random_str

