def process_file(file_name):
    try:
        with open(file_name, 'r') as file:
            lines = sorted(file.readlines())
            for line in lines:
                if line.strip():
                    break
            sequence_number = int(line.split()[-1].strip('[]'))
            return sequence_number
    except FileNotFoundError:
        print(f"Error: The file '{file_name}' was not found.")
        return None
    except IndexError:
        print(f"Error: The last line in the file '{file_name}' is empty or does not contain a sequence number.")
        return None
    except ValueError:
        print(f"Error: The last line in the file '{file_name}' contains an invalid sequence number.")
        return None

