import gzip
from io import StringIO

def gff3_to_gtf(gff3_file, dialect):
    if gff3_file.endswith('.gz'):
        with gzip.open(gff3_file, 'rt') as f:
            file_contents = f.read()
    else:
        with open(gff3_file) as f:
            file_contents = f.read()

    lines = file_contents.splitlines()

    output_lines = []
    for line in lines:
        if line.startswith('#'):
            output_lines.append(line)
        elif line:
            fields = line.split('\t')
            output_line = [fields[0], 'GTF', dialect]
            for i, field in enumerate(fields):
                if i == 3 or i == 8:  # seqid and frame
                    continue
                elif i > 2:
                    output_line.append(str(i-1) + '. ' + field)
            output_lines.append('\t'.join(output_line))

    return '\n'.join(output_lines)

