class Quantity:
    def __init__(self, data):
        self.amount = data['amount']
        self.unit = data['unit']
        self.lowerBound = 0
        if 'lowerBound' in data:
            self.lowerBound = data['lowerBound']
        self.upperBound = data['upperBound']

    @classmethod
    def fromWikibase(cls, data):
        return cls({
            'amount': data['amount'],
            'unit': data.get('unit', ''),
            'upperBound': data.get('upperBound', 0)
        })

    def __str__(self):
        return '{"amount": {}, "unit": "{}", "upperBound": {}}'.format(self.amount, self.unit, self.upperBound)

    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return False
        return (self.amount == other.amount and 
                self.unit == other.unit and 
                self.lowerBound == other.lowerBound and 
                self.upperBound == other.upperBound)
