import os
import time
import signal
import ctypes

def terminate_process(pid):
    if not os.path.exists('/proc/%s' % pid):
        return -1

    initial_sleep = 0.5
    max_sleep = 10
    factor = 2

    while True:
        try:
            if os.name == 'posix':
                os.kill(int(pid), signal.SIGTERM)
            elif os.name == 'nt':
                kernel32 = ctypes.windll.kernel32
                process_handle = kernel32.OpenProcess(1, False, int(pid))
                kernel32.TerminateProcess(process_handle, 0)
                kernel32.CloseHandle(process_handle)
            return 0
        except:
            if os.path.exists('/proc/%s' % pid):
                time.sleep(initial_sleep)
                initial_sleep *= factor
                if initial_sleep > max_sleep:
                    break
    return -1
