def crud_operation(db_name, table_name, condition=None):
    conn = None
    try:
        conn = sqlite3.connect(db_name)
        c = conn.cursor()

        if not condition:
            operation = input("Enter the operation (C/R/U/D): ")

            if operation.upper() == "C":
                data = input("Enter the data to be inserted: ").split(',')
                sql = f"INSERT INTO {table_name} VALUES ({', '.join(['?'] * len(data))})"
                c.execute(sql, tuple(data))
                conn.commit()
                print(f"{operation.capitalize()}d successfully!")

            elif operation.upper() == "R":
                if condition:
                    sql = f"SELECT * FROM {table_name} WHERE {condition}"
                else:
                    sql = f"SELECT * FROM {table_name}"
                c.execute(sql)
                rows = c.fetchall()
                for row in rows:
                    print(row)

            elif operation.upper() == "U":
                if condition:
                    data = input("Enter the updated data: ").split(',')
                    sql = f"UPDATE {table_name} SET {', '.join([f'{col} = ?' for col in table_name.split('_')[1:]])} WHERE {condition}"
                    c.execute(sql, tuple(data + [condition]))
                else:
                    print("No condition provided. Cannot update.")

            elif operation.upper() == "D":
                if condition:
                    sql = f"DELETE FROM {table_name} WHERE {condition}"
                else:
                    print("No condition provided. Cannot delete.")

                c.execute(sql)
                conn.commit()
                print(f"{operation.capitalize()}d successfully!")
        else:
            if condition.startswith('WHERE'):
                operation = condition[5:]
            data = input(f"Enter the {operation} data: ").split(',')
            sql = f"UPDATE {table_name} SET {', '.join([f'{col} = ?' for col in table_name.split('_')[1:]])} WHERE {condition}"
            c.execute(sql, tuple(data + [condition[5:]]))
            conn.commit()
            print(f"{operation.capitalize()}d successfully!")

    except Error as e:
        print(e)

    finally:
        if conn:
            conn.close()

