import re

def parse_token(token):
    if token[0] == '_':
        return f"lambda _n: {token}"
    elif token in {'+','-','*','/'}:
        return f"_n {token} _n"
    elif token in {'**', 'and', 'or', 'not', 'in', '=='}:
        return f"{token}"
    else:
        return f"int({token})"

def compile_template(template):
    tokens = re.split(r'(\W)', template)
    code = ''
    for token in tokens:
        if token:
            code += parse_token(token) + '\n'
    return 'lambda _n: ' + code[:-1] + ' _n'

compiled_template = compile_template('''
(1*_n+2) * (3-4/_n)
''')

