import time
import shelve
from functools import wraps

def call_after_delay(callback):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            time.sleep(3)
            callback(sum(result.values()))
            return result
        return wrapper
    return decorator

@call_after_delay
def set_value(filename, key, value):
    store = shelve.open(filename)
    if key in store:
        store[key] = value
    else:
        store[key] = value
    store.close()

