import sqlite3
from collections import defaultdict

def get_row_counts(table_names):
    conn = sqlite3.connect(':memory:')
    cursor = conn.cursor()

    schema = set()

    for table_name in table_names:
        try:
            cursor.execute(f"PRAGMA table_info({table_name})")
            row = cursor.fetchone()
            while row:
                schema.add(row[1])
                row = cursor.fetchone()
        except sqlite3.Error as e:
            raise Exception(f"Error getting schema for {table_name}: {e}")

    if len(schema) != 0 and len(set(schema)) != 1:
        raise Exception("Tables have different schemas")

    row_counts = defaultdict(int)

    for table_name in table_names:
        try:
            cursor.execute(f"SELECT COUNT(*) FROM {table_name}")
            row_count, = cursor.fetchone()
            if row_count == 0:
                raise Exception(f"Table {table_name} has no rows")
            row_counts[table_name] = row_count
        except sqlite3.Error as e:
            raise Exception(f"Error getting row count for {table_name}: {e}")

    conn.close()
    return dict(row_counts)

