def adjust_volume(direction):
    mixer = alsaaudio.Mixer('PCM')
    if direction == 'up':
        mixer.setvolume(min(100, mixer.getvolume() + 10))
    elif direction == 'down':
        mixer.setvolume(max(0, mixer.getvolume() - 10))
