def extract_info(filename):
    try:
        with open(filename, 'r') as file:
            lines = file.readlines()
    except FileNotFoundError:
        print("File not found")
        return []
    except IOError:
        print("Error reading file")
        return []

    groups = []
    current_group = []
    in_group = False

    for line in lines:
        if line.startswith('#'):
            continue
        if line.strip() == '':
            continue
        if line.startswith('---') and not in_group:
            if current_group:
                groups.append(current_group)
            in_group = True
            current_group = []
        elif in_group:
            current_group.append(line.strip().split(','))
    if current_group:
        groups.append(current_group)

    return groups

