import os
from nltk.stem import PorterStemmer
from nltk.tokenize import word_tokenize
from bs4 import BeautifulSoup
from shelve import open

def startIndexer():
    global shelves
    shelves = {"invertedIndex": {}, "forwardIndex": {}, "idToUrl": {}}

def finishIndexer():
    for shelf in list(shelves.keys()):
        shelves[shelf].close()
    del shelves

def build_index(directory_path):
    porter_stemmer = PorterStemmer()

    for filename in os.listdir(directory_path):
        url = directory_path + "/" + filename
        with open(url, 'r') as file:
            text = file.read()
            soup = BeautifulSoup(text, 'html.parser')
            text = str(soup.get_text())
            doc_id = filename.split('.')[0]
            shelves["forwardIndex"][doc_id] = word_tokenize(text.lower())
            for token in word_tokenize(text.lower()):
                stemmed_token = porter_stemmer.stem(token)
                if stemmed_token not in shelves["invertedIndex"]:
                    shelves["invertedIndex"][stemmed_token] = [doc_id]
                elif doc_id not in shelves["invertedIndex"][stemmed_token]:
                    shelves["invertedIndex"][stemmed_token].append(doc_id)
            shelves["idToUrl"][doc_id] = url

shelves = {}

