import hashlib
import os
import secrets

class UserAccount:
    def __init__(self, username):
        self.username = username
        self.password_hash = None
        self.phone_number = None
        self.emergency_contact = None

    def set_password(self, password):
        salt = os.urandom(16)
        hashed_password = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        self.password_hash = f"{hashed_password}:{salt.hex()}"

    def verify_password(self, password):
        if not self.password_hash:
            return False
        salt, hashed_password = self.password_hash.split(":")
        computed_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), 100000).hex()
        return computed_hash == hashed_password

    def generate_secret_key(self):
        return secrets.token_urlsafe(16)
