import subprocess
import re

def get_server_info():
    try:
        output = subprocess.check_output(['command_to_execute'])
        pattern = r'(?P<value>\d+)'
        match = re.search(pattern, output.decode('utf-8'))
        if match:
            value = match.group('value')
            if re.match(r'^\d+$', value):
                return int(value)
            else:
                raise ValueError(f"Invalid format: {value}")
        else:
            raise ValueError("Failed to extract the value")
    except subprocess.CalledProcessError as e:
        print(f"Command execution failed with error code {e.returncode}: {e.output.decode('utf-8')}")
    except Exception as e:
        print(f"An error occurred: {str(e)}")

