import subprocess
from collections import defaultdict

def analyze_commit_history(repo_path):
    commit_history = {}
    parents_map = defaultdict(dict)

    for line in subprocess.check_output(['hg', 'log', '--template', '{node|short}\n{parents}\n', '-r', '.']).decode().splitlines():
        if not line:
            continue
        node = line.strip()
        parent_lines = line.split('\n')[1].strip().split(',')
        for parent in parent_lines:
            if parent:
                parents_map[node][parent.strip()] = None

    for node, parents in parents_map.items():
        commit_history[node] = len(parents) + 1
        for parent, _ in parents.items():
            if parent not in commit_history:
                commit_history[parent] = len([p for p in parents_map[parent].keys()]) + 1

    return {k: v for k, v in sorted(commit_history.items())}
