import hashlib
import time

def request_hash(request, delta=False):
    params = {}
    for key, value in request.items():
        if not key.startswith('_'):
            params[key] = str(value)
    sorted_params = sorted(params.items())
    param_str = ','.join([f"{key}={value}" for key, value in sorted_params])
    hash_string = f"{param_str},{time.time() if delta else 0}"
    return hashlib.md5(hash_string.encode()).hexdigest(), time.time() if delta else None

