class InputReader:
    def __init__(self, filename=None, bucket_name=None, fail_on_missing=False):
        self.filename = filename
        self.bucket_name = bucket_name
        self.fail_on_missing = fail_on_missing
        self.content = None

    def load(self, json_data):
        if 'filename' in json_data:
            self.filename = json_data['filename']
        if 'bucket_name' in json_data:
            self.bucket_name = json_data['bucket_name']
        if 'fail_on_missing' in json_data:
            self.fail_on_missing = json_data['fail_on_missing']

    def to_json(self):
        return {'filename': self.filename, 
                'bucket_name': self.bucket_name, 
                'fail_on_missing': self.fail_on_missing}

    def __iter__(self):
        if self.filename and os.path.exists(self.filename):
            with open(self.filename, 'r') as f:
                for line in f:
                    yield line.strip()
        elif self.bucket_name:
            # implementation for bucket reader
            pass
        else:
            if self.fail_on_missing:
                raise ValueError('Input file or bucket is missing')
            else:
                return iter([])
