import pickle
import os

def load_and_save_state(file_path):
    try:
        if os.path.exists(file_path):
            with open(file_path, 'rb') as f:
                state_data = pickle.load(f)
        else:
            state_data = {}  # start with a clean slate
    except (FileNotFoundError, pickle.UnpicklingError) as e:
        print(f"Error loading state data: {e}")
        state_data = {}  # start with a clean slate

    yield state_data

    try:
        with open(file_path, 'wb') as f:
            pickle.dump(state_data, f)
    except (FileNotFoundError, pickle.PicklingError) as e:
        print(f"Error saving state data: {e}")

def convert_to_kib(size_gb):
    KiB = 1024
    size_KiB = size_gb * 1024 ** 3
    format_string = "{:.2f} KiB"
    return format_string.format(size_KiB / KiB)

