@app.route('/payment', methods=['POST'])
def process_payment():
    client_id = request.form['client_id']
    client_secret = request.form['client_secret']

    # Get access token
    auth_url = 'https://api.paypal.com/v1/oauth2/token'
    headers = {'Content-Type': 'application/x-www-form-urlencoded'}
    data = {'grant_type': 'client_credentials'}
    response = requests.post(auth_url, headers=headers, data=data, auth=(client_id, client_secret))
    access_token = response.json()['access_token']

    # Create payment
    payment_url = 'https://api.paypal.com/v1/payments/payouts'
    headers = {'Authorization': f'Bearer {access_token}'}
    data = {'intent': 'authorize', 'payer': {'payment_method_types': ['PAYPAL']}}
    response = requests.post(payment_url, headers=headers, json=data)
    payment_id = response.json()['id']

    # Redirect to PayPal login
    return redirect(f'https://www.paypal.com/cgi-binwebscr?cmd=_express-checkout&token=0U12345678')

@app.route('/payment-return', methods=['GET'])
def confirm_payment():
    payment_id = request.args.get('paymentId')

    # Confirm payment ID with PayPal API
    payment_url = f'https://api.paypal.com/v1/payments/payouts/{payment_id}'
    headers = {'Authorization': f'Bearer {access_token}'}
    response = requests.get(payment_url, headers=headers)
    if response.status_code == 200:
        return 'Payment successful!'
    else:
        return 'Error processing payment'

if __name__ == '__main__':
    app.run(debug=True)

