from django.contrib.auth.models import User
from django.template.loader import get_template
from django.template import Context, Template
from django.core.exceptions import ValidationError
from django.conf import settings

def send_password_reset_email(request):
    user = request.user
    if not user.is_authenticated:
        raise ValueError('User must be authenticated')

    email_address = request.POST.get('email')
    if not email_address or not validate_email(email_address):
        raise ValueError('Invalid Email Address')

    try:
        user = User.objects.get(email=email_address)
    except User.DoesNotExist:
        raise ValueError('No such user with this email')

    token_generator = default_token_generator
    request.session['password_reset_token'] = token_generator.make_token(user)

    send_email.delay(user.email, 'Password Reset', 'auth/password_reset_email.html')
    return render(request, 'auth/password_reset_form.html', {})


def password_reset_form(request):
    if request.method == 'POST':
        form = PasswordResetForm(request.POST)
        if form.is_valid():
            user = User.objects.get(email=form.cleaned_data['email'])
            token_generator = default_token_generator
            request.session['password_reset_token'] = token_generator.make_token(user)
            send_email.delay(user.email, 'Password Reset', 'auth/password_reset_email.html')
            return render(request, 'auth/password_reset_done.html', {})
    else:
        form = PasswordResetForm()

    return render(request, 'auth/password_reset_form.html', {'form': form})


def password_reset_done(request):
    if not request.session.get('password_reset_token'):
        raise ValueError('Password Reset Token Not Found')

    user = User.objects.get(email=request.user.email)
    token_generator = default_token_generator
    try:
        token = token_generator.validate(token=request.session.pop('password_reset_token'))
        user = User.objects.get(email=token.user.username)
        return render(request, 'auth/password_reset_done.html', {})
    except (ValidationError, User.DoesNotExist):
        raise ValueError('Invalid Password Reset Token')

