def extract_metadata(file_path, metadata_dict_name):
    with open(file_path, 'r') as file:
        lines = file.readlines()

    for line in lines:
        if line.strip().startswith('Version:'):
            version = line.split()[1]
            break

    if not version:
        return {}

    globals()[metadata_dict_name] = {'version': version}
    return eval(metadata_dict_name)

