import subprocess
import re

def check_job_status(cmd):
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, err = proc.communicate()

    if proc.returncode == 0:
        if "completed" in str(out.decode()):
            return 0
        elif "failed" in str(out.decode()):
            return 1
        else:
            return None
    elif proc.returncode > 0:
        if re.search(r"failed", str(err.decode()), re.IGNORECASE):
            return 1
        else:
            return None

