CREATE OR REPLACE FUNCTION create_and_drop_triggers(
    p_table_name varchar,
    p_trigger_name_prefix varchar
) RETURNS void AS $$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT * FROM pg_get_triggers(p_table_name)
    LOOP
        IF r.trigger_name LIKE p_trigger_name_prefix || '%' THEN
            EXECUTE 'DROP TRIGGER ' || r.trigger_name || ' ON ' || p_table_name;
        END IF;
    END LOOP;

    FOR r IN SELECT * FROM pg_get_triggers(p_table_name)
    LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE trigger_name = r.trigger_name) THEN
            PERFORM 'CREATE TRIGGER ' || r.trigger_name || ' BEFORE/INSERT UPDATE ON ' || p_table_name || ' FOR EACH ROW EXECUTE PROCEDURE ' || r.function_schema || '.' || r.function_name || '(''row''::' || r.table_name || ');';
        END IF;
    END LOOP;

    IF NOT EXISTS (SELECT 1 FROM pg_language WHERE lanname = 'plpgsql') THEN
        PERFORM 'CREATE LANGUAGE plpgsql;';
    END IF;
END;$$ LANGUAGE plpgsql;

