            return self.filter(location__icontains=location)
        return self.all()

    def render_event_page(self, request):
        if 'password' in request.GET and request.GET['password'] == 'secret':
            template_name = 'event/event.html'
        else:
            template_name = 'event/access_denied.html'

        return {
            'template': template_name,
            'event_title': self.title,
        }

    def __str__(self):
        return f"{self.title} on {self.date} at {self.time} in {self.location}"
