import hashlib

def get_md5(file_path_or_string):
    if isinstance(file_path_or_string, str):
        md5 = hashlib.md5()
        md5.update(file_path_or_string.encode())
    else:
        with open(file_path_or_string, 'rb') as f:
            md5 = hashlib.md5()
            for chunk in iter(lambda: f.read(4096), b''):
                md5.update(chunk)
    return md5.hexdigest()

