import os
import subprocess

def encrypt_zip(file_path, key1, key2, output_dir):
    # Create a new directory for the encrypted file
    artefacts_dir = 'artefacts'
    if not os.path.exists(artefacts_dir):
        os.makedirs(artefacts_dir)

    # Set the encryption command
    encrypt_cmd = f'openssl enc -aes-256-cbc -in {file_path} -out {output_dir}/encrypted.zip -k {key1} -P {key2}'

    try:
        # Execute the encryption command
        subprocess.run(encrypt_cmd, shell=True)

        # Check if the encryption was successful
        if os.path.exists(f'{artefacts_dir}/encrypted.zip'):
            print('Encryption successful')
        else:
            print('Error: Encryption failed')
    except Exception as e:
        print(f'Error: {str(e)}')

