import sqlite3
from typing import Dict

def analyze_indexes(db_file: str, table_name: str) -> Dict:
    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()

    cursor.execute("PRAGMA index_list(?);", (table_name,))
    indexes = {item[1]: [] for item in cursor.fetchall()}

    for index_name in indexes:
        cursor.execute("PRAGMA index_info(?);", (index_name,))
        columns = [row[1] for row in cursor.fetchall()]

        if index_name.startswith('u_'):
            is_unique = True
        else:
            is_unique = False

        indexes[index_name] = {'columns': columns, 'is_unique': is_unique}

    conn.close()

    return indexes

