import importlib.util
from pathlib import Path

def load_extension(file_path):
    spec = importlib.util.spec_from_file_location('extension', file_path)
    if spec:
        module = importlib.util.module_from_spec(spec)
        try:
            spec.loader.exec_module(module)
            return module.Extend
        except Exception as e:
            print(f"Failed to load extension from {file_path}: {e}")
            return None
    else:
        print(f"Could not find specification for file {file_path}.")
        return None

def deserialize_json(obj_str, decode_keys=False):
    import json
    if not decode_keys:
        return json.loads(obj_str)
    else:
        def obj_hook(obj):
            if isinstance(obj, str) and '.' in obj:
                return eval(obj)
            return obj
        return json.loads(obj_str, object_hook=obj_hook)

