def combine_hashes(input_list, hash_function='md5', unit=None):
    if isinstance(input_list, list):
        if not input_list:
            raise ValueError("Input list is empty")
        hash_object = hashlib.new(hash_function)
        for string in input_list:
            if not isinstance(string, str):
                raise TypeError("All strings must be in the same encoding")
            hash_object.update(string.encode('utf-8'))
        return '{:s}{}{}'.format(hash_object.hexdigest(), ' ' + unit if unit else '', '\n' if unit else '')
    else:
        raise ValueError("Input is not a list")

