import os
import hashlib
import threading

class ProcessLock:
    def __init__(self):
        self.locks = {}

    def run_process(self, command_line):
        process_name = ' '.join(map(str, command_line))
        hash_value = hashlib.md5(process_name.encode()).hexdigest()
        lock_name = f'{hash_value}_{os.getpid()}'

        if lock_name in self.locks:
            return self.locks[lock_name]

        self.locks[lock_name] = threading.Lock()
        with self.locks[lock_name]:
            file_name = 'process_id.txt'
            try:
                with open(file_name, 'r') as f:
                    existing_pid = int(f.read())
                if os.getpid() == existing_pid:
                    return (os.getpid(), command_line, file_name)
                else:
                    os.remove(file_name)
                    raise Exception("Process already running")
            except FileNotFoundError:
                with open(file_name, 'w') as f:
                    f.write(str(os.getpid()))
                return (os.getpid(), command_line, file_name)

