def hash_function(attributes):
    hashes = {}
    def attr_hash(attr_tuple):
        key = repr(attr_tuple)
        if key in hashes:
            return hashes[key]
        else:
            string = ''.join(repr(a) for a in attr_tuple)
            result = hashlib.sha1(string.encode()).hexdigest()
            hashes[key] = result
            return result
    return attr_hash

