use std::boxed::Box;
use std::marker::PhantomData;
use rtio::{EventLoop, EventLoopHandle};
use uv;

struct UvHandle {
    handle: *mut uv::uv_handle_t,
    _phantom: PhantomData<EventLoop>,
}

impl UvHandle {
    fn as_mut(&self) -> *mut uv::uv_handle_t { self.handle }
    fn loop_as_mut(&self) -> &mut EventLoop { unsafe { &mut *(self._phantom.as_ptr() as *mut EventLoop) } }
}

fn create_event_loop() -> Box<dyn UvHandle + Send> {
    let mut loop_ = EventLoop::new().unwrap();
