enum IpVersion {
    V4,
    V6,
}

fn get_ip_version(sockaddr: *const ::std::os::raw::sockaddr) -> IpVersion {
    if ::std::ptr::eq(sockaddr, std::ptr::null()) {
        panic!("Null pointer");
    }

    let sa = if sockaddr.is_null() {
        return IpVersion::V4; // assume v4 for null pointer
    } else if unsafe { (*sockaddr).sa_family == ::std::os::raw::AF_INET } {
        IpVersion::V4
    } else if unsafe { (*sockaddr).sa_family == ::std::os::raw::AF_INET6 } {
        IpVersion::V6
    } else {
        panic!("Unknown family");
    };

    sa
}
