enum SendError<T> {
    Closed,
    Value(T),
}

async fn oneshot_send<T>(value: T) -> Result<(), SendError<T>> {
    let (tx, rx) = tokio::sync::mpsc::channel(1);
    tx.send(value).await.unwrap_or_else(|_| Err(SendError::Value(value)));
    drop(rx);
    Ok(())
}

