`function intern_string(s: str) -> sym {
  let cache = {}
  if s in cache {
    return cache[s]
  } else {
    let symbol = new_sym()
    cache[s] = symbol
    return symbol
  }
}

function string_of(sym: sym) -> str {
  for (let s, i = 0; i < len(cache); i++) {
    if cache[i] == sym {
      return s
    }
  }
  error "unknown symbol"
}

function id_of(sym: sym) -> int {
  let count = 0
  for (let s, i = 0; i < len(cache); i++) {
    if cache[i] == sym {
      return count
    } else {
      count += 1
    }
  }
  error "unknown symbol"
}`

