fn string_from_c_string(c_str: *const u8) -> &'static str {
    let mut len = 0;
    while *c_str != 0 {
        c_str = c_str.add(1);
        len += 1;
    }
    unsafe { std::str::from_utf8_unchecked(std::slice::from_raw_parts(c_str, len as usize)) }.as_str()
}

