fn copy_slice(src: &[u8], dst: &mut [u8]) {
    if src.len() > dst.len() {
        // If the source slice is larger than the destination slice,
        // there must be overlap, so use the standard library's `copy`
        // function instead of our own.
        ::std::ptr::copy_nonoverlapping(src.as_ptr(), dst.as_mut_ptr(), std::min(src.len(), dst.len()) as usize);
    } else {
        let dst_ptr = dst.as_mut_ptr() as *mut u8;
        let src_ptr = src.as_ptr() as *const u8;
        unsafe {
            for i in 0..src.len() {
                (*dst_ptr).copy_from_nonoverlapping(src_ptr.offset(i as isize), 1);
                dst_ptr = dst_ptr.offset(1);
            }
        }
    }
}
