#include <memory>
#include <string>

std::string checkMemoryLayout(void* ptr) {
    using namespace std::mem;

    size_t structSize = size_of(*static_cast<void**>(&ptr));
    size_t align = align_of(*static_cast<void**>(&ptr));

    void* field1Ptr = static_cast<void*>(ptr);
    void* field2Ptr = static_cast<void*>(ptr) + offset_of(*static_cast<void**>(&ptr), offsetof(MyStruct, x));
    void* field3Ptr = static_cast<void*>(ptr) + offset_of(*static_cast<void**>(&ptr), offsetof(MyStruct, y));

    return std::to_string(structSize) +
           " bytes\nAlignment: " + std::to_string(align) +
           "\nField1 at " + std::to_string((size_t)field1Ptr - (size_t)ptr) +
           " bytes from start of struct.\nField2 at " + std::to_string((size_t)field2Ptr - (size_t)ptr) +
           " bytes from start of struct." +
           "\nField3 at " + std::to_string((size_t)field3Ptr - (size_t)ptr) +
           " bytes from start of struct.";
}
