impl<T> IoResult<T> {
    fn run_with_io(&self, f: impl FnOnce(IoResult<T>) -> T) -> Result<T, IoError>
    where
        T: Send + 'static,
    {
        let io_res = self.clone();
        match &io_res {
            Ok(_) => f(io_res),
            Err(err) => {
                let mut task = IoTask::new(IoFactory::get(), Some(self.clone()));
                let _ = task.detach();
                let res: T = unsafe { std::mem::transmute_copy(&task as *const _) };
                Err(err).map(|e| e.combine(res))
            }
        }
    }
}
