struct ServerId {
    id: u32,
}

type ServerHandle = u32;

pub fn start_server(server_id: &ServerId, ip_address: String, port: String) -> ServerHandle {
    // Set the RUST_LOG environment variable
    std::env::set_var("RUST_LOG", "sccache=trace");
    env_logger::init_from_env((LevelFilter::Debug,));

    let server_pid = Command::new("std")
        .arg("net")
        .arg("fork")
        .arg("-b")
        .arg("-c")
        .arg(&format!("http -l {}/{} &", ip_address, port))
        .spawn()
        .expect("Failed to fork the new process")
        .wait()
        .unwrap();
    let pid = id();

    ServerHandle(pid)
}
