def parse_args(cmd_line):
    args = []
    arg = ''
    in_quotes = False
    for char in cmd_line:
        if in_quotes:
            if char == '"':
                in_quotes = False
            else:
                arg += char
        elif char in [' ', '\t', '\n']:
            if arg:
                args.append(arg.strip())
                arg = ''
        else:
            if not arg:
                arg = char
            elif char == '"':
                in_quotes = True
            else:
                arg += char
    if arg:
        args.append(arg.strip())
    return args

