    thread::sleep(std::time::Duration::from_millis(100));
    let mut chars = chars.lock().unwrap();
    if let Err(e) = File::create("output.txt").and_then(|mut f| {
        for c in &chars.chars().collect::<Vec<char>>()[..] {
            writeln!(f, "{}", c)
        }
        Ok(())
    }) {
        error::Error::new(io::Error::new(io::ErrorKind::Other, e)).into();
    };
}
