        Event::Input(input) => match input {
            glutin::input::KeyboardInput {
                state,
                virtual_keycode: Some(glutin::VirtualKeyCode::Char('1')),
                ..
            } if state == glutin::ElementState::Pressed => menu_selected = 0,
            glutin::input::KeyboardInput {
                state,
                virtual_keycode: Some(glutin::VirtualKeyCode::Char('2')),
                ..
            } if state == glutin::ElementState::Pressed => menu_selected = 1,
            glutin::input::KeyboardInput {
                state,
                virtual_keycode: Some(glutin::VirtualKeyCode::Char('3')),
