        println!("Usage: {} <ip_address>:<port> <num_streams>", &args[0]);
        return;
    }
    let (ip, port) = args[1].split_once(":").unwrap();
    let ip_addr = Ipv4Addr::new(IpAddr::V4, ip);
    let port: u16 = port.parse().unwrap();

    let socket = UdpSocket::bind(&ip_addr, port).unwrap();

    let num_streams: usize = args[2].parse().unwrap();

    for _ in 0..num_streams {
        let dest_ip = Ipv4Addr::new(IpAddr::V4, "127.0.0.1");
        let dest_port = 12345;
        let dest_addr = SocketAddr::from((dest_ip, dest_port));

        let mut buffer: [u8; 10] = [0; 10];
        let message = "Hello from UDP!";
        let len = message.len();
        buffer[..len].copy_from_slice(message.as_bytes());

        socket.send_to(&buffer[..len], &dest_addr).unwrap();
    }
}
