struct Request {
    message_args: Vec<String>,
}

struct Response {
    mid: u32,
    err_code: i32,
    result: String,
}

fn handle_request(req: Request) -> Response {
    let response = Response {
        mid: 0, // assume a default message ID
        err_code: 0, // assume a default error code
        result: req.message_args.iter().next().unwrap().clone(),
    };
    process::exit(0); // shut down the program
    response
}
