use cargo::{Cargo, Package};

pub fn update_toml<P>(path: P, verbose: bool, quiet: bool, color: bool, frozen: bool, locked: bool)
where
    P: AsRef<std::path::Path>,
{
    let mut cargo = Cargo::new(path.as_ref());

    if verbose {
        cargo.verbose();
    } else if quiet {
        cargo.quiet();
    }

    if color {
        cargo.color(true);
    } else {
        cargo.color(false);
    }

    match (frozen, locked) {
        (true, true) => cargo.frozen_and_locked(),
        (false, false) => cargo.no_constraints(),
        (_, _) => cargo.locked(),
    };

    let manifest_path = "Cargo.toml";
    if let Some(manifest_path) = std::env::var("CARGO_MANIFEST_PATH").ok() {
        cargo.manifest_path(Some(&manifest_path));
    } else {
        cargo.manifest_path(None);
    }

    // Respect the project's dependencies, updating them if necessary
    match cargo.update() {
        Ok(_) => println!("Cargo.toml updated successfully"),
        Err(e) => eprintln!("Error updating Cargo.toml: {}", e),
    }
}
