use std::io::{Read, Write};
use std::net::TcpListener;
use std::sync::Arc;
use std::thread;
use flate2::{Compression, write::GzEncoder};
useflate2::{read::ZlibDecoder, write::GzBuilder};

fn main() {
    let listener = TcpListener::bind("0.0.0.0:8080").unwrap();
    println!("Listening on 0.0.0.0:8080");

    for stream in listener.incoming() {
        match stream {
            Ok(mut stream) => {
                thread::spawn(move || {
                    let pool = Arc::new(rayon::Scope::new());
                    let mut decoder = GzBuilder::writer(std::io::stdout()).filename("temp.gz").build();
                    let encoder = GzEncoder::new(&mut decoder, Compression::fast());

                    stream.set_read_timeout(None).unwrap();
                    stream.set_write_timeout(None).unwrap();

                    loop {
                        let mut buffer = [0; 1024];
                        match stream.read(&mut buffer) {
                            Ok(size) => {
                                if size > 0 {
                                    encoder.write_all(&buffer[..size]).unwrap();
                                }
                            },
                            Err(_) => break,
                        }
                    }

                    stream.flush().unwrap();
                });
            },
            Err(e) => println!("Error: {}", e),
        }
    }
}
