use std::sync::LogBuilder;
use std::sync::LogLevel;

fn init_logger() -> LogBuilder {
    let log_level = match env!("LOG_LEVEL").to_lowercase().as_str() {
        "debug" => LogLevel::Debug,
        "info" => LogLevel::Info,
        "warn" => LogLevel::Warn,
        "error" => LogLevel::Error,
        _ => LogLevel::Info,
    };

    LogBuilder::new()
        .set_level(log_level)
        .filter(|log_record| log_record.level() <= &log_level)
        .format_closures(|record| {
            format!("{} [{}] {}", record.message(), record.filename().unwrap_or(""),
                   record.line())
        })
}

