use std::sync::{mpsc, mpsc::channel};
use std::thread;
use std::time::Duration;

struct Snake {
    length: u32,
    width: u32,
}

fn simulate_snakes() -> (Vec<Snake>, mpsc::Receiver<String>) {
    let (tx, rx) = channel();
    let mut snakes = vec![Snake { length: 2, width: 10 }, Snake { length: 2, width: 10 }];
    let mut i = 0;

    loop {
        thread::sleep(Duration::from_secs(1));
        i += 1;
        snakes.push(Snake { length: (i as u32) % 3 + 1, width: (i as u32) * 2 });

        if let Err(_) = tx.send(format!("Snakes updated. Length: {}, Width: {}.", snakes[0].length, snakes[0].width)) {
            break;
        }
    }

    (snakes, rx)
}
