fn create_unique_directory(name: &str) -> String {
    let executable_dir = env::current_exe().unwrap();
    let mut root_dir = executable_dir.parent().unwrap().to_path_buf();

    if root_dir.file_name().map_or(false, |n| n.to_string() == "deps") {
        root_dir.pop();
    }

    let dir_name = format!("{}-{}", name, u128::new(std::time::SystemTime::now().duration().as_millis()).to_string());
    let dir_path = root_dir.join(dir_name);
    std::fs::create_dir(&dir_path).unwrap();
    dir_path.to_str().map_or(String::new(), |s| s.to_string())
}
