use serial;
use serial::SystemPort;

fn open_and_probe_port(port_name: &str, settings: &serial::SystemPortSettings) -> Result<serial::SystemPort, serial::Error> {
    let mut port = serial::SystemPort::new(port_name, settings)?;
    port.set_config(&settings)?;
    Ok(port)
}

fn probe_port(port: &mut serial::SystemPort) -> Result<(), serial::Error> {
    for pin in 0..port.get_max_pin() {
        match port.probe(pin)? {
            serial::PinState::Open => println!("Pin {} is open", pin),
            serial::PinState::ShortToVcc => println!("Pin {} is short to VCC", pin),
            serial::PinState::ShortToGnd => println!("Pin {} is short to GND", pin),
            serial::PinState::Isolated => println!("Pin {} is isolated", pin),
        }
    }
    Ok(())
}

fn main() {
    let port_name = "COM1";
    let settings = serial::SystemPortSettings {
        // configure here
    };
    match open_and_probe_port(port_name, &settings) {
        Ok(mut port) => {
            if let Err(err) = probe_port(&mut port) {
                println!("Error probing port: {}", err);
            }
        },
        Err(err) => println!("Error opening port: {}", err),
    };
}
