use hmac::{Hmac, Mac};
use sha1::Sha1;
use std::convert::TryInto;

fn verify_signature(payload: &[u8], signature: &[u8]) -> bool {
    let secret_key = [0u8; 20]; // Replace with your actual secret key
    let mac = Hmac::<Sha1, _>(secret_key.as_ref()).compute_payload(payload);
    let mut expected_signature: [u8; 20] = [0u8; 20];
    expected_signature.copy_from_slice(&mac);

    (0..20).all(|i| {
        let a = signature[i];
        let b = expected_signature[i];
        ((a as u8) ^ (b as u8)) == 0
    })
}
