use SHA1::{digest};
use hmac::{Hmac, Mac};
use hmac::mac::HMac;
use digest::{Digest};

fn decrypt_blob(encrypted_data: &str) -> Vec<u8> {
    let device_id = "your_device_id_here";
    let username = "your_username_here";

    // Convert strings to byte vectors
    let device_id_bytes = device_id.as_bytes();
    let username_bytes = username.as_bytes();

    // Generate the secret key using SHA-1 hash function
    let mut sha = digest::Sha1::new();
    sha.update(device_id_bytes);
    sha.update(username_bytes);
    let secret_key = sha.finalize();

    // Create an Hmac-SHA-1 object with the generated key
    let hmac = Hmac::<digest::Sha1, MacAsRef>::new(Void);
    hmac.update(secret_key.as_ref());
    hmac.update(b"your_initialization_vector_here");

    // Decrypt the encrypted blob using the HMAC object
    let decrypted_data = hmac.finalize();

    decrypted_data.into()
}
