use hmac::{Hmac, Mac};
use hashlib::sha1;
use serde_json::json;

fn process_request(req: &serde_json::Value, config: &serde_json::Value) -> serde_json::Value {
    let header_value = req.get("header_name").unwrap().as_str();

    if let Some(request_body) = req.get("body") {
        let key = config.get("secret_key").unwrap().as_str();
        let mut hmac = Hmac::new(sha1(), key.as_bytes());
        hmac.update(req["body"].as_str().unwrap().as_bytes());
        let computed_signature = hex::encode(hmac.finalize());

        if header_value != &computed_signature {
            json!({
                "status": 404,
                "message": "Request body is invalid"
            })
        } else {
            json!({
                "status": 200,
                "body": request_body.to_string()
            })
        }
    } else {
        json!({
            "status": 500,
            "message": "Invalid request"
        })
    }
}
