        .spawn()
        .expect("Failed to spawn rustfmt command");

    let status = child.wait().unwrap();

    if !status.success() {
        eprintln!("Error formatting the string: {}", child.stderr().as_str());
    } else {
        println!("Formatted string written to: {}", output_path);
        fs::read_dir(output_path).unwrap();
    }
}

