#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <json-c/json.h>

void handle_child(int child_stdin, int child_stdout) {
    json_object *obj = json_object_new_object();
    json_object_object_add(obj, "status", json_string("success"));
    char *msg = json_object_to_json_string(obj);
    write(child_stdout, msg, strlen(msg));

    json_object_free(obj);

    close(child_stdin);
    close(child_stdout);
}

int main() {
    pid_t child_pid;
    int child_stdin[2], child_stdout[2];

    if (pipe(child_stdin) < 0 || pipe(child_stdout) < 0) {
        perror("pipe");
        exit(1);
    }

    child_pid = fork();

    if (child_pid == -1) {
        perror("fork");
        exit(1);
    } else if (child_pid > 0) { // parent process
        close(child_stdin[0]);
        close(child_stdout[1]);

        int sock_fd = socket(AF_INET, SOCK_STREAM, 0);

        struct sockaddr_in serv_addr;
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(8080);
        inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);

        bind(sock_fd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
        listen(sock_fd, 3);

        struct sockaddr_in cli_addr;
        socklen_t clilen = sizeof(cli_addr);

        int client_fd = accept(sock_fd, (struct sockaddr *)&cli_addr, &clilen);

        close(child_stdin[1]);
        write(child_stdin[0], "start_service", strlen("start_service"));

        char buffer[256];
        read(child_stdout[0], buffer, 256);
        printf("%s\n", buffer);

        close(client_fd);
        close(sock_fd);
    } else { // child process
        close(child_stdin[1]);
        close(child_stdout[0]);

        dup2(child_stdin[0], STDIN_FILENO);
        dup2(child_stdout[1], STDOUT_FILENO);

        if (fork() == 0) {
            execl("/usr/bin/python", "python", "-m", "your_service.py", NULL);
        } else {
            exit(0);
        }
    }

    return 0;
}

