thread_local!(static UNIQUE_ID: io::Cursor = {
    let mut id: String = "".to_string();
    for (k, v) in env::vars() {
        if k.starts_with("RUST_TASK_ID") {
            id.push_str(&v);
        }
    }
    id
});

fn current_task_dir() -> PathBuf {
    let unique_id = UNIQUE_ID.borrow();
    let mut dir_path = std::env::current_exe().unwrap();
    while !dir_path.is_dir() && !dir_path.is_empty() {
        if dir_path.parent().is_some() {
            dir_path = dir_path.parent().unwrap().to_path_buf();
        } else {
            break;
        }
    }
    let mut task_dir_path = dir_path.clone();
    task_dir_path.push(unique_id);
    task_dir_path
}

