use std::path::{Path, PathBuf};
use std::process::Command;
use lazy_static;

lazy_static! {
    static ref ROOT_DIR: PathBuf = find_root_dir();
}

fn find_root_dir() -> PathBuf {
    let mut cwd = std::env::current_dir().unwrap();
    loop {
        if cwd.exists() && cwd.read_dir().is_ok() {
            let cargo_lock = Path::join(&cwd, "Cargo.lock");
            if cargo_lock.exists() {
                return cwd;
            }
        }
        match cwd.parent() {
            Some(parent) => cwd = parent,
            None => return cwd,
        }
    }
}

