use std::string::String;
use percent_encoding::{percent_encode, ALL_ACCEPTABLE};
use hmac::{Hmac, Mac};

fn generate_signature(method: &str, uri: &str, query: &str, consumer_secret: &str) -> String {
    let key = percent_encode(consumer_secret.as_bytes(), ALL_ACCEPTABLE).to_string();
    let signature_input = format!("{}&{}&{}", method, uri, query);
    let mut hmac = Hmac::new(|b| b.write(key.as_bytes()), |b| b.write(signature_input.as_bytes()));
    hmac.set_output_len(160); // HMAC-SHA1 output length is 160 bits
    let signature = base64::encode(&hmac.finalize().unwrap());
    format!("HMAC-SHA1-{}{}", method, percent_encode(&signature, ALL_ACCEPTABLE))
}
