use iron::prelude::*;
use iron::{Request, Response};
use std::path::Path;

fn start_server(address: &str) -> Iron<Mount> {
    let mut app = Iron::new();

    app.listen(Path::new(address), |req: Request| {
        match req.url_path().as_str() {
            "/" => Response::with_body("Hello from Iron!", "text/plain"),
            "/api" => {
                let response = Response::with_body("API endpoint", "text/plain");
                response
            }
            _ => Response::with_status_code(404).body("Not found").unwrap(),
        }
    });

    app.mount("/", Mount::new(StaticFiles::with_root(Path::new("public"))));
    app.mount("/api", Mount::new(api_handler()));

    app
}

fn api_handler() -> Box<Fn(Request) + 'static> {
    box |req: Request| {
        let response = Response::with_body(req.url_path().to_string(), "text/plain");
        response
    }
}
