    if let Ok(entries) = fs::read_dir(directory) {
        for entry in entries {
            let entry = entry.expect("Failed to read directory");
            let path = entry.path();
            if path.is_file() && path.extension().unwrap_or_default().to_string_lossy().into_owned() == "md" {
                let post = create_post(&path, config);
                if let Ok(_) = post.save_to(&Path::new(directory).join("site")) {
                    post_count += 1;
                }
            }
        }
    }
    post_count
