fn update_hosts_file(path: &Path, ip: &str, hostname: &str) -> io::Result<()> {
    let mut file = BufReader::new(fs::open(path)?);
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    if !contents.contains(hostname) {
        let new_line = format!("{} {}", ip, hostname);

        let mut writer = BufWriter::new(fs::open(path)?;
        writer.write_all(contents.as_bytes())?;
        writer.write_all(new_line.as_bytes())?;
        writer.write_all(b"\n")?;

        Ok(())
    } else {
        Err(io::Error::new(io::ErrorKind::InvalidInput, "Host already exists"))
    }
}
