use std::path::PathBuf;
use sysctl;

fn get_executable_path() -> PathBuf {
    let mut mib = [0; 3];
    mib[0] = sysctl::CTL_KERN as i32;
    mib[1] = sysctl::KERN_PROC as i32;
    mib[2] = sysctl::KERN_PROC_PATHNAME as i32;

    let mut path = [0; PathBuf::MAX_LENGTH as usize];
    let size = unsafe { sysctl::sysctlbyname(&mib, &mut path as *mut _, path.len() as _, 0) };
    if size == -1 {
        panic!("Failed to get executable path");
    }

    PathBuf::from(std::str::from_utf8_lossy(&path).to_string())
}
