use std::hash::{SipHasher};
use digest::{Digest, Md5, Sha1, Sha224, Sha256, Sha384, Sha512};

fn hash(algorithm: &str, data: &str) -> (&str, Box<dyn Digest>, u32) {
    match algorithm {
        "MD5" => (
            algorithm,
            Box::new(Md5::new()),
            128
        ),
        "SHA1" => (
            algorithm,
            Box::new(Sha1::new()),
            160
        ),
        "SHA224" => (
            algorithm,
            Box::new(Sha224::new()),
            224
        ),
        "SHA256" => (
            algorithm,
            Box::new(Sha256::new()),
            256
        ),
        "SHA384" => (
            algorithm,
            Box::new(Sha384::new()),
            384
        ),
        "SHA512" => (
            algorithm,
            Box::new(Sha512::new()),
            512
        ),
        "SHA3" => {
            let bits = match data.parse::<u32>() {
                Ok(n) if n <= 0 || n > 1024 => panic!("Invalid number of bits for SHA3"),
                Ok(n) => n,
                Err(_) => panic!("Failed to parse the number of bits for SHA3"),
            };
            (
                algorithm,
                Box::new(sha3::Keccak512::new().set_output_size(bits * 8)),
                bits * 8
            )
        },
        _ => panic!("Unsupported algorithm"),
    }
}
