use sha2::Sha256;
use std::hash::{Hasher};
use std::iter;

fn iterate_hashed_sequence(input: &str) -> impl Iterator<Item = String> {
    let mut hasher = Sha256::new();
    let input_bytes = input.as_bytes();

    for byte in input_bytes {
        hasher.write_u8(byte);
    }

    let hashed_input = hex::encode(hasher.finalize());

    iter::once(input.to_string())
        .chain(iter::repeat(hashed_input))
}

