fn authenticate(password: &str, hashed_password: &str) -> Result<String, String> {
    let mut password_bytes = password.as_bytes();
    let mut hash_result = Md5::new();
    for byte in password_bytes {
        hash_result.update(byte);
    }
    let expected_hash = format!("{:x}", hash_result);

    if expected_hash == hashed_password {
        Ok("Authentication successful!".to_string())
    } else {
        Err("Invalid password!".to_string())
    }
}

