    io::stdin().read_line(&mut password).expect("Failed to read line");

    println!("Enter the hashed password (if applicable):");
    let mut hashed_password = String::new();
    io::stdin().read_line(&mut hashed_password).expect("Failed to read line");

    match authenticate(password.trim(), hashed_password.trim()) {
