use std::path::{Path, PathBuf};
use std::io;
use fs::CopyOptions;

fn copy_dir(src: &Path, dst: &Path) -> io::Result<()> {
    for entry in src.read_dir()? {
        let entry = entry?;
        let name = entry.file_name();
        let path = dst.join(name);

        if !path.exists() {
            match entryMetadata(entry.path())? {
                std::os::unix::fs::MetadataType::Dir => {
                    fs::create_dir_all(&path)?;
                    copy_dir(entry.path(), &path)?
                }
                std::os::unix::fs::MetadataType::File => {
                    let mut opts = CopyOptions::new();
                    opts.owner(true);
                    opts.permissions(false);
                    fs::copy(entry.path(), &path)?
                }
                _ => return Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid metadata")),
            }
        }
    }
    Ok(())
}

fn entryMetadata(path: &Path) -> io::Result<MetadataType> {
    let meta = fs::metadata(path)?;
    if meta.is_dir() {
        Ok(MetadataType::Dir)
    } else {
        Ok(MetadataType::File)
    }
}

enum MetadataType {
    Dir,
    File
}
