use bencode::Bencode;
use digest::{Digest, Sha1};
use hashmap;

fn extract_metadata(bencode_map: &hashmap::HashMap<String, Bencode>) -> Metadata {
    let info = match bencode_map.get("info") {
        Some(info) => info,
        None => panic!("No 'info' key in the map"),
    };

    let length = match *info.as_map().get("length") {
        Some(length) => length.as_i64().unwrap(),
        None => panic!("No 'length' value in the info map"),
    };

    let pieces = match *info.as_map().get("pieces") {
        Some(pieces) => pieces.as_vec().unwrap(),
        None => panic!("No 'pieces' value in the info map"),
    };

    let sha1_hash = {
        let mut hasher = Sha1::new();
        for piece in pieces {
            hasher.update(piece.as_bytes());
        }
        let hash = hasher.finalize();
        hash.bytes()
    };

    Metadata {
        length,
        pieces,
        sha1_hash,
    }
}
