fn create_pool(executor: &Executor, store: &Store, size: usize) -> (NailgunPool, Vec<String>, Vec<(String, String)>) {
    let pool_dir = tempfile::tempdir().unwrap();
    let mut named_caches = Vec::new();
    let mut immutable_inputs = Vec::new();

    for i in 0..size {
        let cache_name = format!("cache-{}", i);
        let input_name = format!("input-{}", i);

        let cache_dir = pool_dir.path().join(&cache_name);
        let _ = std::fs::create_dir_all(cache_dir).unwrap();
        named_caches.push(cache_name.clone());

        immutable_inputs.push((cache_name, input_name));
    }

    let pool = NailgunPool::new(executor, store, pool_dir.path());
    (pool, named_caches, immutable_inputs)
}

