fn json_hash(path: &str, disable_fs_checks: bool) -> Result<String, String> {
    let mut hasher = Sha256::new();

    if !disable_fs_checks && !Path::new(path).exists() {
        return Err("File does not exist".to_string());
    }

    match read_to_string(path) {
        Ok(json_contents) => {
            match from_reader(&mut json_contents.as_bytes()) {
                Ok(_) => {
                    hasher.update(json_contents.as_bytes());
                    let hash = format!("{:x}", *hasher);
                    Ok(hash)
                },
                Err(e) => Err(format!("Failed to parse JSON: {}", e)),
            }
        },
        Err(e) => Err(format!("Failed to read file: {}", e)),
    }
}

