use std::collections::BTreeMap;
use rust_bencode::{BDict, BValue};
use sha1::{Sha1, Digest};

fn calculate_sha1(input: Vec<u8>) -> (DecodeResult<BDict>, u64) {
    let mut dict = BDict::new();
    let mut pos = 0;
    let chunk_size = 65536;

    loop {
        let end = if pos + chunk_size > input.len() { input.len() } else { pos + chunk_size };
        let chunk = &input[pos..end];
        let mut sha1 = Sha1::new();
        sha1.update(chunk);
        let hash = format!("{:x}", sha1.finalize());

        dict.insert(BValue::from_str(&hash), BValue::from_bytes(chunk.to_vec()));
        if end >= input.len() {
            break;
        }
        pos = end;
    }

    (dict.into(), pos as u64)
}
