use std::fs;
use std::io::{ErrorKind, Write};

struct History {
    buffers: Vec<Vec<u8>>,
}

impl History {
    fn new(max_file_size: u32) -> Self {
        History { buffers: vec![] }
    }

    fn push(&mut self, buffer: &Vec<u8>) {
        self.buffers.push(buffer.clone());
    }

    fn commit_to_file(&self, file_path: &str) -> Result<(), ErrorKind> {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create(true)
            .open(file_path)?;
        for buffer in &self.buffers {
            file.write_all(buffer)?; // assume Write implementation is correct
        }
        Ok(())
    }
}

fn main() {
    let history = History::new(1024);
    let buffers: Vec<Vec<u8>> = (0..5).map(|_| vec![1, 2, 3]).collect();
    for buffer in buffers.iter() {
        history.push(buffer);
    }
    history.commit_to_file("example.txt").unwrap();

    let committed_history = fs::read_dir("example.txt").unwrap().count();
    assert_eq!(committed_history, 5);

