use crypto::md5::{Md5, Md5Hasher};
use crypto::hmac::{Hmac, HmacMac};
use pbkdf2::{PBKDF2, PBKDF2OutputBytes};
use std::error::Error;
use std::str;

fn hash_password(password: &str, salt: &str) -> Result<String, Box<dyn Error>> {
    if salt.len() < 16 {
        return Err("Invalid salt length. Must be at least 16 bytes." .to_string().into());
    }

    let mut md5 = Md5::new();
    md5.update(salt.as_bytes());
    let hash = md5.finalize();

    let mut hmac = Hmac::new(Md5Hasher);
    hmac.set_key(&hash);

    let mut pbkdf2 = PBKDF2::new(hmac, 1000, password.as_bytes(), 32).unwrap();
    let hashed_password = str::from_utf8(&pbkdf2.output())?.to_string();

    Ok(hashed_password)
}

