use std::env;
use std::process;

fn get_default_browser() -> Option<&'static str> {
    env::var("BROWSER").ok()
}

fn open_with(program: &str, path: &str) -> Result<(), String> {
    process::Command::new(program)
        .arg(path)
        .spawn()
        .map(|p| p.wait())?;
    Ok(())
}

fn try_open(path: &str) -> Result<String, String> {
    let default_browser = get_default_browser();
    if let Some(browser) = default_browser {
        match open_with(browser, path) {
            Ok(_) => return Ok(browser.to_string()),
            Err(_) => println!("{} failed", browser),
        }
    }

    vec!["xdg-open", "gnome-open", "kde-open"]
        .into_iter()
        .find_map(|program| open_with(program, path).ok())
        .map_or_else(
            || -> Result<String, String> {
                let mut methods = Vec::new();
                for program in ["xdg-open", "gnome-open", "kde-open"].iter() {
                    match open_with(program, path) {
                        Ok(_) => return Ok(program.to_string()),
                        Err(_) => methods.push(program),
                    }
                }
                Err(format!("Failed to open with {}", methods.join(", ")))
            },
            |program| Ok(program.to_string())
        )
}

fn main() -> Result<(), String> {
    let path = "/path/to/file";
    match try_open(path) {
        Ok(browser) => println!("{}", browser),
        Err(err) => println!("{}", err),
    }
}

