use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn find_command(command: &str) -> Option<PathBuf> {
    let mut dirs = vec![env::current_exe().unwrap().parent().unwrap().to_path_buf()];
    dirs.push(env::current_dir().unwrap());

    for path in env::var("PATH").unwrap().split(':') {
        dirs.extend(path.split_whitespace());
    }

    for dir in dirs {
        if let Some(exe) = dir.join(command).extension() {
            if exe == "exe" || exe == "" {
                return Some(dir.join(command));
            }
        }
    }

    None
}

fn find_config_file() -> Option<String> {
    let mut config_path = None;

    // Get the working directory
    let wd = env::current_dir().ok()?;
    if let Ok(p) = config_path_from_dir(&wd, "config.json") {
        config_path = Some(p);
    }

    // Get the directory of the executable
    let exe_dir = dirs::data_directory().ok()?;
    if let Ok(p) = config_path_from_dir(&exe_dir, "config.json") {
        config_path = Some(p);
    }

    // Get the user's home directory
    let home_dir = dirs::home_directory().ok()?;
    if let Ok(p) = config_path_from_dir(&home_dir, ".config/config.json") {
        config_path = Some(p);
    }

    config_path
}

fn config_path_from_dir(dir: &PathBuf, filename: &str) -> Option<PathBuf> {
