use reqwest;
use std::collections::HashMap;
use std::{option, result};

async fn process_provider_info(
    provider_info: &ProviderInfo,
    interaction: &Interaction,
    verification_options: &VerificationOptions,
    provider_state_executor: &ProviderStateExecutor,
) -> Result<Option<String>, MismatchResult> {
    let client = reqwest::Client::new();
    let mut provider_states_results = HashMap::new();

    // iterate over the provider states
    futures::stream::iter(provider_info.states.iter())
        .map_async(|state| {
            if let Some(result) = provider_states_results.get(state) {
                return Ok(Some(result.clone()));
            }

            let request_url = format!("https://{}/api/{}", state, interaction.provider);
            let response = client
                .get(&request_url)
                .send()
                .await?
                .text()
                .await?;

            if !response.contains(interaction.expected_response) {
                return Err(MismatchResult { provider: interaction.provider, expected_response: interaction.expected_response });
            }

            // execute the provider state
            let result = provider_state_executor.execute(state).await?;
            provider_states_results.insert(state.clone(), result);

            Ok(Some(result))
        })
        .collect()
        .await?
        .into_iter()
        .flatten()
        .next()
}
