use base64::{encode_config, STANDARD_ENCODE_CONFIG};
use uuid::Uuid;

pub fn hash_input(input: &[u8]) -> String {
    let guid = Uuid::new_v4().to_string();
    let mut input_guid = guid.as_bytes();
    input_guid.extend_from_slice(input);

    let mut hasher = Sha1::new();
    hasher.update(input_guid);
