use std::collections::HashMap;
use std::sync::atomic::{self, AtomicUsize};

struct Args {
    server_port: u16,
    user_data_path: String,
    rally_point_port: u16,
}

static CACHED_ARGS: AtomicUsize = AtomicUsize::new(0);
lazy_static! {
    static ref ARGS_CACHE: HashMap<usize, Args> = HashMap::new();
}

fn parse_args() -> Args {
    let mut args_map = HashMap::new();
    if let Some(ref mut map) = *ARGS_CACHE.get_or_insert_with(||
        std::fs::read_to_string("/proc/self/cmdline").unwrap()
            .trim_matches('\0')
            .splitn(2, |s| s.contains('/'))
            .skip(1)
            .fold("", |mut acc, arg| {
                let parts: Vec<_> = arg.split_whitespace().collect();
                for i in (1..).step_by(2) {
                    let mut key_value = parts.get(i).unwrap_or(&"").trim_matches(' ');
                    let colon_index = key_value.find('=');
                    let key = if let Some(colon_index) = colon_index {
                        &key_value[..colon_index]
                    } else {
                        &key_value
                    };
                    let value = if let Some(colon_index) = colon_index {
                        &key_value[colon_index + 1..].trim_matches(' ')
                    } else {
                        "default"
                    };
                    *acc += format!("{}={}\n", key, value);
                }
                acc
            })
    ) {
        let server_port_str = args_map.remove("server_port");
        let user_data_path_str = args_map.remove("user_data_path");
        let rally_point_port_str = args_map.remove("rally_point_port");

        if let (Some(server_port), Some(user_data_path), Some(rally_point_port)) = (
            server_port_str.map(|s| s.parse::<u16>().ok()),
            user_data_path_str,
            rally_point_port_str.map(|s| s.parse::<u16>().ok()),
        ) {
            Args {
                server_port: server_port.unwrap(),
                user_data_path: user_data_path.clone(),
                rally_point_port: rally_point_port.unwrap(),
            }
        } else {
            unreachable!("Invalid arguments");
        }
    } else {
        let cached_key = CACHED_ARGS.load(std::sync::atomic::Ordering::SeqCst);
        Args::clone_from(&ARGS_CACHE[&cached_key]).unwrap()
    }
}
