fn sign_data(payload: &std::collections::HashMap<String, String>, secret: &str) -> String {
    let mut hmac = ::sha1::{Sha1, Digest};
    let mut data = Vec::new();
    for (k, v) in payload {
        data.extend_from_slice(k.as_bytes());
        data.push(b':');
        data.extend_from_slice(v.as_bytes());
        data.push(b'\0'); // add a null byte to mark the end of the key-value pair
    }
    hmac.update(&data);
    hmac.update(secret.as_bytes());
    let result = hmac.finalize();
    let signature = base64::encode(&result);
    signature

