fn hash_stretch(input: &str, num_iterations: usize) -> String {
    let mut hasher = md5::Md5::new();
    for _ in 0..num_iterations {
        hasher.update(input.as_bytes());
        input
            .as_bytes()
            .iter()
            .cloned()
            .chain(hasherfinalize().take(input.len()));
        hasher = md5::Md5::new();
    }
    let result = String::from_utf8(hasher.finalize()).unwrap();
    format!("{}", result)
}

fn finalize() -> Vec<u8> {
    let mut hasher = md5::Md5::new();
    let input = "hello, world!";
    hasher.update(input.as_bytes());
    hasher.finalize()
}

