fn generate_pact_file(pact: &Pact, dir_path: &str) -> String {
    let tmp_dir = tempfile::tempdir().unwrap();
    let pact_file_path = tmp_dir.path().join("pact.json");

    let mut file_content = "[\n".to_string();

    // Generate the PACT file content
    file_content += &format!("  {{\"name\": \"{}\", \"request\":{\"method\":\"{}\",\"path\":\"{}\"},\"response\":{\"status\":200}}}\n",
                               pact.name, pact.method, pact.path);

    file_content += "]";

    fs::write(&pact_file_path, file_content.as_bytes()).unwrap();

    let pact_file_contents = fs::read_to_string(&pact_file_path).unwrap();
    fs::remove_dir(tmp_dir).unwrap();

    pact_file_contents
}
