use std::fs::File;
use std::io::{Read, BufReader};
use std::path::Path;
use md5::{Md5, Md5Result};

struct FileInfo {
    name: String,
    path: String,
    size: usize,
    hash: String,
}

fn get_file_info(path: &str) -> FileInfo {
    let file_path = Path::new(path);
    let file_name = file_path.file_name().unwrap();
    let mut file_size = 0;

    let file = File::open(&file_path).expect("Failed to open file");
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line.unwrap();
        file_size += line.len() as usize;
    }

    let mut md5 = Md5::new();
    let mut buffer = String::new();
    reader.read_to_string(&mut buffer).unwrap();
    let hash_result: Md5Result = md5.update(buffer.as_bytes()).finalize();
    let hash = format!("{:x}", hash_result);

    FileInfo {
        name: file_name.to_str().unwrap().to_string(),
        path: file_path.to_str().unwrap().to_string(),
        size: file_size,
        hash: hash,
    }
}

