use std::process::{Command, exit};
use std::time::{Instant, Duration};
use sysinfo::{System, SystemExt};
use synclazy::SyncLazy;

fn rustc() -> i32 {
    let start = Instant::now();
    let mut system = System::new();
    let resident_set_size_before = system.virtual_memory().resident_set();

    let _log_hook = SyncLazy::new(|| { println!("Custom logging hook installed"); });

    match Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("--out-dir=.")
        .output()
    {
        Ok(result) => {
            let resident_set_size_after = system.virtual_memory().resident_set();
            let duration = start.elapsed();

            if result.status().code() != 0 {
                early_error::early_error(&format!("Compilation failed with exit code {}", result.status().code()));
                exit(result.status().code());
            }
        },
        Err(_) => {
            early_error::early_error("Failed to run rustc");
            exit(1);
        }
    }

    resident_set_size_after as i32 - resident_set_size_before as i32
}
