use std::io;

fn create_wallet(config_value: &str) -> io::Result<PathBuf> {
    let wallet_dir = format!("wallets/{}", config_value);
    let path = Path::new(&wallet_dir);
    let dir_path = PathBuf::from(path);

    if !dir_path.exists() {
        fs::create_dir_all(dir_path.parent().unwrap())?;
    }

    let private_key_file = "private.key";
    let key_path = dir_path.join(private_key_file);

    if key_path.exists() {
        fs::remove_file(key_path)?;
    }

    let mut file = fs::OpenOptions::new()
        .write(true)
        .create(true)
        .open(key_path)?;

    file.write_all(b"your_private_key")?;

    Ok(key_path.to_owned())
}

