use std::process::{Command, exit};
use std::io;
use std::env;

fn run_program(program: &str, env_vars: &std::collections::HashMap<String, String>, lld_flavor: LldFlavor) -> io::Result<String> {
    let mut cmd = Command::new(program);
    if let Some(flavor) = lld_flavor {
        match flavor {
            LldFlavor::Wasm => {
                let wasm_arg = format!("--target=wasm-unknown-emscripten --sysroot /");
                cmd.arg(wasm_arg);
            }
            LldFlavor::X86_64_Linux_Gnu => {
                let x86_arg = "gcc -m32".to_string();
                cmd.arg(x86_arg);
            }
        };
    }
    for (key, value) in env_vars {
        cmd.env(key, value);
    }
    match cmd.output() {
        Ok(output) => {
            let out = String::from_utf8_lossy(&output.stdout).trim().to_string();
            Ok(out)
        }
        Err(why) => {
            eprintln!("Error: {}", why);
            exit(1);
        }
    }
}

#[derive(Debug, Copy, Clone)]
enum LldFlavor {
    Wasm,
    X86_64_Linux_Gnu
}
