struct Headers {
    fields: Vec<String>,
}

impl Headers {
    fn new() -> Self {
        Headers { fields: vec![] }
    }

    fn insert_raw(&mut self, key: &str, value: &str) {
        self.fields.push(format!("{}: {}", key, value));
    }
}

fn format_header(input: &str) -> String {
    let mut headers = Headers::new();
    let lines: Vec<&str> = input.split('\n').collect();

    for line in lines {
        if let Some((key, value)) = line.split_once(':') {
            headers.insert_raw(key.trim(), value.trim());
        }
    }

    format!("{}", headers.fields.join("\n"))
}
