use reqwest::{blocking::get, Client};
use reqwest::header;
use reqwest::redirect;
use reqwest::connect::{InsecureTls, InsecureTlsConfig};

fn create_reqwest_client(user_agent: &str, connection_header_value: &str, cert_path: &str) -> Client {
    let mut client = Client::new();

    // Set custom User-Agent header
    client.header("User-Agent", user_agent);

    // Set Connection header to 'close'
    client.header("Connection", connection_header_value);

    // Load certificates from files at the specified path
    let certs = std::fs::read_dir(cert_path).unwrap().map(|entry| entry.unwrap().path()).collect();
    client = InsecureTls::with_config(InsecureTlsConfig::new(), &certs);

    client
}
