use std::io;
use std::net::TcpStream;
use tls::TLSConfig;
use tls::{TlsConnect, TlsStream};

fn create_secure_connection(host: &str, port: u16, verify: bool, nodelay: bool) -> Result<TlsStream<io::TakeReadExceedingCapacity>, io::Error> {
    let config = TLSConfig::builder()
        .domain_name(host)
        .build()?;

    let mut stream = TcpStream::connect((host, port))?;
    TlsConnect::new(&mut stream, &config).unwrap_or_else(|e| {
        eprintln!("Failed to establish TLS connection: {}", e);
        io::Error::new(io::ErrorKind::Other, "TLS connection failed")
    })?;

    if !verify {
        let mut config = TLSConfig::builder()?;
        config.set_verify(false);
        TlsStream::from_config(&mut stream, &config)?;
    } else {
        TlsStream::new(stream)?;
    }

    if nodelay {
        stream.set_nodelay(true)?;
    }

    Ok(TlsStream::new(stream)?)
}
