use std::process;
use std::path::{Path, PathBuf};
use std::borrow::Cow;

fn create_command(line: &str) -> process::Command {
    let mut parts = line.split_whitespace();
    let command = Cow::from(parts.next().expect("no command"));
    let args: Vec<_> = parts.map(|s| s.to_string()).collect();

    if let Some(flavor) = args.get(0).and_then(|s| s.strip_prefix("--flavor=").map(|s| s.parse().ok())) {
        match flavor {
            1 | "wasm" => {
                process::Command::new("wasm")
                    .args(["run", &command].concat())
                    .inherit()
            }
            _ => {
                process::Command::new("cmd").arg("/c").arg(&format!("{} {}", command, args.join(" ")))
            }
        }
    } else if command.ends_with(".bat") || command.ends_with(".cmd") {
        process::Command::new("cmd").arg("/c").arg(&format!("{} {}", command, args.join(" ")))
    } else {
        process::Command::new(command).args(args)
    }
}

fn main() {
    let line = "node myscript.js --flavor=1";
    let command = create_command(line);
    // ...
}
