use std::process::{Command, Stdio};

pub fn open_file_command(path: &str) -> Result<String, String> {
    let mut commands = vec!["$BROWSER", "xdg-open", "gnome-open", "kde-open"];

    for command in commands.iter() {
        if Command::new(command)
            .arg(path)
            .stdout(Stdio::null())
            .status()
            .is_ok()
        {
            return Ok(format!("{} {}", command, path));
        }
    }

    let attempted_commands = commands.join(", ");
    Err(format!("Failed to open file. Attempted commands: {}", attempted_commands))
}

