use std::sync::{Arc, Mutex};
use std::thread;
use std::thread::Thread;
use std::threadpool::{ThreadPoolExecutor, ThreadPoolHandle};
use std::time::Duration;

struct DBSupervisor {
    pool: Arc<Mutex<ThreadPoolExecutor>>,
}

impl DBSupervisor {
    fn new() -> Self {
        Self { pool: Arc::new(Mutex::new(ThreadPoolExecutor::new(4).unwrap())) }
    }

    fn start(&self) {
        let client_chan = chan::async::<String, String>();

        let db_handle = self.pool.lock().unwrap().execute(move || {
            loop {
                thread::sleep(Duration::from_millis(100));
                if let Ok(msg) = client_chan.recv() {
                    println!("Received query: {}", msg);
                }
            }
        });

        let query_client = QueryClient { chan: client_chan };

        thread::spawn(move || {
            loop {
                thread::sleep(Duration::from_millis(1000));
                query_client.send_query("SELECT * FROM users WHERE id = 1".to_string());
            }
        });
    }
}

struct QueryClient {
    chan: chan::async<String, String>,
}

impl QueryClient {
    fn send_query(&self, query: String) {
        self.chan.send(query).unwrap();
    }
}
